UPDATE character_profiles SET voice_actors_json=json('[{"language":"Китайский","name":"王宇航"},{"language":"Английский","name":"Jacob Craner"},{"language":"Японский","name":"森川智之"},{"language":"Корейский","name":"심규혁"},{"language":"Китайский","name":"Wang Yuhang (王宇航)"},{"language":"Японский","name":"Toshiyuki Morikawa (森川 智之)"},{"language":"Корейский","name":"Shim Kyu-hyeok (심규혁)"}]') WHERE character_id='adler' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:18:27');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"en-Play_Vo_Char_NPC010_hobby_001","title":"Хобби","description":"Кулинария требует дисциплины… от выбора ингредиентов до получения отзыва, каждое блюдо — уникальное путешествие. Мне нравится готовить для всех в «Эйбоне», хотя лучше бы Сакири не была такой привередой.","language":"Английский","audioUrl":"/nte-meta/game-audio/121299d8b5a20b9ddd08.ogg"},{"id":"ja-Play_Vo_Char_NPC010_deploy_002","title":"Отправка I","description":"Полезно немного потренироваться.","language":"Японский","audioUrl":"/nte-meta/game-audio/339541739f878ec225b2.ogg"},{"id":"ja-Play_Vo_Char_NPC010_weather_002","title":"Дождливо","description":"Кажется, прогнозы погоды не всегда надежны. Давай найдем, где переждать дождь.","language":"Японский","audioUrl":"/nte-meta/game-audio/73a6b8eacba6bcfd12bc.ogg"},{"id":"ko-Play_Vo_Char_NPC010_fh_001","title":"Исцеление I","description":"Теперь мне лучше.","language":"Корейский","audioUrl":"/nte-meta/game-audio/2f8122dd3f0e88a152e8.ogg"},{"id":"zh-Play_Vo_Char_NPC010_about_006","title":"О Тайгедо","description":"Я благодарен Тайгедо за постоянную помощь в магазине, особенно за его любопытные маленькие изобретения. И хотя Сакири, Наналли и даже госпожа шутят о том, чтобы продать его для погашения долгов, они все время спрашивают о нем, стоит ему отлучиться.","language":"Китайский","audioUrl":"/nte-meta/game-audio/21c34c710829f426d91b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_dead_003","title":"Потеря сознания III","description":"Прости, что разочаровал.","language":"Японский","audioUrl":"/nte-meta/game-audio/feba75d0a2ad1e4916f0.ogg"},{"id":"ja-Play_Vo_Char_NPC010_gift_003","title":"Подарок получен III","description":"Оценщик, я всегда знал, что у вас превосходный вкус.Оценщица, я всегда знал, что у вас превосходный вкус.","language":"Японский","audioUrl":"/nte-meta/game-audio/ebc484e48a433ddcf861.ogg"},{"id":"ja-Play_Vo_Char_NPC010_talk_002","title":"Тема: этикет","description":"Опрятный внешний вид производит хорошее впечатление, но истинный этикет заключается в том, чтобы учитывать чувства других, а не насаждать свои привычки. Принуждение других следовать нашим принципам — грубейшее нарушение этикета.","language":"Японский","audioUrl":"/nte-meta/game-audio/6ae5e8c7a573472df8e4.ogg"},{"id":"ko-Play_Vo_Char_NPC010_windfall_006","title":"Неожиданная добыча VI","description":"Хорошее качество. Это мы оставим себе.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e681b276a83f2d3262b6.ogg"},{"id":"zh-Play_Vo_Char_NPC010_struck_001","title":"Урон I","description":"Моя ошибка.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3e19cbaf0e9d5fa0b364.ogg"},{"id":"voice-6dwxfr","title":"О Сакири","description":"Сакири не очень хорошо выражает свои чувства. Для такой чувствительной натуры, как она, поступки говорят громче слов. Она действительно переживает, но не показывает этого. Чтобы постепенно раскрыться, ей нужно личное пространство.","language":"Английский","audioUrl":"/nte-meta/game-audio/63201ee9e5ece6b6e208.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"ja-Play_Vo_Char_NPC010_anomaly_003","title":"Нуллификация I","description":"Нужно что-нибудь, чтобы восстановить силы?","language":"Японский","audioUrl":"/nte-meta/game-audio/f774e0d376d6b6a8649f.ogg"},{"id":"ko-Play_Vo_Char_NPC010_dead_003","title":"Потеря сознания III","description":"Прости, что разочаровал.","language":"Корейский","audioUrl":"/nte-meta/game-audio/450f64b48dbbcd0891ba.ogg"},{"id":"ko-Play_Vo_Char_NPC010_SSC_004","title":"Особое переключение — Эдгар","description":"Мне обслужить твои компьютерные детали?","language":"Корейский","audioUrl":"/nte-meta/game-audio/63493f6931dbdb9b9c34.ogg"},{"id":"zh-Play_Vo_Char_NPC010_about_005","title":"О Даффодил","description":"Даффодил демонстрирует непоколебимую преданность госпоже, лично решая все её проблемы — на неё действительно можно положиться. С её поддержкой я могу сконцентрироваться на выполнении других задач… Хотя иногда мне хотелось бы, чтобы она заботилась и о себе.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7c9059098465f7bc8cc3.ogg"},{"id":"zh-Play_Vo_Char_NPC010_Fly_001","title":"Планирование I","description":"Ветер набирает силу?","language":"Китайский","audioUrl":"/nte-meta/game-audio/52c366f5a4c5c4d04514.ogg"},{"id":"zh-Play_Vo_Char_NPC010_TeammateDown_005","title":"Поражен товарищ по команде – Даффодил","description":"Даффодил, спасибо за усердную работу.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2d81e6b690b28487284d.ogg"},{"id":"en-Play_Vo_Char_NPC010_DodgeCombo_001","title":"Серия критических уклонений I","description":"Я кое-чему научился.","language":"Английский","audioUrl":"/nte-meta/game-audio/dad96d895ababa181ed4.ogg"},{"id":"en-Play_Vo_Char_NPC010_ug_001","title":"Вознесение персонажа I","description":"Учение не знает границ.","language":"Английский","audioUrl":"/nte-meta/game-audio/ec180b37d89ffe5eded9.ogg"},{"id":"ja-Play_Vo_Char_NPC010_meet_001","title":"Первая встреча","description":"Добро пожаловать в «Эйбон». Я Алоис фон Адлер, дворецкий. Пожалуйста, зови меня Адлер. Если что-то понадобится, дай знать. Я к твоим услугам.","language":"Японский","audioUrl":"/nte-meta/game-audio/2dc6dd20bcbce84fc460.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_005","title":"Неожиданная добыча V","description":"Как насчет устроить сегодня особенный ужин?","language":"Японский","audioUrl":"/nte-meta/game-audio/bc81716445a486a0dab2.ogg"},{"id":"zh-Play_Vo_Char_NPC010_gift_002","title":"Подарок получен II","description":"Это напомнило мне кое о чём из прошлого… Подарок мне очень понравился. Спасибо.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5fb249adc157a8c1fdcb.ogg"},{"id":"en-Play_Vo_Char_NPC010_skill_003","title":"Навык перенаправления III","description":"Осмысли.","language":"Английский","audioUrl":"/nte-meta/game-audio/4ae643482c0863a402bb.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Наналли, не нагружай себя так!","language":"Английский","audioUrl":"/nte-meta/game-audio/8369a82675b8392a2efe.ogg"},{"id":"ja-Play_Vo_Char_NPC010_kill_001","title":"Убийство I","description":"Ты в порядке?","language":"Японский","audioUrl":"/nte-meta/game-audio/db88daa2b1aeabd94674.ogg"},{"id":"ko-Play_Vo_Char_NPC010_about_002","title":"О Наналли","description":"Наналли — обычный ребенок. Благодаря ей в «Эйбоне» стало гораздо веселее. Конечно, когда что-то случается, хотелось бы, чтобы она была более… Но я не жалуюсь на шум. В этом возрасте детям нужно играть.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f3d4587c9866b64bb2e0.ogg"},{"id":"ko-Play_Vo_Char_NPC010_self_001","title":"Обо мне: броня","description":"Это броня Озарение. Она не моя; мне просто повезло ею пользоваться. В ней обитает Сунья, облегчая домашние дела.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a307ce04d59d210c5192.ogg"},{"id":"zh-Play_Vo_Char_NPC010_hstruck_001","title":"Сильный урон I","description":"Это может обернуться неприятностями.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5953913f6ef8e7b580ca.ogg"},{"id":"zh-Play_Vo_Char_NPC010_TeammateDown_006","title":"Поражен товарищ по команде – Ноль","description":"Ты отлично держался, оценщик. Остальное беру на себя.Ты отлично держалась, оценщица. Остальное беру на себя.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d9405e0776b4e5561643.ogg"},{"id":"zh-Play_Vo_Char_NPC010_vexation_001","title":"Проблемы","description":"Проблемы? Магазин работает в убыток, госпожа купила очередную подделку под антиквариат, а махинации Наналли приводят к нам на порог разъяренных соседей. От всего этого у меня голова болит, но больше всего меня беспокоит то, как все пренебрегают своим благополучием. Как дворецкий «Эйбона» я уделяю особое внимание таким вопросам.","language":"Китайский","audioUrl":"/nte-meta/game-audio/8ab226e68d06e63f8a4a.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_003","title":"О Сакири","description":"Сакири не очень хорошо выражает свои чувства. Для такой чувствительной натуры, как она, поступки говорят громче слов. Она действительно переживает, но не показывает этого. Чтобы постепенно раскрыться, ей нужно личное пространство.","language":"Японский","audioUrl":"/nte-meta/game-audio/f1a2e64c122ecbbf84ed.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Parry_002","title":"Парирование II","description":"Все то же мастерство.","language":"Японский","audioUrl":"/nte-meta/game-audio/99642ad07c5bbe73b7e9.ogg"},{"id":"ko-Play_Vo_Char_NPC010_anomaly_004","title":"Нуллификация II","description":"Иди, отдохни. С остальным я сам разберусь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ac2ea1087398fd6f608f.ogg"},{"id":"ko-Play_Vo_Char_NPC010_SSC_003","title":"Особое переключение — Сакири","description":"Сакири, осторожнее.","language":"Корейский","audioUrl":"/nte-meta/game-audio/7c6db5f4a78cd6d5f739.ogg"},{"id":"zh-Play_Vo_Char_NPC010_hobby_001","title":"Хобби","description":"Кулинария требует дисциплины… от выбора ингредиентов до получения отзыва, каждое блюдо — уникальное путешествие. Мне нравится готовить для всех в «Эйбоне», хотя лучше бы Сакири не была такой привередой.","language":"Китайский","audioUrl":"/nte-meta/game-audio/aeadab279948a2d8b2e0.ogg"},{"id":"zh-Play_Vo_Char_NPC010_Switch_003","title":"Переключение III","description":"Я тебя не подведу!","language":"Китайский","audioUrl":"/nte-meta/game-audio/c16509369ab3bfb4e25b.ogg"},{"id":"voice-iekw4p","title":"О Тайгедо","description":"Я благодарен Тайгедо за постоянную помощь в магазине, особенно за его любопытные маленькие изобретения. И хотя Сакири, Наналли и даже госпожа шутят о том, чтобы продать его для погашения долгов, они все время спрашивают о нем, стоит ему отлучиться.","language":"Английский","audioUrl":"/nte-meta/game-audio/57beb051f8bc91959a4d.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"ja-Play_Vo_Char_NPC010_hstruck_002","title":"Сильный урон II","description":"Непростая ситуация.","language":"Японский","audioUrl":"/nte-meta/game-audio/6a81dfd188333deabb55.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_001","title":"Неожиданная добыча I","description":"Стоит добавить в коллекцию.","language":"Японский","audioUrl":"/nte-meta/game-audio/e0ad3aa446ec4e0ab0e8.ogg"},{"id":"ko-Play_Vo_Char_NPC010_hp_001","title":"Низкий уровень здоровья I","description":"Это неожиданно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c2d834d600cd83e68d32.ogg"},{"id":"zh-Play_Vo_Char_NPC010_skill_001","title":"Навык перенаправления I","description":"Озари.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b77c485e7f1d12179e63.ogg"},{"id":"en-Play_Vo_Char_NPC010_chat_002","title":"Чат: списки","description":"Выпивка, конфеты, манга, игровые картриджи, антикоррозийное масло… да, это все.","language":"Английский","audioUrl":"/nte-meta/game-audio/e1926235014ce7b85443.ogg"},{"id":"en-Play_Vo_Char_NPC010_skill_001","title":"Навык перенаправления I","description":"Озари.","language":"Английский","audioUrl":"/nte-meta/game-audio/1b3764d86386acf8c6b3.ogg"},{"id":"ko-Play_Vo_Char_NPC010_aoe_UI_003","title":"Сверхспособность III","description":"Желаю тебе обрести вечный покой.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4bc9cd4053fac3dc1acb.ogg"},{"id":"ko-Play_Vo_Char_NPC010_TeammateDown_004","title":"Поражен товарищ по команде – Эдгар","description":"Ты хорошо поработал, Эдгар.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5d7ecd8b1a8bc332e96e.ogg"},{"id":"zh-Play_Vo_Char_NPC010_Switch_002","title":"Переключение II","description":"Хорошо, что я не опоздал.","language":"Китайский","audioUrl":"/nte-meta/game-audio/53ca1aafe296b3b5f026.ogg"},{"id":"zh-Play_Vo_Char_NPC010_weather_001","title":"Солнечно","description":"Отличная погода для прогулки. Приготовлю бенто-боксы для Наналли и остальных.","language":"Китайский","audioUrl":"/nte-meta/game-audio/384a5d1d5d02bae1cda9.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_003","title":"Особое переключение — Сакири","description":"Сакири, осторожнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/9a66d14749fb89b33a9c.ogg"},{"id":"ja-Play_Vo_Char_NPC010_DodgeCombo_002","title":"Серия критических уклонений II","description":"Терпение важнее спешки.","language":"Японский","audioUrl":"/nte-meta/game-audio/78eeb69fd9d1069ac22d.ogg"},{"id":"ja-Play_Vo_Char_NPC010_greet_002","title":"Дневное приветствие","description":"Что хочешь поесть? Я собираюсь готовить.","language":"Японский","audioUrl":"/nte-meta/game-audio/e0b06bf8d3e1e789f259.ogg"},{"id":"ko-Play_Vo_Char_NPC010_containment_001","title":"Сдерживание I","description":"Я позабочусь об уборке.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f53be03fe76ef190ec66.ogg"},{"id":"ko-Play_Vo_Char_NPC010_weather_001","title":"Солнечно","description":"Отличная погода для прогулки. Приготовлю бенто-боксы для Наналли и остальных.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ff650d882a13925cedd3.ogg"},{"id":"ko-Play_Vo_Char_NPC010_windfall_004","title":"Неожиданная добыча IV","description":"Похоже, в этом месяце мы получим прибыль.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b5ab335437effa96dcd0.ogg"},{"id":"zh-Play_Vo_Char_NPC010_fh_001","title":"Исцеление I","description":"Теперь мне лучше.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d710cf1824710a056d74.ogg"},{"id":"zh-Play_Vo_Char_NPC010_self_003","title":"Обо мне: очки","description":"Эти очки? Наналли купила их мне с первой зарплаты от поручений после того, как присоединилась к команде «Эйбона». Сияя от восторга, она заявила: «Вот как одеваются благородные бандиты в кино!» Она так радовалась, что я не мог не принять этот уникальный жест. Что касается её пары… она подобрала их, чтобы воплотить стиль… «босса Ити-дайме»? Такие подарки вполне в духе Наналли.","language":"Китайский","audioUrl":"/nte-meta/game-audio/4ea5bf436a19aab75f60.ogg"},{"id":"ja-Play_Vo_Char_NPC010_chat_002","title":"Чат: списки","description":"Выпивка, конфеты, манга, игровые картриджи, антикоррозийное масло… да, это все.","language":"Японский","audioUrl":"/nte-meta/game-audio/55ab8ed36b4184d90fff.ogg"},{"id":"ja-Play_Vo_Char_NPC010_weather_004","title":"Жарко","description":"Не следует слишком сильно охлаждаться в жару… может заболеть живот, что очень неприятно.","language":"Японский","audioUrl":"/nte-meta/game-audio/18b3b06bfcb6447ebe4c.ogg"},{"id":"ko-Play_Vo_Char_NPC010_about_001","title":"О Хотори","description":"У госпожи столько забот… Стыдно признаться, но я могу помочь ей только с повседневными делами, хотя для меня честь взять на себя даже малую часть её ответственности.","language":"Корейский","audioUrl":"/nte-meta/game-audio/072cc6ac5e0c7151f50f.ogg"},{"id":"zh-Play_Vo_Char_NPC010_containment_002","title":"Сдерживание II","description":"Спасибо за старания.","language":"Китайский","audioUrl":"/nte-meta/game-audio/dae38f581ae4ee7a185b.ogg"},{"id":"ko-Play_Vo_Char_NPC010_hp_003","title":"Низкий уровень здоровья III","description":"Пожалуйста, держись за моей спиной.","language":"Корейский","audioUrl":"/nte-meta/game-audio/cfa1b37671c021617dd2.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_001","title":"Поражен товарищ по команде – Хотори","description":"Госпожа! Это моя вина…","language":"Английский","audioUrl":"/nte-meta/game-audio/d511b2554afe00aa19fb.ogg"},{"id":"ko-Play_Vo_Char_NPC010_greet_001","title":"Утреннее приветствие","description":"Доброе утро. Как прошёл отдых? Завтрак уже готов.","language":"Корейский","audioUrl":"/nte-meta/game-audio/9e342481d3782af4bd4b.ogg"},{"id":"zh-Play_Vo_Char_NPC010_hp_002","title":"Низкий уровень здоровья II","description":"Не волнуйся, я в порядке.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c7cc372fbef3fe3820b7.ogg"},{"id":"en-Play_Vo_Char_NPC010_chat_001","title":"Чат: бизнес","description":"Доход в этом месяце… выглядит не слишком многообещающим.","language":"Английский","audioUrl":"/nte-meta/game-audio/b72c6e7f7e28ca042054.ogg"},{"id":"en-Play_Vo_Char_NPC010_hp_003","title":"Низкий уровень здоровья III","description":"Пожалуйста, держись за моей спиной.","language":"Английский","audioUrl":"/nte-meta/game-audio/ac55b7e9e813e42749f0.ogg"},{"id":"en-Play_Vo_Char_NPC010_Switch_001","title":"Переключение I","description":"Отдохни немного.","language":"Английский","audioUrl":"/nte-meta/game-audio/12827c080e1a958acef5.ogg"},{"id":"ja-Play_Vo_Char_NPC010_self_002","title":"Обо мне: способности эспера","description":"Мне трудно сохранять нейтралитет по отношению к способностям эспера или аномалиям, ведь у меня, несомненно, есть к ним особый интерес… Большинство людей недоумевают, когда впервые встречают меня. Им непонятно, как слепой человек может воспринимать мир вокруг с такой ясностью. Когда-то я был обычным незрячим и во многом зависел от других. Озарение даровало мне способность ощущать мир, а вместе с ней и обязательство быть защитником.","language":"Японский","audioUrl":"/nte-meta/game-audio/7c1fbdeaaeb63293875c.ogg"},{"id":"ja-Play_Vo_Char_NPC010_weather_001","title":"Солнечно","description":"Отличная погода для прогулки. Приготовлю бенто-боксы для Наналли и остальных.","language":"Японский","audioUrl":"/nte-meta/game-audio/596aa31724f047a85c4f.ogg"},{"id":"ko-Play_Vo_Char_NPC010_containment_002","title":"Сдерживание II","description":"Спасибо за старания.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e4169e8ca98e98053625.ogg"},{"id":"ko-Play_Vo_Char_NPC010_QTE_003","title":"Атака на входе III","description":"Все это лишь иллюзия.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e753090574e65e232a11.ogg"},{"id":"ko-Play_Vo_Char_NPC010_skill_001","title":"Навык перенаправления I","description":"Озари.","language":"Корейский","audioUrl":"/nte-meta/game-audio/bad28f73f6889c39cef5.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_005","title":"Поражен товарищ по команде – Даффодил","description":"Даффодил, спасибо за усердную работу.","language":"Английский","audioUrl":"/nte-meta/game-audio/327260b58395a2474dab.ogg"},{"id":"en-Play_Vo_Char_NPC010_weather_002","title":"Дождливо","description":"Кажется, прогнозы погоды не всегда надежны. Давай найдем, где переждать дождь.","language":"Английский","audioUrl":"/nte-meta/game-audio/011353fcfe64c7c213c7.ogg"},{"id":"ja-Play_Vo_Char_NPC010_deploy_001","title":"Отправка II","description":"Чем я могу вам помочь?","language":"Японский","audioUrl":"/nte-meta/game-audio/2ee31f7a0bf5a5fc5d06.ogg"},{"id":"ja-Play_Vo_Char_NPC010_gift_002","title":"Подарок получен II","description":"Это напомнило мне кое о чём из прошлого… Подарок мне очень понравился. Спасибо.","language":"Японский","audioUrl":"/nte-meta/game-audio/f3db86e2bd4267811ede.ogg"},{"id":"ja-Play_Vo_Char_NPC010_QTE_002","title":"Атака на входе II","description":"Закончим с этим побыстрее.","language":"Японский","audioUrl":"/nte-meta/game-audio/b7965c4ff0f22a2399ad.ogg"},{"id":"zh-Play_Vo_Char_NPC010_talk_003","title":"Тема: советы","description":"Секрет быстрой работы? Для повседневных задач я просто заранее готовлю списки и следую плану. Разумеется, иногда случаются неожиданности… в таком случае пригодятся терпение и немного удачи… Думаю, с опытом начинаешь замечать закономерности в том, как справляться с делами.","language":"Китайский","audioUrl":"/nte-meta/game-audio/628c4f375ef274924230.ogg"},{"id":"zh-Play_Vo_Char_NPC010_weather_002","title":"Дождливо","description":"Кажется, прогнозы погоды не всегда надежны. Давай найдем, где переждать дождь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0b90d255781182e1a911.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_003","title":"Поражен товарищ по команде – Сакири","description":"Даже Кирумару нужно время, чтобы все переварить.","language":"Английский","audioUrl":"/nte-meta/game-audio/a04c758a2a9f8adab93f.ogg"},{"id":"ja-Play_Vo_Char_NPC010_ug_001","title":"Вознесение персонажа I","description":"Учение не знает границ.","language":"Японский","audioUrl":"/nte-meta/game-audio/cf9865603119277034e5.ogg"},{"id":"zh-Play_Vo_Char_NPC010_greet_003","title":"Вечернее приветствие","description":"Эй, расслабься. Сейчас свободное время, клиенты, как правило, не приходят в эти часы.","language":"Китайский","audioUrl":"/nte-meta/game-audio/09556ffe77c1a0466819.ogg"},{"id":"zh-Play_Vo_Char_NPC010_kill_002","title":"Убийство II","description":"Я ещё не потерял хватку.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f3c2200941e25e7c5d8b.ogg"},{"id":"zh-Play_Vo_Char_NPC010_QTE_003","title":"Атака на входе III","description":"Все это лишь иллюзия.","language":"Китайский","audioUrl":"/nte-meta/game-audio/db688e9906e1c5d624ba.ogg"},{"id":"zh-Play_Vo_Char_NPC010_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Наналли, не нагружай себя так!","language":"Китайский","audioUrl":"/nte-meta/game-audio/f3654223124b611374bf.ogg"},{"id":"en-Play_Vo_Char_NPC010_fh_001","title":"Исцеление I","description":"Теперь мне лучше.","language":"Английский","audioUrl":"/nte-meta/game-audio/0a464cd554b7dab82ef6.ogg"},{"id":"voice-1qe3zmo","title":"Дневное приветствие","description":"Что хочешь поесть? Я собираюсь готовить.","language":"Английский","audioUrl":"/nte-meta/game-audio/f11a648f5702267b72df.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"ja-Play_Vo_Char_NPC010_chat_003","title":"Чат: Сунья","description":"Спасибо всем за помощь сегодня.","language":"Японский","audioUrl":"/nte-meta/game-audio/a6a7dc2de305dbfd52fd.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Fly_002","title":"Планирование II","description":"Очень удобный способ путешествовать.","language":"Японский","audioUrl":"/nte-meta/game-audio/d50edfd46b1de2947ebc.ogg"},{"id":"ja-Play_Vo_Char_NPC010_struck_002","title":"Урон II","description":"Осторожнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/47b4934524f3240a1042.ogg"},{"id":"ko-Play_Vo_Char_NPC010_aoe_UI_001","title":"Сверхспособность I","description":"Все, что имеет форму, нереально.","language":"Корейский","audioUrl":"/nte-meta/game-audio/cb10747ba22a67abc903.ogg"},{"id":"ko-Play_Vo_Char_NPC010_skill_002","title":"Навык перенаправления II","description":"Рассей.","language":"Корейский","audioUrl":"/nte-meta/game-audio/98e48378ea2ec084aade.ogg"},{"id":"zh-Play_Vo_Char_NPC010_about_001","title":"О Хотори","description":"У госпожи столько забот… Стыдно признаться, но я могу помочь ей только с повседневными делами, хотя для меня честь взять на себя даже малую часть её ответственности.","language":"Китайский","audioUrl":"/nte-meta/game-audio/bb56de038829cfbdcdf3.ogg"},{"id":"zh-Play_Vo_Char_NPC010_about_003","title":"О Сакири","description":"Сакири не очень хорошо выражает свои чувства. Для такой чувствительной натуры, как она, поступки говорят громче слов. Она действительно переживает, но не показывает этого. Чтобы постепенно раскрыться, ей нужно личное пространство.","language":"Китайский","audioUrl":"/nte-meta/game-audio/891537cc47ddf8e7cbcb.ogg"},{"id":"zh-Play_Vo_Char_NPC010_hstruck_002","title":"Сильный урон II","description":"Непростая ситуация.","language":"Китайский","audioUrl":"/nte-meta/game-audio/226c53e3b35f67bdb817.ogg"},{"id":"en-Play_Vo_Char_NPC010_containment_001","title":"Сдерживание I","description":"Я позабочусь об уборке.","language":"Английский","audioUrl":"/nte-meta/game-audio/c83645b5b14d2241460b.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_002","title":"Особое переключение — Наналли","description":"Молодец, Наналли.","language":"Английский","audioUrl":"/nte-meta/game-audio/7e0abf8dcdd8fd39878f.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_007","title":"Об антикварном магазине Эйбон","description":"«Эйбон» не всегда был таким оживленным. Когда мы только поселились на улице Ханкаку, всё было довольно уныло. Сакири почти не разговаривала, а госпожа и Даффодил решали проблемы с утра до ночи. Ситуация изменилась, когда мы нашли Тайгедо, и ещё больше — с появлением Наналли и Эдгара. Магазин наполнился теплом и смехом. Теперь, когда ты с нами, «Эйбон» стал для нас настоящим домом.","language":"Японский","audioUrl":"/nte-meta/game-audio/33f8bb4493201a3c26cd.ogg"},{"id":"ja-Play_Vo_Char_NPC010_skill_002","title":"Навык перенаправления II","description":"Рассей.","language":"Японский","audioUrl":"/nte-meta/game-audio/4ce8a2a473fa737169c8.ogg"},{"id":"ja-Play_Vo_Char_NPC010_ug_002","title":"Вознесение персонажа II","description":"Никогда не перестану совершенствоваться.","language":"Японский","audioUrl":"/nte-meta/game-audio/33e3a21830b74eac569e.ogg"},{"id":"zh-Play_Vo_Char_NPC010_meet_001","title":"Первая встреча","description":"Добро пожаловать в «Эйбон». Я Алоис фон Адлер, дворецкий. Пожалуйста, зови меня Адлер. Если что-то понадобится, дай знать. Я к твоим услугам.","language":"Китайский","audioUrl":"/nte-meta/game-audio/412c921be6c15fa86bdc.ogg"},{"id":"zh-Play_Vo_Char_NPC010_self_001","title":"Обо мне: броня","description":"Это броня Озарение. Она не моя; мне просто повезло ею пользоваться. В ней обитает Сунья, облегчая домашние дела.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b585ece9322f3bb1f985.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Я защищу тебя.","language":"Английский","audioUrl":"/nte-meta/game-audio/a363d677b3eaa0b6c7cc.ogg"},{"id":"ja-Play_Vo_Char_NPC010_hp_002","title":"Низкий уровень здоровья II","description":"Не волнуйся, я в порядке.","language":"Японский","audioUrl":"/nte-meta/game-audio/f6cd108a5f5cb4589711.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_006","title":"Неожиданная добыча VI","description":"Хорошее качество. Это мы оставим себе.","language":"Японский","audioUrl":"/nte-meta/game-audio/a3ad96a4fa4654495f42.ogg"},{"id":"ko-Play_Vo_Char_NPC010_DodgeCombo_002","title":"Серия критических уклонений II","description":"Терпение важнее спешки.","language":"Корейский","audioUrl":"/nte-meta/game-audio/93d3380af35742783d22.ogg"},{"id":"zh-Play_Vo_Char_NPC010_skill_003","title":"Навык перенаправления III","description":"Осмысли.","language":"Китайский","audioUrl":"/nte-meta/game-audio/594fb7859e4824908a6c.ogg"},{"id":"zh-Play_Vo_Char_NPC010_TeammateDown_001","title":"Поражен товарищ по команде – Хотори","description":"Госпожа! Это моя вина…","language":"Китайский","audioUrl":"/nte-meta/game-audio/549b90c8b5e4e6217258.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_001","title":"Поражен товарищ по команде – Хотори","description":"Госпожа! Это моя вина…","language":"Японский","audioUrl":"/nte-meta/game-audio/de46192ad7fbc79d454e.ogg"},{"id":"ko-Play_Vo_Char_NPC010_fh_002","title":"Исцеление II","description":"Все хорошо.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1404ae991fb2fb969518.ogg"},{"id":"en-Play_Vo_Char_NPC010_windfall_006","title":"Неожиданная добыча VI","description":"Хорошее качество. Это мы оставим себе.","language":"Английский","audioUrl":"/nte-meta/game-audio/8b8bf36347bd66bed751.ogg"},{"id":"ja-Play_Vo_Char_NPC010_hstruck_001","title":"Сильный урон I","description":"Это может обернуться неприятностями.","language":"Японский","audioUrl":"/nte-meta/game-audio/3ad7bbe9c638035a3a3e.ogg"},{"id":"ko-Play_Vo_Char_NPC010_chat_001","title":"Чат: бизнес","description":"Доход в этом месяце… выглядит не слишком многообещающим.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5a9b70b2cfded5938cd8.ogg"},{"id":"ko-Play_Vo_Char_NPC010_kill_002","title":"Убийство II","description":"Я ещё не потерял хватку.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6b539466a642358c9f48.ogg"},{"id":"ko-Play_Vo_Char_NPC010_Switch_002","title":"Переключение II","description":"Хорошо, что я не опоздал.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a5e1412d4800a04af575.ogg"},{"id":"zh-Play_Vo_Char_NPC010_ug_002","title":"Вознесение персонажа II","description":"Никогда не перестану совершенствоваться.","language":"Китайский","audioUrl":"/nte-meta/game-audio/de93d678928ea4e910ab.ogg"},{"id":"en-Play_Vo_Char_NPC010_gift_002","title":"Подарок получен II","description":"Это напомнило мне кое о чём из прошлого… Подарок мне очень понравился. Спасибо.","language":"Английский","audioUrl":"/nte-meta/game-audio/1c24b852c602e9752769.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_004","title":"Поражен товарищ по команде – Эдгар","description":"Ты хорошо поработал, Эдгар.","language":"Японский","audioUrl":"/nte-meta/game-audio/8043554cb529a4656eb1.ogg"},{"id":"ko-Play_Vo_Char_NPC010_TeammateDown_001","title":"Поражен товарищ по команде – Хотори","description":"Госпожа! Это моя вина…","language":"Корейский","audioUrl":"/nte-meta/game-audio/4139d19a62d9178e24da.ogg"},{"id":"zh-Play_Vo_Char_NPC010_chat_002","title":"Чат: списки","description":"Выпивка, конфеты, манга, игровые картриджи, антикоррозийное масло… да, это все.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c7b838e48f35041db253.ogg"},{"id":"voice-q1mnrf","title":"О Даффодил","description":"Даффодил демонстрирует непоколебимую преданность госпоже, лично решая все её проблемы — на неё действительно можно положиться. С её поддержкой я могу сконцентрироваться на выполнении других задач… Хотя иногда мне хотелось бы, чтобы она заботилась и о себе.","language":"Английский","audioUrl":"/nte-meta/game-audio/81174c5264abf7bd4d93.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"ja-Play_Vo_Char_NPC010_fh_002","title":"Исцеление II","description":"Все хорошо.","language":"Японский","audioUrl":"/nte-meta/game-audio/e27c675160aa8fe90405.ogg"},{"id":"ja-Play_Vo_Char_NPC010_vexation_001","title":"Проблемы","description":"Проблемы? Магазин работает в убыток, госпожа купила очередную подделку под антиквариат, а махинации Наналли приводят к нам на порог разъяренных соседей. От всего этого у меня голова болит, но больше всего меня беспокоит то, как все пренебрегают своим благополучием. Как дворецкий «Эйбона» я уделяю особое внимание таким вопросам.","language":"Японский","audioUrl":"/nte-meta/game-audio/64d6a4fa92969eede129.ogg"},{"id":"ko-Play_Vo_Char_NPC010_dead_001","title":"Потеря сознания I","description":"Мы можем пойти… дальше…","language":"Корейский","audioUrl":"/nte-meta/game-audio/0d5df317a66ad3b787a8.ogg"},{"id":"ko-Play_Vo_Char_NPC010_TeammateDown_006","title":"Поражен товарищ по команде – Ноль","description":"Ты отлично держался, оценщик. Остальное беру на себя.Ты отлично держалась, оценщица. Остальное беру на себя.","language":"Корейский","audioUrl":"/nte-meta/game-audio/20ec8d227635fad56a4a.ogg"},{"id":"ko-Play_Vo_Char_NPC010_weather_002","title":"Дождливо","description":"Кажется, прогнозы погоды не всегда надежны. Давай найдем, где переждать дождь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/2331232c50093bd010e0.ogg"},{"id":"zh-Play_Vo_Char_NPC010_about_007","title":"Об антикварном магазине Эйбон","description":"«Эйбон» не всегда был таким оживленным. Когда мы только поселились на улице Ханкаку, всё было довольно уныло. Сакири почти не разговаривала, а госпожа и Даффодил решали проблемы с утра до ночи. Ситуация изменилась, когда мы нашли Тайгедо, и ещё больше — с появлением Наналли и Эдгара. Магазин наполнился теплом и смехом. Теперь, когда ты с нами, «Эйбон» стал для нас настоящим домом.","language":"Китайский","audioUrl":"/nte-meta/game-audio/524b43fb7fd0dd651d0a.ogg"},{"id":"zh-Play_Vo_Char_NPC010_dead_002","title":"Потеря сознания II","description":"Пожалуйста… позаботься о них…","language":"Китайский","audioUrl":"/nte-meta/game-audio/48b722c1858a063108c6.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_002","title":"Особое переключение — Наналли","description":"Молодец, Наналли.","language":"Японский","audioUrl":"/nte-meta/game-audio/1595575d049412a3e9b9.ogg"},{"id":"zh-Play_Vo_Char_NPC010_anomaly_004","title":"Нуллификация II","description":"Иди, отдохни. С остальным я сам разберусь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7fbc61fe73c752788dc6.ogg"},{"id":"zh-Play_Vo_Char_NPC010_SSC_002","title":"Особое переключение — Наналли","description":"Молодец, Наналли.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d32fd3d2d67ce03926d9.ogg"},{"id":"en-Play_Vo_Char_NPC010_aoe_UI_001","title":"Сверхспособность I","description":"Все, что имеет форму, нереально.","language":"Английский","audioUrl":"/nte-meta/game-audio/70db728fcbf9002c3ee7.ogg"},{"id":"en-Play_Vo_Char_NPC010_QTE_002","title":"Атака на входе II","description":"Закончим с этим побыстрее.","language":"Английский","audioUrl":"/nte-meta/game-audio/23bd84195d1f9ed7197a.ogg"},{"id":"en-Play_Vo_Char_NPC010_weather_001","title":"Солнечно","description":"Отличная погода для прогулки. Приготовлю бенто-боксы для Наналли и остальных.","language":"Английский","audioUrl":"/nte-meta/game-audio/d09e193bcd21f17e6324.ogg"},{"id":"ja-Play_Vo_Char_NPC010_aoe_UI_002","title":"Сверхспособность II","description":"Безликое, бесформенное.","language":"Японский","audioUrl":"/nte-meta/game-audio/f214b2785a2c33142092.ogg"},{"id":"ja-Play_Vo_Char_NPC010_aoe_UI_003","title":"Сверхспособность III","description":"Желаю тебе обрести вечный покой.","language":"Японский","audioUrl":"/nte-meta/game-audio/ed83b51774c141737c88.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_003","title":"Особое переключение — Сакири","description":"Сакири, осторожнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/ea5af4a950ec6112e595.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_004","title":"Поражен товарищ по команде – Эдгар","description":"Ты хорошо поработал, Эдгар.","language":"Английский","audioUrl":"/nte-meta/game-audio/694e56739daf2508b711.ogg"},{"id":"ko-Play_Vo_Char_NPC010_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Наналли, не нагружай себя так!","language":"Корейский","audioUrl":"/nte-meta/game-audio/4cee2b6ec2fe756cf0cf.ogg"},{"id":"zh-Play_Vo_Char_NPC010_about_002","title":"О Наналли","description":"Наналли — обычный ребенок. Благодаря ей в «Эйбоне» стало гораздо веселее. Конечно, когда что-то случается, хотелось бы, чтобы она была более… Но я не жалуюсь на шум. В этом возрасте детям нужно играть.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3b0219748d8a092feefd.ogg"},{"id":"zh-Play_Vo_Char_NPC010_TeammateDown_003","title":"Поражен товарищ по команде – Сакири","description":"Даже Кирумару нужно время, чтобы все переварить.","language":"Китайский","audioUrl":"/nte-meta/game-audio/1024b4b2e56c42e6453b.ogg"},{"id":"en-Play_Vo_Char_NPC010_QTE_003","title":"Атака на входе III","description":"Все это лишь иллюзия.","language":"Английский","audioUrl":"/nte-meta/game-audio/a5b083757340fcd25b0b.ogg"},{"id":"en-Play_Vo_Char_NPC010_TeammateDown_006","title":"Поражен товарищ по команде – Ноль","description":"Ты отлично держался, оценщик. Остальное беру на себя.Ты отлично держалась, оценщица. Остальное беру на себя.","language":"Английский","audioUrl":"/nte-meta/game-audio/c9026bad5404c83b5fa4.ogg"},{"id":"ko-Play_Vo_Char_NPC010_self_003","title":"Обо мне: очки","description":"Эти очки? Наналли купила их мне с первой зарплаты от поручений после того, как присоединилась к команде «Эйбона». Сияя от восторга, она заявила: «Вот как одеваются благородные бандиты в кино!» Она так радовалась, что я не мог не принять этот уникальный жест. Что касается её пары… она подобрала их, чтобы воплотить стиль… «босса Ити-дайме»? Такие подарки вполне в духе Наналли.","language":"Корейский","audioUrl":"/nte-meta/game-audio/7e51c58e7f6f41814140.ogg"},{"id":"ko-Play_Vo_Char_NPC010_weather_003","title":"Холодно","description":"Должен напомнить всем, что нужно одеваться теплее. На всякий случай приготовлю лекарство от простуды.","language":"Корейский","audioUrl":"/nte-meta/game-audio/85a07fc2a72655ca1b30.ogg"},{"id":"zh-Play_Vo_Char_NPC010_about_004","title":"Об Эдгаре","description":"Необщительность — необязательно плохо. У каждого свой стиль жизни, и сам Эдгар не страдает от сложностей в общении с другими людьми, что не может не радовать. К тому же, рядом с ним всегда Сакири и Наналли, которые понимают его лучше всего и всегда готовы его выслушать.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7739fbb8b12d4e5a59d8.ogg"},{"id":"zh-Play_Vo_Char_NPC010_chat_001","title":"Чат: бизнес","description":"Доход в этом месяце… выглядит не слишком многообещающим.","language":"Китайский","audioUrl":"/nte-meta/game-audio/eb0407e68a1b29e00fbb.ogg"},{"id":"zh-Play_Vo_Char_NPC010_deploy_002","title":"Отправка I","description":"Полезно немного потренироваться.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5d01d6965510cb0d5944.ogg"},{"id":"zh-Play_Vo_Char_NPC010_DodgeCombo_001","title":"Серия критических уклонений I","description":"Я кое-чему научился.","language":"Китайский","audioUrl":"/nte-meta/game-audio/acd86e7486505cef3dc1.ogg"},{"id":"zh-Play_Vo_Char_NPC010_gift_001","title":"Подарок получен I","description":"Какой прекрасный подарок. Спасибо, оценщик.Какой прекрасный подарок. Спасибо, оценщица.","language":"Китайский","audioUrl":"/nte-meta/game-audio/154e04bb0c73265106c0.ogg"},{"id":"zh-Play_Vo_Char_NPC010_ug_003","title":"Вознесение персонажа III","description":"Памятный момент.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d877ae5f6fc443316dcd.ogg"},{"id":"ja-Play_Vo_Char_NPC010_dead_001","title":"Потеря сознания I","description":"Мы можем пойти… дальше…","language":"Японский","audioUrl":"/nte-meta/game-audio/e03d32b0f6241437626a.ogg"},{"id":"ja-Play_Vo_Char_NPC010_greet_004","title":"Спокойной ночи","description":"Для поддержания хорошего здоровья необходимо высыпаться… Конечно, если ты захочешь ещё поболтать, я всегда к твоим услугам.","language":"Японский","audioUrl":"/nte-meta/game-audio/9dcdc80e791f068c62eb.ogg"},{"id":"ja-Play_Vo_Char_NPC010_hp_001","title":"Низкий уровень здоровья I","description":"Это неожиданно.","language":"Японский","audioUrl":"/nte-meta/game-audio/da987ef5dd0004a8e39e.ogg"},{"id":"ko-Play_Vo_Char_NPC010_DodgeCombo_001","title":"Серия критических уклонений I","description":"Я кое-чему научился.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e02377bb9fe0ebd2f8f9.ogg"},{"id":"ko-Play_Vo_Char_NPC010_skill_003","title":"Навык перенаправления III","description":"Осмысли.","language":"Корейский","audioUrl":"/nte-meta/game-audio/38dd07caed29f5ee467c.ogg"},{"id":"zh-Play_Vo_Char_NPC010_containment_001","title":"Сдерживание I","description":"Я позабочусь об уборке.","language":"Китайский","audioUrl":"/nte-meta/game-audio/16314c8f556d58487293.ogg"},{"id":"en-Play_Vo_Char_NPC010_anomaly_003","title":"Нуллификация I","description":"Нужно что-нибудь, чтобы восстановить силы?","language":"Английский","audioUrl":"/nte-meta/game-audio/13725740cb659cee9141.ogg"},{"id":"zh-Play_Vo_Char_NPC010_windfall_001","title":"Неожиданная добыча I","description":"Стоит добавить в коллекцию.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2e4ea3c5ff8ade9ad31e.ogg"},{"id":"voice-9ro03m","title":"Первая встреча","description":"Добро пожаловать в «Эйбон». Я Алоис фон Адлер, дворецкий. Пожалуйста, зови меня Адлер. Если что-то понадобится, дай знать. Я к твоим услугам.","language":"Английский","audioUrl":"/nte-meta/game-audio/1ee8b82ff797a21e9818.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_self_001","title":"Обо мне: броня","description":"Это броня Озарение. Она не моя; мне просто повезло ею пользоваться. В ней обитает Сунья, облегчая домашние дела.","language":"Английский","audioUrl":"/nte-meta/game-audio/96f5646a994673eb4f89.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_005","title":"Особое переключение — Даффодил","description":"Смена меняется. Хорошая работа.","language":"Японский","audioUrl":"/nte-meta/game-audio/688f77d8e33d5b79ba3a.ogg"},{"id":"zh-Play_Vo_Char_NPC010_Parry_002","title":"Парирование II","description":"Все то же мастерство.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5b66af663a2ebe58fd7d.ogg"},{"id":"voice-yka0tx","title":"О Наналли","description":"Наналли — обычный ребенок. Благодаря ей в «Эйбоне» стало гораздо веселее. Конечно, когда что-то случается, хотелось бы, чтобы она была более… Но я не жалуюсь на шум. В этом возрасте детям нужно играть.","language":"Английский","audioUrl":"/nte-meta/game-audio/731cd928cd106dbb15f1.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_dead_003","title":"Потеря сознания III","description":"Прости, что разочаровал.","language":"Английский","audioUrl":"/nte-meta/game-audio/58a6d7bfe41202923783.ogg"},{"id":"en-Play_Vo_Char_NPC010_hstruck_001","title":"Сильный урон I","description":"Это может обернуться неприятностями.","language":"Английский","audioUrl":"/nte-meta/game-audio/9ccc2beb6f119f41d025.ogg"},{"id":"ja-Play_Vo_Char_NPC010_fh_001","title":"Исцеление I","description":"Теперь мне лучше.","language":"Японский","audioUrl":"/nte-meta/game-audio/e9677c506f7bbfb0c7f4.ogg"},{"id":"ko-Play_Vo_Char_NPC010_about_007","title":"Об антикварном магазине Эйбон","description":"«Эйбон» не всегда был таким оживленным. Когда мы только поселились на улице Ханкаку, всё было довольно уныло. Сакири почти не разговаривала, а госпожа и Даффодил решали проблемы с утра до ночи. Ситуация изменилась, когда мы нашли Тайгедо, и ещё больше — с появлением Наналли и Эдгара. Магазин наполнился теплом и смехом. Теперь, когда ты с нами, «Эйбон» стал для нас настоящим домом.","language":"Корейский","audioUrl":"/nte-meta/game-audio/fe81c95ca1dd42231863.ogg"},{"id":"ko-Play_Vo_Char_NPC010_aoe_UI_002","title":"Сверхспособность II","description":"Безликое, бесформенное.","language":"Корейский","audioUrl":"/nte-meta/game-audio/bd461b0b0c984ae99d54.ogg"},{"id":"ko-Play_Vo_Char_NPC010_self_004","title":"Обо мне: стремление к идеалу","description":"Мастер на все руки… Слишком громкое слово. Я всего лишь немного старше и видел чуть больше людей и событий. Когда я был в возрасте Наналли и остальных, по энергии и смелости я им и в подмётки не годился.","language":"Корейский","audioUrl":"/nte-meta/game-audio/18f1d2c29a2f03c7f96d.ogg"},{"id":"zh-Play_Vo_Char_NPC010_hp_001","title":"Низкий уровень здоровья I","description":"Это неожиданно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2ad2ba9d02a5ca5bc397.ogg"},{"id":"zh-Play_Vo_Char_NPC010_Switch_001","title":"Переключение I","description":"Отдохни немного.","language":"Китайский","audioUrl":"/nte-meta/game-audio/cef734f81643398b2cee.ogg"},{"id":"en-Play_Vo_Char_NPC010_anomaly_004","title":"Нуллификация II","description":"Иди, отдохни. С остальным я сам разберусь.","language":"Английский","audioUrl":"/nte-meta/game-audio/963b1b4d42c1cbc22a18.ogg"},{"id":"en-Play_Vo_Char_NPC010_Fly_001","title":"Планирование I","description":"Ветер набирает силу?","language":"Английский","audioUrl":"/nte-meta/game-audio/f487ceae9e55387f89ac.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_003","title":"Неожиданная добыча III","description":"Незнакомый предмет коллекции… нужно взять его с собой для подробного изучения.","language":"Японский","audioUrl":"/nte-meta/game-audio/9aa825c7b5dc592b450f.ogg"},{"id":"ko-Play_Vo_Char_NPC010_SSC_005","title":"Особое переключение — Даффодил","description":"Смена меняется. Хорошая работа.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5134cac7fafdb6dd6f82.ogg"},{"id":"ja-Play_Vo_Char_NPC010_containment_001","title":"Сдерживание I","description":"Я позабочусь об уборке.","language":"Японский","audioUrl":"/nte-meta/game-audio/ab39df3f301473a14dc6.ogg"},{"id":"ja-Play_Vo_Char_NPC010_self_004","title":"Обо мне: стремление к идеалу","description":"Мастер на все руки… Слишком громкое слово. Я всего лишь немного старше и видел чуть больше людей и событий. Когда я был в возрасте Наналли и остальных, по энергии и смелости я им и в подмётки не годился.","language":"Японский","audioUrl":"/nte-meta/game-audio/0f85112de1f627e3cb29.ogg"},{"id":"ko-Play_Vo_Char_NPC010_Parry_002","title":"Парирование II","description":"Все то же мастерство.","language":"Корейский","audioUrl":"/nte-meta/game-audio/516faaf68b515a5b776c.ogg"},{"id":"zh-Play_Vo_Char_NPC010_greet_001","title":"Утреннее приветствие","description":"Доброе утро. Как прошёл отдых? Завтрак уже готов.","language":"Китайский","audioUrl":"/nte-meta/game-audio/06010bca644b5693dfe7.ogg"},{"id":"zh-Play_Vo_Char_NPC010_QTE_001","title":"Атака на входе I","description":"Продолжительные бои бесцельны.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2a2e30754f2b4ab25f91.ogg"},{"id":"zh-Play_Vo_Char_NPC010_SSC_003","title":"Особое переключение — Сакири","description":"Сакири, осторожнее.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e7485925eb77168c15fb.ogg"},{"id":"voice-7kbebi","title":"Утреннее приветствие","description":"Доброе утро. Как прошёл отдых? Завтрак уже готов.","language":"Английский","audioUrl":"/nte-meta/game-audio/3dfc640408411e79951a.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"ja-Play_Vo_Char_NPC010_anomaly_004","title":"Нуллификация II","description":"Иди, отдохни. С остальным я сам разберусь.","language":"Японский","audioUrl":"/nte-meta/game-audio/8ea76123b6c9ec09ff05.ogg"},{"id":"ja-Play_Vo_Char_NPC010_greet_003","title":"Вечернее приветствие","description":"Эй, расслабься. Сейчас свободное время, клиенты, как правило, не приходят в эти часы.","language":"Японский","audioUrl":"/nte-meta/game-audio/e003dfc41803497d9db5.ogg"},{"id":"ja-Play_Vo_Char_NPC010_QTE_001","title":"Атака на входе I","description":"Продолжительные бои бесцельны.","language":"Японский","audioUrl":"/nte-meta/game-audio/4f3793b367ae1c92c761.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Switch_001","title":"Переключение I","description":"Отдохни немного.","language":"Японский","audioUrl":"/nte-meta/game-audio/a4ba51f1eb7adc44513e.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Switch_003","title":"Переключение III","description":"Я тебя не подведу!","language":"Японский","audioUrl":"/nte-meta/game-audio/2d1094ee7f4084299e9d.ogg"},{"id":"ja-Play_Vo_Char_NPC010_weather_003","title":"Холодно","description":"Должен напомнить всем, что нужно одеваться теплее. На всякий случай приготовлю лекарство от простуды.","language":"Японский","audioUrl":"/nte-meta/game-audio/19bb2791886a54b18060.ogg"},{"id":"ko-Play_Vo_Char_NPC010_anomaly_003","title":"Нуллификация I","description":"Нужно что-нибудь, чтобы восстановить силы?","language":"Корейский","audioUrl":"/nte-meta/game-audio/aa77e75f1961fb70f7a4.ogg"},{"id":"ko-Play_Vo_Char_NPC010_greet_003","title":"Вечернее приветствие","description":"Эй, расслабься. Сейчас свободное время, клиенты, как правило, не приходят в эти часы.","language":"Корейский","audioUrl":"/nte-meta/game-audio/fa571ea3cae3df2ea082.ogg"},{"id":"ko-Play_Vo_Char_NPC010_hp_002","title":"Низкий уровень здоровья II","description":"Не волнуйся, я в порядке.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6bf0188baa96e36d2ffc.ogg"},{"id":"zh-Play_Vo_Char_NPC010_kill_001","title":"Убийство I","description":"Ты в порядке?","language":"Китайский","audioUrl":"/nte-meta/game-audio/2e283b0880e6ba291e80.ogg"},{"id":"en-Play_Vo_Char_NPC010_self_003","title":"Обо мне: очки","description":"Эти очки? Наналли купила их мне с первой зарплаты от поручений после того, как присоединилась к команде «Эйбона». Сияя от восторга, она заявила: «Вот как одеваются благородные бандиты в кино!» Она так радовалась, что я не мог не принять этот уникальный жест. Что касается её пары… она подобрала их, чтобы воплотить стиль… «босса Ити-дайме»? Такие подарки вполне в духе Наналли.","language":"Английский","audioUrl":"/nte-meta/game-audio/c33d354dcecfce35e608.ogg"},{"id":"en-Play_Vo_Char_NPC010_Switch_003","title":"Переключение III","description":"Я тебя не подведу!","language":"Английский","audioUrl":"/nte-meta/game-audio/2c6f7baf84a2e5c94f38.ogg"}]') WHERE character_id='adler' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:18:27');

UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT value FROM json_each('[{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Наналли, не нагружай себя так!","language":"Японский","audioUrl":"/nte-meta/game-audio/54708abfc1873a83d053.ogg"},{"id":"ko-Play_Vo_Char_NPC010_deploy_002","title":"Отправка I","description":"Полезно немного потренироваться.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b96e11c4f2bf1cd8a26e.ogg"},{"id":"ko-Play_Vo_Char_NPC010_SSC_002","title":"Особое переключение — Наналли","description":"Молодец, Наналли.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4aced66a2bcf827675a5.ogg"},{"id":"en-Play_Vo_Char_NPC010_hstruck_002","title":"Сильный урон II","description":"Непростая ситуация.","language":"Английский","audioUrl":"/nte-meta/game-audio/c856c81c0bf7fed7b62a.ogg"},{"id":"ko-Play_Vo_Char_NPC010_self_002","title":"Обо мне: способности эспера","description":"Мне трудно сохранять нейтралитет по отношению к способностям эспера или аномалиям, ведь у меня, несомненно, есть к ним особый интерес… Большинство людей недоумевают, когда впервые встречают меня. Им непонятно, как слепой человек может воспринимать мир вокруг с такой ясностью. Когда-то я был обычным незрячим и во многом зависел от других. Озарение даровало мне способность ощущать мир, а вместе с ней и обязательство быть защитником.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6927a82c15e7fc81f7c6.ogg"},{"id":"zh-Play_Vo_Char_NPC010_aoe_UI_002","title":"Сверхспособность II","description":"Безликое, бесформенное.","language":"Китайский","audioUrl":"/nte-meta/game-audio/ddcc16a29b20638a5f4d.ogg"},{"id":"zh-Play_Vo_Char_NPC010_deploy_001","title":"Отправка II","description":"Чем я могу вам помочь?","language":"Китайский","audioUrl":"/nte-meta/game-audio/a2d68ad167184f46fd9f.ogg"},{"id":"en-Play_Vo_Char_NPC010_ug_003","title":"Вознесение персонажа III","description":"Памятный момент.","language":"Английский","audioUrl":"/nte-meta/game-audio/6717336720f06673b68b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_dead_002","title":"Потеря сознания II","description":"Пожалуйста… позаботься о них…","language":"Японский","audioUrl":"/nte-meta/game-audio/3aba353ff6de4ad6cbdd.ogg"},{"id":"ko-Play_Vo_Char_NPC010_weather_004","title":"Жарко","description":"Не следует слишком сильно охлаждаться в жару… может заболеть живот, что очень неприятно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c004acf7c7ddbae7bde0.ogg"},{"id":"zh-Play_Vo_Char_NPC010_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Я защищу тебя.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3feabbfafc74b94b7bdd.ogg"},{"id":"en-Play_Vo_Char_NPC010_Fly_002","title":"Планирование II","description":"Очень удобный способ путешествовать.","language":"Английский","audioUrl":"/nte-meta/game-audio/9009d129d5f8a83a85cc.ogg"},{"id":"en-Play_Vo_Char_NPC010_aoe_UI_002","title":"Сверхспособность II","description":"Безликое, бесформенное.","language":"Английский","audioUrl":"/nte-meta/game-audio/153b8b4415919aea74de.ogg"},{"id":"en-Play_Vo_Char_NPC010_windfall_001","title":"Неожиданная добыча I","description":"Стоит добавить в коллекцию.","language":"Английский","audioUrl":"/nte-meta/game-audio/60e0b1e262e92ab9db6b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_002","title":"О Наналли","description":"Наналли — обычный ребенок. Благодаря ей в «Эйбоне» стало гораздо веселее. Конечно, когда что-то случается, хотелось бы, чтобы она была более… Но я не жалуюсь на шум. В этом возрасте детям нужно играть.","language":"Японский","audioUrl":"/nte-meta/game-audio/4824da27ba4fde41f2cd.ogg"},{"id":"ja-Play_Vo_Char_NPC010_self_001","title":"Обо мне: броня","description":"Это броня Озарение. Она не моя; мне просто повезло ею пользоваться. В ней обитает Сунья, облегчая домашние дела.","language":"Японский","audioUrl":"/nte-meta/game-audio/f1c5c4909794bdf5574e.ogg"},{"id":"ko-Play_Vo_Char_NPC010_meet_001","title":"Первая встреча","description":"Добро пожаловать в «Эйбон». Я Алоис фон Адлер, дворецкий. Пожалуйста, зови меня Адлер. Если что-то понадобится, дай знать. Я к твоим услугам.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ec201e1d082a06646834.ogg"},{"id":"ko-Play_Vo_Char_NPC010_windfall_005","title":"Неожиданная добыча V","description":"Как насчет устроить сегодня особенный ужин?","language":"Корейский","audioUrl":"/nte-meta/game-audio/fba86ffb3ec969d574b6.ogg"},{"id":"zh-Play_Vo_Char_NPC010_windfall_003","title":"Неожиданная добыча III","description":"Незнакомый предмет коллекции… нужно взять его с собой для подробного изучения.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a7d8980daf40762a9f9c.ogg"},{"id":"en-Play_Vo_Char_NPC010_struck_002","title":"Урон II","description":"Осторожнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/ab793a0ddaddf5249653.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_001","title":"О Хотори","description":"У госпожи столько забот… Стыдно признаться, но я могу помочь ей только с повседневными делами, хотя для меня честь взять на себя даже малую часть её ответственности.","language":"Японский","audioUrl":"/nte-meta/game-audio/c112e6ec500d45be11ad.ogg"},{"id":"ja-Play_Vo_Char_NPC010_containment_002","title":"Сдерживание II","description":"Спасибо за старания.","language":"Японский","audioUrl":"/nte-meta/game-audio/d04d5c1257a61e76a1f1.ogg"},{"id":"ko-Play_Vo_Char_NPC010_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Я защищу тебя.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a0de50baaa922c301ddb.ogg"},{"id":"zh-Play_Vo_Char_NPC010_TeammateDown_004","title":"Поражен товарищ по команде – Эдгар","description":"Ты хорошо поработал, Эдгар.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c0e645a4622ec51df2eb.ogg"},{"id":"en-Play_Vo_Char_NPC010_chat_003","title":"Чат: Сунья","description":"Спасибо всем за помощь сегодня.","language":"Английский","audioUrl":"/nte-meta/game-audio/035099ac497610b30e94.ogg"},{"id":"en-Play_Vo_Char_NPC010_dead_002","title":"Потеря сознания II","description":"Пожалуйста… позаботься о них…","language":"Английский","audioUrl":"/nte-meta/game-audio/f607e1acf1b8cb973e64.ogg"},{"id":"ja-Play_Vo_Char_NPC010_gift_004","title":"Подарок получен IV","description":"Я буду дорожить этим подарком и тем, сколько сил вы в него вложили.","language":"Японский","audioUrl":"/nte-meta/game-audio/4301f51bad79f233f0fc.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_004","title":"Особое переключение — Эдгар","description":"Мне обслужить твои компьютерные детали?","language":"Японский","audioUrl":"/nte-meta/game-audio/74816839597734ce9d4a.ogg"},{"id":"ja-Play_Vo_Char_NPC010_ug_003","title":"Вознесение персонажа III","description":"Памятный момент.","language":"Японский","audioUrl":"/nte-meta/game-audio/adb6025bb505f341c40b.ogg"},{"id":"ko-Play_Vo_Char_NPC010_gift_002","title":"Подарок получен II","description":"Это напомнило мне кое о чём из прошлого… Подарок мне очень понравился. Спасибо.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b6fd007511d45116d4e4.ogg"},{"id":"ko-Play_Vo_Char_NPC010_greet_004","title":"Спокойной ночи","description":"Для поддержания хорошего здоровья необходимо высыпаться… Конечно, если ты захочешь ещё поболтать, я всегда к твоим услугам.","language":"Корейский","audioUrl":"/nte-meta/game-audio/85dbeeea441a7fe9e007.ogg"},{"id":"en-Play_Vo_Char_NPC010_gift_001","title":"Подарок получен I","description":"Какой прекрасный подарок. Спасибо, оценщик.Какой прекрасный подарок. Спасибо, оценщица.","language":"Английский","audioUrl":"/nte-meta/game-audio/4939b25039309475463d.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Fly_001","title":"Планирование I","description":"Ветер набирает силу?","language":"Японский","audioUrl":"/nte-meta/game-audio/a7770d3e5d13d7cd2f1e.ogg"},{"id":"ja-Play_Vo_Char_NPC010_talk_003","title":"Тема: советы","description":"Секрет быстрой работы? Для повседневных задач я просто заранее готовлю списки и следую плану. Разумеется, иногда случаются неожиданности… в таком случае пригодятся терпение и немного удачи… Думаю, с опытом начинаешь замечать закономерности в том, как справляться с делами.","language":"Японский","audioUrl":"/nte-meta/game-audio/88333b6d577e87250de3.ogg"},{"id":"ko-Play_Vo_Char_NPC010_ug_002","title":"Вознесение персонажа II","description":"Никогда не перестану совершенствоваться.","language":"Корейский","audioUrl":"/nte-meta/game-audio/80b742509a7aadca63d2.ogg"},{"id":"zh-Play_Vo_Char_NPC010_gift_003","title":"Подарок получен III","description":"Оценщик, я всегда знал, что у вас превосходный вкус.Оценщица, я всегда знал, что у вас превосходный вкус.","language":"Китайский","audioUrl":"/nte-meta/game-audio/aeba17ffc39540d6e71a.ogg"},{"id":"zh-Play_Vo_Char_NPC010_self_002","title":"Обо мне: способности эспера","description":"Мне трудно сохранять нейтралитет по отношению к способностям эспера или аномалиям, ведь у меня, несомненно, есть к ним особый интерес… Большинство людей недоумевают, когда впервые встречают меня. Им непонятно, как слепой человек может воспринимать мир вокруг с такой ясностью. Когда-то я был обычным незрячим и во многом зависел от других. Озарение даровало мне способность ощущать мир, а вместе с ней и обязательство быть защитником.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a8069ee27a761ee33490.ogg"},{"id":"en-Play_Vo_Char_NPC010_gift_003","title":"Подарок получен III","description":"Оценщик, я всегда знал, что у вас превосходный вкус.Оценщица, я всегда знал, что у вас превосходный вкус.","language":"Английский","audioUrl":"/nte-meta/game-audio/4ad7a4019a2169a6292e.ogg"},{"id":"en-Play_Vo_Char_NPC010_kill_002","title":"Убийство II","description":"Я ещё не потерял хватку.","language":"Английский","audioUrl":"/nte-meta/game-audio/b190c53edb28850ebe39.ogg"},{"id":"en-Play_Vo_Char_NPC010_self_002","title":"Обо мне: способности эспера","description":"Мне трудно сохранять нейтралитет по отношению к способностям эспера или аномалиям, ведь у меня, несомненно, есть к ним особый интерес… Большинство людей недоумевают, когда впервые встречают меня. Им непонятно, как слепой человек может воспринимать мир вокруг с такой ясностью. Когда-то я был обычным незрячим и во многом зависел от других. Озарение даровало мне способность ощущать мир, а вместе с ней и обязательство быть защитником.","language":"Английский","audioUrl":"/nte-meta/game-audio/66a0870d9d1a238e5f42.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_001","title":"Особое переключение — Хотори","description":"Я с этим разберусь, госпожа.","language":"Английский","audioUrl":"/nte-meta/game-audio/d6a0959bf0f7cc3232fc.ogg"},{"id":"ja-Play_Vo_Char_NPC010_gift_001","title":"Подарок получен I","description":"Какой прекрасный подарок. Спасибо, оценщик.Какой прекрасный подарок. Спасибо, оценщица.","language":"Японский","audioUrl":"/nte-meta/game-audio/dd49002f04175181a593.ogg"},{"id":"ko-Play_Vo_Char_NPC010_about_005","title":"О Даффодил","description":"Даффодил демонстрирует непоколебимую преданность госпоже, лично решая все её проблемы — на неё действительно можно положиться. С её поддержкой я могу сконцентрироваться на выполнении других задач… Хотя иногда мне хотелось бы, чтобы она заботилась и о себе.","language":"Корейский","audioUrl":"/nte-meta/game-audio/fbe0d70271da2b4ff13c.ogg"},{"id":"zh-Play_Vo_Char_NPC010_Fly_002","title":"Планирование II","description":"Очень удобный способ путешествовать.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7acac0b2701a6907d4ca.ogg"},{"id":"zh-Play_Vo_Char_NPC010_SSC_001","title":"Особое переключение — Хотори","description":"Я с этим разберусь, госпожа.","language":"Китайский","audioUrl":"/nte-meta/game-audio/de3fa4d51bafa11f1b17.ogg"},{"id":"zh-Play_Vo_Char_NPC010_talk_001","title":"Тема: аномалии","description":"Большинство Странностей на самом деле довольно дружелюбны… просто они не умеют выражать свои мысли и чувства, а может быть способы их выражения отличаются от привычных нам. Если будет возможность, попробуй пообщаться с ними. Возможно, перед тобой откроется абсолютно новый мир.","language":"Китайский","audioUrl":"/nte-meta/game-audio/1274f72aea064925a223.ogg"},{"id":"zh-Play_Vo_Char_NPC010_weather_003","title":"Холодно","description":"Должен напомнить всем, что нужно одеваться теплее. На всякий случай приготовлю лекарство от простуды.","language":"Китайский","audioUrl":"/nte-meta/game-audio/db210d131019fb4e395e.ogg"},{"id":"en-Play_Vo_Char_NPC010_deploy_001","title":"Отправка II","description":"Чем я могу вам помочь?","language":"Английский","audioUrl":"/nte-meta/game-audio/a78fcfc4c46f2b61783f.ogg"},{"id":"ja-Play_Vo_Char_NPC010_struck_001","title":"Урон I","description":"Моя ошибка.","language":"Японский","audioUrl":"/nte-meta/game-audio/c0e132bde820a333f38c.ogg"},{"id":"ja-Play_Vo_Char_NPC010_talk_001","title":"Тема: аномалии","description":"Большинство Странностей на самом деле довольно дружелюбны… просто они не умеют выражать свои мысли и чувства, а может быть способы их выражения отличаются от привычных нам. Если будет возможность, попробуй пообщаться с ними. Возможно, перед тобой откроется абсолютно новый мир.","language":"Японский","audioUrl":"/nte-meta/game-audio/c0b0d225e132af75b9ee.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_006","title":"Поражен товарищ по команде – Ноль","description":"Ты отлично держался, оценщик. Остальное беру на себя.Ты отлично держалась, оценщица. Остальное беру на себя.","language":"Японский","audioUrl":"/nte-meta/game-audio/1195adb1316e40709d7c.ogg"},{"id":"ko-Play_Vo_Char_NPC010_kill_001","title":"Убийство I","description":"Ты в порядке?","language":"Корейский","audioUrl":"/nte-meta/game-audio/cc52d96f548c5c197c30.ogg"},{"id":"ko-Play_Vo_Char_NPC010_struck_002","title":"Урон II","description":"Осторожнее.","language":"Корейский","audioUrl":"/nte-meta/game-audio/101ad5213ebbd9c4af13.ogg"},{"id":"ko-Play_Vo_Char_NPC010_talk_003","title":"Тема: советы","description":"Секрет быстрой работы? Для повседневных задач я просто заранее готовлю списки и следую плану. Разумеется, иногда случаются неожиданности… в таком случае пригодятся терпение и немного удачи… Думаю, с опытом начинаешь замечать закономерности в том, как справляться с делами.","language":"Корейский","audioUrl":"/nte-meta/game-audio/41a461aaa527b80de476.ogg"},{"id":"zh-Play_Vo_Char_NPC010_QTE_002","title":"Атака на входе II","description":"Закончим с этим побыстрее.","language":"Китайский","audioUrl":"/nte-meta/game-audio/4c6a2f4a231da1e879e0.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_005","title":"Особое переключение — Даффодил","description":"Смена меняется. Хорошая работа.","language":"Английский","audioUrl":"/nte-meta/game-audio/3cd72d072f5cfdf727b5.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_003","title":"Поражен товарищ по команде – Сакири","description":"Даже Кирумару нужно время, чтобы все переварить.","language":"Японский","audioUrl":"/nte-meta/game-audio/ed67a90495588bf5d332.ogg"},{"id":"ko-Play_Vo_Char_NPC010_about_004","title":"Об Эдгаре","description":"Необщительность — необязательно плохо. У каждого свой стиль жизни, и сам Эдгар не страдает от сложностей в общении с другими людьми, что не может не радовать. К тому же, рядом с ним всегда Сакири и Наналли, которые понимают его лучше всего и всегда готовы его выслушать.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d9d2a5dcbfeac4c4253b.ogg"},{"id":"ko-Play_Vo_Char_NPC010_greet_002","title":"Дневное приветствие","description":"Что хочешь поесть? Я собираюсь готовить.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4ad01dc9011e3140c9ce.ogg"},{"id":"ko-Play_Vo_Char_NPC010_Parry_001","title":"Парирование I","description":"Хороший выбор.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6165d108285e39c166d9.ogg"},{"id":"en-Play_Vo_Char_NPC010_dead_001","title":"Потеря сознания I","description":"Мы можем пойти… дальше…","language":"Английский","audioUrl":"/nte-meta/game-audio/8e2652e46ca05fa187e3.ogg"},{"id":"ja-Play_Vo_Char_NPC010_kill_002","title":"Убийство II","description":"Я ещё не потерял хватку.","language":"Японский","audioUrl":"/nte-meta/game-audio/cc49d02153b8bb0cffbd.ogg"},{"id":"ko-Play_Vo_Char_NPC010_chat_003","title":"Чат: Сунья","description":"Спасибо всем за помощь сегодня.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d090577b44ef9be6008a.ogg"},{"id":"ko-Play_Vo_Char_NPC010_hobby_001","title":"Хобби","description":"Кулинария требует дисциплины… от выбора ингредиентов до получения отзыва, каждое блюдо — уникальное путешествие. Мне нравится готовить для всех в «Эйбоне», хотя лучше бы Сакири не была такой привередой.","language":"Корейский","audioUrl":"/nte-meta/game-audio/200ace3bb00d6289d0bc.ogg"},{"id":"ko-Play_Vo_Char_NPC010_ug_001","title":"Вознесение персонажа I","description":"Учение не знает границ.","language":"Корейский","audioUrl":"/nte-meta/game-audio/08e9eeafc18cc1add28f.ogg"},{"id":"en-Play_Vo_Char_NPC010_aoe_UI_003","title":"Сверхспособность III","description":"Желаю тебе обрести вечный покой.","language":"Английский","audioUrl":"/nte-meta/game-audio/bdd2366dfdea86196e04.ogg"},{"id":"en-Play_Vo_Char_NPC010_containment_002","title":"Сдерживание II","description":"Спасибо за старания.","language":"Английский","audioUrl":"/nte-meta/game-audio/3f47c10798c22a82cd5c.ogg"},{"id":"ko-Play_Vo_Char_NPC010_gift_001","title":"Подарок получен I","description":"Какой прекрасный подарок. Спасибо, оценщик.Какой прекрасный подарок. Спасибо, оценщица.","language":"Корейский","audioUrl":"/nte-meta/game-audio/bc5cb4a801dc9c40eab1.ogg"},{"id":"zh-Play_Vo_Char_NPC010_chat_003","title":"Чат: Сунья","description":"Спасибо всем за помощь сегодня.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3d76ab4561e1c3821ac9.ogg"},{"id":"en-Play_Vo_Char_NPC010_skill_002","title":"Навык перенаправления II","description":"Рассей.","language":"Английский","audioUrl":"/nte-meta/game-audio/f9802b18f883cb9fd87a.ogg"},{"id":"voice-lcezki","title":"Тема: аномалии","description":"Большинство Странностей на самом деле довольно дружелюбны… просто они не умеют выражать свои мысли и чувства, а может быть способы их выражения отличаются от привычных нам. Если будет возможность, попробуй пообщаться с ними. Возможно, перед тобой откроется абсолютно новый мир.","language":"Английский","audioUrl":"/nte-meta/game-audio/f791236f82a064c3633d.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_weather_003","title":"Холодно","description":"Должен напомнить всем, что нужно одеваться теплее. На всякий случай приготовлю лекарство от простуды.","language":"Английский","audioUrl":"/nte-meta/game-audio/0f209c9d7bc04d3692ee.ogg"},{"id":"ja-Play_Vo_Char_NPC010_hobby_001","title":"Хобби","description":"Кулинария требует дисциплины… от выбора ингредиентов до получения отзыва, каждое блюдо — уникальное путешествие. Мне нравится готовить для всех в «Эйбоне», хотя лучше бы Сакири не была такой привередой.","language":"Японский","audioUrl":"/nte-meta/game-audio/4a29fc19a9a028c0f60a.ogg"},{"id":"ko-Play_Vo_Char_NPC010_about_006","title":"О Тайгедо","description":"Я благодарен Тайгедо за постоянную помощь в магазине, особенно за его любопытные маленькие изобретения. И хотя Сакири, Наналли и даже госпожа шутят о том, чтобы продать его для погашения долгов, они все время спрашивают о нем, стоит ему отлучиться.","language":"Корейский","audioUrl":"/nte-meta/game-audio/41f089c704eda2a78a45.ogg"},{"id":"en-Play_Vo_Char_NPC010_self_004","title":"Обо мне: стремление к идеалу","description":"Мастер на все руки… Слишком громкое слово. Я всего лишь немного старше и видел чуть больше людей и событий. Когда я был в возрасте Наналли и остальных, по энергии и смелости я им и в подмётки не годился.","language":"Английский","audioUrl":"/nte-meta/game-audio/708da5db72c96d992079.ogg"},{"id":"en-Play_Vo_Char_NPC010_SSC_004","title":"Особое переключение — Эдгар","description":"Мне обслужить твои компьютерные детали?","language":"Английский","audioUrl":"/nte-meta/game-audio/1c22c058f3e834fc827b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_005","title":"О Даффодил","description":"Даффодил демонстрирует непоколебимую преданность госпоже, лично решая все её проблемы — на неё действительно можно положиться. С её поддержкой я могу сконцентрироваться на выполнении других задач… Хотя иногда мне хотелось бы, чтобы она заботилась и о себе.","language":"Японский","audioUrl":"/nte-meta/game-audio/8b28cd37bb354c700823.ogg"},{"id":"ja-Play_Vo_Char_NPC010_aoe_UI_001","title":"Сверхспособность I","description":"Все, что имеет форму, нереально.","language":"Японский","audioUrl":"/nte-meta/game-audio/54fa063cf3857bfb2c9b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_001","title":"Особое переключение — Хотори","description":"Я с этим разберусь, госпожа.","language":"Японский","audioUrl":"/nte-meta/game-audio/f63ed1c3a1c4ebc177be.ogg"},{"id":"ko-Play_Vo_Char_NPC010_Fly_001","title":"Планирование I","description":"Ветер набирает силу?","language":"Корейский","audioUrl":"/nte-meta/game-audio/fb84e0f721d64d563c0c.ogg"},{"id":"ko-Play_Vo_Char_NPC010_gift_004","title":"Подарок получен IV","description":"Я буду дорожить этим подарком и тем, сколько сил вы в него вложили.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b27e1312807e7926ed34.ogg"},{"id":"ko-Play_Vo_Char_NPC010_Switch_001","title":"Переключение I","description":"Отдохни немного.","language":"Корейский","audioUrl":"/nte-meta/game-audio/583041ca230a8a5daf91.ogg"},{"id":"ko-Play_Vo_Char_NPC010_windfall_001","title":"Неожиданная добыча I","description":"Стоит добавить в коллекцию.","language":"Корейский","audioUrl":"/nte-meta/game-audio/41a5c6ff4ea418a2683e.ogg"},{"id":"zh-Play_Vo_Char_NPC010_greet_002","title":"Дневное приветствие","description":"Что хочешь поесть? Я собираюсь готовить.","language":"Китайский","audioUrl":"/nte-meta/game-audio/557c4f33d288d6e5f4ec.ogg"},{"id":"zh-Play_Vo_Char_NPC010_skill_002","title":"Навык перенаправления II","description":"Рассей.","language":"Китайский","audioUrl":"/nte-meta/game-audio/37d75fb45d6f512c1cac.ogg"},{"id":"en-Play_Vo_Char_NPC010_weather_004","title":"Жарко","description":"Не следует слишком сильно охлаждаться в жару… может заболеть живот, что очень неприятно.","language":"Английский","audioUrl":"/nte-meta/game-audio/372eb9472b8cae469282.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_004","title":"Об Эдгаре","description":"Необщительность — необязательно плохо. У каждого свой стиль жизни, и сам Эдгар не страдает от сложностей в общении с другими людьми, что не может не радовать. К тому же, рядом с ним всегда Сакири и Наналли, которые понимают его лучше всего и всегда готовы его выслушать.","language":"Японский","audioUrl":"/nte-meta/game-audio/981f2e26dc94548a2175.ogg"},{"id":"ko-Play_Vo_Char_NPC010_gift_003","title":"Подарок получен III","description":"Оценщик, я всегда знал, что у вас превосходный вкус.Оценщица, я всегда знал, что у вас превосходный вкус.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e8f23f2f7c99a50addd8.ogg"},{"id":"ko-Play_Vo_Char_NPC010_TeammateDown_005","title":"Поражен товарищ по команде – Даффодил","description":"Даффодил, спасибо за усердную работу.","language":"Корейский","audioUrl":"/nte-meta/game-audio/57e0457981c2baf49db5.ogg"},{"id":"ko-Play_Vo_Char_NPC010_vexation_001","title":"Проблемы","description":"Проблемы? Магазин работает в убыток, госпожа купила очередную подделку под антиквариат, а махинации Наналли приводят к нам на порог разъяренных соседей. От всего этого у меня голова болит, но больше всего меня беспокоит то, как все пренебрегают своим благополучием. Как дворецкий «Эйбона» я уделяю особое внимание таким вопросам.","language":"Корейский","audioUrl":"/nte-meta/game-audio/17365f59e965ee19b046.ogg"},{"id":"zh-Play_Vo_Char_NPC010_DodgeCombo_002","title":"Серия критических уклонений II","description":"Терпение важнее спешки.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d366dc8c543193d96cd9.ogg"},{"id":"en-Play_Vo_Char_NPC010_hp_002","title":"Низкий уровень здоровья II","description":"Не волнуйся, я в порядке.","language":"Английский","audioUrl":"/nte-meta/game-audio/61fc08099db3c866f0ba.ogg"},{"id":"voice-5ocvbl","title":"Тема: этикет","description":"Опрятный внешний вид производит хорошее впечатление, но истинный этикет заключается в том, чтобы учитывать чувства других, а не насаждать свои привычки. Принуждение других следовать нашим принципам — грубейшее нарушение этикета.","language":"Английский","audioUrl":"/nte-meta/game-audio/73a1c6303239721f6d85.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_windfall_002","title":"Неожиданная добыча II","description":"Какой приятный сюрприз… кажется, сегодня будет отличный день.","language":"Английский","audioUrl":"/nte-meta/game-audio/770270b9629faed54291.ogg"},{"id":"ja-Play_Vo_Char_NPC010_about_006","title":"О Тайгедо","description":"Я благодарен Тайгедо за постоянную помощь в магазине, особенно за его любопытные маленькие изобретения. И хотя Сакири, Наналли и даже госпожа шутят о том, чтобы продать его для погашения долгов, они все время спрашивают о нем, стоит ему отлучиться.","language":"Японский","audioUrl":"/nte-meta/game-audio/cb58291fed15bc72a599.ogg"},{"id":"ja-Play_Vo_Char_NPC010_DodgeCombo_001","title":"Серия критических уклонений I","description":"Я кое-чему научился.","language":"Японский","audioUrl":"/nte-meta/game-audio/dc2b1208dd252fbb3c3a.ogg"},{"id":"ko-Play_Vo_Char_NPC010_talk_002","title":"Тема: этикет","description":"Опрятный внешний вид производит хорошее впечатление, но истинный этикет заключается в том, чтобы учитывать чувства других, а не насаждать свои привычки. Принуждение других следовать нашим принципам — грубейшее нарушение этикета.","language":"Корейский","audioUrl":"/nte-meta/game-audio/222720870188fe2bad91.ogg"},{"id":"zh-Play_Vo_Char_NPC010_anomaly_003","title":"Нуллификация I","description":"Нужно что-нибудь, чтобы восстановить силы?","language":"Китайский","audioUrl":"/nte-meta/game-audio/2c9261e4c28c0d84c4ed.ogg"},{"id":"zh-Play_Vo_Char_NPC010_greet_004","title":"Спокойной ночи","description":"Для поддержания хорошего здоровья необходимо высыпаться… Конечно, если ты захочешь ещё поболтать, я всегда к твоим услугам.","language":"Китайский","audioUrl":"/nte-meta/game-audio/acf1e9dfe519c578579f.ogg"},{"id":"zh-Play_Vo_Char_NPC010_talk_002","title":"Тема: этикет","description":"Опрятный внешний вид производит хорошее впечатление, но истинный этикет заключается в том, чтобы учитывать чувства других, а не насаждать свои привычки. Принуждение других следовать нашим принципам — грубейшее нарушение этикета.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a72c564718bdd3e226eb.ogg"},{"id":"en-Play_Vo_Char_NPC010_talk_003","title":"Тема: советы","description":"Секрет быстрой работы? Для повседневных задач я просто заранее готовлю списки и следую плану. Разумеется, иногда случаются неожиданности… в таком случае пригодятся терпение и немного удачи… Думаю, с опытом начинаешь замечать закономерности в том, как справляться с делами.","language":"Английский","audioUrl":"/nte-meta/game-audio/510a56883a5f137053fb.ogg"},{"id":"ja-Play_Vo_Char_NPC010_chat_001","title":"Чат: бизнес","description":"Доход в этом месяце… выглядит не слишком многообещающим.","language":"Японский","audioUrl":"/nte-meta/game-audio/cf9b60ca1d55ff44d97a.ogg"},{"id":"ja-Play_Vo_Char_NPC010_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Я защищу тебя.","language":"Японский","audioUrl":"/nte-meta/game-audio/4a07585ed642ad05ae71.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_002","title":"Неожиданная добыча II","description":"Какой приятный сюрприз… кажется, сегодня будет отличный день.","language":"Японский","audioUrl":"/nte-meta/game-audio/f57e7dc3eac8c461851b.ogg"},{"id":"ko-Play_Vo_Char_NPC010_QTE_002","title":"Атака на входе II","description":"Закончим с этим побыстрее.","language":"Корейский","audioUrl":"/nte-meta/game-audio/84684befd85e357f2a54.ogg"},{"id":"en-Play_Vo_Char_NPC010_windfall_003","title":"Неожиданная добыча III","description":"Незнакомый предмет коллекции… нужно взять его с собой для подробного изучения.","language":"Английский","audioUrl":"/nte-meta/game-audio/ddf87ce49da412355749.ogg"},{"id":"ko-Play_Vo_Char_NPC010_talk_001","title":"Тема: аномалии","description":"Большинство Странностей на самом деле довольно дружелюбны… просто они не умеют выражать свои мысли и чувства, а может быть способы их выражения отличаются от привычных нам. Если будет возможность, попробуй пообщаться с ними. Возможно, перед тобой откроется абсолютно новый мир.","language":"Корейский","audioUrl":"/nte-meta/game-audio/026e50559467812b7fb6.ogg"},{"id":"en-Play_Vo_Char_NPC010_QTE_001","title":"Атака на входе I","description":"Продолжительные бои бесцельны.","language":"Английский","audioUrl":"/nte-meta/game-audio/260e6d0f71b0a516cab8.ogg"},{"id":"ko-Play_Vo_Char_NPC010_deploy_001","title":"Отправка II","description":"Чем я могу вам помочь?","language":"Корейский","audioUrl":"/nte-meta/game-audio/2c559c9c4934151f51c2.ogg"},{"id":"voice-1mv2h3f","title":"О Хотори","description":"У госпожи столько забот… Стыдно признаться, но я могу помочь ей только с повседневными делами, хотя для меня честь взять на себя даже малую часть её ответственности.","language":"Английский","audioUrl":"/nte-meta/game-audio/b460900d1e83de9cbf48.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_vexation_001","title":"Проблемы","description":"Проблемы? Магазин работает в убыток, госпожа купила очередную подделку под антиквариат, а махинации Наналли приводят к нам на порог разъяренных соседей. От всего этого у меня голова болит, но больше всего меня беспокоит то, как все пренебрегают своим благополучием. Как дворецкий «Эйбона» я уделяю особое внимание таким вопросам.","language":"Английский","audioUrl":"/nte-meta/game-audio/9285b56ee3adddc9b8a1.ogg"},{"id":"zh-Play_Vo_Char_NPC010_hp_003","title":"Низкий уровень здоровья III","description":"Пожалуйста, держись за моей спиной.","language":"Китайский","audioUrl":"/nte-meta/game-audio/9ee627d8eb2c1049209f.ogg"},{"id":"en-Play_Vo_Char_NPC010_struck_001","title":"Урон I","description":"Моя ошибка.","language":"Английский","audioUrl":"/nte-meta/game-audio/3cbd6ba96e04d48b853b.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Parry_001","title":"Парирование I","description":"Хороший выбор.","language":"Японский","audioUrl":"/nte-meta/game-audio/1ec1dfa45b7847b85975.ogg"},{"id":"ja-Play_Vo_Char_NPC010_self_003","title":"Обо мне: очки","description":"Эти очки? Наналли купила их мне с первой зарплаты от поручений после того, как присоединилась к команде «Эйбона». Сияя от восторга, она заявила: «Вот как одеваются благородные бандиты в кино!» Она так радовалась, что я не мог не принять этот уникальный жест. Что касается её пары… она подобрала их, чтобы воплотить стиль… «босса Ити-дайме»? Такие подарки вполне в духе Наналли.","language":"Японский","audioUrl":"/nte-meta/game-audio/6ed8daef1fa151c500c0.ogg"},{"id":"ja-Play_Vo_Char_NPC010_windfall_004","title":"Неожиданная добыча IV","description":"Похоже, в этом месяце мы получим прибыль.","language":"Японский","audioUrl":"/nte-meta/game-audio/18dcc020c1b343de67a1.ogg"},{"id":"ko-Play_Vo_Char_NPC010_struck_001","title":"Урон I","description":"Моя ошибка.","language":"Корейский","audioUrl":"/nte-meta/game-audio/306dd2eb54d03e2bb5d4.ogg"},{"id":"zh-Play_Vo_Char_NPC010_aoe_UI_001","title":"Сверхспособность I","description":"Все, что имеет форму, нереально.","language":"Китайский","audioUrl":"/nte-meta/game-audio/8d37548d8c880dfa9c7a.ogg"},{"id":"zh-Play_Vo_Char_NPC010_SSC_005","title":"Особое переключение — Даффодил","description":"Смена меняется. Хорошая работа.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b77af60521031d78660d.ogg"},{"id":"zh-Play_Vo_Char_NPC010_struck_002","title":"Урон II","description":"Осторожнее.","language":"Китайский","audioUrl":"/nte-meta/game-audio/ac9b6aeca930a4dc116a.ogg"},{"id":"voice-1oli6ym","title":"Спокойной ночи","description":"Для поддержания хорошего здоровья необходимо высыпаться… Конечно, если ты захочешь ещё поболтать, я всегда к твоим услугам.","language":"Английский","audioUrl":"/nte-meta/game-audio/8cc6ebe2062ae1d856a7.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_kill_001","title":"Убийство I","description":"Ты в порядке?","language":"Английский","audioUrl":"/nte-meta/game-audio/d863ba9b2019e0de9898.ogg"},{"id":"ja-Play_Vo_Char_NPC010_greet_001","title":"Утреннее приветствие","description":"Доброе утро. Как прошёл отдых? Завтрак уже готов.","language":"Японский","audioUrl":"/nte-meta/game-audio/92829092c16f1c2cead1.ogg"},{"id":"ko-Play_Vo_Char_NPC010_ug_003","title":"Вознесение персонажа III","description":"Памятный момент.","language":"Корейский","audioUrl":"/nte-meta/game-audio/88f3ac881ba29e27a7e8.ogg"},{"id":"en-Play_Vo_Char_NPC010_deploy_002","title":"Отправка I","description":"Полезно немного потренироваться.","language":"Английский","audioUrl":"/nte-meta/game-audio/58f9374d18e7292622e3.ogg"},{"id":"en-Play_Vo_Char_NPC010_Parry_002","title":"Парирование II","description":"Все то же мастерство.","language":"Английский","audioUrl":"/nte-meta/game-audio/ad9bf2edc271fa88aab8.ogg"},{"id":"en-Play_Vo_Char_NPC010_ug_002","title":"Вознесение персонажа II","description":"Никогда не перестану совершенствоваться.","language":"Английский","audioUrl":"/nte-meta/game-audio/cc3a329cde57a054b548.ogg"},{"id":"ja-Play_Vo_Char_NPC010_TeammateDown_005","title":"Поражен товарищ по команде – Даффодил","description":"Даффодил, спасибо за усердную работу.","language":"Японский","audioUrl":"/nte-meta/game-audio/15ad0297d713025e60ce.ogg"},{"id":"ko-Play_Vo_Char_NPC010_dead_002","title":"Потеря сознания II","description":"Пожалуйста… позаботься о них…","language":"Корейский","audioUrl":"/nte-meta/game-audio/c21247eb4ff6319ee1de.ogg"},{"id":"ko-Play_Vo_Char_NPC010_SSC_001","title":"Особое переключение — Хотори","description":"Я с этим разберусь, госпожа.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6d6e9cd271ed27af36de.ogg"},{"id":"zh-Play_Vo_Char_NPC010_gift_004","title":"Подарок получен IV","description":"Я буду дорожить этим подарком и тем, сколько сил вы в него вложили.","language":"Китайский","audioUrl":"/nte-meta/game-audio/85c9558c196ad88e59c4.ogg"},{"id":"en-Play_Vo_Char_NPC010_Switch_002","title":"Переключение II","description":"Хорошо, что я не опоздал.","language":"Английский","audioUrl":"/nte-meta/game-audio/eddd2bd3e1fcd7494e12.ogg"},{"id":"ja-Play_Vo_Char_NPC010_hp_003","title":"Низкий уровень здоровья III","description":"Пожалуйста, держись за моей спиной.","language":"Японский","audioUrl":"/nte-meta/game-audio/4245fe33295f62ac3488.ogg"},{"id":"ko-Play_Vo_Char_NPC010_QTE_001","title":"Атака на входе I","description":"Продолжительные бои бесцельны.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4810cfb98444b88b0d1b.ogg"},{"id":"ko-Play_Vo_Char_NPC010_Switch_003","title":"Переключение III","description":"Я тебя не подведу!","language":"Корейский","audioUrl":"/nte-meta/game-audio/283e102c8e9078a64e93.ogg"},{"id":"ko-Play_Vo_Char_NPC010_TeammateDown_003","title":"Поражен товарищ по команде – Сакири","description":"Даже Кирумару нужно время, чтобы все переварить.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6d785850189ffc4ea68f.ogg"},{"id":"zh-Play_Vo_Char_NPC010_aoe_UI_003","title":"Сверхспособность III","description":"Желаю тебе обрести вечный покой.","language":"Китайский","audioUrl":"/nte-meta/game-audio/ef4662fcee1a2aa927d8.ogg"},{"id":"zh-Play_Vo_Char_NPC010_dead_001","title":"Потеря сознания I","description":"Мы можем пойти… дальше…","language":"Китайский","audioUrl":"/nte-meta/game-audio/2de6c1c519449f31bd28.ogg"},{"id":"zh-Play_Vo_Char_NPC010_dead_003","title":"Потеря сознания III","description":"Прости, что разочаровал.","language":"Китайский","audioUrl":"/nte-meta/game-audio/6c7f51f8700438970351.ogg"},{"id":"zh-Play_Vo_Char_NPC010_weather_004","title":"Жарко","description":"Не следует слишком сильно охлаждаться в жару… может заболеть живот, что очень неприятно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/68f57b2cc5cfe8f67e94.ogg"},{"id":"en-Play_Vo_Char_NPC010_gift_004","title":"Подарок получен IV","description":"Я буду дорожить этим подарком и тем, сколько сил вы в него вложили.","language":"Английский","audioUrl":"/nte-meta/game-audio/b4f44419cdb960d9617a.ogg"},{"id":"ko-Play_Vo_Char_NPC010_windfall_002","title":"Неожиданная добыча II","description":"Какой приятный сюрприз… кажется, сегодня будет отличный день.","language":"Корейский","audioUrl":"/nte-meta/game-audio/825e23d3bf1abfb8608f.ogg"},{"id":"zh-Play_Vo_Char_NPC010_Parry_001","title":"Парирование I","description":"Хороший выбор.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c24d049d3ec7914b2c83.ogg"},{"id":"zh-Play_Vo_Char_NPC010_windfall_004","title":"Неожиданная добыча IV","description":"Похоже, в этом месяце мы получим прибыль.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f3e9b3f74e1bfb69df82.ogg"},{"id":"en-Play_Vo_Char_NPC010_DodgeCombo_002","title":"Серия критических уклонений II","description":"Терпение важнее спешки.","language":"Английский","audioUrl":"/nte-meta/game-audio/b77020c42024628f22c6.ogg"},{"id":"ko-Play_Vo_Char_NPC010_hstruck_001","title":"Сильный урон I","description":"Это может обернуться неприятностями.","language":"Корейский","audioUrl":"/nte-meta/game-audio/90dd30abba3ff797a727.ogg"},{"id":"zh-Play_Vo_Char_NPC010_SSC_004","title":"Особое переключение — Эдгар","description":"Мне обслужить твои компьютерные детали?","language":"Китайский","audioUrl":"/nte-meta/game-audio/57d1f49bece3434f3a45.ogg"},{"id":"ja-Play_Vo_Char_NPC010_skill_003","title":"Навык перенаправления III","description":"Осмысли.","language":"Японский","audioUrl":"/nte-meta/game-audio/b1293d3dd8bd2e8b9413.ogg"},{"id":"zh-Play_Vo_Char_NPC010_windfall_002","title":"Неожиданная добыча II","description":"Какой приятный сюрприз… кажется, сегодня будет отличный день.","language":"Китайский","audioUrl":"/nte-meta/game-audio/ed4c40485a2c6eec4ed1.ogg"},{"id":"zh-Play_Vo_Char_NPC010_windfall_006","title":"Неожиданная добыча VI","description":"Хорошее качество. Это мы оставим себе.","language":"Китайский","audioUrl":"/nte-meta/game-audio/763ee829df39917dc63d.ogg"},{"id":"voice-14zv6l0","title":"Об антикварном магазине «Эйбон»","description":"«Эйбон» не всегда был таким оживленным. Когда мы только поселились на улице Ханкаку, всё было довольно уныло. Сакири почти не разговаривала, а госпожа и Даффодил решали проблемы с утра до ночи. Ситуация изменилась, когда мы нашли Тайгедо, и ещё больше — с появлением Наналли и Эдгара. Магазин наполнился теплом и смехом. Теперь, когда ты с нами, «Эйбон» стал для нас настоящим домом.","language":"Английский","audioUrl":"/nte-meta/game-audio/d566884d73c56cbe26d7.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"voice-15ui49k","title":"Вечернее приветствие","description":"Эй, расслабься. Сейчас свободное время, клиенты, как правило, не приходят в эти часы.","language":"Английский","audioUrl":"/nte-meta/game-audio/7a5747eabc0aea0cfd7c.ogg","sourceUrl":"https://neverness-to-everness.fandom.com/api.php?action=query&generator=images&gimlimit=max&prop=imageinfo&iiprop=url|mime|size&format=json&formatversion=2&titles=Adler%2FVoice-Overs&origin=*"},{"id":"en-Play_Vo_Char_NPC010_Parry_001","title":"Парирование I","description":"Хороший выбор.","language":"Английский","audioUrl":"/nte-meta/game-audio/bd82f7c7353875aee3c1.ogg"},{"id":"ko-Play_Vo_Char_NPC010_windfall_003","title":"Неожиданная добыча III","description":"Незнакомый предмет коллекции… нужно взять его с собой для подробного изучения.","language":"Корейский","audioUrl":"/nte-meta/game-audio/cd29a14803d1671dc397.ogg"},{"id":"ja-Play_Vo_Char_NPC010_Switch_002","title":"Переключение II","description":"Хорошо, что я не опоздал.","language":"Японский","audioUrl":"/nte-meta/game-audio/fa873140f832a822550a.ogg"},{"id":"ko-Play_Vo_Char_NPC010_about_003","title":"О Сакири","description":"Сакири не очень хорошо выражает свои чувства. Для такой чувствительной натуры, как она, поступки говорят громче слов. Она действительно переживает, но не показывает этого. Чтобы постепенно раскрыться, ей нужно личное пространство.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d8af46d9dc12c2af939a.ogg"},{"id":"ko-Play_Vo_Char_NPC010_chat_002","title":"Чат: списки","description":"Выпивка, конфеты, манга, игровые картриджи, антикоррозийное масло… да, это все.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6f9fb1ce2e9b5c796db1.ogg"},{"id":"ko-Play_Vo_Char_NPC010_hstruck_002","title":"Сильный урон II","description":"Непростая ситуация.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5f4e20fe55cce0ad6222.ogg"},{"id":"zh-Play_Vo_Char_NPC010_fh_002","title":"Исцеление II","description":"Все хорошо.","language":"Китайский","audioUrl":"/nte-meta/game-audio/587e60dea03210a01401.ogg"},{"id":"zh-Play_Vo_Char_NPC010_self_004","title":"Обо мне: стремление к идеалу","description":"Мастер на все руки… Слишком громкое слово. Я всего лишь немного старше и видел чуть больше людей и событий. Когда я был в возрасте Наналли и остальных, по энергии и смелости я им и в подмётки не годился.","language":"Китайский","audioUrl":"/nte-meta/game-audio/417cd6c9a7bc7e45fcbc.ogg"},{"id":"zh-Play_Vo_Char_NPC010_ug_001","title":"Вознесение персонажа I","description":"Учение не знает границ.","language":"Китайский","audioUrl":"/nte-meta/game-audio/411534811d4a411f1edd.ogg"},{"id":"zh-Play_Vo_Char_NPC010_windfall_005","title":"Неожиданная добыча V","description":"Как насчет устроить сегодня особенный ужин?","language":"Китайский","audioUrl":"/nte-meta/game-audio/a39f454cac126008212a.ogg"},{"id":"en-Play_Vo_Char_NPC010_about_004","title":"Об Эдгаре","description":"Необщительность — необязательно плохо. У каждого свой стиль жизни, и сам Эдгар не страдает от сложностей в общении с другими людьми, что не может не радовать. К тому же, рядом с ним всегда Сакири и Наналли, которые понимают его лучше всего и всегда готовы его выслушать.","language":"Английский","audioUrl":"/nte-meta/game-audio/130e822647dcde0b3248.ogg"},{"id":"en-Play_Vo_Char_NPC010_fh_002","title":"Исцеление II","description":"Все хорошо.","language":"Английский","audioUrl":"/nte-meta/game-audio/047a532aea6616aec05b.ogg"},{"id":"en-Play_Vo_Char_NPC010_hp_001","title":"Низкий уровень здоровья I","description":"Это неожиданно.","language":"Английский","audioUrl":"/nte-meta/game-audio/dbb2ccdc08be8adfe788.ogg"},{"id":"en-Play_Vo_Char_NPC010_windfall_004","title":"Неожиданная добыча IV","description":"Похоже, в этом месяце мы получим прибыль.","language":"Английский","audioUrl":"/nte-meta/game-audio/3bd880ea58b3975cf94a.ogg"},{"id":"en-Play_Vo_Char_NPC010_windfall_005","title":"Неожиданная добыча V","description":"Как насчет устроить сегодня особенный ужин?","language":"Английский","audioUrl":"/nte-meta/game-audio/a7ce427dc0c90cba4439.ogg"},{"id":"ja-Play_Vo_Char_NPC010_QTE_003","title":"Атака на входе III","description":"Все это лишь иллюзия.","language":"Японский","audioUrl":"/nte-meta/game-audio/5da703c5632edb32b8ac.ogg"},{"id":"ja-Play_Vo_Char_NPC010_skill_001","title":"Навык перенаправления I","description":"Озари.","language":"Японский","audioUrl":"/nte-meta/game-audio/98b6be1c272eb3899614.ogg"},{"id":"ko-Play_Vo_Char_NPC010_Fly_002","title":"Планирование II","description":"Очень удобный способ путешествовать.","language":"Корейский","audioUrl":"/nte-meta/game-audio/deee1e476ca469fbd20c.ogg"}]'))) WHERE character_id='adler' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:18:27');

UPDATE character_profiles SET abilities_json=json('[{"id":"ability-1m6y4tw","name":"Избавление","type":"Базовая атака","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Adler_Melee.png","description":"Базовая атака: Избавление\n\nПроводит до 5 последовательных атак подряд своим оружием, нанося урон от чар.\n\nБазовая атака: Освобождение\n\nПереходит в режим прицеливания и наносит 1 экземпляр урона от чар одному противнику в прицеле.\n\nБазовая атака: Невежество\n\nПикирует, нанося 1 экземпляр урона от чар по области при ударе. Урон увеличивается в зависимости от высоты падения (до 100 %).\n\nКритический контрудар: откровение\n\nАктивируется при использовании «Избавления» после срабатывания критического уклонения. Уклоняется от атаки быстрым рывком, ловит момент и наносит быстрый удар оружием, нанося 1 экземпляр урона от чар по области, снижая показатель разрушения цели.\n\nКарма\n\nДает Адлеру 1 уровень кармы, когда Избавление или Невежество поражает врага.\n\nДает Адлеру 2 уровня кармы, когда Освобождение поражает врага.\n\nМакс. уровней кармы: 20.\n\nТрость – весьма подходящий аксессуар. Оружие джентльмена.","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 20.1 % · 2: 21.7 % · 3: 23.4 % · 4: 25.3 % · 5: 27.3 % · 6: 29.5 % · 7: 31.9 % · 8: 34.4 % · 9: 37.2 % · 10: 40.2 % · 11: 43.4 % · 12: 46.9 % · 13: 50.6 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 57.7 % · 2: 62.3 % · 3: 67.3 % · 4: 72.7 % · 5: 78.5 % · 6: 84.8 % · 7: 91.6 % · 8: 98.9 % · 9: 106.8 % · 10: 115.3 % · 11: 124.6 % · 12: 134.5 % · 13: 145.3 %"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 15.4 %*2 · 2: 16.6 %*2 · 3: 18 %*2 · 4: 19.4 %*2 · 5: 21 %*2 · 6: 22.6 %*2 · 7: 24.4 %*2 · 8: 26.4 %*2 · 9: 28.5 %*2 · 10: 30.8 %*2 · 11: 33.2 %*2 · 12: 35.9 %*2 · 13: 38.8 %*2"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 21.9 %+23.1 %+74.6 % · 2: 23.7 %+24.9 %+80.6 % · 3: 25.5 %+26.9 %+87 % · 4: 27.6 %+29.1 %+94 % · 5: 29.8 %+31.4 %+101.5 % · 6: 32.2 %+33.9 %+109.6 % · 7: 34.8 %+36.7 %+118.4 % · 8: 37.5 %+39.6 %+127.9 % · 9: 40.5 %+42.8 %+138.1 % · 10: 43.8 %+46.2 %+149.1 % · 11: 47.3 %+49.9 %+161.1 % · 12: 51.1 %+53.9 %+173.9 % · 13: 55.1 %+58.2 %+187.9 %"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 87.5 % · 2: 94.5 % · 3: 102.1 % · 4: 110.2 % · 5: 119 % · 6: 128.6 % · 7: 138.9 % · 8: 150 % · 9: 162 % · 10: 174.9 % · 11: 188.9 % · 12: 204 % · 13: 220.3 %"},{"id":"parameter-5","label":"Множитель урона заряженной атаки","value":"1: 10.4 % · 2: 11.2 % · 3: 12.1 % · 4: 13.1 % · 5: 14.1 % · 6: 15.3 % · 7: 16.5 % · 8: 17.8 % · 9: 19.2 % · 10: 20.8 % · 11: 22.5 % · 12: 24.2 % · 13: 26.2 %"},{"id":"parameter-6","label":"Множитель урона атаки в падении","value":"1: 36 % · 2: 38.9 % · 3: 42 % · 4: 45.3 % · 5: 49 % · 6: 52.9 % · 7: 57.1 % · 8: 61.7 % · 9: 66.6 % · 10: 72 % · 11: 77.7 % · 12: 83.9 % · 13: 90.7 %"},{"id":"parameter-7","label":"Множитель урона контратаки после критического уклонения","value":"1: 176 % · 2: 190.1 % · 3: 205.3 % · 4: 221.7 % · 5: 239.4 % · 6: 258.6 % · 7: 279.3 % · 8: 301.6 % · 9: 325.8 % · 10: 351.8 % · 11: 380 % · 12: 410.4 % · 13: 443.2 %"}]},{"id":"ability-1i6khf1","name":"Проклятие зла","type":"Навык","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Adler_Skill.png","description":"Нужна помощь? Адлер призывает фантомов Суньи для атаки врагов, нанося 1 экземпляр урона от чар по области, а затем накладывает на противников эффект периодического урона от чар и наделяет активных персонажей щитом с Благословением.\n\nТратит все уровни Кармы при использовании навыка. Каждый потраченный уровень увеличивает урон от навыка Адлера на 2 %.\n\n«Это поручение… надо сначала познакомиться с нашей целью. Мы…»\n\n«Колуччи! Выдвигаемся!»\n\n«Не высовывайся, а я займусь всем остальным».","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 70 % защиты*3 · 2: 75.6 % защиты*3 · 3: 81.6 % защиты*3 · 4: 88.2 % защиты*3 · 5: 95.2 % защиты*3 · 6: 102.9 % защиты*3 · 7: 111.1 % защиты*3 · 8: 120 % защиты*3 · 9: 129.6 % защиты*3 · 10: 139.9 % защиты*3 · 11: 151.1 % защиты*3 · 12: 163.2 % защиты*3 · 13: 176.3 % защиты*3"},{"id":"parameter-1","label":"Множитель периодического урона","value":"1: 20 % защиты · 2: 21.6 % защиты · 3: 23.3 % защиты · 4: 25.2 % защиты · 5: 27.2 % защиты · 6: 29.4 % защиты · 7: 31.7 % защиты · 8: 34.3 % защиты · 9: 37 % защиты · 10: 40 % защиты · 11: 43.2 % защиты · 12: 46.6 % защиты · 13: 50.4 % защиты"},{"id":"parameter-2","label":"Множитель щита","value":"1: 1000+80 % защиты · 2: 1080+86 % защиты · 3: 1166+93 % защиты · 4: 1260+100 % защиты · 5: 1361+108 % защиты · 6: 1470+117 % защиты · 7: 1587+126 % защиты · 8: 1714+137 % защиты · 9: 1851+148 % защиты · 10: 2000+159 % защиты · 11: 2160+172 % защиты · 12: 2332+186 % защиты · 13: 2519+201 % защиты"},{"id":"parameter-3","label":"Длительность периодического урона","value":"1: 10 сек. · 2: 10 сек. · 3: 10 сек. · 4: 10 сек. · 5: 10 сек. · 6: 10 сек. · 7: 10 сек. · 8: 10 сек. · 9: 10 сек. · 10: 10 сек. · 11: 10 сек. · 12: 10 сек. · 13: 10 сек."},{"id":"parameter-4","label":"Интервал периодического урона","value":"1: 1 сек. · 2: 1 сек. · 3: 1 сек. · 4: 1 сек. · 5: 1 сек. · 6: 1 сек. · 7: 1 сек. · 8: 1 сек. · 9: 1 сек. · 10: 1 сек. · 11: 1 сек. · 12: 1 сек. · 13: 1 сек."},{"id":"parameter-5","label":"Длительность щита","value":"1: 8 сек. · 2: 8 сек. · 3: 8 сек. · 4: 8 сек. · 5: 8 сек. · 6: 8 сек. · 7: 8 сек. · 8: 8 сек. · 9: 8 сек. · 10: 8 сек. · 11: 8 сек. · 12: 8 сек. · 13: 8 сек."}]},{"id":"ability-1inhugo","name":"Спокойствие","type":"Сверхспособность","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Adler_UltraSkill.png","description":"Хотелось бы обойтись без боя… Адлер призывает Рупу, Ведану, Санну, Виннану и Санкхару — всего 5 сунья, — чтобы атаковать всех врагов. Каждая цель получает 5 экземпляров урона от чар. Если на поле боя остается только один противник, сунья проводят вторую атаку, нанося в сумме 10 экземпляров урона от чар.\n\nВ «Эйбоне» любят угадывать имена cунья Адлера. Те, кто угадывает правильно, получают от Адлера десерты ручной работы!","attributes":[{"id":"parameter-0","label":"Множитель урона за удар","value":"1: 100 % защиты · 2: 108 % защиты · 3: 116.6 % защиты · 4: 126 % защиты · 5: 136 % защиты · 6: 146.9 % защиты · 7: 158.7 % защиты · 8: 171.4 % защиты · 9: 185.1 % защиты · 10: 199.9 % защиты · 11: 215.9 % защиты · 12: 233.2 % защиты · 13: 251.8 % защиты"}]},{"id":"ability-7ny4ug","name":"Идеальное отражение","type":"Навык поддержки","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Adler_QTE.png","description":"Этот бой нельзя больше затягивать. Прицелиться и выпустить 1 компрессионный заряд по врагу, который при попадании наносит 1 экземпляр урона от чар по области.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"ability-1w2as9b","name":"Умеренность","type":"Пассивный навык","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Adler_Pas1.png","description":"Усиление ожога: При каждом срабатывании «Ожога» на цель накладывается одно из трёх случайных ослаблений: −20 % атаки, -10 % сопротивляемости эсперам или +10 % к эффективности разрушения. Действует 15 сек., эффекты не складываются.\n\nТщательно отглаженная форма и идеально уложенные волосы даже в бою. Первый урок дворецкого – поддерживать безупречный внешний вид.","attributes":[]},{"id":"ability-1eojm57","name":"Праведное сердце","type":"Пассивный навык","iconUrl":"https://interactivemap.app/neverness-to-everness/database/assets/skills/Adler_Pas2.png","description":"+20 % к защите Адлера\n\n«Иногда тактика силы предпочтительнее длительных переговоров».","attributes":[]},{"id":"daabeaa1-c9c5-4c66-80a1-02822ac929cd","name":"Кофейный мастер","type":"Повседневный навык","iconUrl":"/nte-meta/game-assets/24ca96ea1e7934e5cf5a.webp","description":"Адлер дополнительно увеличивает цены блюд на 0,12 фонса.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Адлер дополнительно увеличивает цены блюд на 0,12 фонса."},{"id":"city-1","label":"Уровень 2","value":"Адлер снижает скорость расхода ингредиентов на 1 %."},{"id":"city-2","label":"Уровень 3","value":"В режиме подборки владельца кофе готовится автоматически."},{"id":"city-3","label":"Уровень 4","value":"Адлер снижает скорость расхода ингредиентов на 1 %."},{"id":"city-4","label":"Уровень 5","value":"Адлер дополнительно увеличивает цены блюд на 0,18 фонса."}]}]') WHERE character_id='adler' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:18:27');

UPDATE character_profiles SET updated_at=CURRENT_TIMESTAMP WHERE character_id='adler' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:18:27');

UPDATE character_profiles SET voice_actors_json=json('[{"language":"Китайский","name":"陈怡萱"},{"language":"Английский","name":"Cristina Vee"},{"language":"Японский","name":"長谷川育美"},{"language":"Корейский","name":"김하루"},{"language":"Китайский","name":"Chen Yixuan (陈怡萱)"},{"language":"Японский","name":"Ikumi Hasegawa (長谷川 育美)"},{"language":"Корейский","name":"Kim Ha-ru (김하루)"}]') WHERE character_id='akane' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 16:33:23');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"zh-Play_Vo_Char_NPC023_Parry_001","title":"Парирование I","description":"Не мой темп!","language":"Китайский","audioUrl":"/nte-meta/game-audio/dc59239ecefbaaa3ff84.ogg"},{"id":"en-Play_Vo_Char_NPC023_Parry_001","title":"Парирование I","description":"Не мой темп!","language":"Английский","audioUrl":"/nte-meta/game-audio/4f3784d08b4c52c29b23.ogg"},{"id":"en-Play_Vo_Char_NPC023_SSC_HY_001","title":"Особое переключение: Аурелия","description":"Как в старые добрые времена, подруга.","language":"Английский","audioUrl":"/nte-meta/game-audio/18a1a664f22164c02716.ogg"},{"id":"ja-Play_Vo_Char_NPC023_skill_003","title":"Навык перенаправления III","description":"Рок-н-ролл!","language":"Японский","audioUrl":"/nte-meta/game-audio/3036e1abfb19838054f2.ogg"},{"id":"ko-Play_Vo_Char_NPC023_chat_002","title":"Чат: подработка","description":"Люди спрашивают обо всём подряд. Многие просят меня поделиться советами для хорошего выступления. На самом деле таких просьб стало настолько много, что теперь я сначала прошу купить мне попить, а уже потом задавать вопросы. Хм… Киесаве стоит прибавить мне зарплату.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ccca4125019d631f6dc1.ogg"},{"id":"en-Play_Vo_Char_NPC023_deploy_002","title":"Отправка II","description":"А где аплодисменты?","language":"Английский","audioUrl":"/nte-meta/game-audio/92f60c875b50c71f4a1f.ogg"},{"id":"en-Play_Vo_Char_NPC023_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Лучший дуэт!","language":"Английский","audioUrl":"/nte-meta/game-audio/e40d079928627624a6d6.ogg"},{"id":"ja-Play_Vo_Char_NPC023_DodgeCombo_001","title":"Серия критических уклонений I","description":"Сможешь поспеть за моим ритмом?","language":"Японский","audioUrl":"/nte-meta/game-audio/e111a08947f328b4b527.ogg"},{"id":"zh-Play_Vo_Char_NPC023_hp_002","title":"Низкий уровень здоровья II","description":"Мой голос… слабеет…","language":"Китайский","audioUrl":"/nte-meta/game-audio/ad9835c198616a418437.ogg"},{"id":"en-Play_Vo_Char_NPC023_SSC_NNL_001","title":"Особое переключение — Наналли","description":"Твоё соло закончилось. Держи ритм.","language":"Английский","audioUrl":"/nte-meta/game-audio/3dc1e376b11254eff4b2.ogg"},{"id":"en-Play_Vo_Char_NPC023_windfall_002","title":"Неожиданная добыча II","description":"Неплохо. Теперь это моё.","language":"Английский","audioUrl":"/nte-meta/game-audio/784e22a8fc990a10174d.ogg"},{"id":"ja-Play_Vo_Char_NPC023_Fly_002","title":"Планирование II","description":"Кажется, я могу парить где угодно.","language":"Японский","audioUrl":"/nte-meta/game-audio/207359a23f90df2b9dfc.ogg"},{"id":"ja-Play_Vo_Char_NPC023_ug_001","title":"Вознесение персонажа I","description":"Восходящая гамма!","language":"Японский","audioUrl":"/nte-meta/game-audio/9dafecf097cd2d2f6a7e.ogg"},{"id":"ko-Play_Vo_Char_NPC023_gift_002","title":"Подарок получен II","description":"Какой подарок — просто прелесть… Буду бережно хранить его в своей витрине.","language":"Корейский","audioUrl":"/nte-meta/game-audio/646baf2248cb34f1ccb5.ogg"},{"id":"ko-Play_Vo_Char_NPC023_SSC_NNL_001","title":"Особое переключение — Наналли","description":"Твоё соло закончилось. Держи ритм.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1c0f8ba6f6c6bb8ea6e0.ogg"},{"id":"zh-Play_Vo_Char_NPC023_ug_001","title":"Вознесение персонажа I","description":"Восходящая гамма!","language":"Китайский","audioUrl":"/nte-meta/game-audio/4b3f1da36ef62a6cc6aa.ogg"},{"id":"en-Play_Vo_Char_NPC023_windfall_004","title":"Неожиданная добыча IV","description":"Я буду бережно его хранить.","language":"Английский","audioUrl":"/nte-meta/game-audio/f5d12ee76ebcb4aee715.ogg"},{"id":"ja-Play_Vo_Char_NPC023_chat_002","title":"Чат: подработка","description":"Люди спрашивают обо всём подряд. Многие просят меня поделиться советами для хорошего выступления. На самом деле таких просьб стало настолько много, что теперь я сначала прошу купить мне попить, а уже потом задавать вопросы. Хм… Киесаве стоит прибавить мне зарплату.","language":"Японский","audioUrl":"/nte-meta/game-audio/511a8bd20e90dc6e226f.ogg"},{"id":"ja-Play_Vo_Char_NPC023_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Лучший дуэт!","language":"Японский","audioUrl":"/nte-meta/game-audio/a7cf830ea09bb8e77cc3.ogg"},{"id":"ko-Play_Vo_Char_NPC023_kill_002","title":"Убийство II","description":"Шоу окончено.","language":"Корейский","audioUrl":"/nte-meta/game-audio/0058a7475c95ef5a849b.ogg"},{"id":"zh-Play_Vo_Char_NPC023_gift_003","title":"Подарок получен III","description":"Для меня? Спасибо. Мне очень нравится.","language":"Китайский","audioUrl":"/nte-meta/game-audio/ed8db60d98dddc2ae6b3.ogg"},{"id":"en-Play_Vo_Char_NPC023_kill_001","title":"Убийство I","description":"Эта песня для тебя.","language":"Английский","audioUrl":"/nte-meta/game-audio/b6e76a9b30cfb79cbeb3.ogg"},{"id":"en-Play_Vo_Char_NPC023_kill_002","title":"Убийство II","description":"Шоу окончено.","language":"Английский","audioUrl":"/nte-meta/game-audio/ecf035c65f8e3ab60ad4.ogg"},{"id":"en-Play_Vo_Char_NPC023_QTE_001","title":"Атака на входе I","description":"Пора на новый лад!","language":"Английский","audioUrl":"/nte-meta/game-audio/32fb95fb40a750a2fee7.ogg"},{"id":"en-Play_Vo_Char_NPC023_self_001","title":"Обо мне: способности эспера","description":"Когда меня переполняют сильные чувства, стоит мне перебрать струны — и из кончиков пальцев вылетают белые звёзды. Круто, правда? А как это работает… понятия не имею, да и выяснять не собираюсь. Только представь: когда я полностью отдаюсь выступлению, у меня прямо встроенные спецэффекты. И выглядят они просто нереально.","language":"Английский","audioUrl":"/nte-meta/game-audio/a592fecedb3e586e0105.ogg"},{"id":"en-Play_Vo_Char_NPC023_self_003","title":"Обо мне: «Девушка-оркестр»","description":"Я одна заменяю целую группу…? Это уже преувеличение. Тебе ведь Аурелия или Судзуха это рассказали, да? Ну, вообще-то правда, что я систематически освоила все основные инструменты, нужные в группе. В детстве я училась играть на них, потому что мне нравилось, как они звучат. А после того, как мы создали группу, мне хотелось лучше понимать, чем занимается каждый, чтобы вместе справляться с любыми трудностями… Вот так мы и остаёмся в одной тональности.","language":"Английский","audioUrl":"/nte-meta/game-audio/e62efb7fdcb125f73eb8.ogg"},{"id":"en-Play_Vo_Char_NPC023_Switch_003","title":"Переключение III","description":"Зажжём!","language":"Английский","audioUrl":"/nte-meta/game-audio/8d43ad3410328f74e722.ogg"},{"id":"en-Play_Vo_Char_NPC023_windfall_001","title":"Неожиданная добыча I","description":"Повезло мне.","language":"Английский","audioUrl":"/nte-meta/game-audio/8930f235843fd0aaa100.ogg"},{"id":"ja-Play_Vo_Char_NPC023_windfall_004","title":"Неожиданная добыча IV","description":"Я буду бережно его хранить.","language":"Японский","audioUrl":"/nte-meta/game-audio/5fec9b2c51c330f4a977.ogg"},{"id":"ja-Play_Vo_Char_NPC023_windfall_005","title":"Неожиданная добыча V","description":"Маленькие радости жизни.","language":"Японский","audioUrl":"/nte-meta/game-audio/eb54f1c7a118e82fc90c.ogg"},{"id":"ko-Play_Vo_Char_NPC023_skill_001","title":"Навык перенаправления I","description":"Громче!","language":"Корейский","audioUrl":"/nte-meta/game-audio/e86d900b834249d0d970.ogg"},{"id":"en-Play_Vo_Char_NPC023_greet_002","title":"Дневное приветствие","description":"Не хочу сегодня есть на работе. Давай лучше перекусим чем-нибудь вкусненьким. Я угощаю.","language":"Английский","audioUrl":"/nte-meta/game-audio/31694ba90ffe40e6cae2.ogg"},{"id":"en-Play_Vo_Char_NPC023_skill_001","title":"Навык перенаправления I","description":"Громче!","language":"Английский","audioUrl":"/nte-meta/game-audio/496196954cd29d91a852.ogg"},{"id":"zh-Play_Vo_Char_NPC023_chat_001","title":"Чат: костюмы","description":"Я не особо слежу за модой. Если бы мне не нужно было выступать на сцене, я бы всегда ходила в повседневной одежде.","language":"Китайский","audioUrl":"/nte-meta/game-audio/1b8253f2d9836ddcfbf0.ogg"},{"id":"zh-Play_Vo_Char_NPC023_containment_001","title":"Сдерживание I","description":"Новый фанат.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0a453b7620a07308d30a.ogg"},{"id":"en-Play_Vo_Char_NPC023_fh_001","title":"Исцеление I","description":"Снова на сцену!","language":"Английский","audioUrl":"/nte-meta/game-audio/d38540f9acdb3db3e285.ogg"},{"id":"zh-Play_Vo_Char_NPC023_weather_001","title":"Солнечно","description":"Какая хорошая погода. Я слишком много времени провожу в «Звёздном знаке». Мне бы не помешало иногда выходить на улицу.","language":"Китайский","audioUrl":"/nte-meta/game-audio/454cd2d98bfd2e3671b9.ogg"},{"id":"en-Play_Vo_Char_NPC023_SSC_HNY_001","title":"Особое переключение — Ханиэль","description":"Я сыграю этот сложный рифф.","language":"Английский","audioUrl":"/nte-meta/game-audio/180bd1cd7bf2960759ba.ogg"},{"id":"en-Play_Vo_Char_NPC023_Switch_002","title":"Переключение II","description":"Не терпится выйти на сцену!","language":"Английский","audioUrl":"/nte-meta/game-audio/6205953a4d98f9297986.ogg"},{"id":"en-Play_Vo_Char_NPC023_ug_001","title":"Вознесение персонажа I","description":"Восходящая гамма!","language":"Английский","audioUrl":"/nte-meta/game-audio/0ddba375ad95f88b474b.ogg"},{"id":"ja-Play_Vo_Char_NPC023_Parry_001","title":"Парирование I","description":"Не мой темп!","language":"Японский","audioUrl":"/nte-meta/game-audio/79c5b9c19c32a6deda52.ogg"},{"id":"zh-Play_Vo_Char_NPC023_talk_001","title":"Тема: моя первая гитара","description":"Моя первая гитара… папа подарил её мне, когда я окончила начальную школу. Я хорошо за ней ухаживаю. Она до сих пор отлично звучит. Время от времени я достаю её и играю простые гаммы.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d387463f7b2e24d7c686.ogg"},{"id":"zh-Play_Vo_Char_NPC023_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"Не надрывайся. Нам нужен каждый участник группы.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f72dc76a55d61d265f51.ogg"},{"id":"ja-Play_Vo_Char_NPC023_greet_004","title":"Спокойной ночи","description":"Спокойной ночи. Не засиживайся в телефоне перед сном.","language":"Японский","audioUrl":"/nte-meta/game-audio/07ec556cb1fbb8ba76d6.ogg"},{"id":"zh-Play_Vo_Char_NPC023_talk_002","title":"Тема: после работы","description":"О, ты тоже за жизнь без лишней суеты? В общем, делаешь только то, что действительно нужно, да и то попроще. Работа каждый день выматывает. Откуда у меня силы ещё и куда-то ходить? Гораздо лучше пораньше вернуться домой, врубить кондёр на полную и листать Bagel. Нынешняя молодёжь просто не понимает, какое это счастье — жить без суеты.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7f1051c01afbb3276dc4.ogg"},{"id":"en-Play_Vo_Char_NPC023_containment_001","title":"Сдерживание I","description":"Новый фанат.","language":"Английский","audioUrl":"/nte-meta/game-audio/0524e3f4840c6ab31c5b.ogg"},{"id":"ja-Play_Vo_Char_NPC023_anomaly_004","title":"Нуллификация II","description":"Фух… напоминает о былых временах.","language":"Японский","audioUrl":"/nte-meta/game-audio/e513bafaf28550078e27.ogg"},{"id":"ja-Play_Vo_Char_NPC023_talk_002","title":"Тема: после работы","description":"О, ты тоже за жизнь без лишней суеты? В общем, делаешь только то, что действительно нужно, да и то попроще. Работа каждый день выматывает. Откуда у меня силы ещё и куда-то ходить? Гораздо лучше пораньше вернуться домой, врубить кондёр на полную и листать Bagel. Нынешняя молодёжь просто не понимает, какое это счастье — жить без суеты.","language":"Японский","audioUrl":"/nte-meta/game-audio/63e54755f058925ac0b2.ogg"},{"id":"ja-Play_Vo_Char_NPC023_vexation_001","title":"Проблемы","description":"То покупаешь новую классную педаль эффектов, то на следующий день — новый альбом. Играя в группе, много фонсов не накопишь. Я уже давно живу от зарплаты до зарплаты.","language":"Японский","audioUrl":"/nte-meta/game-audio/ca75864530e1e50a15e8.ogg"},{"id":"ko-Play_Vo_Char_NPC023_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Лучший дуэт!","language":"Корейский","audioUrl":"/nte-meta/game-audio/9a3c206a1799ffd9a3d6.ogg"},{"id":"zh-Play_Vo_Char_NPC023_anomaly_004","title":"Нуллификация II","description":"Фух… напоминает о былых временах.","language":"Китайский","audioUrl":"/nte-meta/game-audio/35b52f03548e96732112.ogg"},{"id":"zh-Play_Vo_Char_NPC023_greet_001","title":"Утреннее приветствие","description":"(*Зевает*) Доброе утро… Ч-Что? Я вчера вечером тайком не репетировала! Честно…!","language":"Китайский","audioUrl":"/nte-meta/game-audio/8249e23da19e99b35c18.ogg"},{"id":"zh-Play_Vo_Char_NPC023_QTE_003","title":"Атака на входе III","description":"Как раз вовремя.","language":"Китайский","audioUrl":"/nte-meta/game-audio/daa4a7759a3aef7b164b.ogg"},{"id":"en-Play_Vo_Char_NPC023_talk_001","title":"Тема: моя первая гитара","description":"Моя первая гитара… папа подарил её мне, когда я окончила начальную школу. Я хорошо за ней ухаживаю. Она до сих пор отлично звучит. Время от времени я достаю её и играю простые гаммы.","language":"Английский","audioUrl":"/nte-meta/game-audio/59f23d74fcbcee8c2723.ogg"},{"id":"ja-Play_Vo_Char_NPC023_dead_002","title":"Потеря сознания II","description":"Звёзды померкли…","language":"Японский","audioUrl":"/nte-meta/game-audio/fa063160a599cc1bfb98.ogg"},{"id":"ko-Play_Vo_Char_NPC023_kill_001","title":"Убийство I","description":"Эта песня для тебя.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ce81178803be9d37328c.ogg"},{"id":"en-Play_Vo_Char_NPC023_talk_002","title":"Тема: после работы","description":"О, ты тоже за жизнь без лишней суеты? В общем, делаешь только то, что действительно нужно, да и то попроще. Работа каждый день выматывает. Откуда у меня силы ещё и куда-то ходить? Гораздо лучше пораньше вернуться домой, врубить кондёр на полную и листать Bagel. Нынешняя молодёжь просто не понимает, какое это счастье — жить без суеты.","language":"Английский","audioUrl":"/nte-meta/game-audio/f90c8d35e15b6cbdd740.ogg"},{"id":"zh-Play_Vo_Char_NPC023_gift_002","title":"Подарок получен II","description":"Какой подарок — просто прелесть… Буду бережно хранить его в своей витрине.","language":"Китайский","audioUrl":"/nte-meta/game-audio/ea794adb5fb66e4ee8f3.ogg"},{"id":"en-Play_Vo_Char_NPC023_weather_003","title":"Холодно","description":"Бр-р-р, холодно-то как. Давай где-нибудь выпьем горячего шоколада.","language":"Английский","audioUrl":"/nte-meta/game-audio/de7a268ebf27bb7a5d24.ogg"},{"id":"ja-Play_Vo_Char_NPC023_fh_002","title":"Исцеление II","description":"Мне уже лучше.","language":"Японский","audioUrl":"/nte-meta/game-audio/0cac34c4cebc618aaf55.ogg"},{"id":"ko-Play_Vo_Char_NPC023_skill_003","title":"Навык перенаправления III","description":"Рок-н-ролл!","language":"Корейский","audioUrl":"/nte-meta/game-audio/4ea3c4ae68b559eb8174.ogg"},{"id":"zh-Play_Vo_Char_NPC023_Switch_002","title":"Переключение II","description":"Не терпится выйти на сцену!","language":"Китайский","audioUrl":"/nte-meta/game-audio/2edcaa8e767c604b522f.ogg"},{"id":"en-Play_Vo_Char_NPC023_gift_001","title":"Подарок получен I","description":"Как же мне тебя отблагодарить…? Это непросто… но обещаю, я найду для тебя что-нибудь, что тебе понравится.","language":"Английский","audioUrl":"/nte-meta/game-audio/4064ff5b9a4d677e8ecf.ogg"},{"id":"ja-Play_Vo_Char_NPC023_dead_001","title":"Потеря сознания I","description":"Моя песня… ещё не допета…","language":"Японский","audioUrl":"/nte-meta/game-audio/ab8e5b9a7db469c7b7b1.ogg"},{"id":"ja-Play_Vo_Char_NPC023_QTE_001","title":"Атака на входе I","description":"Пора на новый лад!","language":"Японский","audioUrl":"/nte-meta/game-audio/0da067553cfebde91d47.ogg"},{"id":"ja-Play_Vo_Char_NPC023_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Отличное выступление. Отдохни немного.","language":"Японский","audioUrl":"/nte-meta/game-audio/61c6de34b13d7f344115.ogg"},{"id":"ja-Play_Vo_Char_NPC023_weather_002","title":"Дождливо","description":"В дождливые дни стоит быть особенно осторожными. Гитарные струны могут быстро заржаветь.","language":"Японский","audioUrl":"/nte-meta/game-audio/884df6b99fe91ec4d868.ogg"},{"id":"ko-Play_Vo_Char_NPC023_struck_002","title":"Урон II","description":"Не так уж и больно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/eadc01cc26ed37e0a803.ogg"},{"id":"ko-Play_Vo_Char_NPC023_weather_002","title":"Дождливо","description":"В дождливые дни стоит быть особенно осторожными. Гитарные струны могут быстро заржаветь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4a4d9fc43e19537817cf.ogg"},{"id":"zh-Play_Vo_Char_NPC023_QTE_002","title":"Атака на входе II","description":"Точно в такт!","language":"Китайский","audioUrl":"/nte-meta/game-audio/eba189e893164b4b85ae.ogg"},{"id":"en-Play_Vo_Char_NPC023_skill_002","title":"Навык перенаправления II","description":"Почувствуй ритм!","language":"Английский","audioUrl":"/nte-meta/game-audio/a092da14738f203541ce.ogg"},{"id":"en-Play_Vo_Char_NPC023_struck_002","title":"Урон II","description":"Не так уж и больно.","language":"Английский","audioUrl":"/nte-meta/game-audio/3e6f3604c92afe639b7d.ogg"},{"id":"ja-Play_Vo_Char_NPC023_meet_001","title":"Первая встреча","description":"Йоу, это Аканэ. Представляться вообще нужно? Мы же и так отлично сработались в группе. Нам всё нипочём, правда?","language":"Японский","audioUrl":"/nte-meta/game-audio/391f2bd4df398a62db41.ogg"},{"id":"ko-Play_Vo_Char_NPC023_Fly_002","title":"Планирование II","description":"Кажется, я могу парить где угодно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/321d1ecf8c8e7691d8e3.ogg"},{"id":"ko-Play_Vo_Char_NPC023_vexation_001","title":"Проблемы","description":"То покупаешь новую классную педаль эффектов, то на следующий день — новый альбом. Играя в группе, много фонсов не накопишь. Я уже давно живу от зарплаты до зарплаты.","language":"Корейский","audioUrl":"/nte-meta/game-audio/216593643da7191574e8.ogg"},{"id":"en-Play_Vo_Char_NPC023_greet_001","title":"Утреннее приветствие","description":"(*Зевает*) Доброе утро… Ч-Что? Я вчера вечером тайком не репетировала! Честно…!","language":"Английский","audioUrl":"/nte-meta/game-audio/208e831d9bf5ef33360e.ogg"},{"id":"en-Play_Vo_Char_NPC023_QTE_002","title":"Атака на входе II","description":"Точно в такт!","language":"Английский","audioUrl":"/nte-meta/game-audio/80335c55735fc0e3ff5a.ogg"},{"id":"ko-Play_Vo_Char_NPC023_self_002","title":"Обо мне: звёзды","description":"Я не то чтобы помешана на астрономии, но обожаю смотреть на звёзды. Мне нравится молча наблюдать, как они заполняют ночное небо. Когда у меня в голове полный беспорядок, я поднимаю взгляд к небу… и мысль о том, что весь этот звёздный свет преодолел немыслимые расстояния, чтобы добраться до нас, каждый раз меня успокаивает.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c3fe8f9c49d35983c58b.ogg"},{"id":"zh-Play_Vo_Char_NPC023_hobby_001","title":"Хобби","description":"Мои хобби помимо музыки? Эмм… считается, если я просто листаю Bagel? Или сижу и задумчиво смотрю на звёзды? Киесава спрашивал меня о том же — хочет, чтобы я нашла себе другие увлечения. Но, если честно, мне вполне хватает слушать музыку и играть на гитаре.","language":"Китайский","audioUrl":"/nte-meta/game-audio/55c1a978a4e3bce2f9cb.ogg"},{"id":"zh-Play_Vo_Char_NPC023_weather_004","title":"Жарко","description":"Жарища… Я весь день буду сидеть в комнате с кондеем.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f55a917797e6525947b9.ogg"},{"id":"en-Play_Vo_Char_NPC023_hobby_001","title":"Хобби","description":"Мои хобби помимо музыки? Эмм… считается, если я просто листаю Bagel? Или сижу и задумчиво смотрю на звёзды? Киесава спрашивал меня о том же — хочет, чтобы я нашла себе другие увлечения. Но, если честно, мне вполне хватает слушать музыку и играть на гитаре.","language":"Английский","audioUrl":"/nte-meta/game-audio/324c55ff246dc35f9358.ogg"},{"id":"ja-Play_Vo_Char_NPC023_greet_003","title":"Вечернее приветствие","description":"Фуух, ещё один рабочий день позади. Может, побаловать себя вкусняшкой?","language":"Японский","audioUrl":"/nte-meta/game-audio/fc2649d77f4c9646f920.ogg"},{"id":"ja-Play_Vo_Char_NPC023_ug_002","title":"Вознесение персонажа II","description":"Продолжаем зажигать.","language":"Японский","audioUrl":"/nte-meta/game-audio/d877018946ea417f3a21.ogg"},{"id":"ja-Play_Vo_Char_NPC023_ultraskill_UI_002","title":"Сверхспособность II","description":"Сцена готова. Пусть звёзды сияют!","language":"Японский","audioUrl":"/nte-meta/game-audio/e5ce20eabddeecdd1078.ogg"},{"id":"ko-Play_Vo_Char_NPC023_anomaly_004","title":"Нуллификация II","description":"Фух… напоминает о былых временах.","language":"Корейский","audioUrl":"/nte-meta/game-audio/0df2b5bc48c2cb63910b.ogg"},{"id":"ko-Play_Vo_Char_NPC023_chat_001","title":"Чат: костюмы","description":"Я не особо слежу за модой. Если бы мне не нужно было выступать на сцене, я бы всегда ходила в повседневной одежде.","language":"Корейский","audioUrl":"/nte-meta/game-audio/2a31b57d284a11d7d370.ogg"},{"id":"ko-Play_Vo_Char_NPC023_dead_001","title":"Потеря сознания I","description":"Моя песня… ещё не допета…","language":"Корейский","audioUrl":"/nte-meta/game-audio/945687946a1fbd6f3706.ogg"},{"id":"zh-Play_Vo_Char_NPC023_gift_001","title":"Подарок получен I","description":"Как же мне тебя отблагодарить…? Это непросто… но обещаю, я найду для тебя что-нибудь, что тебе понравится.","language":"Китайский","audioUrl":"/nte-meta/game-audio/de824b9dc29221549a23.ogg"},{"id":"zh-Play_Vo_Char_NPC023_Switch_001","title":"Переключение I","description":"Моё соло!","language":"Китайский","audioUrl":"/nte-meta/game-audio/f8c68bf3e90c8e2e7486.ogg"},{"id":"en-Play_Vo_Char_NPC023_hp_002","title":"Низкий уровень здоровья II","description":"Мой голос… слабеет…","language":"Английский","audioUrl":"/nte-meta/game-audio/7fddda01c1cd726fd884.ogg"},{"id":"ja-Play_Vo_Char_NPC023_containment_001","title":"Сдерживание I","description":"Новый фанат.","language":"Японский","audioUrl":"/nte-meta/game-audio/6b6cfeae8336ada6facb.ogg"},{"id":"ja-Play_Vo_Char_NPC023_greet_001","title":"Утреннее приветствие","description":"(*Зевает*) Доброе утро… Ч-Что? Я вчера вечером тайком не репетировала! Честно…!","language":"Японский","audioUrl":"/nte-meta/game-audio/80a60d17ef1ef59c1c25.ogg"},{"id":"ja-Play_Vo_Char_NPC023_kill_001","title":"Убийство I","description":"Эта песня для тебя.","language":"Японский","audioUrl":"/nte-meta/game-audio/db640770d80119386bd1.ogg"},{"id":"ko-Play_Vo_Char_NPC023_QTE_001","title":"Атака на входе I","description":"Пора на новый лад!","language":"Корейский","audioUrl":"/nte-meta/game-audio/d2a390bc0c0389d95b07.ogg"},{"id":"ko-Play_Vo_Char_NPC023_windfall_001","title":"Неожиданная добыча I","description":"Повезло мне.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d9bd7b058cc03a9ea817.ogg"},{"id":"zh-Play_Vo_Char_NPC023_containment_002","title":"Сдерживание II","description":"Ты тоже любишь музыку?","language":"Китайский","audioUrl":"/nte-meta/game-audio/869f8c53deec460774a4.ogg"},{"id":"en-Play_Vo_Char_NPC023_containment_002","title":"Сдерживание II","description":"Ты тоже любишь музыку?","language":"Английский","audioUrl":"/nte-meta/game-audio/9c16dfd14b0d7d08d7f1.ogg"},{"id":"ja-Play_Vo_Char_NPC023_struck_001","title":"Урон I","description":"Надо быть осторожнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/b9d845d69eb2f1fe393a.ogg"},{"id":"ja-Play_Vo_Char_NPC023_hstruck_002","title":"Сильный урон II","description":"Фальшивлю.","language":"Японский","audioUrl":"/nte-meta/game-audio/64c8a56a9af0feb4dcc0.ogg"},{"id":"ko-Play_Vo_Char_NPC023_windfall_006","title":"Неожиданная добыча VI","description":"Теперь я смогу позволить себе новый альбом.","language":"Корейский","audioUrl":"/nte-meta/game-audio/767ae40890625ece3e40.ogg"},{"id":"zh-Play_Vo_Char_NPC023_skill_003","title":"Навык перенаправления III","description":"Рок-н-ролл!","language":"Китайский","audioUrl":"/nte-meta/game-audio/b4e40a48deb26507ce9c.ogg"},{"id":"zh-Play_Vo_Char_NPC023_weather_003","title":"Холодно","description":"Бр-р-р, холодно-то как. Давай где-нибудь выпьем горячего шоколада.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5211ad210d84c64fe395.ogg"},{"id":"en-Play_Vo_Char_NPC023_greet_004","title":"Спокойной ночи","description":"Спокойной ночи. Не засиживайся в телефоне перед сном.","language":"Английский","audioUrl":"/nte-meta/game-audio/7359c92ba34547a16a57.ogg"},{"id":"ja-Play_Vo_Char_NPC023_anomaly_003","title":"Нуллификация I","description":"Шоу закончилось. Всё, сворачиваемся!","language":"Японский","audioUrl":"/nte-meta/game-audio/c0167107bb7772e64237.ogg"},{"id":"ja-Play_Vo_Char_NPC023_QTE_002","title":"Атака на входе II","description":"Точно в такт!","language":"Японский","audioUrl":"/nte-meta/game-audio/8861e103b104744ee703.ogg"},{"id":"ja-Play_Vo_Char_NPC023_SSC_HNY_001","title":"Особое переключение — Ханиэль","description":"Я сыграю этот сложный рифф.","language":"Японский","audioUrl":"/nte-meta/game-audio/b9b20772e1d2b447f506.ogg"},{"id":"ko-Play_Vo_Char_NPC023_talk_002","title":"Тема: после работы","description":"О, ты тоже за жизнь без лишней суеты? В общем, делаешь только то, что действительно нужно, да и то попроще. Работа каждый день выматывает. Откуда у меня силы ещё и куда-то ходить? Гораздо лучше пораньше вернуться домой, врубить кондёр на полную и листать Bagel. Нынешняя молодёжь просто не понимает, какое это счастье — жить без суеты.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4c03642d0a1002e326af.ogg"},{"id":"zh-Play_Vo_Char_NPC023_fh_001","title":"Исцеление I","description":"Снова на сцену!","language":"Китайский","audioUrl":"/nte-meta/game-audio/2252ca58a9cc054799f7.ogg"},{"id":"en-Play_Vo_Char_NPC023_anomaly_003","title":"Нуллификация I","description":"Шоу закончилось. Всё, сворачиваемся!","language":"Английский","audioUrl":"/nte-meta/game-audio/9efbe9b2d2c89ef4687a.ogg"},{"id":"en-Play_Vo_Char_NPC023_gift_002","title":"Подарок получен II","description":"Какой подарок — просто прелесть… Буду бережно хранить его в своей витрине.","language":"Английский","audioUrl":"/nte-meta/game-audio/63a6b6f20394f8419346.ogg"},{"id":"en-Play_Vo_Char_NPC023_ug_002","title":"Вознесение персонажа II","description":"Продолжаем зажигать.","language":"Английский","audioUrl":"/nte-meta/game-audio/3925ec0d1fa981b280f8.ogg"},{"id":"ko-Play_Vo_Char_NPC023_hstruck_002","title":"Сильный урон II","description":"Фальшивлю.","language":"Корейский","audioUrl":"/nte-meta/game-audio/cf29a214a497e550e828.ogg"},{"id":"ko-Play_Vo_Char_NPC023_windfall_002","title":"Неожиданная добыча II","description":"Неплохо. Теперь это моё.","language":"Корейский","audioUrl":"/nte-meta/game-audio/63badba02712fbb4dc73.ogg"},{"id":"zh-Play_Vo_Char_NPC023_Fly_001","title":"Планирование I","description":"Я могу коснуться звёзд?","language":"Китайский","audioUrl":"/nte-meta/game-audio/6865f2dbd51ad73f7b77.ogg"},{"id":"en-Play_Vo_Char_NPC023_greet_003","title":"Вечернее приветствие","description":"Фуух, ещё один рабочий день позади. Может, побаловать себя вкусняшкой?","language":"Английский","audioUrl":"/nte-meta/game-audio/f3d96f93c5594fcd1060.ogg"},{"id":"en-Play_Vo_Char_NPC023_struck_001","title":"Урон I","description":"Надо быть осторожнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/377615f0450199ce4784.ogg"},{"id":"ja-Play_Vo_Char_NPC023_gift_001","title":"Подарок получен I","description":"Как же мне тебя отблагодарить…? Это непросто… но обещаю, я найду для тебя что-нибудь, что тебе понравится.","language":"Японский","audioUrl":"/nte-meta/game-audio/1bc4e38b490835d87ead.ogg"},{"id":"ja-Play_Vo_Char_NPC023_windfall_001","title":"Неожиданная добыча I","description":"Повезло мне.","language":"Японский","audioUrl":"/nte-meta/game-audio/8b9bfd2db669cecba321.ogg"},{"id":"ko-Play_Vo_Char_NPC023_deploy_002","title":"Отправка II","description":"А где аплодисменты?","language":"Корейский","audioUrl":"/nte-meta/game-audio/a79c8b71612df3b1e7ab.ogg"},{"id":"ko-Play_Vo_Char_NPC023_ug_003","title":"Вознесение персонажа III","description":"Время новой песни.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b29c6193e456d8b5b312.ogg"},{"id":"zh-Play_Vo_Char_NPC023_skill_002","title":"Навык перенаправления II","description":"Почувствуй ритм!","language":"Китайский","audioUrl":"/nte-meta/game-audio/b36eb13f2404df6d3b2b.ogg"},{"id":"ko-Play_Vo_Char_NPC023_DodgeCombo_001","title":"Серия критических уклонений I","description":"Сможешь поспеть за моим ритмом?","language":"Корейский","audioUrl":"/nte-meta/game-audio/7e4bb298b9a2f97aff61.ogg"},{"id":"ko-Play_Vo_Char_NPC023_gift_001","title":"Подарок получен I","description":"Как же мне тебя отблагодарить…? Это непросто… но обещаю, я найду для тебя что-нибудь, что тебе понравится.","language":"Корейский","audioUrl":"/nte-meta/game-audio/9c5a8a6d07316b70eb45.ogg"},{"id":"en-Play_Vo_Char_NPC023_gift_003","title":"Подарок получен III","description":"Для меня? Спасибо. Мне очень нравится.","language":"Английский","audioUrl":"/nte-meta/game-audio/6a7f0dcb0ba9a519813c.ogg"},{"id":"ja-Play_Vo_Char_NPC023_Switch_001","title":"Переключение I","description":"Моё соло!","language":"Японский","audioUrl":"/nte-meta/game-audio/4167b40609eb59f6afe9.ogg"},{"id":"ko-Play_Vo_Char_NPC023_greet_001","title":"Утреннее приветствие","description":"(*Зевает*) Доброе утро… Ч-Что? Я вчера вечером тайком не репетировала! Честно…!","language":"Корейский","audioUrl":"/nte-meta/game-audio/3a51fb832a0a1dc8df6f.ogg"},{"id":"en-Play_Vo_Char_NPC023_weather_004","title":"Жарко","description":"Жарища… Я весь день буду сидеть в комнате с кондеем.","language":"Английский","audioUrl":"/nte-meta/game-audio/d118b9988fcf25bb0ef5.ogg"},{"id":"en-Play_Vo_Char_NPC023_dead_003","title":"Потеря сознания III","description":"Снова покидаю сцену…?","language":"Английский","audioUrl":"/nte-meta/game-audio/df371d3e4b90db7f74b2.ogg"},{"id":"en-Play_Vo_Char_NPC023_fh_002","title":"Исцеление II","description":"Мне уже лучше.","language":"Английский","audioUrl":"/nte-meta/game-audio/d58dafc04fe286c270ea.ogg"},{"id":"en-Play_Vo_Char_NPC023_skill_003","title":"Навык перенаправления III","description":"Рок-н-ролл!","language":"Английский","audioUrl":"/nte-meta/game-audio/636a50772e1bd955cd1e.ogg"},{"id":"ja-Play_Vo_Char_NPC023_about_002","title":"О «КОШАЧЬЕМ КОНЦЕРТЕ!!!!»","description":"«Шумная Совушка, громкий Котёнок — скорее цирк, чем группа». Вот что я подумала, когда Ханиэль сказала, что хочет создать группу. Пфф… Никогда бы не подумала, что у нас и правда получится, не говоря уже о том, что мы ещё и отыграли успешные концерты. Наверное, в этом и есть смысл группы — это место, где сбывается любая мечта, какой бы нелепой она ни была.","language":"Японский","audioUrl":"/nte-meta/game-audio/f32252b93ca02a37a7ad.ogg"},{"id":"ko-Play_Vo_Char_NPC023_QTE_003","title":"Атака на входе III","description":"Как раз вовремя.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f801643802908b081204.ogg"},{"id":"ko-Play_Vo_Char_NPC023_Switch_003","title":"Переключение III","description":"Зажжём!","language":"Корейский","audioUrl":"/nte-meta/game-audio/fcf373da7f9d97203823.ogg"},{"id":"ko-Play_Vo_Char_NPC023_weather_003","title":"Холодно","description":"Бр-р-р, холодно-то как. Давай где-нибудь выпьем горячего шоколада.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4776c10e1a6eaa5ffaa2.ogg"},{"id":"ko-Play_Vo_Char_NPC023_windfall_003","title":"Неожиданная добыча III","description":"Иногда полезно куда-нибудь выбраться.","language":"Корейский","audioUrl":"/nte-meta/game-audio/db2cdcae2c5f8a5082b3.ogg"},{"id":"zh-Play_Vo_Char_NPC023_SSC_NNL_001","title":"Особое переключение — Наналли","description":"Твоё соло закончилось. Держи ритм.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c7ec9865f7d8022cf34c.ogg"},{"id":"ja-Play_Vo_Char_NPC023_skill_002","title":"Навык перенаправления II","description":"Почувствуй ритм!","language":"Японский","audioUrl":"/nte-meta/game-audio/ec9bd006aacde37bcab6.ogg"},{"id":"ko-Play_Vo_Char_NPC023_about_002","title":"О «КОШАЧЬЕМ КОНЦЕРТЕ!!!!»","description":"«Шумная Совушка, громкий Котёнок — скорее цирк, чем группа». Вот что я подумала, когда Ханиэль сказала, что хочет создать группу. Пфф… Никогда бы не подумала, что у нас и правда получится, не говоря уже о том, что мы ещё и отыграли успешные концерты. Наверное, в этом и есть смысл группы — это место, где сбывается любая мечта, какой бы нелепой она ни была.","language":"Корейский","audioUrl":"/nte-meta/game-audio/31dc34e9344aef04e9d8.ogg"},{"id":"ko-Play_Vo_Char_NPC023_deploy_001","title":"Отправка I","description":"Шоу начинается!","language":"Корейский","audioUrl":"/nte-meta/game-audio/a6bd5f0d192fa7452832.ogg"},{"id":"ko-Play_Vo_Char_NPC023_TeammateDown_001","title":"Поражён товарищ по команде: Аурелия","description":"Я этого больше не допущу.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d5d39126f00a3ee33293.ogg"},{"id":"zh-Play_Vo_Char_NPC023_anomaly_003","title":"Нуллификация I","description":"Шоу закончилось. Всё, сворачиваемся!","language":"Китайский","audioUrl":"/nte-meta/game-audio/65d7936c5ea3be008bfa.ogg"},{"id":"zh-Play_Vo_Char_NPC023_dead_001","title":"Потеря сознания I","description":"Моя песня… ещё не допета…","language":"Китайский","audioUrl":"/nte-meta/game-audio/eb8d5f3f8c1c758c3e82.ogg"},{"id":"zh-Play_Vo_Char_NPC023_vexation_001","title":"Проблемы","description":"То покупаешь новую классную педаль эффектов, то на следующий день — новый альбом. Играя в группе, много фонсов не накопишь. Я уже давно живу от зарплаты до зарплаты.","language":"Китайский","audioUrl":"/nte-meta/game-audio/362828b6b8aa32848a67.ogg"},{"id":"zh-Play_Vo_Char_NPC023_windfall_005","title":"Неожиданная добыча V","description":"Маленькие радости жизни.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d4621a8307098e273ccd.ogg"},{"id":"ja-Play_Vo_Char_NPC023_hstruck_001","title":"Сильный урон I","description":"Ай, щиплет.","language":"Японский","audioUrl":"/nte-meta/game-audio/eb5d6b59416bdb2fc0ef.ogg"},{"id":"ko-Play_Vo_Char_NPC023_Fly_001","title":"Планирование I","description":"Я могу коснуться звёзд?","language":"Корейский","audioUrl":"/nte-meta/game-audio/90d0297bcd6f346b2937.ogg"},{"id":"ko-Play_Vo_Char_NPC023_hobby_001","title":"Хобби","description":"Мои хобби помимо музыки? Эмм… считается, если я просто листаю Bagel? Или сижу и задумчиво смотрю на звёзды? Киесава спрашивал меня о том же — хочет, чтобы я нашла себе другие увлечения. Но, если честно, мне вполне хватает слушать музыку и играть на гитаре.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a0b0b187afaf5bf342d7.ogg"},{"id":"ko-Play_Vo_Char_NPC023_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"Не надрывайся. Нам нужен каждый участник группы.","language":"Корейский","audioUrl":"/nte-meta/game-audio/884008c1eb273707f60a.ogg"},{"id":"zh-Play_Vo_Char_NPC023_DodgeCombo_002","title":"Серия критических уклонений II","description":"Не совсем в ноту.","language":"Китайский","audioUrl":"/nte-meta/game-audio/6912f30f4910962a890f.ogg"},{"id":"zh-Play_Vo_Char_NPC023_Parry_002","title":"Парирование II","description":"Поймала ритм!","language":"Китайский","audioUrl":"/nte-meta/game-audio/3f0922a7f1889d1f14ba.ogg"},{"id":"zh-Play_Vo_Char_NPC023_self_001","title":"Обо мне: способности эспера","description":"Когда меня переполняют сильные чувства, стоит мне перебрать струны — и из кончиков пальцев вылетают белые звёзды. Круто, правда? А как это работает… понятия не имею, да и выяснять не собираюсь. Только представь: когда я полностью отдаюсь выступлению, у меня прямо встроенные спецэффекты. И выглядят они просто нереально.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b60b22e2b78a3ef4bed5.ogg"},{"id":"ja-Play_Vo_Char_NPC023_containment_002","title":"Сдерживание II","description":"Ты тоже любишь музыку?","language":"Японский","audioUrl":"/nte-meta/game-audio/3c0946b986142ae5f081.ogg"},{"id":"ja-Play_Vo_Char_NPC023_struck_002","title":"Урон II","description":"Не так уж и больно.","language":"Японский","audioUrl":"/nte-meta/game-audio/f6c4edc74c84bab2d433.ogg"},{"id":"ja-Play_Vo_Char_NPC023_TeammateDown_001","title":"Поражён товарищ по команде: Аурелия","description":"Я этого больше не допущу.","language":"Японский","audioUrl":"/nte-meta/game-audio/c991fa3b763738c77289.ogg"},{"id":"ja-Play_Vo_Char_NPC023_ug_003","title":"Вознесение персонажа III","description":"Время новой песни.","language":"Японский","audioUrl":"/nte-meta/game-audio/1b6d0e36fb1b398e2598.ogg"},{"id":"zh-Play_Vo_Char_NPC023_self_002","title":"Обо мне: звёзды","description":"Я не то чтобы помешана на астрономии, но обожаю смотреть на звёзды. Мне нравится молча наблюдать, как они заполняют ночное небо. Когда у меня в голове полный беспорядок, я поднимаю взгляд к небу… и мысль о том, что весь этот звёздный свет преодолел немыслимые расстояния, чтобы добраться до нас, каждый раз меня успокаивает.","language":"Китайский","audioUrl":"/nte-meta/game-audio/01395001db8882289a4b.ogg"},{"id":"en-Play_Vo_Char_NPC023_self_002","title":"Обо мне: звёзды","description":"Я не то чтобы помешана на астрономии, но обожаю смотреть на звёзды. Мне нравится молча наблюдать, как они заполняют ночное небо. Когда у меня в голове полный беспорядок, я поднимаю взгляд к небу… и мысль о том, что весь этот звёздный свет преодолел немыслимые расстояния, чтобы добраться до нас, каждый раз меня успокаивает.","language":"Английский","audioUrl":"/nte-meta/game-audio/4544937f9a8d176f7dde.ogg"},{"id":"en-Play_Vo_Char_NPC023_ultraskill_UI_001","title":"Сверхспособность I","description":"Всё внимание на мне — и я его не упущу!","language":"Английский","audioUrl":"/nte-meta/game-audio/dd835ab3053770de9fa7.ogg"},{"id":"en-Play_Vo_Char_NPC023_windfall_003","title":"Неожиданная добыча III","description":"Иногда полезно куда-нибудь выбраться.","language":"Английский","audioUrl":"/nte-meta/game-audio/9ebf70180df808cab1a6.ogg"},{"id":"ja-Play_Vo_Char_NPC023_ultraskill_UI_003","title":"Сверхспособность III","description":"Готовы к шоу, которому нет конца?","language":"Японский","audioUrl":"/nte-meta/game-audio/d471e987859701f074a7.ogg"},{"id":"ja-Play_Vo_Char_NPC023_windfall_002","title":"Неожиданная добыча II","description":"Неплохо. Теперь это моё.","language":"Японский","audioUrl":"/nte-meta/game-audio/4d63109ec71aa2ab712e.ogg"},{"id":"ko-Play_Vo_Char_NPC023_about_001","title":"Об Аурелии","description":"Аурелия всегда была самой заботливой и мягкой — и в группе, и за её пределами. Без неё мы бы растеряли половину своих вещей: тюнер, который я оставила в репетиционной комнате, или куртку, которую Судзуха забыла в машине. Тогда она занималась почти всей организацией группы. А теперь, когда я встречаю её за работой на Улице Тамамочи, она всё такая же внимательная и сосредоточенная. Всё та же Аурелия. Ни капельки не изменилась.","language":"Корейский","audioUrl":"/nte-meta/game-audio/cdea55c29533a644ac3d.ogg"},{"id":"ko-Play_Vo_Char_NPC023_greet_004","title":"Спокойной ночи","description":"Спокойной ночи. Не засиживайся в телефоне перед сном.","language":"Корейский","audioUrl":"/nte-meta/game-audio/74b39c068ae350c43d7f.ogg"},{"id":"zh-Play_Vo_Char_NPC023_hstruck_002","title":"Сильный урон II","description":"Фальшивлю.","language":"Китайский","audioUrl":"/nte-meta/game-audio/15828675f8a68973d3c5.ogg"},{"id":"zh-Play_Vo_Char_NPC023_SSC_HNY_001","title":"Особое переключение — Ханиэль","description":"Я сыграю этот сложный рифф.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b92b833106fc59b2a2ea.ogg"},{"id":"en-Play_Vo_Char_NPC023_Switch_001","title":"Переключение I","description":"Моё соло!","language":"Английский","audioUrl":"/nte-meta/game-audio/3859e36a32f4d58d8e64.ogg"},{"id":"ja-Play_Vo_Char_NPC023_Switch_003","title":"Переключение III","description":"Зажжём!","language":"Японский","audioUrl":"/nte-meta/game-audio/400c59f538375e4ab036.ogg"},{"id":"ko-Play_Vo_Char_NPC023_talk_003","title":"Тема: школьные годы","description":"Мои школьные годы? Дай подумать… Я практически всё отдавала группе. Сейчас меня, наверное, сочли бы этакой раздолбайкой в учёбе. Хотя я слышала, что тогда половина девчонок в школе были моими фанатками… понятия не имею, правда ли это.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4d2029518f5e913eaebe.ogg"},{"id":"ja-Play_Vo_Char_NPC023_deploy_001","title":"Отправка I","description":"Шоу начинается!","language":"Японский","audioUrl":"/nte-meta/game-audio/eba25a8d2aa8fdeaa296.ogg"},{"id":"ja-Play_Vo_Char_NPC023_hobby_001","title":"Хобби","description":"Мои хобби помимо музыки? Эмм… считается, если я просто листаю Bagel? Или сижу и задумчиво смотрю на звёзды? Киесава спрашивал меня о том же — хочет, чтобы я нашла себе другие увлечения. Но, если честно, мне вполне хватает слушать музыку и играть на гитаре.","language":"Японский","audioUrl":"/nte-meta/game-audio/ab7a9659c697ceadf4c5.ogg"},{"id":"ko-Play_Vo_Char_NPC023_dead_003","title":"Потеря сознания III","description":"Снова покидаю сцену…?","language":"Корейский","audioUrl":"/nte-meta/game-audio/88b74d2525227a9dc1f8.ogg"},{"id":"zh-Play_Vo_Char_NPC023_self_003","title":"Обо мне: «Девушка-оркестр»","description":"Я одна заменяю целую группу…? Это уже преувеличение. Тебе ведь Аурелия или Судзуха это рассказали, да? Ну, вообще-то правда, что я систематически освоила все основные инструменты, нужные в группе. В детстве я училась играть на них, потому что мне нравилось, как они звучат. А после того, как мы создали группу, мне хотелось лучше понимать, чем занимается каждый, чтобы вместе справляться с любыми трудностями… Вот так мы и остаёмся в одной тональности.","language":"Китайский","audioUrl":"/nte-meta/game-audio/bdcc9e8f7b0a06113b87.ogg"},{"id":"zh-Play_Vo_Char_NPC023_weather_002","title":"Дождливо","description":"В дождливые дни стоит быть особенно осторожными. Гитарные струны могут быстро заржаветь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f087d9c4931f4c68f7ff.ogg"},{"id":"en-Play_Vo_Char_NPC023_hp_001","title":"Низкий уровень здоровья I","description":"Ещё чуть-чуть…","language":"Английский","audioUrl":"/nte-meta/game-audio/fa0fc63d93682da2d032.ogg"},{"id":"en-Play_Vo_Char_NPC023_hstruck_001","title":"Сильный урон I","description":"Ай, щиплет.","language":"Английский","audioUrl":"/nte-meta/game-audio/0a43e9eca94ba06460ee.ogg"},{"id":"zh-Play_Vo_Char_NPC023_dead_002","title":"Потеря сознания II","description":"Звёзды померкли…","language":"Китайский","audioUrl":"/nte-meta/game-audio/a400cd494dfb181c7412.ogg"},{"id":"zh-Play_Vo_Char_NPC023_ultraskill_UI_001","title":"Сверхспособность I","description":"Всё внимание на мне — и я его не упущу!","language":"Китайский","audioUrl":"/nte-meta/game-audio/6e72da74beac8a131e9b.ogg"},{"id":"en-Play_Vo_Char_NPC023_QTE_003","title":"Атака на входе III","description":"Как раз вовремя.","language":"Английский","audioUrl":"/nte-meta/game-audio/19b3c8b845f9788ec091.ogg"},{"id":"en-Play_Vo_Char_NPC023_deploy_001","title":"Отправка I","description":"Шоу начинается!","language":"Английский","audioUrl":"/nte-meta/game-audio/170e658f5f75415a9bb9.ogg"},{"id":"ja-Play_Vo_Char_NPC023_dead_003","title":"Потеря сознания III","description":"Снова покидаю сцену…?","language":"Японский","audioUrl":"/nte-meta/game-audio/d71a9310b9e3c8641cd3.ogg"},{"id":"ko-Play_Vo_Char_NPC023_hstruck_001","title":"Сильный урон I","description":"Ай, щиплет.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e6be29564609dced6d53.ogg"},{"id":"ko-Play_Vo_Char_NPC023_skill_002","title":"Навык перенаправления II","description":"Почувствуй ритм!","language":"Корейский","audioUrl":"/nte-meta/game-audio/756f893402ebce49dcd2.ogg"},{"id":"zh-Play_Vo_Char_NPC023_greet_002","title":"Дневное приветствие","description":"Не хочу сегодня есть на работе. Давай лучше перекусим чем-нибудь вкусненьким. Я угощаю.","language":"Китайский","audioUrl":"/nte-meta/game-audio/39b2d6dc0483e03b08f7.ogg"},{"id":"zh-Play_Vo_Char_NPC023_greet_004","title":"Спокойной ночи","description":"Спокойной ночи. Не засиживайся в телефоне перед сном.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7ad1173bf2ddff3604d3.ogg"},{"id":"zh-Play_Vo_Char_NPC023_windfall_006","title":"Неожиданная добыча VI","description":"Теперь я смогу позволить себе новый альбом.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0f591c2b407910b7231e.ogg"},{"id":"en-Play_Vo_Char_NPC023_anomaly_004","title":"Нуллификация II","description":"Фух… напоминает о былых временах.","language":"Английский","audioUrl":"/nte-meta/game-audio/f6c469c751a7ecaac115.ogg"},{"id":"ja-Play_Vo_Char_NPC023_skill_001","title":"Навык перенаправления I","description":"Громче!","language":"Японский","audioUrl":"/nte-meta/game-audio/d209d3c12251a1e3958e.ogg"},{"id":"zh-Play_Vo_Char_NPC023_about_001","title":"Об Аурелии","description":"Аурелия всегда была самой заботливой и мягкой — и в группе, и за её пределами. Без неё мы бы растеряли половину своих вещей: тюнер, который я оставила в репетиционной комнате, или куртку, которую Судзуха забыла в машине. Тогда она занималась почти всей организацией группы. А теперь, когда я встречаю её за работой на Улице Тамамочи, она всё такая же внимательная и сосредоточенная. Всё та же Аурелия. Ни капельки не изменилась.","language":"Китайский","audioUrl":"/nte-meta/game-audio/38a01f274a22f272912d.ogg"},{"id":"zh-Play_Vo_Char_NPC023_meet_001","title":"Первая встреча","description":"Йоу, это Аканэ. Представляться вообще нужно? Мы же и так отлично сработались в группе. Нам всё нипочём, правда?","language":"Китайский","audioUrl":"/nte-meta/game-audio/db82fd9a3f0ac2844806.ogg"},{"id":"zh-Play_Vo_Char_NPC023_QTE_001","title":"Атака на входе I","description":"Пора на новый лад!","language":"Китайский","audioUrl":"/nte-meta/game-audio/54286e49900ccba58daa.ogg"},{"id":"zh-Play_Vo_Char_NPC023_TeammateDown_004","title":"Поражен товарищ по команде – Ханиэль","description":"Отдохни. Я тебя подменю.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d1bf1207ff366e31f59a.ogg"},{"id":"en-Play_Vo_Char_NPC023_Fly_002","title":"Планирование II","description":"Кажется, я могу парить где угодно.","language":"Английский","audioUrl":"/nte-meta/game-audio/e85345c8e69fdf56b79f.ogg"},{"id":"zh-Play_Vo_Char_NPC023_deploy_002","title":"Отправка II","description":"А где аплодисменты?","language":"Китайский","audioUrl":"/nte-meta/game-audio/b0cd5d4b9a546c4295ad.ogg"},{"id":"ja-Play_Vo_Char_NPC023_talk_001","title":"Тема: моя первая гитара","description":"Моя первая гитара… папа подарил её мне, когда я окончила начальную школу. Я хорошо за ней ухаживаю. Она до сих пор отлично звучит. Время от времени я достаю её и играю простые гаммы.","language":"Японский","audioUrl":"/nte-meta/game-audio/72b8bbc0a880d64e48e2.ogg"},{"id":"ko-Play_Vo_Char_NPC023_Switch_002","title":"Переключение II","description":"Не терпится выйти на сцену!","language":"Корейский","audioUrl":"/nte-meta/game-audio/5948deaa0e5bd4cd8232.ogg"},{"id":"zh-Play_Vo_Char_NPC023_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Отличное выступление. Отдохни немного.","language":"Китайский","audioUrl":"/nte-meta/game-audio/6faaa7b21a00c24f8976.ogg"},{"id":"en-Play_Vo_Char_NPC023_hstruck_002","title":"Сильный урон II","description":"Фальшивлю.","language":"Английский","audioUrl":"/nte-meta/game-audio/b26e3fab7ce3367c980e.ogg"},{"id":"en-Play_Vo_Char_NPC023_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"Не надрывайся. Нам нужен каждый участник группы.","language":"Английский","audioUrl":"/nte-meta/game-audio/3d97dc8bcaa9c39dafa4.ogg"},{"id":"ja-Play_Vo_Char_NPC023_Switch_002","title":"Переключение II","description":"Не терпится выйти на сцену!","language":"Японский","audioUrl":"/nte-meta/game-audio/fca1228cfe73b514aff8.ogg"},{"id":"ja-Play_Vo_Char_NPC023_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"Не надрывайся. Нам нужен каждый участник группы.","language":"Японский","audioUrl":"/nte-meta/game-audio/97f80fb4483795a70c38.ogg"},{"id":"ko-Play_Vo_Char_NPC023_struck_001","title":"Урон I","description":"Надо быть осторожнее.","language":"Корейский","audioUrl":"/nte-meta/game-audio/2482c31c4e633ec5d84c.ogg"},{"id":"zh-Play_Vo_Char_NPC023_fh_002","title":"Исцеление II","description":"Мне уже лучше.","language":"Китайский","audioUrl":"/nte-meta/game-audio/222182df4cbb5dd6c02a.ogg"},{"id":"zh-Play_Vo_Char_NPC023_hp_003","title":"Низкий уровень здоровья III","description":"Мне нужно передохнуть…","language":"Китайский","audioUrl":"/nte-meta/game-audio/b6db3be55d65a1a80a23.ogg"},{"id":"en-Play_Vo_Char_NPC023_chat_001","title":"Чат: костюмы","description":"Я не особо слежу за модой. Если бы мне не нужно было выступать на сцене, я бы всегда ходила в повседневной одежде.","language":"Английский","audioUrl":"/nte-meta/game-audio/e3db987b4903cdcb6513.ogg"}]') WHERE character_id='akane' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 16:33:23');

UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT value FROM json_each('[{"id":"en-Play_Vo_Char_NPC023_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Отличное выступление. Отдохни немного.","language":"Английский","audioUrl":"/nte-meta/game-audio/1e973d844113f16e9817.ogg"},{"id":"ja-Play_Vo_Char_NPC023_gift_003","title":"Подарок получен III","description":"Для меня? Спасибо. Мне очень нравится.","language":"Японский","audioUrl":"/nte-meta/game-audio/0007ee6cf5c2aa2aa196.ogg"},{"id":"ja-Play_Vo_Char_NPC023_self_001","title":"Обо мне: способности эспера","description":"Когда меня переполняют сильные чувства, стоит мне перебрать струны — и из кончиков пальцев вылетают белые звёзды. Круто, правда? А как это работает… понятия не имею, да и выяснять не собираюсь. Только представь: когда я полностью отдаюсь выступлению, у меня прямо встроенные спецэффекты. И выглядят они просто нереально.","language":"Японский","audioUrl":"/nte-meta/game-audio/0d311a5d32757e52a9b4.ogg"},{"id":"ko-Play_Vo_Char_NPC023_self_003","title":"Обо мне: «Девушка-оркестр»","description":"Я одна заменяю целую группу…? Это уже преувеличение. Тебе ведь Аурелия или Судзуха это рассказали, да? Ну, вообще-то правда, что я систематически освоила все основные инструменты, нужные в группе. В детстве я училась играть на них, потому что мне нравилось, как они звучат. А после того, как мы создали группу, мне хотелось лучше понимать, чем занимается каждый, чтобы вместе справляться с любыми трудностями… Вот так мы и остаёмся в одной тональности.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1bd5f681cec9a4a40af1.ogg"},{"id":"ko-Play_Vo_Char_NPC023_talk_001","title":"Тема: моя первая гитара","description":"Моя первая гитара… папа подарил её мне, когда я окончила начальную школу. Я хорошо за ней ухаживаю. Она до сих пор отлично звучит. Время от времени я достаю её и играю простые гаммы.","language":"Корейский","audioUrl":"/nte-meta/game-audio/9492881d2e8c0b1577cc.ogg"},{"id":"zh-Play_Vo_Char_NPC023_windfall_004","title":"Неожиданная добыча IV","description":"Я буду бережно его хранить.","language":"Китайский","audioUrl":"/nte-meta/game-audio/63f05d5f71071dd526e7.ogg"},{"id":"en-Play_Vo_Char_NPC023_windfall_005","title":"Неожиданная добыча V","description":"Маленькие радости жизни.","language":"Английский","audioUrl":"/nte-meta/game-audio/4418ecf3dd2f125ea10b.ogg"},{"id":"ja-Play_Vo_Char_NPC023_hp_001","title":"Низкий уровень здоровья I","description":"Ещё чуть-чуть…","language":"Японский","audioUrl":"/nte-meta/game-audio/6c2b184d3df13e8e3ab0.ogg"},{"id":"ko-Play_Vo_Char_NPC023_SSC_HNY_001","title":"Особое переключение — Ханиэль","description":"Я сыграю этот сложный рифф.","language":"Корейский","audioUrl":"/nte-meta/game-audio/609760472f2c2f208e08.ogg"},{"id":"zh-Play_Vo_Char_NPC023_DodgeCombo_001","title":"Серия критических уклонений I","description":"Сможешь поспеть за моим ритмом?","language":"Китайский","audioUrl":"/nte-meta/game-audio/98c2eb420af365e66928.ogg"},{"id":"zh-Play_Vo_Char_NPC023_skill_001","title":"Навык перенаправления I","description":"Громче!","language":"Китайский","audioUrl":"/nte-meta/game-audio/5223e862b63d15231b98.ogg"},{"id":"zh-Play_Vo_Char_NPC023_Switch_003","title":"Переключение III","description":"Зажжём!","language":"Китайский","audioUrl":"/nte-meta/game-audio/1ad1cb4aaca946fc78d8.ogg"},{"id":"zh-Play_Vo_Char_NPC023_ug_002","title":"Вознесение персонажа II","description":"Продолжаем зажигать.","language":"Китайский","audioUrl":"/nte-meta/game-audio/bb1506365d9612c23cb7.ogg"},{"id":"zh-Play_Vo_Char_NPC023_ug_003","title":"Вознесение персонажа III","description":"Время новой песни.","language":"Китайский","audioUrl":"/nte-meta/game-audio/592f7a87626a07d6cd06.ogg"},{"id":"zh-Play_Vo_Char_NPC023_talk_003","title":"Тема: школьные годы","description":"Мои школьные годы? Дай подумать… Я практически всё отдавала группе. Сейчас меня, наверное, сочли бы этакой раздолбайкой в учёбе. Хотя я слышала, что тогда половина девчонок в школе были моими фанатками… понятия не имею, правда ли это.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2cdd01bdb4bd96219b52.ogg"},{"id":"en-Play_Vo_Char_NPC023_chat_002","title":"Чат: подработка","description":"Люди спрашивают обо всём подряд. Многие просят меня поделиться советами для хорошего выступления. На самом деле таких просьб стало настолько много, что теперь я сначала прошу купить мне попить, а уже потом задавать вопросы. Хм… Киесаве стоит прибавить мне зарплату.","language":"Английский","audioUrl":"/nte-meta/game-audio/15ad1ea5d08ebc80ee0b.ogg"},{"id":"en-Play_Vo_Char_NPC023_DodgeCombo_002","title":"Серия критических уклонений II","description":"Не совсем в ноту.","language":"Английский","audioUrl":"/nte-meta/game-audio/10a32417d13310b8a584.ogg"},{"id":"en-Play_Vo_Char_NPC023_ultraskill_UI_003","title":"Сверхспособность III","description":"Готовы к шоу, которому нет конца?","language":"Английский","audioUrl":"/nte-meta/game-audio/163c3223e8b5f5477c09.ogg"},{"id":"en-Play_Vo_Char_NPC023_windfall_006","title":"Неожиданная добыча VI","description":"Теперь я смогу позволить себе новый альбом.","language":"Английский","audioUrl":"/nte-meta/game-audio/9b1dd0945464996d5b82.ogg"},{"id":"ja-Play_Vo_Char_NPC023_weather_004","title":"Жарко","description":"Жарища… Я весь день буду сидеть в комнате с кондеем.","language":"Японский","audioUrl":"/nte-meta/game-audio/52a5a76c3a3332e0ec44.ogg"},{"id":"ko-Play_Vo_Char_NPC023_Parry_002","title":"Парирование II","description":"Поймала ритм!","language":"Корейский","audioUrl":"/nte-meta/game-audio/bc889cbcac1ddf794fc7.ogg"},{"id":"ko-Play_Vo_Char_NPC023_ultraskill_UI_003","title":"Сверхспособность III","description":"Готовы к шоу, которому нет конца?","language":"Корейский","audioUrl":"/nte-meta/game-audio/7f99b6581b484a0b4c8a.ogg"},{"id":"zh-Play_Vo_Char_NPC023_ultraskill_UI_002","title":"Сверхспособность II","description":"Сцена готова. Пусть звёзды сияют!","language":"Китайский","audioUrl":"/nte-meta/game-audio/47b7f1af0c1a2d5a4e8e.ogg"},{"id":"ko-Play_Vo_Char_NPC023_containment_002","title":"Сдерживание II","description":"Ты тоже любишь музыку?","language":"Корейский","audioUrl":"/nte-meta/game-audio/6805160980e473bf94af.ogg"},{"id":"zh-Play_Vo_Char_NPC023_windfall_001","title":"Неожиданная добыча I","description":"Повезло мне.","language":"Китайский","audioUrl":"/nte-meta/game-audio/531ea71fa22a7b1e5113.ogg"},{"id":"zh-Play_Vo_Char_NPC023_windfall_003","title":"Неожиданная добыча III","description":"Иногда полезно куда-нибудь выбраться.","language":"Китайский","audioUrl":"/nte-meta/game-audio/dbcd4aafc3e611358da2.ogg"},{"id":"en-Play_Vo_Char_NPC023_vexation_001","title":"Проблемы","description":"То покупаешь новую классную педаль эффектов, то на следующий день — новый альбом. Играя в группе, много фонсов не накопишь. Я уже давно живу от зарплаты до зарплаты.","language":"Английский","audioUrl":"/nte-meta/game-audio/71af33f69c840a49362c.ogg"},{"id":"ja-Play_Vo_Char_NPC023_gift_004","title":"Подарок получен IV","description":"В следующий раз, как заглянешь в «Звёздный знак», угощаю.","language":"Японский","audioUrl":"/nte-meta/game-audio/bb61dbbc4230c7b5767b.ogg"},{"id":"ja-Play_Vo_Char_NPC023_windfall_006","title":"Неожиданная добыча VI","description":"Теперь я смогу позволить себе новый альбом.","language":"Японский","audioUrl":"/nte-meta/game-audio/4a4795377771e79da069.ogg"},{"id":"ko-Play_Vo_Char_NPC023_anomaly_003","title":"Нуллификация I","description":"Шоу закончилось. Всё, сворачиваемся!","language":"Корейский","audioUrl":"/nte-meta/game-audio/7b73bb15b6fc21c919d3.ogg"},{"id":"ko-Play_Vo_Char_NPC023_self_001","title":"Обо мне: способности эспера","description":"Когда меня переполняют сильные чувства, стоит мне перебрать струны — и из кончиков пальцев вылетают белые звёзды. Круто, правда? А как это работает… понятия не имею, да и выяснять не собираюсь. Только представь: когда я полностью отдаюсь выступлению, у меня прямо встроенные спецэффекты. И выглядят они просто нереально.","language":"Корейский","audioUrl":"/nte-meta/game-audio/03a9bfe6c761935b94fe.ogg"},{"id":"zh-Play_Vo_Char_NPC023_deploy_001","title":"Отправка I","description":"Шоу начинается!","language":"Китайский","audioUrl":"/nte-meta/game-audio/cb4f1dd1065308122a52.ogg"},{"id":"en-Play_Vo_Char_NPC023_talk_003","title":"Тема: школьные годы","description":"Мои школьные годы? Дай подумать… Я практически всё отдавала группе. Сейчас меня, наверное, сочли бы этакой раздолбайкой в учёбе. Хотя я слышала, что тогда половина девчонок в школе были моими фанатками… понятия не имею, правда ли это.","language":"Английский","audioUrl":"/nte-meta/game-audio/2e2b0f1dee55e9ec04e8.ogg"},{"id":"en-Play_Vo_Char_NPC023_ultraskill_UI_002","title":"Сверхспособность II","description":"Сцена готова. Пусть звёзды сияют!","language":"Английский","audioUrl":"/nte-meta/game-audio/242cf7bfc6091312a874.ogg"},{"id":"ja-Play_Vo_Char_NPC023_chat_001","title":"Чат: костюмы","description":"Я не особо слежу за модой. Если бы мне не нужно было выступать на сцене, я бы всегда ходила в повседневной одежде.","language":"Японский","audioUrl":"/nte-meta/game-audio/a8157ee4c20fe4e2219e.ogg"},{"id":"ja-Play_Vo_Char_NPC023_talk_003","title":"Тема: школьные годы","description":"Мои школьные годы? Дай подумать… Я практически всё отдавала группе. Сейчас меня, наверное, сочли бы этакой раздолбайкой в учёбе. Хотя я слышала, что тогда половина девчонок в школе были моими фанатками… понятия не имею, правда ли это.","language":"Японский","audioUrl":"/nte-meta/game-audio/3376f8457e2af2dbc63a.ogg"},{"id":"ko-Play_Vo_Char_NPC023_meet_001","title":"Первая встреча","description":"Йоу, это Аканэ. Представляться вообще нужно? Мы же и так отлично сработались в группе. Нам всё нипочём, правда?","language":"Корейский","audioUrl":"/nte-meta/game-audio/76afd0deb125116c94cb.ogg"},{"id":"ko-Play_Vo_Char_NPC023_windfall_005","title":"Неожиданная добыча V","description":"Маленькие радости жизни.","language":"Корейский","audioUrl":"/nte-meta/game-audio/043a3f2041407a6fc244.ogg"},{"id":"zh-Play_Vo_Char_NPC023_struck_001","title":"Урон I","description":"Надо быть осторожнее.","language":"Китайский","audioUrl":"/nte-meta/game-audio/fb757066c69a3dca9d3c.ogg"},{"id":"en-Play_Vo_Char_NPC023_weather_001","title":"Солнечно","description":"Какая хорошая погода. Я слишком много времени провожу в «Звёздном знаке». Мне бы не помешало иногда выходить на улицу.","language":"Английский","audioUrl":"/nte-meta/game-audio/c1b27cfab8f93d358d9e.ogg"},{"id":"ja-Play_Vo_Char_NPC023_about_001","title":"Об Аурелии","description":"Аурелия всегда была самой заботливой и мягкой — и в группе, и за её пределами. Без неё мы бы растеряли половину своих вещей: тюнер, который я оставила в репетиционной комнате, или куртку, которую Судзуха забыла в машине. Тогда она занималась почти всей организацией группы. А теперь, когда я встречаю её за работой на Улице Тамамочи, она всё такая же внимательная и сосредоточенная. Всё та же Аурелия. Ни капельки не изменилась.","language":"Японский","audioUrl":"/nte-meta/game-audio/8765f399eba4e06a797d.ogg"},{"id":"ja-Play_Vo_Char_NPC023_greet_002","title":"Дневное приветствие","description":"Не хочу сегодня есть на работе. Давай лучше перекусим чем-нибудь вкусненьким. Я угощаю.","language":"Японский","audioUrl":"/nte-meta/game-audio/42d665413bef4cdafb62.ogg"},{"id":"ko-Play_Vo_Char_NPC023_containment_001","title":"Сдерживание I","description":"Новый фанат.","language":"Корейский","audioUrl":"/nte-meta/game-audio/922f94970b4be9f7fcb7.ogg"},{"id":"ko-Play_Vo_Char_NPC023_hp_002","title":"Низкий уровень здоровья II","description":"Мой голос… слабеет…","language":"Корейский","audioUrl":"/nte-meta/game-audio/1e313fd3a6f2da8b1d86.ogg"},{"id":"zh-Play_Vo_Char_NPC023_about_002","title":"О «КОШАЧЬЕМ КОНЦЕРТЕ!!!!»","description":"«Шумная Совушка, громкий Котёнок — скорее цирк, чем группа». Вот что я подумала, когда Ханиэль сказала, что хочет создать группу. Пфф… Никогда бы не подумала, что у нас и правда получится, не говоря уже о том, что мы ещё и отыграли успешные концерты. Наверное, в этом и есть смысл группы — это место, где сбывается любая мечта, какой бы нелепой она ни была.","language":"Китайский","audioUrl":"/nte-meta/game-audio/000f1185bce3b6e70dc4.ogg"},{"id":"zh-Play_Vo_Char_NPC023_chat_002","title":"Чат: подработка","description":"Люди спрашивают обо всём подряд. Многие просят меня поделиться советами для хорошего выступления. На самом деле таких просьб стало настолько много, что теперь я сначала прошу купить мне попить, а уже потом задавать вопросы. Хм… Киесаве стоит прибавить мне зарплату.","language":"Китайский","audioUrl":"/nte-meta/game-audio/dd373120eaf5d2de160b.ogg"},{"id":"zh-Play_Vo_Char_NPC023_Fly_002","title":"Планирование II","description":"Кажется, я могу парить где угодно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5ce066c41f0e51c5fb87.ogg"},{"id":"zh-Play_Vo_Char_NPC023_gift_004","title":"Подарок получен IV","description":"В следующий раз, как заглянешь в «Звёздный знак», угощаю.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f840d1ac3744f2e8b439.ogg"},{"id":"zh-Play_Vo_Char_NPC023_TeammateDown_001","title":"Поражён товарищ по команде: Аурелия","description":"Я этого больше не допущу.","language":"Китайский","audioUrl":"/nte-meta/game-audio/bd13af4fc7d5e9f6b951.ogg"},{"id":"en-Play_Vo_Char_NPC023_dead_002","title":"Потеря сознания II","description":"Звёзды померкли…","language":"Английский","audioUrl":"/nte-meta/game-audio/517f764ef5be7172499f.ogg"},{"id":"ja-Play_Vo_Char_NPC023_self_002","title":"Обо мне: звёзды","description":"Я не то чтобы помешана на астрономии, но обожаю смотреть на звёзды. Мне нравится молча наблюдать, как они заполняют ночное небо. Когда у меня в голове полный беспорядок, я поднимаю взгляд к небу… и мысль о том, что весь этот звёздный свет преодолел немыслимые расстояния, чтобы добраться до нас, каждый раз меня успокаивает.","language":"Японский","audioUrl":"/nte-meta/game-audio/14106e2d16eee46dd0b2.ogg"},{"id":"zh-Play_Vo_Char_NPC023_ultraskill_UI_003","title":"Сверхспособность III","description":"Готовы к шоу, которому нет конца?","language":"Китайский","audioUrl":"/nte-meta/game-audio/b10d24d1ecb429039212.ogg"},{"id":"en-Play_Vo_Char_NPC023_chat_003","title":"Чат: наушники","description":"В наши дни многие предпочитают беспроводные наушники, но я всё равно считаю, что проводные и выглядят лучше, и работают надёжнее. Судзуха постоянно меня подкалывает: мол, разъём для наушников уже давно стал пережитком прошлого… Неужели всё настолько плохо?","language":"Английский","audioUrl":"/nte-meta/game-audio/b4841e3b602836b9080a.ogg"},{"id":"en-Play_Vo_Char_NPC023_gift_004","title":"Подарок получен IV","description":"В следующий раз, как заглянешь в «Звёздный знак», угощаю.","language":"Английский","audioUrl":"/nte-meta/game-audio/224b940c1f0a8bc035d9.ogg"},{"id":"ja-Play_Vo_Char_NPC023_SSC_NNL_001","title":"Особое переключение — Наналли","description":"Твоё соло закончилось. Держи ритм.","language":"Японский","audioUrl":"/nte-meta/game-audio/7f59daee59aa4ac3e58b.ogg"},{"id":"ko-Play_Vo_Char_NPC023_QTE_002","title":"Атака на входе II","description":"Точно в такт!","language":"Корейский","audioUrl":"/nte-meta/game-audio/55890212430810c83501.ogg"},{"id":"ko-Play_Vo_Char_NPC023_ug_002","title":"Вознесение персонажа II","description":"Продолжаем зажигать.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6c7155dc000d4ce01895.ogg"},{"id":"ko-Play_Vo_Char_NPC023_weather_001","title":"Солнечно","description":"Какая хорошая погода. Я слишком много времени провожу в «Звёздном знаке». Мне бы не помешало иногда выходить на улицу.","language":"Корейский","audioUrl":"/nte-meta/game-audio/9f43645ef619ba673193.ogg"},{"id":"ja-Play_Vo_Char_NPC023_deploy_002","title":"Отправка II","description":"А где аплодисменты?","language":"Японский","audioUrl":"/nte-meta/game-audio/f9c80da25b82e38e83a8.ogg"},{"id":"ja-Play_Vo_Char_NPC023_hp_003","title":"Низкий уровень здоровья III","description":"Мне нужно передохнуть…","language":"Японский","audioUrl":"/nte-meta/game-audio/774ba0fa28aae7fdc026.ogg"},{"id":"ja-Play_Vo_Char_NPC023_self_003","title":"Обо мне: «Девушка-оркестр»","description":"Я одна заменяю целую группу…? Это уже преувеличение. Тебе ведь Аурелия или Судзуха это рассказали, да? Ну, вообще-то правда, что я систематически освоила все основные инструменты, нужные в группе. В детстве я училась играть на них, потому что мне нравилось, как они звучат. А после того, как мы создали группу, мне хотелось лучше понимать, чем занимается каждый, чтобы вместе справляться с любыми трудностями… Вот так мы и остаёмся в одной тональности.","language":"Японский","audioUrl":"/nte-meta/game-audio/2ace3ca108461082c9d4.ogg"},{"id":"ja-Play_Vo_Char_NPC023_windfall_003","title":"Неожиданная добыча III","description":"Иногда полезно куда-нибудь выбраться.","language":"Японский","audioUrl":"/nte-meta/game-audio/5f9d92d0242cb0e9fa9f.ogg"},{"id":"ko-Play_Vo_Char_NPC023_Parry_001","title":"Парирование I","description":"Не мой темп!","language":"Корейский","audioUrl":"/nte-meta/game-audio/9617d8539ecc13111211.ogg"},{"id":"ko-Play_Vo_Char_NPC023_windfall_004","title":"Неожиданная добыча IV","description":"Я буду бережно его хранить.","language":"Корейский","audioUrl":"/nte-meta/game-audio/61209fff71525ca5c8d8.ogg"},{"id":"en-Play_Vo_Char_NPC023_dead_001","title":"Потеря сознания I","description":"Моя песня… ещё не допета…","language":"Английский","audioUrl":"/nte-meta/game-audio/4511dd06f801bd358656.ogg"},{"id":"ko-Play_Vo_Char_NPC023_dead_002","title":"Потеря сознания II","description":"Звёзды померкли…","language":"Корейский","audioUrl":"/nte-meta/game-audio/a33a3a23797c34aabb80.ogg"},{"id":"ko-Play_Vo_Char_NPC023_fh_001","title":"Исцеление I","description":"Снова на сцену!","language":"Корейский","audioUrl":"/nte-meta/game-audio/f6d8942874e1264b58a8.ogg"},{"id":"zh-Play_Vo_Char_NPC023_windfall_002","title":"Неожиданная добыча II","description":"Неплохо. Теперь это моё.","language":"Китайский","audioUrl":"/nte-meta/game-audio/909777fdd1fdbf78ba96.ogg"},{"id":"en-Play_Vo_Char_NPC023_about_001","title":"Об Аурелии","description":"Аурелия всегда была самой заботливой и мягкой — и в группе, и за её пределами. Без неё мы бы растеряли половину своих вещей: тюнер, который я оставила в репетиционной комнате, или куртку, которую Судзуха забыла в машине. Тогда она занималась почти всей организацией группы. А теперь, когда я встречаю её за работой на Улице Тамамочи, она всё такая же внимательная и сосредоточенная. Всё та же Аурелия. Ни капельки не изменилась.","language":"Английский","audioUrl":"/nte-meta/game-audio/34f0db5541b362864dbb.ogg"},{"id":"ko-Play_Vo_Char_NPC023_hp_003","title":"Низкий уровень здоровья III","description":"Мне нужно передохнуть…","language":"Корейский","audioUrl":"/nte-meta/game-audio/6c6a83a44fa9eefea9f1.ogg"},{"id":"ja-Play_Vo_Char_NPC023_DodgeCombo_002","title":"Серия критических уклонений II","description":"Не совсем в ноту.","language":"Японский","audioUrl":"/nte-meta/game-audio/fdf25666fb49286aed81.ogg"},{"id":"ja-Play_Vo_Char_NPC023_ultraskill_UI_001","title":"Сверхспособность I","description":"Всё внимание на мне — и я его не упущу!","language":"Японский","audioUrl":"/nte-meta/game-audio/e009ad742badaccd0815.ogg"},{"id":"ko-Play_Vo_Char_NPC023_DodgeCombo_002","title":"Серия критических уклонений II","description":"Не совсем в ноту.","language":"Корейский","audioUrl":"/nte-meta/game-audio/bf70d787a84b93b61c18.ogg"},{"id":"ko-Play_Vo_Char_NPC023_SSC_HY_001","title":"Особое переключение: Аурелия","description":"Как в старые добрые времена, подруга.","language":"Корейский","audioUrl":"/nte-meta/game-audio/410b207aeb486dd7fd52.ogg"},{"id":"ja-Play_Vo_Char_NPC023_QTE_003","title":"Атака на входе III","description":"Как раз вовремя.","language":"Японский","audioUrl":"/nte-meta/game-audio/b96fc4ff1d95d0ad5c93.ogg"},{"id":"ja-Play_Vo_Char_NPC023_SSC_HY_001","title":"Особое переключение: Аурелия","description":"Как в старые добрые времена, подруга.","language":"Японский","audioUrl":"/nte-meta/game-audio/650356d8fc26e89500a5.ogg"},{"id":"ja-Play_Vo_Char_NPC023_TeammateDown_004","title":"Поражен товарищ по команде – Ханиэль","description":"Отдохни. Я тебя подменю.","language":"Японский","audioUrl":"/nte-meta/game-audio/73cb8cd31cb4a764ffbb.ogg"},{"id":"zh-Play_Vo_Char_NPC023_chat_003","title":"Чат: наушники","description":"В наши дни многие предпочитают беспроводные наушники, но я всё равно считаю, что проводные и выглядят лучше, и работают надёжнее. Судзуха постоянно меня подкалывает: мол, разъём для наушников уже давно стал пережитком прошлого… Неужели всё настолько плохо?","language":"Китайский","audioUrl":"/nte-meta/game-audio/c4e8b16b5533ea5424cb.ogg"},{"id":"zh-Play_Vo_Char_NPC023_greet_003","title":"Вечернее приветствие","description":"Фуух, ещё один рабочий день позади. Может, побаловать себя вкусняшкой?","language":"Китайский","audioUrl":"/nte-meta/game-audio/365ef2693c607278eeed.ogg"},{"id":"zh-Play_Vo_Char_NPC023_SSC_HY_001","title":"Особое переключение: Аурелия","description":"Как в старые добрые времена, подруга.","language":"Китайский","audioUrl":"/nte-meta/game-audio/befc7bcc0520f59f1072.ogg"},{"id":"en-Play_Vo_Char_NPC023_about_002","title":"О «КОШАЧЬЕМ КОНЦЕРТЕ!!!!»","description":"«Шумная Совушка, громкий Котёнок — скорее цирк, чем группа». Вот что я подумала, когда Ханиэль сказала, что хочет создать группу. Пфф… Никогда бы не подумала, что у нас и правда получится, не говоря уже о том, что мы ещё и отыграли успешные концерты. Наверное, в этом и есть смысл группы — это место, где сбывается любая мечта, какой бы нелепой она ни была.","language":"Английский","audioUrl":"/nte-meta/game-audio/ce339f13f41d418f148a.ogg"},{"id":"ko-Play_Vo_Char_NPC023_gift_004","title":"Подарок получен IV","description":"В следующий раз, как заглянешь в «Звёздный знак», угощаю.","language":"Корейский","audioUrl":"/nte-meta/game-audio/32b74425da793835caf2.ogg"},{"id":"ko-Play_Vo_Char_NPC023_Switch_001","title":"Переключение I","description":"Моё соло!","language":"Корейский","audioUrl":"/nte-meta/game-audio/7a228fa30274d7e99add.ogg"},{"id":"ko-Play_Vo_Char_NPC023_ultraskill_UI_001","title":"Сверхспособность I","description":"Всё внимание на мне — и я его не упущу!","language":"Корейский","audioUrl":"/nte-meta/game-audio/2160fc236faf09eb13ac.ogg"},{"id":"zh-Play_Vo_Char_NPC023_hp_001","title":"Низкий уровень здоровья I","description":"Ещё чуть-чуть…","language":"Китайский","audioUrl":"/nte-meta/game-audio/dce965f90477cabc4092.ogg"},{"id":"en-Play_Vo_Char_NPC023_DodgeCombo_001","title":"Серия критических уклонений I","description":"Сможешь поспеть за моим ритмом?","language":"Английский","audioUrl":"/nte-meta/game-audio/8c1189cabeb1f5281460.ogg"},{"id":"en-Play_Vo_Char_NPC023_ug_003","title":"Вознесение персонажа III","description":"Время новой песни.","language":"Английский","audioUrl":"/nte-meta/game-audio/3d9228b2d15dfce7f4c0.ogg"},{"id":"ja-Play_Vo_Char_NPC023_hp_002","title":"Низкий уровень здоровья II","description":"Мой голос… слабеет…","language":"Японский","audioUrl":"/nte-meta/game-audio/46311bc44864aaf7738d.ogg"},{"id":"ja-Play_Vo_Char_NPC023_kill_002","title":"Убийство II","description":"Шоу окончено.","language":"Японский","audioUrl":"/nte-meta/game-audio/30237e859c81d9d53161.ogg"},{"id":"ko-Play_Vo_Char_NPC023_chat_003","title":"Чат: наушники","description":"В наши дни многие предпочитают беспроводные наушники, но я всё равно считаю, что проводные и выглядят лучше, и работают надёжнее. Судзуха постоянно меня подкалывает: мол, разъём для наушников уже давно стал пережитком прошлого… Неужели всё настолько плохо?","language":"Корейский","audioUrl":"/nte-meta/game-audio/6655ef67b7d5ef0ed3b1.ogg"},{"id":"zh-Play_Vo_Char_NPC023_dead_003","title":"Потеря сознания III","description":"Снова покидаю сцену…?","language":"Китайский","audioUrl":"/nte-meta/game-audio/0ff329969e9c4b92c91d.ogg"},{"id":"zh-Play_Vo_Char_NPC023_struck_002","title":"Урон II","description":"Не так уж и больно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c3652fe532638ae7b08a.ogg"},{"id":"en-Play_Vo_Char_NPC023_Fly_001","title":"Планирование I","description":"Я могу коснуться звёзд?","language":"Английский","audioUrl":"/nte-meta/game-audio/c80cecc2a2d6c98338c4.ogg"},{"id":"ja-Play_Vo_Char_NPC023_chat_003","title":"Чат: наушники","description":"В наши дни многие предпочитают беспроводные наушники, но я всё равно считаю, что проводные и выглядят лучше, и работают надёжнее. Судзуха постоянно меня подкалывает: мол, разъём для наушников уже давно стал пережитком прошлого… Неужели всё настолько плохо?","language":"Японский","audioUrl":"/nte-meta/game-audio/d22cd6001cfe1f6a445d.ogg"},{"id":"ja-Play_Vo_Char_NPC023_Fly_001","title":"Планирование I","description":"Я могу коснуться звёзд?","language":"Японский","audioUrl":"/nte-meta/game-audio/afaecaedfec024ebf3a0.ogg"},{"id":"zh-Play_Vo_Char_NPC023_hstruck_001","title":"Сильный урон I","description":"Ай, щиплет.","language":"Китайский","audioUrl":"/nte-meta/game-audio/6312675fcdbbb2e9f113.ogg"},{"id":"en-Play_Vo_Char_NPC023_meet_001","title":"Первая встреча","description":"Йоу, это Аканэ. Представляться вообще нужно? Мы же и так отлично сработались в группе. Нам всё нипочём, правда?","language":"Английский","audioUrl":"/nte-meta/game-audio/30758e6f21b8fd0c3e55.ogg"},{"id":"en-Play_Vo_Char_NPC023_TeammateDown_001","title":"Поражён товарищ по команде: Аурелия","description":"Я этого больше не допущу.","language":"Английский","audioUrl":"/nte-meta/game-audio/911ec7bfef8388999240.ogg"},{"id":"en-Play_Vo_Char_NPC023_TeammateDown_004","title":"Поражен товарищ по команде – Ханиэль","description":"Отдохни. Я тебя подменю.","language":"Английский","audioUrl":"/nte-meta/game-audio/1d2d8f77b9e48be83601.ogg"},{"id":"ko-Play_Vo_Char_NPC023_gift_003","title":"Подарок получен III","description":"Для меня? Спасибо. Мне очень нравится.","language":"Корейский","audioUrl":"/nte-meta/game-audio/47b439e20e0262f318c7.ogg"},{"id":"ko-Play_Vo_Char_NPC023_hp_001","title":"Низкий уровень здоровья I","description":"Ещё чуть-чуть…","language":"Корейский","audioUrl":"/nte-meta/game-audio/9bd05a34c681ac1fab4a.ogg"},{"id":"ko-Play_Vo_Char_NPC023_ug_001","title":"Вознесение персонажа I","description":"Восходящая гамма!","language":"Корейский","audioUrl":"/nte-meta/game-audio/9860d61a995c3199d8aa.ogg"},{"id":"zh-Play_Vo_Char_NPC023_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Лучший дуэт!","language":"Китайский","audioUrl":"/nte-meta/game-audio/b12262a4a2c3aaf6b249.ogg"},{"id":"en-Play_Vo_Char_NPC023_Parry_002","title":"Парирование II","description":"Поймала ритм!","language":"Английский","audioUrl":"/nte-meta/game-audio/edd6266f36adbd7f1d05.ogg"},{"id":"en-Play_Vo_Char_NPC023_weather_002","title":"Дождливо","description":"В дождливые дни стоит быть особенно осторожными. Гитарные струны могут быстро заржаветь.","language":"Английский","audioUrl":"/nte-meta/game-audio/5af4e96e11b0e48a6a2f.ogg"},{"id":"ja-Play_Vo_Char_NPC023_fh_001","title":"Исцеление I","description":"Снова на сцену!","language":"Японский","audioUrl":"/nte-meta/game-audio/ef3fdfc7d52a6ea7a69f.ogg"},{"id":"ja-Play_Vo_Char_NPC023_weather_003","title":"Холодно","description":"Бр-р-р, холодно-то как. Давай где-нибудь выпьем горячего шоколада.","language":"Японский","audioUrl":"/nte-meta/game-audio/aa30d9d45fe4ecd3e864.ogg"},{"id":"ko-Play_Vo_Char_NPC023_TeammateDown_004","title":"Поражен товарищ по команде – Ханиэль","description":"Отдохни. Я тебя подменю.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ed9c56cf3efea7c43b77.ogg"},{"id":"ko-Play_Vo_Char_NPC023_weather_004","title":"Жарко","description":"Жарища… Я весь день буду сидеть в комнате с кондеем.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1b060a4fe325bb71ed43.ogg"},{"id":"zh-Play_Vo_Char_NPC023_kill_001","title":"Убийство I","description":"Эта песня для тебя.","language":"Китайский","audioUrl":"/nte-meta/game-audio/4fcb2b0542671d18cfe2.ogg"},{"id":"zh-Play_Vo_Char_NPC023_kill_002","title":"Убийство II","description":"Шоу окончено.","language":"Китайский","audioUrl":"/nte-meta/game-audio/42bc39d3afbcb739f0d7.ogg"},{"id":"en-Play_Vo_Char_NPC023_hp_003","title":"Низкий уровень здоровья III","description":"Мне нужно передохнуть…","language":"Английский","audioUrl":"/nte-meta/game-audio/c99c7655f3915a876b1a.ogg"},{"id":"ja-Play_Vo_Char_NPC023_Parry_002","title":"Парирование II","description":"Поймала ритм!","language":"Японский","audioUrl":"/nte-meta/game-audio/48b628d3a9dab79a8776.ogg"},{"id":"ko-Play_Vo_Char_NPC023_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Отличное выступление. Отдохни немного.","language":"Корейский","audioUrl":"/nte-meta/game-audio/eed69641d57e8a471397.ogg"},{"id":"ja-Play_Vo_Char_NPC023_weather_001","title":"Солнечно","description":"Какая хорошая погода. Я слишком много времени провожу в «Звёздном знаке». Мне бы не помешало иногда выходить на улицу.","language":"Японский","audioUrl":"/nte-meta/game-audio/61ad0d16d81ab7a4fa44.ogg"},{"id":"ko-Play_Vo_Char_NPC023_greet_002","title":"Дневное приветствие","description":"Не хочу сегодня есть на работе. Давай лучше перекусим чем-нибудь вкусненьким. Я угощаю.","language":"Корейский","audioUrl":"/nte-meta/game-audio/3855130c35aa2de4c507.ogg"},{"id":"ja-Play_Vo_Char_NPC023_gift_002","title":"Подарок получен II","description":"Какой подарок — просто прелесть… Буду бережно хранить его в своей витрине.","language":"Японский","audioUrl":"/nte-meta/game-audio/1c3888e50cf357ed7742.ogg"},{"id":"ko-Play_Vo_Char_NPC023_fh_002","title":"Исцеление II","description":"Мне уже лучше.","language":"Корейский","audioUrl":"/nte-meta/game-audio/9940710b5980873d0fe3.ogg"},{"id":"ko-Play_Vo_Char_NPC023_greet_003","title":"Вечернее приветствие","description":"Фуух, ещё один рабочий день позади. Может, побаловать себя вкусняшкой?","language":"Корейский","audioUrl":"/nte-meta/game-audio/786905a854c1f9822bf3.ogg"},{"id":"ko-Play_Vo_Char_NPC023_ultraskill_UI_002","title":"Сверхспособность II","description":"Сцена готова. Пусть звёзды сияют!","language":"Корейский","audioUrl":"/nte-meta/game-audio/dab084c208cf9556f980.ogg"}]'))) WHERE character_id='akane' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 16:33:23');

UPDATE character_profiles SET abilities_json=json('[{"id":"f75991d9-4d92-4c86-918b-bc00f6e3036e","name":"Струнный клинок","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/23c20db8531648abd235.webp","description":"Даже самый простой удар по струнам способен пробудить бурю в душе.","attributes":[{"id":"parameter-0","label":"Базовый множитель урона 1-го удара «Струнным клинком» и получаемая Струнная энергия","value":"1: 14.9 % *2, 1 · 2: 16.1 % *2, 1 · 3: 17.4 % *2, 1 · 4: 18.8 % *2, 1 · 5: 20.3 % *2, 1 · 6: 21.9 % *2, 1 · 7: 23.6 % *2, 1 · 8: 25.5 % *2, 1 · 9: 27.6 % *2, 1 · 10: 29.8 % *2, 1 · 11: 32.2 % *2, 1 · 12: 34.7 % *2, 1 · 13: 37.5 % *2, 1"},{"id":"parameter-1","label":"Базовый множитель урона 2-го удара «Струнным клинком» и получаемая Струнная энергия","value":"1: 21.9 % *2, 1 · 2: 23.7 % *2, 1 · 3: 25.5 % *2, 1 · 4: 27.6 % *2, 1 · 5: 29.8 % *2, 1 · 6: 32.2 % *2, 1 · 7: 34.8 % *2, 1 · 8: 37.5 % *2, 1 · 9: 40.5 % *2, 1 · 10: 43.8 % *2, 1 · 11: 47.3 % *2, 1 · 12: 51.1 % *2, 1 · 13: 55.1 % *2, 1"},{"id":"parameter-2","label":"Базовый множитель урона 3-го удара «Струнным клинком» и получаемая Струнная энергия","value":"1: 10.3 % *3 + 13.5 % *4, 2 · 2: 11.1 % *3 + 14.6 % *4, 2 · 3: 12 % *3 + 15.7 % *4, 2 · 4: 13 % *3 + 17 % *4, 2 · 5: 14 % *3 + 18.4 % *4, 2 · 6: 15.1 % *3 + 19.8 % *4, 2 · 7: 16.3 % *3 + 21.4 % *4, 2 · 8: 17.7 % *3 + 23.1 % *4, 2 · 9: 19.1 % *3 + 25 % *4, 2 · 10: 20.6 % *3 + 27 % *4, 2 · 11: 22.2 % *3 + 29.1 % *4, 2 · 12: 24 % *3 + 31.5 % *4, 2 · 13: 25.9 % *3 + 34 % *4, 2"},{"id":"parameter-3","label":"Базовый множитель урона 4-го удара «Струнным клинком» и получаемая Струнная энергия","value":"1: 424.7 %, 6 · 2: 458.7 %, 6 · 3: 495.4 %, 6 · 4: 535 %, 6 · 5: 577.8 %, 6 · 6: 624 %, 6 · 7: 673.9 %, 6 · 8: 727.9 %, 6 · 9: 786.1 %, 6 · 10: 849 %, 6 · 11: 916.9 %, 6 · 12: 990.2 %, 6 · 13: 1069.5 %, 6"},{"id":"parameter-5","label":"Множитель урона атаки в падении & полученная Струнная энергия","value":"1: 62.5 %, 1 · 2: 67.5 %, 1 · 3: 72.9 %, 1 · 4: 78.7 %, 1 · 5: 85 %, 1 · 6: 91.8 %, 1 · 7: 99.2 %, 1 · 8: 107.1 %, 1 · 9: 115.7 %, 1 · 10: 124.9 %, 1 · 11: 134.9 %, 1 · 12: 145.7 %, 1 · 13: 157.4 %, 1"},{"id":"parameter-6","label":"Множитель критического контрудара и получаемая Струнная энергия","value":"1: 137.5 %, 2 · 2: 148.5 %, 2 · 3: 160.4 %, 2 · 4: 173.2 %, 2 · 5: 187.1 %, 2 · 6: 202 %, 2 · 7: 218.2 %, 2 · 8: 235.7 %, 2 · 9: 254.5 %, 2 · 10: 274.9 %, 2 · 11: 296.9 %, 2 · 12: 320.6 %, 2 · 13: 346.2 %, 2"}]},{"id":"f66d9ae1-f9be-42a8-872d-bc4678c13675","name":"Ритмическая волна","type":"Навык","iconUrl":"/nte-meta/game-assets/f009892b425f141ccc05.webp","description":"Навык «Ритмическая волна» Аканэ Рин можно применять двумя способами. Нажатие: накладывает Обертон на цель на 25 сек. и наносит урон лакшаны. Когда Аканэ Рин выполняет базовую атаку, Обертон резонирует: базовая атака переносится на дальнее расстояние и поражает цель под этим эффектом, при этом множитель урона перенесённой базовой атаки увеличивается на 32,5 %. Удерживание: создаёт Поле реверберации на 25 сек. и наносит урон лакшаны врагам в радиусе действия. Когда Аканэ Рин выполняет базовую атаку, Поле реверберации резонирует: базовая атака передаётся через поле, нанося 1 удар урона базовой атаки всем врагам в радиусе действия, при этом урон перенесённой базовой атаки увеличивается ещё на 36 %. На поле боя может существовать только один эффект — либо Обертон, либо Поле реверберации. Успешное создание новой формы заменяет собой предыдущую. Оба способа активации имеют общую перезарядку. Как только время перезарядки истекает, вы можете снова выбрать любую из форм. Доступ к навыку «Синхронизированный резонанс» открывается, когда Струнная энергия достигает 30 ед. и действует Обертон или Поле реверберации. Активирует усиленный эффект в зависимости от текущей формы: Обертон: наносит 1 удар огромного урона лакшаны по одной цели. Поле реверберации: наносит 1 удар усиленного урона лакшаны с эффектом разброса врагам в радиусе действия. Попадание «Синхронизированным резонансом» расходует 30 ед. Струнной энергии; в случае промаха энергия не тратится. При этом текущий Обертон или Поле реверберации сохраняются, но оставшееся время их действия не обновляется. «Синхронизированный резонанс» не имеет собственной перезарядки и не влияет на обычную перезарядку «Ритмической волны». «Синхронизированный резонанс» невозможно применить, если не активен ни Обертон, ни Поле реверберации — сначала необходимо создать один из эффектов с помощью «Ритмической волны».","attributes":[{"id":"parameter-0","label":"Множитель урона Обертона и получаемая Струнная энергия","value":"1: 360 %, 6 · 2: 388.8 %, 6 · 3: 419.9 %, 6 · 4: 453.5 %, 6 · 5: 489.8 %, 6 · 6: 529 %, 6 · 7: 571.3 %, 6 · 8: 617 %, 6 · 9: 666.3 %, 6 · 10: 719.6 %, 6 · 11: 777.2 %, 6 · 12: 839.4 %, 6 · 13: 906.5 %, 6"},{"id":"parameter-2","label":"Множитель урона Поля реверберации и получаемая Струнная энергия","value":"1: 162 % *2, 6 · 2: 175 % *2, 6 · 3: 189 % *2, 6 · 4: 204.1 % *2, 6 · 5: 220.4 % *2, 6 · 6: 238 % *2, 6 · 7: 257.1 % *2, 6 · 8: 277.6 % *2, 6 · 9: 299.9 % *2, 6 · 10: 323.8 % *2, 6 · 11: 349.7 % *2, 6 · 12: 377.7 % *2, 6 · 13: 407.9 % *2, 6"},{"id":"parameter-4","label":"Обертон: множитель урона «Синхронизированного резонанса»","value":"1: 1125 % · 2: 1215 % · 3: 1312.2 % · 4: 1417.2 % · 5: 1530.6 % · 6: 1653 % · 7: 1785.2 % · 8: 1928.1 % · 9: 2082.3 % · 10: 2248.9 % · 11: 2428.8 % · 12: 2623.1 % · 13: 2832.9 %"},{"id":"parameter-7","label":"Поле реверберации: множитель урона «Синхронизированного резонанса»","value":"1: 1012.5 % · 2: 1093.5 % · 3: 1181 % · 4: 1275.5 % · 5: 1377.5 % · 6: 1487.7 % · 7: 1606.7 % · 8: 1735.2 % · 9: 1874.1 % · 10: 2024 % · 11: 2185.9 % · 12: 2360.8 % · 13: 2549.6 %"}]},{"id":"GA_Akane_UltraSkill_End_name","name":"Звуковой удар","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/fef649cbf515bb5b2cc6.webp","description":"Аканэ Рин применяет первый этап «Звукового удара», нанося несколько ударов с огромным уроном лакшаны врагам в целевой области, и входит в состояние «Сольная каденция» на 20 сек. Пока это состояние активно, её устойчивость к прерываниям повышается.\n\nСпустя 4 сек. после применения «Сольной каденции» повторное нажатие кнопки навыка «Звуковой удар» позволяет в любой момент применить второй этап навыка, что досрочно завершает действие «Сольной каденции» и наносит 1 удар с огромным уроном лакшаны врагам в целевой области. Второй этап необходимо применять вручную. По окончании «Сольной каденции» он не применяется автоматически. Если второй этап не был применён до завершения «Сольной каденции», он становится недоступным.\n\n«Сольная каденция» действует независимо от Обертона и Поля реверберации и не снимает и не заменяет ни один из этих эффектов.\n\nНаходясь вне боя, Аканэ Рин восстанавливает по 3 ед. энергии сверхспособности в секунду.","attributes":[{"id":"parameter-0","label":"Множитель урона 1-го этапа","value":"1: 64.8 % *10 · 2: 70 % *10 · 3: 75.6 % *10 · 4: 81.6 % *10 · 5: 88.2 % *10 · 6: 95.2 % *10 · 7: 102.8 % *10 · 8: 111.1 % *10 · 9: 119.9 % *10 · 10: 129.5 % *10 · 11: 139.9 % *10 · 12: 151.1 % *10 · 13: 163.2 % *10"},{"id":"parameter-1","label":"Множитель урона 2-го этапа","value":"1: 918 % · 2: 991.4 % · 3: 1070.8 % · 4: 1156.4 % · 5: 1248.9 % · 6: 1348.8 % · 7: 1456.8 % · 8: 1573.3 % · 9: 1699.2 % · 10: 1835.1 % · 11: 1981.9 % · 12: 2140.4 % · 13: 2311.7 %"}]},{"id":"GA_Akane_QTE_name","name":"Альтерированный аккорд","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/e528a3ac414ad4ce9546.webp","description":"Аканэ Рин мощно проводит по струнам и 1 раз наносит урон лакшаны.","attributes":[{"id":"parameter-0","label":"Множитель урона и получаемая Струнная энергия","value":"1: 200 %, 4 · 2: 216 %, 4 · 3: 233.3 %, 4 · 4: 251.9 %, 4 · 5: 272.1 %, 4 · 6: 293.9 %, 4 · 7: 317.4 %, 4 · 8: 342.8 %, 4 · 9: 370.2 %, 4 · 10: 399.8 %, 4 · 11: 431.8 %, 4 · 12: 466.3 %, 4 · 13: 503.6 %, 4"}]},{"id":"GA_Akane_Passive1_name","name":"Абсолютный слух","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/a153c7ecd5c868b57040.webp","description":"Усиление Реморы: когда отряд впервые активирует эффект «Ремора», Аканэ Рин получает усиление, которое действует до тех пор, пока она не покинет бой. Каждые 3 сек. накладывает Ремору на цель под действием Обертона и на всех врагов внутри Поля реверберации.\n\nКаждый раз, когда отряд повторно накладывает Ремору на уже поражённую цель, Аканэ Рин наносит урон лакшаны (считается уроном от навыка перенаправления) в размере 150 % от показателя атаки Аканэ Рин. Этот урон увеличивается на 20 % за каждую 1 сек. оставшегося времени действия Реморы на цели (максимальное увеличение — 160 %).\n\nОставшееся время действия Реморы рассчитывается для каждой цели индивидуально. Этот урон может срабатывать на одной цели не чаще одного раза в 1 сек.","attributes":[]},{"id":"GA_Akane_Passive2_name","name":"Звёздный гимн","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/a153c7ecd5c868b57040.webp","description":"Увеличивает атаку Аканэ Рин на 20 % в течение 20 сек. после применения «Звукового удара». Эффект не складывается. При повторном срабатывании длительность обновляется.","attributes":[]},{"id":"GA_Akane_Skill_Gitar_name","name":"Играть по слуху","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/f009892b425f141ccc05.webp","description":"В открытом мире Аканэ Рин может в любой момент взять в руки гитару и сыграть любую мелодию, которая придёт ей в голову.","attributes":[]},{"id":"City_Ability_Akane_01","name":"Фирменный коктейль","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/2ec38429b2b7dc4bfe65.webp","description":"Аканэ Рин увеличивает поток посетителей на 18.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Аканэ Рин увеличивает поток посетителей на 18."},{"id":"city-1","label":"Уровень 2","value":"Аканэ Рин снижает скорость расхода ингредиентов на 1 %."},{"id":"city-2","label":"Уровень 3","value":"Аканэ Рин увеличивает поток посетителей на 18."},{"id":"city-3","label":"Уровень 4","value":"Аканэ Рин снижает скорость расхода ингредиентов на 1 %."},{"id":"city-4","label":"Уровень 5","value":"Аканэ Рин увеличивает поток посетителей на 27."}]},{"id":"City_Ability_Akane_02","name":"Блистательный кумир","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/e3dcd8b30da1ff381602.webp","description":"«Суперзвук» расходует на 1 ед. больше выносливости в городе за один забег.","attributes":[{"id":"city-0","label":"Уровень 1","value":"«Суперзвук» расходует на 1 ед. больше выносливости в городе за один забег."},{"id":"city-1","label":"Уровень 2","value":"«Суперзвук» расходует на 1 ед. больше выносливости в городе за один забег."}]}]') WHERE character_id='akane' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 16:33:23');

UPDATE character_profiles SET updated_at=CURRENT_TIMESTAMP WHERE character_id='akane' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 16:33:23');

UPDATE character_profiles SET voice_actors_json=json('[{"language":"Китайский","name":"葛子瑞"},{"language":"Английский","name":"Kira Buckland"},{"language":"Японский","name":"高橋花林"},{"language":"Корейский","name":"정해은"},{"language":"Китайский","name":"Ge Zirui (葛子瑞)"},{"language":"Японский","name":"Karin Takahashi (高橋花林)"},{"language":"Корейский","name":"Jeong Hae-eun (정해은)"}]') WHERE character_id='aurelia' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:07:15');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"zh-Play_Vo_Char_NPC1029_windfall_001","title":"Неожиданная добыча I","description":"Вполне неплохо.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b2f89686cb4a25bd2bad.ogg"},{"id":"en-Play_Vo_Char_NPC1029_self_002","title":"Обо мне: реабилитация","description":"Врач сказал, что вряд ли я когда-нибудь полностью поправлюсь. Но если я не брошу реабилитацию и лечение, может быть, однажды смогу снова встать на ноги. Тебе может показаться, что это лишь несбыточная мечта и я глупо поступаю, цепляясь за неё… но я верю, что пока жизнь не подошла к концу, возможно всё. Если случится чудо, а я окажусь к нему не готова — разве не будет обидно?","language":"Английский","audioUrl":"/nte-meta/game-audio/5fa5be1939c2acff0e2d.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_Fly_001","title":"Планирование I","description":"Как птица.","language":"Корейский","audioUrl":"/nte-meta/game-audio/21d735fa9cc5964749ea.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_containment_001","title":"Сдерживание I","description":"Хе-хе, попался!","language":"Китайский","audioUrl":"/nte-meta/game-audio/1115605fda45e0850733.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_hobby_001","title":"Хобби","description":"Ой, да много всего! Я обожаю пробовать всё новое, правда, быстро теряю интерес… Но если и есть что-то, что осталось со мной надолго, так это созерцание моря. Далёкая линия горизонта, где небо встречается с водой, и мерный ритм волн… это так успокаивает. Словно я — крошечная нота в огромном вечном хоре… Все тревоги исчезают, когда я смотрю на море.","language":"Японский","audioUrl":"/nte-meta/game-audio/b25d3270d57514055395.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_anomaly_003","title":"Нуллификация I","description":"Надеюсь, следующая аномалия будет такой же простой.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6f3fcc3bb084c476c94c.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_DodgeCombo_001","title":"Серия критических уклонений I","description":"А мы быстрые, знаешь ли!","language":"Корейский","audioUrl":"/nte-meta/game-audio/1f563adefb3bdb1d65da.ogg"},{"id":"en-Play_Vo_Char_NPC1029_containment_001","title":"Сдерживание I","description":"Хе-хе, попался!","language":"Английский","audioUrl":"/nte-meta/game-audio/f61e1c6d01f46ca55fdf.ogg"},{"id":"en-Play_Vo_Char_NPC1029_dead_001","title":"Потеря сознания I","description":"Нужно… снова… выйти на сцену…","language":"Английский","audioUrl":"/nte-meta/game-audio/dfa97410d23359dfbd36.ogg"},{"id":"en-Play_Vo_Char_NPC1029_struck_001","title":"Урон I","description":"Со мной всё нормально.","language":"Английский","audioUrl":"/nte-meta/game-audio/e788c590c844e21b97c7.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_Fly_001","title":"Планирование I","description":"Как птица.","language":"Японский","audioUrl":"/nte-meta/game-audio/476857a8e6d8c51d7c2d.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_SSC_MY_001","title":"Особое переключение: Аканэ","description":"Аканэ, антракт!","language":"Японский","audioUrl":"/nte-meta/game-audio/31f1ad1c4b6ec621c6c7.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_self_003","title":"Обо мне: деликатесы","description":"На улице Тамамочи, где я работаю, полно отличных забегаловок. Жареная утка «У Дина» — всегда с хрустящей корочкой и нежная внутри; рамен в лапшичной «Некомару» просто чудесный, но с горячим бульоном нужно быть поосторожнее. А моё любимое — это булочки с кремом из «Большого баоцзы». Обожаю в холодные дни держать в руках горячую булочку, откусить кусочек и почувствовать тёплую, ароматную сладость внутри… настоящее блаженство. Правда, если я съем слишком много и прибавлю в весе, моей медузе станет тяжело меня носить… Похоже, придётся держать себя в руках.","language":"Китайский","audioUrl":"/nte-meta/game-audio/cd4b3137b426f72a4f95.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_gift_004","title":"Подарок получен IV","description":"Какой особенный подарок!.. Сегодня какой-то важный день?","language":"Корейский","audioUrl":"/nte-meta/game-audio/075caf6315bb12559de1.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_hstruck_002","title":"Сильный урон II","description":"Нельзя расслабляться…","language":"Корейский","audioUrl":"/nte-meta/game-audio/c1cf0fed2e6752e8fc0f.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_anomaly_003","title":"Нуллификация I","description":"Надеюсь, следующая аномалия будет такой же простой.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7ac71e1dd31594c3332b.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_self_002","title":"Обо мне: реабилитация","description":"Врач сказал, что вряд ли я когда-нибудь полностью поправлюсь. Но если я не брошу реабилитацию и лечение, может быть, однажды смогу снова встать на ноги. Тебе может показаться, что это лишь несбыточная мечта и я глупо поступаю, цепляясь за неё… но я верю, что пока жизнь не подошла к концу, возможно всё. Если случится чудо, а я окажусь к нему не готова — разве не будет обидно?","language":"Китайский","audioUrl":"/nte-meta/game-audio/ebd97dc5d7bcd53095a5.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_chat_001","title":"Чат: совет","description":"Никогда не надевай широкие штаны, если садишься за барабаны! Если сильно ударишь по педали, штанина может легко запутаться в колотушке бас-бочки…","language":"Японский","audioUrl":"/nte-meta/game-audio/3157a3474dbc4db91027.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_Parry_002","title":"Парирование II","description":"Точно в ритм!","language":"Японский","audioUrl":"/nte-meta/game-audio/5e5ea00e61289d42bade.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_fh_002","title":"Исцеление II","description":"Фух, намного лучше.","language":"Корейский","audioUrl":"/nte-meta/game-audio/558e79d3c1fe397bdd0e.ogg"},{"id":"en-Play_Vo_Char_NPC1029_hstruck_001","title":"Сильный урон I","description":"Всё в порядке… мне не больно.","language":"Английский","audioUrl":"/nte-meta/game-audio/a94948730d1e23aa63ad.ogg"},{"id":"en-Play_Vo_Char_NPC1029_struck_002","title":"Урон II","description":"Да это всего лишь царапина.","language":"Английский","audioUrl":"/nte-meta/game-audio/247b4156bc259a6cab1e.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_dead_003","title":"Потеря сознания III","description":"Только не так…","language":"Японский","audioUrl":"/nte-meta/game-audio/035d2923146228da6424.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Хорошо поспал? Доброе утро! Хорошо поспала?","language":"Японский","audioUrl":"/nte-meta/game-audio/a8b59eba66544d216ff6.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_aoe_UI_001","title":"Сверхспособность I","description":"Кружись в полёте галактик.","language":"Корейский","audioUrl":"/nte-meta/game-audio/de3be4829daf1d92165c.ogg"},{"id":"en-Play_Vo_Char_NPC1029_greet_003","title":"Вечернее приветствие","description":"Закат завораживает. Может, сходить на побережье, пока солнце ещё не село?","language":"Английский","audioUrl":"/nte-meta/game-audio/564141319dee028a30d6.ogg"},{"id":"en-Play_Vo_Char_NPC1029_QTE_002","title":"Атака на входе II","description":"Занять позиции!","language":"Английский","audioUrl":"/nte-meta/game-audio/d8ebb979b4ecd537fab7.ogg"},{"id":"en-Play_Vo_Char_NPC1029_SSC_MY_001","title":"Особое переключение: Аканэ","description":"Аканэ, антракт!","language":"Английский","audioUrl":"/nte-meta/game-audio/0941c7185ba90a76fa88.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_fh_001","title":"Исцеление I","description":"А теперь — песня на бис!","language":"Корейский","audioUrl":"/nte-meta/game-audio/6c9f5b27f60ddf0c94ec.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_anomaly_004","title":"Нуллификация II","description":"Миссия выполнена. Спасибо за помощь!","language":"Китайский","audioUrl":"/nte-meta/game-audio/81666b99c1448a1600ee.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_Parry_001","title":"Парирование I","description":"Уф, пронесло!","language":"Китайский","audioUrl":"/nte-meta/game-audio/c05447f2d9a2aefdb13f.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_windfall_003","title":"Неожиданная добыча III","description":"Выглядит как что-то годное.","language":"Китайский","audioUrl":"/nte-meta/game-audio/93bf069d5bb8c89c0d8d.ogg"},{"id":"en-Play_Vo_Char_NPC1029_talk_001","title":"Тема: медузы","description":"Время от времени на берегу можно найти медуз, которых выбросило отступающим приливом, — может, они тоже сбились с пути… Если увидишь медузу на пляже, пожалуйста, не трогай её. Они могут казаться мягкими и безобидными, но многие из них ядовиты. Ой, но те, что со мной, совершенно безобидные, так что не переживай!","language":"Английский","audioUrl":"/nte-meta/game-audio/7319e6f5f60e7c7a4c63.ogg"},{"id":"en-Play_Vo_Char_NPC1029_ug_001","title":"Вознесение персонажа I","description":"Освежает, как морской бриз!","language":"Английский","audioUrl":"/nte-meta/game-audio/001b89ca502741f3a7d4.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_gift_001","title":"Подарок получен I","description":"Какой продуманный подарок! Значит… мы уже настоящие друзья?","language":"Японский","audioUrl":"/nte-meta/game-audio/5cc39f8f0e6c8ae5fa89.ogg"},{"id":"en-Play_Vo_Char_NPC1029_about_001_02","title":"О «ЛИНИЯХ»","description":"Правда в том, что группа «ЛИНИИ» появилась не из желания играть музыку. Я просто хотела найти причину, чтобы мы трое не расставались после выпуска. Наверное, поэтому, когда я больше не могла играть, группа просто распалась… Но связи между людьми — это не только прямые линии — даже если одна точка пересечения исчезает, у нас всё равно остаётся шанс встретиться снова. Жаль, что я не поняла этого раньше… но даже сейчас ещё не слишком поздно.","language":"Английский","audioUrl":"/nte-meta/game-audio/b5c87f988fc6f0535774.ogg"},{"id":"en-Play_Vo_Char_NPC1029_deploy_002","title":"Отправка II","description":"Я тебе помогу.","language":"Английский","audioUrl":"/nte-meta/game-audio/97735c493f75397ae71e.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_aoe_UI_003","title":"Сверхспособность III","description":"Пусть мелодия расправит крылья!","language":"Японский","audioUrl":"/nte-meta/game-audio/e13dd6cbac1cea1031a4.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_self_001","title":"Обо мне: способности эспера","description":"Моя способность довольно слабая. Я могу управлять только медузами, но благодаря этим малышам я смогла вернуться к нормальной жизни. Когда я остаюсь одна, они составляют мне компанию, так что я никогда не чувствую себя одиноко. Поэтому я искренне благодарна за такую способность. Как говорится: «Лучшее для тебя — то, что тебе подходит». Всё просто.","language":"Японский","audioUrl":"/nte-meta/game-audio/277a67d02ad073c303ee.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_talk_002","title":"Тема: опасное вождение","description":"Эта медуза просто слишком большая, чтобы поместиться в большинстве видов транспорта. К счастью, она быстрая, так что даже если случится что-то срочное — не будет проблемы из-за того, что не смогу в машину сесть… Хм? Хочешь знать, насколько она быстрая? Ну… скажем так: недостаточно быстрая, чтобы офицер Усатик выписал мне штраф за превышение скорости при езде на медузе по городу.","language":"Японский","audioUrl":"/nte-meta/game-audio/1864cc6e473df694ef02.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_weather_004","title":"Жарко","description":"Так жарко… мои медузы совсем разомлели. Давай отдохнём в теньке.","language":"Японский","audioUrl":"/nte-meta/game-audio/94a099d86f9ca82412d5.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_about_001_01","title":"Об Аканэ","description":"Спасибо, что поддержал возвращение Аканэ на сцену. Для меня это тоже очень много значит. Ты ведь и сам барабанщик, так что наверняка понимаешь. Когда я смотрю на Аканэ со спины, она на сцене буквально сияет — будто рождена выступать… Отныне я буду болеть за «Кошачий концерт»!!!! ещё сильнее. И не забывай — я твоя фанатка номер один с самого первого концерта! Спасибо, что поддержала возвращение Аканэ на сцену. Для меня это тоже очень много значит. Ты ведь и сама барабанщица, так что наверняка понимаешь. Когда я смотрю на Аканэ со спины, она на сцене буквально сияет — будто рождена выступать… Отныне я буду болеть за «Кошачий концерт»!!!! ещё сильнее. И не забывай — я твоя фанатка номер один с самого первого концерта!","language":"Корейский","audioUrl":"/nte-meta/game-audio/75e12bbc0648c081d257.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_kill_002","title":"Убийство II","description":"Не недооценивай меня!","language":"Корейский","audioUrl":"/nte-meta/game-audio/a33d15fc708b958e515a.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_Parry_002","title":"Парирование II","description":"Точно в ритм!","language":"Корейский","audioUrl":"/nte-meta/game-audio/ad59188176d511a73e4f.ogg"},{"id":"en-Play_Vo_Char_NPC1029_meet_001","title":"Первая встреча","description":"Привет, меня зовут Аурелия… Ой, моя медуза тебя пугает? Прости, она просто так радуется встрече с новым другом… Надеюсь, ты не против. Хм? Тебе совсем не страшно? Вот и славно! Привет, меня зовут Аурелия… Ой, моя медуза тебя пугает? Прости, она просто так радуется встрече с новой подругой… Надеюсь, ты не против. Хм? Тебе совсем не страшно? Вот и славно!","language":"Английский","audioUrl":"/nte-meta/game-audio/0003d13073a0c4dd048d.ogg"},{"id":"en-Play_Vo_Char_NPC1029_vexation_001","title":"Проблемы","description":"Мой привычный навигатор в последнее время постоянно обновляется и жутко глючит. В итоге я теперь всё время теряюсь. На этой неделе я уже несколько раз опаздывала на подработку… Моя добрая начальница не стала вычитать это из зарплаты, но мне всё равно неловко… Наверное, стоит купить бумажную карту, пока приложение не починят.","language":"Английский","audioUrl":"/nte-meta/game-audio/99427173f0d08cdb3ea7.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_windfall_004","title":"Неожиданная добыча IV","description":"М-м, я сберегу это.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0d400ad67165022c8432.ogg"},{"id":"en-Play_Vo_Char_NPC1029_self_003","title":"Обо мне: деликатесы","description":"На улице Тамамочи, где я работаю, полно отличных забегаловок. Жареная утка «У Дина» — всегда с хрустящей корочкой и нежная внутри; рамен в лапшичной «Некомару» просто чудесный, но с горячим бульоном нужно быть поосторожнее. А моё любимое — это булочки с кремом из «Большого баоцзы». Обожаю в холодные дни держать в руках горячую булочку, откусить кусочек и почувствовать тёплую, ароматную сладость внутри… настоящее блаженство. Правда, если я съем слишком много и прибавлю в весе, моей медузе станет тяжело меня носить… Похоже, придётся держать себя в руках.","language":"Английский","audioUrl":"/nte-meta/game-audio/80af4e9d785686c5af93.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_dead_001","title":"Потеря сознания I","description":"Нужно… снова… выйти на сцену…","language":"Японский","audioUrl":"/nte-meta/game-audio/9c7489a2409865081f40.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_Parry_001","title":"Парирование I","description":"Уф, пронесло!","language":"Корейский","audioUrl":"/nte-meta/game-audio/324c673c3e097cc97ca6.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_self_003","title":"Обо мне: деликатесы","description":"На улице Тамамочи, где я работаю, полно отличных забегаловок. Жареная утка «У Дина» — всегда с хрустящей корочкой и нежная внутри; рамен в лапшичной «Некомару» просто чудесный, но с горячим бульоном нужно быть поосторожнее. А моё любимое — это булочки с кремом из «Большого баоцзы». Обожаю в холодные дни держать в руках горячую булочку, откусить кусочек и почувствовать тёплую, ароматную сладость внутри… настоящее блаженство. Правда, если я съем слишком много и прибавлю в весе, моей медузе станет тяжело меня носить… Похоже, придётся держать себя в руках.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5c14f03524cd1d57a0db.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_greet_003","title":"Вечернее приветствие","description":"Закат завораживает. Может, сходить на побережье, пока солнце ещё не село?","language":"Китайский","audioUrl":"/nte-meta/game-audio/511ee2e4639c26d02fd1.ogg"},{"id":"en-Play_Vo_Char_NPC1029_talk_002","title":"Тема: опасное вождение","description":"Эта медуза просто слишком большая, чтобы поместиться в большинстве видов транспорта. К счастью, она быстрая, так что даже если случится что-то срочное — не будет проблемы из-за того, что не смогу в машину сесть… Хм? Хочешь знать, насколько она быстрая? Ну… скажем так: недостаточно быстрая, чтобы офицер Усатик выписал мне штраф за превышение скорости при езде на медузе по городу.","language":"Английский","audioUrl":"/nte-meta/game-audio/5da844eb26c55b4a8485.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_ug_002","title":"Вознесение персонажа II","description":"Хм… могу лучше!","language":"Японский","audioUrl":"/nte-meta/game-audio/5fe9d90647f72e3f52cc.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_QTE_002","title":"Атака на входе II","description":"Занять позиции!","language":"Корейский","audioUrl":"/nte-meta/game-audio/e10fb61afa8671e2fe5e.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_ug_001","title":"Вознесение персонажа I","description":"Освежает, как морской бриз!","language":"Корейский","audioUrl":"/nte-meta/game-audio/e18154eae471b01700fb.ogg"},{"id":"en-Play_Vo_Char_NPC1029_hp_002","title":"Низкий уровень здоровья II","description":"Голова кругом…","language":"Английский","audioUrl":"/nte-meta/game-audio/02966aa9a48190f6e3a0.ogg"},{"id":"en-Play_Vo_Char_NPC1029_Parry_001","title":"Парирование I","description":"Уф, пронесло!","language":"Английский","audioUrl":"/nte-meta/game-audio/aaee2e5a754f35879ebc.ogg"},{"id":"en-Play_Vo_Char_NPC1029_QTE_003","title":"Атака на входе III","description":"Все в унисон!","language":"Английский","audioUrl":"/nte-meta/game-audio/5db4c9ac346ee5edd9e7.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_hp_003","title":"Низкий уровень здоровья III","description":"Уф… нельзя… проигрывать.","language":"Японский","audioUrl":"/nte-meta/game-audio/7ecad74767d7c0889de8.ogg"},{"id":"en-Play_Vo_Char_NPC1029_skill_001","title":"Навык перенаправления I","description":"Шоу начинается!","language":"Английский","audioUrl":"/nte-meta/game-audio/d941b61ff243ea1296c5.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_QTE_002","title":"Атака на входе II","description":"Занять позиции!","language":"Японский","audioUrl":"/nte-meta/game-audio/5a5eadceacbbeeb44fa6.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_ug_003","title":"Вознесение персонажа III","description":"Хе-хе, медузы пляшут.","language":"Японский","audioUrl":"/nte-meta/game-audio/6fb0e4354d44ce886e7b.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_gift_003","title":"Подарок получен III","description":"Спасибо! Я тоже подарок приготовлю — тебе точно понравится!","language":"Китайский","audioUrl":"/nte-meta/game-audio/bc1c47b8112fed914b07.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_windfall_005","title":"Неожиданная добыча V","description":"Чувствую, мне сегодня везёт. Если я куплю «Глоток свежести», дадут ещё один бесплатно?","language":"Китайский","audioUrl":"/nte-meta/game-audio/0f1082c284fbf812135a.ogg"},{"id":"en-Play_Vo_Char_NPC1029_DodgeCombo_002","title":"Серия критических уклонений II","description":"Идеальный ритм!","language":"Английский","audioUrl":"/nte-meta/game-audio/f7e4908e92ae41261141.ogg"},{"id":"en-Play_Vo_Char_NPC1029_weather_003","title":"Холодно","description":"Так холодно… Может, заскочить в «Безумный кот» за чем-нибудь горяченьким?..","language":"Английский","audioUrl":"/nte-meta/game-audio/d3a060e074152a6465d9.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_chat_003","title":"Чат: музыка","description":"У каждого музыкального жанра своё очарование, и каждая песня несёт в себе уникальные эмоции её автора. Но если ты спросишь про мою любимую группу… я не смогу выбрать какую-то одну. Давай я лучше составлю для тебя целый плейлист!","language":"Японский","audioUrl":"/nte-meta/game-audio/94a124487654f55a6959.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_SSC_MY_001","title":"Особое переключение: Аканэ","description":"Аканэ, антракт!","language":"Корейский","audioUrl":"/nte-meta/game-audio/5017de75e3fd1b484e7d.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_windfall_002","title":"Неожиданная добыча II","description":"Не забудь прихватить это!","language":"Корейский","audioUrl":"/nte-meta/game-audio/aa08b4e7a136b4a03b8d.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_gift_002","title":"Подарок получен II","description":"Ох, как раз то, что я хотела! Ты что, фея, исполняющая желания?","language":"Китайский","audioUrl":"/nte-meta/game-audio/aa373f4dcb82139a00b4.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_hp_003","title":"Низкий уровень здоровья III","description":"Уф… нельзя… проигрывать.","language":"Китайский","audioUrl":"/nte-meta/game-audio/aaaf0dfa5a6dd3ff72c9.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_gift_004","title":"Подарок получен IV","description":"Какой особенный подарок!.. Сегодня какой-то важный день?","language":"Китайский","audioUrl":"/nte-meta/game-audio/7c37e91b05d7aa154a7e.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_windfall_002","title":"Неожиданная добыча II","description":"Не забудь прихватить это!","language":"Японский","audioUrl":"/nte-meta/game-audio/3991f659717262b1de2e.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_gift_002","title":"Подарок получен II","description":"Ох, как раз то, что я хотела! Ты что, фея, исполняющая желания?","language":"Корейский","audioUrl":"/nte-meta/game-audio/d94a87c232b1222cd9d8.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_gift_003","title":"Подарок получен III","description":"Спасибо! Я тоже подарок приготовлю — тебе точно понравится!","language":"Корейский","audioUrl":"/nte-meta/game-audio/f360f98cb912ef798475.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_skill_001","title":"Навык перенаправления I","description":"Шоу начинается!","language":"Корейский","audioUrl":"/nte-meta/game-audio/a666c84acd1f91c62756.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_deploy_002","title":"Отправка II","description":"Я тебе помогу.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b3c4e2f3f47745a258ef.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_Parry_002","title":"Парирование II","description":"Точно в ритм!","language":"Китайский","audioUrl":"/nte-meta/game-audio/f8b0420c37020c35d224.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_struck_001","title":"Урон I","description":"Со мной всё нормально.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1c71a130cbdbeb249ee4.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_Switch_001","title":"Переключение I","description":"Безопасность прежде всего. Отдохни.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d2e672cc5c9ac4b6d6d7.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_ug_002","title":"Вознесение персонажа II","description":"Хм… могу лучше!","language":"Корейский","audioUrl":"/nte-meta/game-audio/fd8a3d8bef51cf669a05.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_hobby_001","title":"Хобби","description":"Ой, да много всего! Я обожаю пробовать всё новое, правда, быстро теряю интерес… Но если и есть что-то, что осталось со мной надолго, так это созерцание моря. Далёкая линия горизонта, где небо встречается с водой, и мерный ритм волн… это так успокаивает. Словно я — крошечная нота в огромном вечном хоре… Все тревоги исчезают, когда я смотрю на море.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a4fef7e7ce88b46097e8.ogg"},{"id":"en-Play_Vo_Char_NPC1029_skill_003","title":"Навык перенаправления III","description":"Услышь песню, что мы должны спеть.","language":"Английский","audioUrl":"/nte-meta/game-audio/8207537677bdb1cd1df3.ogg"},{"id":"en-Play_Vo_Char_NPC1029_Switch_002","title":"Переключение II","description":"Время следующего сета!","language":"Английский","audioUrl":"/nte-meta/game-audio/e14e0bf26e2a6f069caa.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_QTE_001","title":"Атака на входе I","description":"Входи на сильную долю!","language":"Японский","audioUrl":"/nte-meta/game-audio/54f858993d900122a4c7.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_DodgeCombo_002","title":"Серия критических уклонений II","description":"Идеальный ритм!","language":"Корейский","audioUrl":"/nte-meta/game-audio/677ad5e8c8747c71db02.ogg"},{"id":"en-Play_Vo_Char_NPC1029_aoe_UI_003","title":"Сверхспособность III","description":"Пусть мелодия расправит крылья!","language":"Английский","audioUrl":"/nte-meta/game-audio/221c7bc03a821f1aeba1.ogg"},{"id":"en-Play_Vo_Char_NPC1029_chat_003","title":"Чат: музыка","description":"У каждого музыкального жанра своё очарование, и каждая песня несёт в себе уникальные эмоции её автора. Но если ты спросишь про мою любимую группу… я не смогу выбрать какую-то одну. Давай я лучше составлю для тебя целый плейлист!","language":"Английский","audioUrl":"/nte-meta/game-audio/f10d48e364956b7337ab.ogg"},{"id":"en-Play_Vo_Char_NPC1029_windfall_004","title":"Неожиданная добыча IV","description":"М-м, я сберегу это.","language":"Английский","audioUrl":"/nte-meta/game-audio/d4078df5a52f334ec735.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_QTE_001","title":"Атака на входе I","description":"Входи на сильную долю!","language":"Корейский","audioUrl":"/nte-meta/game-audio/5c0ef1d50cd231774c00.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_ug_002","title":"Вознесение персонажа II","description":"Хм… могу лучше!","language":"Китайский","audioUrl":"/nte-meta/game-audio/e31770ad8ee7c01f296b.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_anomaly_004","title":"Нуллификация II","description":"Миссия выполнена. Спасибо за помощь!","language":"Японский","audioUrl":"/nte-meta/game-audio/65266097fee30b5e6a95.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_meet_001","title":"Первая встреча","description":"Привет, меня зовут Аурелия… Ой, моя медуза тебя пугает? Прости, она просто так радуется встрече с новым другом… Надеюсь, ты не против. Хм? Тебе совсем не страшно? Вот и славно! Привет, меня зовут Аурелия… Ой, моя медуза тебя пугает? Прости, она просто так радуется встрече с новой подругой… Надеюсь, ты не против. Хм? Тебе совсем не страшно? Вот и славно!","language":"Корейский","audioUrl":"/nte-meta/game-audio/3fd563a4c547b319659f.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_QTE_003","title":"Атака на входе III","description":"Все в унисон!","language":"Корейский","audioUrl":"/nte-meta/game-audio/87a5e6c54b621f2f16c9.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_skill_002","title":"Навык перенаправления II","description":"Пусть зазвучит гимн океана!","language":"Китайский","audioUrl":"/nte-meta/game-audio/72fca7d04e1c5c00997e.ogg"},{"id":"en-Play_Vo_Char_NPC1029_DodgeCombo_001","title":"Серия критических уклонений I","description":"А мы быстрые, знаешь ли!","language":"Английский","audioUrl":"/nte-meta/game-audio/60a99e0cd7156e5b3401.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_aoe_UI_002","title":"Сверхспособность II","description":"Утяни приливы в саму ночь.","language":"Японский","audioUrl":"/nte-meta/game-audio/ef975e137d0de2b7ea1c.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_Fly_002","title":"Планирование II","description":"Главное — мягкая посадка.","language":"Японский","audioUrl":"/nte-meta/game-audio/a7348f1cc9a8a1521c8b.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_windfall_001","title":"Неожиданная добыча I","description":"Вполне неплохо.","language":"Японский","audioUrl":"/nte-meta/game-audio/16cf1dad5d96323baa33.ogg"},{"id":"en-Play_Vo_Char_NPC1029_hobby_001","title":"Хобби","description":"Ой, да много всего! Я обожаю пробовать всё новое, правда, быстро теряю интерес… Но если и есть что-то, что осталось со мной надолго, так это созерцание моря. Далёкая линия горизонта, где небо встречается с водой, и мерный ритм волн… это так успокаивает. Словно я — крошечная нота в огромном вечном хоре… Все тревоги исчезают, когда я смотрю на море.","language":"Английский","audioUrl":"/nte-meta/game-audio/2d5353cbc966f11a0561.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_gift_003","title":"Подарок получен III","description":"Спасибо! Я тоже подарок приготовлю — тебе точно понравится!","language":"Японский","audioUrl":"/nte-meta/game-audio/755b22742351d54d85b5.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_meet_001","title":"Первая встреча","description":"Привет, меня зовут Аурелия… Ой, моя медуза тебя пугает? Прости, она просто так радуется встрече с новым другом… Надеюсь, ты не против. Хм? Тебе совсем не страшно? Вот и славно! Привет, меня зовут Аурелия… Ой, моя медуза тебя пугает? Прости, она просто так радуется встрече с новой подругой… Надеюсь, ты не против. Хм? Тебе совсем не страшно? Вот и славно!","language":"Японский","audioUrl":"/nte-meta/game-audio/b166098e03252a5fc06e.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_self_003","title":"Обо мне: деликатесы","description":"На улице Тамамочи, где я работаю, полно отличных забегаловок. Жареная утка «У Дина» — всегда с хрустящей корочкой и нежная внутри; рамен в лапшичной «Некомару» просто чудесный, но с горячим бульоном нужно быть поосторожнее. А моё любимое — это булочки с кремом из «Большого баоцзы». Обожаю в холодные дни держать в руках горячую булочку, откусить кусочек и почувствовать тёплую, ароматную сладость внутри… настоящее блаженство. Правда, если я съем слишком много и прибавлю в весе, моей медузе станет тяжело меня носить… Похоже, придётся держать себя в руках.","language":"Японский","audioUrl":"/nte-meta/game-audio/3ad7f29493c46cb1d15a.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_Switch_002","title":"Переключение II","description":"Время следующего сета!","language":"Корейский","audioUrl":"/nte-meta/game-audio/d18a4d54df9fa487a831.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_weather_002","title":"Дождливо","description":"Капли дождя — как тонкие ниточки. Так уютно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/cb1b915684fa7cba13b6.ogg"},{"id":"en-Play_Vo_Char_NPC1029_weather_001","title":"Солнечно","description":"Опять отличный день! Солнышко светит ярко, и у меня на душе тоже светло!","language":"Английский","audioUrl":"/nte-meta/game-audio/48eb558ec9a406faa35c.ogg"},{"id":"en-Play_Vo_Char_NPC1029_windfall_001","title":"Неожиданная добыча I","description":"Вполне неплохо.","language":"Английский","audioUrl":"/nte-meta/game-audio/74fd77a2707e9d609408.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_greet_003","title":"Вечернее приветствие","description":"Закат завораживает. Может, сходить на побережье, пока солнце ещё не село?","language":"Японский","audioUrl":"/nte-meta/game-audio/7a0c31e036e352cfdeda.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_weather_001","title":"Солнечно","description":"Опять отличный день! Солнышко светит ярко, и у меня на душе тоже светло!","language":"Японский","audioUrl":"/nte-meta/game-audio/51bb0625a20e6d963150.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_windfall_004","title":"Неожиданная добыча IV","description":"М-м, я сберегу это.","language":"Корейский","audioUrl":"/nte-meta/game-audio/30652006a4b5a5612fe2.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_hstruck_001","title":"Сильный урон I","description":"Всё в порядке… мне не больно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e330026a3b9c094296ae.ogg"},{"id":"en-Play_Vo_Char_NPC1029_gift_001","title":"Подарок получен I","description":"Какой продуманный подарок! Значит… мы уже настоящие друзья?","language":"Английский","audioUrl":"/nte-meta/game-audio/379f0f631e12448159b2.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_skill_003","title":"Навык перенаправления III","description":"Услышь песню, что мы должны спеть.","language":"Корейский","audioUrl":"/nte-meta/game-audio/243e00558630b2114630.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_Fly_001","title":"Планирование I","description":"Как птица.","language":"Китайский","audioUrl":"/nte-meta/game-audio/54e4d6e9ec77cbd19ea9.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_hstruck_002","title":"Сильный урон II","description":"Нельзя расслабляться…","language":"Китайский","audioUrl":"/nte-meta/game-audio/d7442ad4e4ec322c18be.ogg"},{"id":"en-Play_Vo_Char_NPC1029_Fly_001","title":"Планирование I","description":"Как птица.","language":"Английский","audioUrl":"/nte-meta/game-audio/f0ec3ceabb33ec9e7188.ogg"},{"id":"en-Play_Vo_Char_NPC1029_windfall_002","title":"Неожиданная добыча II","description":"Не забудь прихватить это!","language":"Английский","audioUrl":"/nte-meta/game-audio/b1a559cfb8a4632b7e33.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_struck_002","title":"Урон II","description":"Да это всего лишь царапина.","language":"Японский","audioUrl":"/nte-meta/game-audio/b3c77bdf095c1ca8fdcd.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_Switch_002","title":"Переключение II","description":"Время следующего сета!","language":"Японский","audioUrl":"/nte-meta/game-audio/e8735ebfe5412c59197d.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_hobby_001","title":"Хобби","description":"Ой, да много всего! Я обожаю пробовать всё новое, правда, быстро теряю интерес… Но если и есть что-то, что осталось со мной надолго, так это созерцание моря. Далёкая линия горизонта, где небо встречается с водой, и мерный ритм волн… это так успокаивает. Словно я — крошечная нота в огромном вечном хоре… Все тревоги исчезают, когда я смотрю на море.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a4d0dee092593ce9b5a4.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_aoe_UI_001","title":"Сверхспособность I","description":"Кружись в полёте галактик.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a73e4bb1c935ec24a452.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_fh_001","title":"Исцеление I","description":"А теперь — песня на бис!","language":"Китайский","audioUrl":"/nte-meta/game-audio/4b338eb8235cf71ef1da.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_talk_003","title":"Тема: аномалия","description":"Если бы я тогда не взялась за задание по нуллификации Парусника, возможно, ничего этого бы не случилось. Та аномалия была настолько же опасна, насколько прекрасна… Я знаю, что ты очень способный охотник за аномалиями, но, пожалуйста, береги себя. Не только ради себя, но и ради тех, кто тебя любит и за тебя переживает.Если бы я тогда не взялась за задание по нуллификации Парусника, возможно, ничего этого бы не случилось. Та аномалия была настолько же опасна, насколько прекрасна… Я знаю, что ты очень способная охотница за аномалиями, но, пожалуйста, береги себя. Не только ради себя, но и ради тех, кто тебя любит и за тебя переживает.","language":"Китайский","audioUrl":"/nte-meta/game-audio/64058a49caaf7ee06a79.ogg"},{"id":"en-Play_Vo_Char_NPC1029_containment_002","title":"Сдерживание II","description":"Оставайся в контейнере.","language":"Английский","audioUrl":"/nte-meta/game-audio/03cc7729c93ab0daf812.ogg"},{"id":"en-Play_Vo_Char_NPC1029_windfall_005","title":"Неожиданная добыча V","description":"Чувствую, мне сегодня везёт. Если я куплю «Глоток свежести», дадут ещё один бесплатно?","language":"Английский","audioUrl":"/nte-meta/game-audio/369c3839062efea40c42.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_containment_001","title":"Сдерживание I","description":"Хе-хе, попался!","language":"Японский","audioUrl":"/nte-meta/game-audio/c65b14bed7ac7f469e71.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_self_002","title":"Обо мне: реабилитация","description":"Врач сказал, что вряд ли я когда-нибудь полностью поправлюсь. Но если я не брошу реабилитацию и лечение, может быть, однажды смогу снова встать на ноги. Тебе может показаться, что это лишь несбыточная мечта и я глупо поступаю, цепляясь за неё… но я верю, что пока жизнь не подошла к концу, возможно всё. Если случится чудо, а я окажусь к нему не готова — разве не будет обидно?","language":"Корейский","audioUrl":"/nte-meta/game-audio/158dfe70f6923c6a474c.ogg"},{"id":"en-Play_Vo_Char_NPC1029_Fly_002","title":"Планирование II","description":"Главное — мягкая посадка.","language":"Английский","audioUrl":"/nte-meta/game-audio/45260a7c38c116f26068.ogg"},{"id":"en-Play_Vo_Char_NPC1029_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Хорошо поспал? Доброе утро! Хорошо поспала?","language":"Английский","audioUrl":"/nte-meta/game-audio/a8a43a8a89230d5b3e16.ogg"},{"id":"en-Play_Vo_Char_NPC1029_hp_001","title":"Низкий уровень здоровья I","description":"Я… справлюсь.","language":"Английский","audioUrl":"/nte-meta/game-audio/b8b732df584cdd7b8723.ogg"},{"id":"en-Play_Vo_Char_NPC1029_kill_001","title":"Убийство I","description":"Фух, справилась!","language":"Английский","audioUrl":"/nte-meta/game-audio/eedd0bd34add3178c390.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_dead_002","title":"Потеря сознания II","description":"Я так и не… научилась…","language":"Японский","audioUrl":"/nte-meta/game-audio/72407311fe0a8daddb7c.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_TeammateDown_001","title":"Поражён товарищ по команде – Аканэ","description":"Тебе не нужно справляться с этим в одиночку — позволь мне помочь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/09ed48062a4f05d95332.ogg"},{"id":"en-Play_Vo_Char_NPC1029_anomaly_003","title":"Нуллификация I","description":"Надеюсь, следующая аномалия будет такой же простой.","language":"Английский","audioUrl":"/nte-meta/game-audio/c6c02ced27cb2e4dd7bf.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_fh_001","title":"Исцеление I","description":"А теперь — песня на бис!","language":"Японский","audioUrl":"/nte-meta/game-audio/712c823c5b78dca67022.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_fh_002","title":"Исцеление II","description":"Фух, намного лучше.","language":"Японский","audioUrl":"/nte-meta/game-audio/9d04a0b59e2da21df027.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_chat_002","title":"Чат: ночная вылазка","description":"Мне нравится гулять по ночам. На улицах почти никого, так что можно не бояться ни с кем столкнуться. Правда, если кто-то увидит, как я парю над дорогой в такой час, может и испугаться…","language":"Корейский","audioUrl":"/nte-meta/game-audio/394ba90f77c3471d1009.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_hstruck_002","title":"Сильный урон II","description":"Нельзя расслабляться…","language":"Японский","audioUrl":"/nte-meta/game-audio/cba8ebce72f658c68f70.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_aoe_UI_002","title":"Сверхспособность II","description":"Утяни приливы в саму ночь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ff4524e347b664a4d4fd.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_deploy_001","title":"Отправка I","description":"По твоей команде.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1b691adedefaafd492dc.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_chat_002","title":"Чат: ночная вылазка","description":"Мне нравится гулять по ночам. На улицах почти никого, так что можно не бояться ни с кем столкнуться. Правда, если кто-то увидит, как я парю над дорогой в такой час, может и испугаться…","language":"Китайский","audioUrl":"/nte-meta/game-audio/4874db73aadf9dfe7c6a.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_fh_002","title":"Исцеление II","description":"Фух, намного лучше.","language":"Китайский","audioUrl":"/nte-meta/game-audio/734d2f63a37ecb087fd9.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Хорошо поспал? Доброе утро! Хорошо поспала?","language":"Китайский","audioUrl":"/nte-meta/game-audio/232ab1e896b69a76502e.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_skill_003","title":"Навык перенаправления III","description":"Услышь песню, что мы должны спеть.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3d4d4df16906d51d1c8d.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_greet_004","title":"Спокойной ночи","description":"Чтобы хорошо провести день, нужно хорошо выспаться. Ложись пораньше, увидимся завтра.","language":"Японский","audioUrl":"/nte-meta/game-audio/de699e9b200d403af91d.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_skill_002","title":"Навык перенаправления II","description":"Пусть зазвучит гимн океана!","language":"Японский","audioUrl":"/nte-meta/game-audio/381c3b3bbb745218dc97.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_weather_003","title":"Холодно","description":"Так холодно… Может, заскочить в «Безумный кот» за чем-нибудь горяченьким?..","language":"Японский","audioUrl":"/nte-meta/game-audio/97a8551a875d8ebbf062.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_greet_003","title":"Вечернее приветствие","description":"Закат завораживает. Может, сходить на побережье, пока солнце ещё не село?","language":"Корейский","audioUrl":"/nte-meta/game-audio/c7d372bce96779062067.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_Fly_002","title":"Планирование II","description":"Главное — мягкая посадка.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e4390b7b5b8561799424.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_vexation_001","title":"Проблемы","description":"Мой привычный навигатор в последнее время постоянно обновляется и жутко глючит. В итоге я теперь всё время теряюсь. На этой неделе я уже несколько раз опаздывала на подработку… Моя добрая начальница не стала вычитать это из зарплаты, но мне всё равно неловко… Наверное, стоит купить бумажную карту, пока приложение не починят.","language":"Японский","audioUrl":"/nte-meta/game-audio/15061dc4937e2bea662b.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_chat_001","title":"Чат: совет","description":"Никогда не надевай широкие штаны, если садишься за барабаны! Если сильно ударишь по педали, штанина может легко запутаться в колотушке бас-бочки…","language":"Корейский","audioUrl":"/nte-meta/game-audio/a71456c130930cd3d95f.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_dead_003","title":"Потеря сознания III","description":"Только не так…","language":"Корейский","audioUrl":"/nte-meta/game-audio/649071bc55816118cb50.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_hp_001","title":"Низкий уровень здоровья I","description":"Я… справлюсь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4ae4fc6aef560df39d4d.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_self_001","title":"Обо мне: способности эспера","description":"Моя способность довольно слабая. Я могу управлять только медузами, но благодаря этим малышам я смогла вернуться к нормальной жизни. Когда я остаюсь одна, они составляют мне компанию, так что я никогда не чувствую себя одиноко. Поэтому я искренне благодарна за такую способность. Как говорится: «Лучшее для тебя — то, что тебе подходит». Всё просто.","language":"Корейский","audioUrl":"/nte-meta/game-audio/01c628633549f8899e29.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_windfall_006","title":"Неожиданная добыча VI","description":"Памятный знак на сегодня.","language":"Корейский","audioUrl":"/nte-meta/game-audio/92de917e9d6465c6a434.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_weather_003","title":"Холодно","description":"Так холодно… Может, заскочить в «Безумный кот» за чем-нибудь горяченьким?..","language":"Китайский","audioUrl":"/nte-meta/game-audio/8438752c7e4371734762.ogg"},{"id":"en-Play_Vo_Char_NPC1029_fh_001","title":"Исцеление I","description":"А теперь — песня на бис!","language":"Английский","audioUrl":"/nte-meta/game-audio/a92f841faa46ac6088ec.ogg"},{"id":"en-Play_Vo_Char_NPC1029_fh_002","title":"Исцеление II","description":"Фух, намного лучше.","language":"Английский","audioUrl":"/nte-meta/game-audio/1627f8df8144cc8a641a.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_about_001_02","title":"О «ЛИНИЯХ»","description":"Правда в том, что группа «ЛИНИИ» появилась не из желания играть музыку. Я просто хотела найти причину, чтобы мы трое не расставались после выпуска. Наверное, поэтому, когда я больше не могла играть, группа просто распалась… Но связи между людьми — это не только прямые линии — даже если одна точка пересечения исчезает, у нас всё равно остаётся шанс встретиться снова. Жаль, что я не поняла этого раньше… но даже сейчас ещё не слишком поздно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5642e68b1690d705791d.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_chat_003","title":"Чат: музыка","description":"У каждого музыкального жанра своё очарование, и каждая песня несёт в себе уникальные эмоции её автора. Но если ты спросишь про мою любимую группу… я не смогу выбрать какую-то одну. Давай я лучше составлю для тебя целый плейлист!","language":"Корейский","audioUrl":"/nte-meta/game-audio/5d219f2697329f288ef0.ogg"},{"id":"en-Play_Vo_Char_NPC1029_ug_002","title":"Вознесение персонажа II","description":"Хм… могу лучше!","language":"Английский","audioUrl":"/nte-meta/game-audio/4a989f67a3e37df0b8bb.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_Fly_002","title":"Планирование II","description":"Главное — мягкая посадка.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5c28af5b3369fc4467f5.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_weather_003","title":"Холодно","description":"Так холодно… Может, заскочить в «Безумный кот» за чем-нибудь горяченьким?..","language":"Корейский","audioUrl":"/nte-meta/game-audio/3bb15f835815cbd160dc.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_weather_002","title":"Дождливо","description":"Капли дождя — как тонкие ниточки. Так уютно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/46233a6118b7dacd4b6f.ogg"},{"id":"en-Play_Vo_Char_NPC1029_talk_003","title":"Тема: аномалия","description":"Если бы я тогда не взялась за задание по нуллификации Парусника, возможно, ничего этого бы не случилось. Та аномалия была настолько же опасна, насколько прекрасна… Я знаю, что ты очень способный охотник за аномалиями, но, пожалуйста, береги себя. Не только ради себя, но и ради тех, кто тебя любит и за тебя переживает.Если бы я тогда не взялась за задание по нуллификации Парусника, возможно, ничего этого бы не случилось. Та аномалия была настолько же опасна, насколько прекрасна… Я знаю, что ты очень способная охотница за аномалиями, но, пожалуйста, береги себя. Не только ради себя, но и ради тех, кто тебя любит и за тебя переживает.","language":"Английский","audioUrl":"/nte-meta/game-audio/22761842589097b7d5d4.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_greet_002","title":"Дневное приветствие","description":"Хе-хе, я сама испекла этот торт! Разве он не прелесть? Давай я отрежу тебе кусочек!","language":"Китайский","audioUrl":"/nte-meta/game-audio/01f0ac2092be78c1bc0b.ogg"},{"id":"en-Play_Vo_Char_NPC1029_hstruck_002","title":"Сильный урон II","description":"Нельзя расслабляться…","language":"Английский","audioUrl":"/nte-meta/game-audio/f1f298a4d17bdb272af5.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_about_001_01","title":"Об Аканэ","description":"Спасибо, что поддержал возвращение Аканэ на сцену. Для меня это тоже очень много значит. Ты ведь и сам барабанщик, так что наверняка понимаешь. Когда я смотрю на Аканэ со спины, она на сцене буквально сияет — будто рождена выступать… Отныне я буду болеть за «Кошачий концерт»!!!! ещё сильнее. И не забывай — я твоя фанатка номер один с самого первого концерта! Спасибо, что поддержала возвращение Аканэ на сцену. Для меня это тоже очень много значит. Ты ведь и сама барабанщица, так что наверняка понимаешь. Когда я смотрю на Аканэ со спины, она на сцене буквально сияет — будто рождена выступать… Отныне я буду болеть за «Кошачий концерт»!!!! ещё сильнее. И не забывай — я твоя фанатка номер один с самого первого концерта!","language":"Японский","audioUrl":"/nte-meta/game-audio/a823be29a7c94caf6166.ogg"}]') WHERE character_id='aurelia' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:07:15');

UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT value FROM json_each('[{"id":"ja-Play_Vo_Char_NPC1029_about_001_02","title":"О «ЛИНИЯХ»","description":"Правда в том, что группа «ЛИНИИ» появилась не из желания играть музыку. Я просто хотела найти причину, чтобы мы трое не расставались после выпуска. Наверное, поэтому, когда я больше не могла играть, группа просто распалась… Но связи между людьми — это не только прямые линии — даже если одна точка пересечения исчезает, у нас всё равно остаётся шанс встретиться снова. Жаль, что я не поняла этого раньше… но даже сейчас ещё не слишком поздно.","language":"Японский","audioUrl":"/nte-meta/game-audio/200ddd7bfaede6d88925.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_talk_001","title":"Тема: медузы","description":"Время от времени на берегу можно найти медуз, которых выбросило отступающим приливом, — может, они тоже сбились с пути… Если увидишь медузу на пляже, пожалуйста, не трогай её. Они могут казаться мягкими и безобидными, но многие из них ядовиты. Ой, но те, что со мной, совершенно безобидные, так что не переживай!","language":"Японский","audioUrl":"/nte-meta/game-audio/0c86dfc05c77dba0b688.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_ug_001","title":"Вознесение персонажа I","description":"Освежает, как морской бриз!","language":"Японский","audioUrl":"/nte-meta/game-audio/3dd848e6c6847b0686ee.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_weather_002","title":"Дождливо","description":"Капли дождя — как тонкие ниточки. Так уютно.","language":"Японский","audioUrl":"/nte-meta/game-audio/f6ef38e89051493bd0c6.ogg"},{"id":"en-Play_Vo_Char_NPC1029_Switch_001","title":"Переключение I","description":"Безопасность прежде всего. Отдохни.","language":"Английский","audioUrl":"/nte-meta/game-audio/0659baf94437a02c1af2.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_deploy_002","title":"Отправка II","description":"Я тебе помогу.","language":"Японский","audioUrl":"/nte-meta/game-audio/56fd056c58491660f27a.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_DodgeCombo_001","title":"Серия критических уклонений I","description":"А мы быстрые, знаешь ли!","language":"Японский","audioUrl":"/nte-meta/game-audio/3aaba6431f5a1a0da5ab.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_kill_002","title":"Убийство II","description":"Не недооценивай меня!","language":"Японский","audioUrl":"/nte-meta/game-audio/a4d4cb1da0b7bc60ed49.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_gift_001","title":"Подарок получен I","description":"Какой продуманный подарок! Значит… мы уже настоящие друзья?","language":"Корейский","audioUrl":"/nte-meta/game-audio/800506c43487fb2ab981.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_skill_002","title":"Навык перенаправления II","description":"Пусть зазвучит гимн океана!","language":"Корейский","audioUrl":"/nte-meta/game-audio/8937e3638719c69a3f40.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_ug_003","title":"Вознесение персонажа III","description":"Хе-хе, медузы пляшут.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f0ad310763b51c58014a.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_self_002","title":"Обо мне: реабилитация","description":"Врач сказал, что вряд ли я когда-нибудь полностью поправлюсь. Но если я не брошу реабилитацию и лечение, может быть, однажды смогу снова встать на ноги. Тебе может показаться, что это лишь несбыточная мечта и я глупо поступаю, цепляясь за неё… но я верю, что пока жизнь не подошла к концу, возможно всё. Если случится чудо, а я окажусь к нему не готова — разве не будет обидно?","language":"Японский","audioUrl":"/nte-meta/game-audio/0fcdaf16c02dcd60058a.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_hp_002","title":"Низкий уровень здоровья II","description":"Голова кругом…","language":"Китайский","audioUrl":"/nte-meta/game-audio/335f830137e9c569b720.ogg"},{"id":"en-Play_Vo_Char_NPC1029_weather_002","title":"Дождливо","description":"Капли дождя — как тонкие ниточки. Так уютно.","language":"Английский","audioUrl":"/nte-meta/game-audio/53f0413a61f21800e6f7.ogg"},{"id":"en-Play_Vo_Char_NPC1029_dead_003","title":"Потеря сознания III","description":"Только не так…","language":"Английский","audioUrl":"/nte-meta/game-audio/39e9d08528e09922afc5.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_TeammateDown_001","title":"Поражён товарищ по команде – Аканэ","description":"Тебе не нужно справляться с этим в одиночку — позволь мне помочь.","language":"Японский","audioUrl":"/nte-meta/game-audio/4839d957ab406c72ef3b.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_dead_001","title":"Потеря сознания I","description":"Нужно… снова… выйти на сцену…","language":"Корейский","audioUrl":"/nte-meta/game-audio/c563c39d15f1eb50d860.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_windfall_006","title":"Неожиданная добыча VI","description":"Памятный знак на сегодня.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2e82120763fc06e2bf60.ogg"},{"id":"en-Play_Vo_Char_NPC1029_Parry_002","title":"Парирование II","description":"Точно в ритм!","language":"Английский","audioUrl":"/nte-meta/game-audio/c199f8c8fb98b83187ab.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_greet_004","title":"Спокойной ночи","description":"Чтобы хорошо провести день, нужно хорошо выспаться. Ложись пораньше, увидимся завтра.","language":"Корейский","audioUrl":"/nte-meta/game-audio/470c8b2f26f0a6fab477.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_aoe_UI_002","title":"Сверхспособность II","description":"Утяни приливы в саму ночь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c38acfc15d8dba4479f9.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_aoe_UI_003","title":"Сверхспособность III","description":"Пусть мелодия расправит крылья!","language":"Китайский","audioUrl":"/nte-meta/game-audio/4c279f930642dcb1b307.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_deploy_001","title":"Отправка I","description":"По твоей команде.","language":"Китайский","audioUrl":"/nte-meta/game-audio/17b7bbe3d6c10a8635f9.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_self_001","title":"Обо мне: способности эспера","description":"Моя способность довольно слабая. Я могу управлять только медузами, но благодаря этим малышам я смогла вернуться к нормальной жизни. Когда я остаюсь одна, они составляют мне компанию, так что я никогда не чувствую себя одиноко. Поэтому я искренне благодарна за такую способность. Как говорится: «Лучшее для тебя — то, что тебе подходит». Всё просто.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7c4d89ae78d73bc62326.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_windfall_002","title":"Неожиданная добыча II","description":"Не забудь прихватить это!","language":"Китайский","audioUrl":"/nte-meta/game-audio/d6f593fce988ce002491.ogg"},{"id":"en-Play_Vo_Char_NPC1029_ug_003","title":"Вознесение персонажа III","description":"Хе-хе, медузы пляшут.","language":"Английский","audioUrl":"/nte-meta/game-audio/a1ac1134e068f889c7da.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_hp_001","title":"Низкий уровень здоровья I","description":"Я… справлюсь.","language":"Японский","audioUrl":"/nte-meta/game-audio/468c93aef8f2cff723a9.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_hp_002","title":"Низкий уровень здоровья II","description":"Голова кругом…","language":"Корейский","audioUrl":"/nte-meta/game-audio/0cc65d6c9c03612b0329.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_dead_003","title":"Потеря сознания III","description":"Только не так…","language":"Китайский","audioUrl":"/nte-meta/game-audio/08414f9819605adebae1.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_ug_003","title":"Вознесение персонажа III","description":"Хе-хе, медузы пляшут.","language":"Китайский","audioUrl":"/nte-meta/game-audio/27db16ce5a00d746fe71.ogg"},{"id":"en-Play_Vo_Char_NPC1029_self_001","title":"Обо мне: способности эспера","description":"Моя способность довольно слабая. Я могу управлять только медузами, но благодаря этим малышам я смогла вернуться к нормальной жизни. Когда я остаюсь одна, они составляют мне компанию, так что я никогда не чувствую себя одиноко. Поэтому я искренне благодарна за такую способность. Как говорится: «Лучшее для тебя — то, что тебе подходит». Всё просто.","language":"Английский","audioUrl":"/nte-meta/game-audio/40ce580f215fb04155ff.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_anomaly_004","title":"Нуллификация II","description":"Миссия выполнена. Спасибо за помощь!","language":"Корейский","audioUrl":"/nte-meta/game-audio/c1e1641ed40c8109d47d.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_DodgeCombo_002","title":"Серия критических уклонений II","description":"Идеальный ритм!","language":"Японский","audioUrl":"/nte-meta/game-audio/17c99e31c92ca97d64f0.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_windfall_003","title":"Неожиданная добыча III","description":"Выглядит как что-то годное.","language":"Японский","audioUrl":"/nte-meta/game-audio/51c588eaa33348d2bae9.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_greet_002","title":"Дневное приветствие","description":"Хе-хе, я сама испекла этот торт! Разве он не прелесть? Давай я отрежу тебе кусочек!","language":"Корейский","audioUrl":"/nte-meta/game-audio/3840ea95e53c9c5b953b.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_kill_002","title":"Убийство II","description":"Не недооценивай меня!","language":"Китайский","audioUrl":"/nte-meta/game-audio/0afd84cd90ede0edbabd.ogg"},{"id":"en-Play_Vo_Char_NPC1029_gift_002","title":"Подарок получен II","description":"Ох, как раз то, что я хотела! Ты что, фея, исполняющая желания?","language":"Английский","audioUrl":"/nte-meta/game-audio/cb8207c847dd07583f8b.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_struck_001","title":"Урон I","description":"Со мной всё нормально.","language":"Японский","audioUrl":"/nte-meta/game-audio/292754aa11ba82a414a1.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_Switch_003","title":"Переключение III","description":"Мы с этим справимся.","language":"Японский","audioUrl":"/nte-meta/game-audio/144aa63b021f10d311a4.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_windfall_005","title":"Неожиданная добыча V","description":"Чувствую, мне сегодня везёт. Если я куплю «Глоток свежести», дадут ещё один бесплатно?","language":"Японский","audioUrl":"/nte-meta/game-audio/a9f7a6fb10ff16a340f7.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_kill_001","title":"Убийство I","description":"Фух, справилась!","language":"Китайский","audioUrl":"/nte-meta/game-audio/dc81ed1c0b2ad0deeb62.ogg"},{"id":"en-Play_Vo_Char_NPC1029_greet_002","title":"Дневное приветствие","description":"Хе-хе, я сама испекла этот торт! Разве он не прелесть? Давай я отрежу тебе кусочек!","language":"Английский","audioUrl":"/nte-meta/game-audio/19e93853b4d47449fb70.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_containment_001","title":"Сдерживание I","description":"Хе-хе, попался!","language":"Корейский","audioUrl":"/nte-meta/game-audio/db0c561854248f1b53b4.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_kill_001","title":"Убийство I","description":"Фух, справилась!","language":"Корейский","audioUrl":"/nte-meta/game-audio/952a7c75f5f001f49da2.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_windfall_003","title":"Неожиданная добыча III","description":"Выглядит как что-то годное.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6963122546becae35df1.ogg"},{"id":"en-Play_Vo_Char_NPC1029_deploy_001","title":"Отправка I","description":"По твоей команде.","language":"Английский","audioUrl":"/nte-meta/game-audio/1ecf0b6f45b3a0089cc5.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_QTE_003","title":"Атака на входе III","description":"Все в унисон!","language":"Японский","audioUrl":"/nte-meta/game-audio/c0b8f04817ab95ab66c6.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_skill_003","title":"Навык перенаправления III","description":"Услышь песню, что мы должны спеть.","language":"Японский","audioUrl":"/nte-meta/game-audio/c869b6efbcbcb6dd1143.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_about_001_01","title":"Об Аканэ","description":"Спасибо, что поддержал возвращение Аканэ на сцену. Для меня это тоже очень много значит. Ты ведь и сам барабанщик, так что наверняка понимаешь. Когда я смотрю на Аканэ со спины, она на сцене буквально сияет — будто рождена выступать… Отныне я буду болеть за «Кошачий концерт»!!!! ещё сильнее. И не забывай — я твоя фанатка номер один с самого первого концерта! Спасибо, что поддержала возвращение Аканэ на сцену. Для меня это тоже очень много значит. Ты ведь и сама барабанщица, так что наверняка понимаешь. Когда я смотрю на Аканэ со спины, она на сцене буквально сияет — будто рождена выступать… Отныне я буду болеть за «Кошачий концерт»!!!! ещё сильнее. И не забывай — я твоя фанатка номер один с самого первого концерта!","language":"Китайский","audioUrl":"/nte-meta/game-audio/432d98cfd044fdbed221.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_dead_002","title":"Потеря сознания II","description":"Я так и не… научилась…","language":"Корейский","audioUrl":"/nte-meta/game-audio/319d91060e5c910d1016.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_QTE_001","title":"Атака на входе I","description":"Входи на сильную долю!","language":"Китайский","audioUrl":"/nte-meta/game-audio/360655fb51e55e5b8169.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_struck_002","title":"Урон II","description":"Да это всего лишь царапина.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f43a3b8ace21629deab3.ogg"},{"id":"en-Play_Vo_Char_NPC1029_gift_004","title":"Подарок получен IV","description":"Какой особенный подарок!.. Сегодня какой-то важный день?","language":"Английский","audioUrl":"/nte-meta/game-audio/26099e0fefcd32ac38c5.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_struck_001","title":"Урон I","description":"Со мной всё нормально.","language":"Китайский","audioUrl":"/nte-meta/game-audio/ab7bb4cc9f8b227ee220.ogg"},{"id":"en-Play_Vo_Char_NPC1029_TeammateDown_001","title":"Поражён товарищ по команде – Аканэ","description":"Тебе не нужно справляться с этим в одиночку — позволь мне помочь.","language":"Английский","audioUrl":"/nte-meta/game-audio/ab7493d49a4009e6b18d.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_chat_002","title":"Чат: ночная вылазка","description":"Мне нравится гулять по ночам. На улицах почти никого, так что можно не бояться ни с кем столкнуться. Правда, если кто-то увидит, как я парю над дорогой в такой час, может и испугаться…","language":"Японский","audioUrl":"/nte-meta/game-audio/60049ba15a7710670d91.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_talk_003","title":"Тема: аномалия","description":"Если бы я тогда не взялась за задание по нуллификации Парусника, возможно, ничего этого бы не случилось. Та аномалия была настолько же опасна, насколько прекрасна… Я знаю, что ты очень способный охотник за аномалиями, но, пожалуйста, береги себя. Не только ради себя, но и ради тех, кто тебя любит и за тебя переживает.Если бы я тогда не взялась за задание по нуллификации Парусника, возможно, ничего этого бы не случилось. Та аномалия была настолько же опасна, насколько прекрасна… Я знаю, что ты очень способная охотница за аномалиями, но, пожалуйста, береги себя. Не только ради себя, но и ради тех, кто тебя любит и за тебя переживает.","language":"Японский","audioUrl":"/nte-meta/game-audio/3ac423217e53cfa16a1c.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_windfall_004","title":"Неожиданная добыча IV","description":"М-м, я сберегу это.","language":"Японский","audioUrl":"/nte-meta/game-audio/75d1c69dac694fcadf5b.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_DodgeCombo_001","title":"Серия критических уклонений I","description":"А мы быстрые, знаешь ли!","language":"Китайский","audioUrl":"/nte-meta/game-audio/7b999fe4223954f7f806.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_Switch_002","title":"Переключение II","description":"Время следующего сета!","language":"Китайский","audioUrl":"/nte-meta/game-audio/1bcac8e7aa282bdb5815.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_talk_002","title":"Тема: опасное вождение","description":"Эта медуза просто слишком большая, чтобы поместиться в большинстве видов транспорта. К счастью, она быстрая, так что даже если случится что-то срочное — не будет проблемы из-за того, что не смогу в машину сесть… Хм? Хочешь знать, насколько она быстрая? Ну… скажем так: недостаточно быстрая, чтобы офицер Усатик выписал мне штраф за превышение скорости при езде на медузе по городу.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c72ceee37c3d0cb2e75e.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_dead_001","title":"Потеря сознания I","description":"Нужно… снова… выйти на сцену…","language":"Китайский","audioUrl":"/nte-meta/game-audio/c072e97ef1d16aafcf08.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_gift_001","title":"Подарок получен I","description":"Какой продуманный подарок! Значит… мы уже настоящие друзья?","language":"Китайский","audioUrl":"/nte-meta/game-audio/e55fed875bcbeb1857c6.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_hp_001","title":"Низкий уровень здоровья I","description":"Я… справлюсь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7f6846b53a94ec8fb1c6.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_SSC_MY_001","title":"Особое переключение: Аканэ","description":"Аканэ, антракт!","language":"Китайский","audioUrl":"/nte-meta/game-audio/dd6d5fbed50f4c59410d.ogg"},{"id":"en-Play_Vo_Char_NPC1029_hp_003","title":"Низкий уровень здоровья III","description":"Уф… нельзя… проигрывать.","language":"Английский","audioUrl":"/nte-meta/game-audio/df0393b9b9206a70a860.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_anomaly_003","title":"Нуллификация I","description":"Надеюсь, следующая аномалия будет такой же простой.","language":"Японский","audioUrl":"/nte-meta/game-audio/c5bcfd6fa28d7962b525.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_deploy_002","title":"Отправка II","description":"Я тебе помогу.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d092f1edee3ddc1c35e3.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_windfall_005","title":"Неожиданная добыча V","description":"Чувствую, мне сегодня везёт. Если я куплю «Глоток свежести», дадут ещё один бесплатно?","language":"Корейский","audioUrl":"/nte-meta/game-audio/b4a4110664fe451b4b4e.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_skill_001","title":"Навык перенаправления I","description":"Шоу начинается!","language":"Китайский","audioUrl":"/nte-meta/game-audio/7af25f4bcfba3d8b03b9.ogg"},{"id":"en-Play_Vo_Char_NPC1029_greet_004","title":"Спокойной ночи","description":"Чтобы хорошо провести день, нужно хорошо выспаться. Ложись пораньше, увидимся завтра.","language":"Английский","audioUrl":"/nte-meta/game-audio/cdb93b88f2d77c8bc49b.ogg"},{"id":"en-Play_Vo_Char_NPC1029_QTE_001","title":"Атака на входе I","description":"Входи на сильную долю!","language":"Английский","audioUrl":"/nte-meta/game-audio/3bba1f4afa800e9d79ed.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_aoe_UI_001","title":"Сверхспособность I","description":"Кружись в полёте галактик.","language":"Японский","audioUrl":"/nte-meta/game-audio/8f7eb737488216653b6f.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_containment_002","title":"Сдерживание II","description":"Оставайся в контейнере.","language":"Японский","audioUrl":"/nte-meta/game-audio/6b28bafbed109cd4dece.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_gift_004","title":"Подарок получен IV","description":"Какой особенный подарок!.. Сегодня какой-то важный день?","language":"Японский","audioUrl":"/nte-meta/game-audio/4d81c591219aed8e464f.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_hp_002","title":"Низкий уровень здоровья II","description":"Голова кругом…","language":"Японский","audioUrl":"/nte-meta/game-audio/1ffabb1db4fceaa4c223.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_skill_001","title":"Навык перенаправления I","description":"Шоу начинается!","language":"Японский","audioUrl":"/nte-meta/game-audio/cdfebc13ba9b48e085d3.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_Switch_001","title":"Переключение I","description":"Безопасность прежде всего. Отдохни.","language":"Японский","audioUrl":"/nte-meta/game-audio/120e817cdeeae10031cf.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_talk_001","title":"Тема: медузы","description":"Время от времени на берегу можно найти медуз, которых выбросило отступающим приливом, — может, они тоже сбились с пути… Если увидишь медузу на пляже, пожалуйста, не трогай её. Они могут казаться мягкими и безобидными, но многие из них ядовиты. Ой, но те, что со мной, совершенно безобидные, так что не переживай!","language":"Китайский","audioUrl":"/nte-meta/game-audio/eeffb25e3541d1e9d443.ogg"},{"id":"en-Play_Vo_Char_NPC1029_chat_002","title":"Чат: ночная вылазка","description":"Мне нравится гулять по ночам. На улицах почти никого, так что можно не бояться ни с кем столкнуться. Правда, если кто-то увидит, как я парю над дорогой в такой час, может и испугаться…","language":"Английский","audioUrl":"/nte-meta/game-audio/3b2b52b851f7ca284a17.ogg"},{"id":"en-Play_Vo_Char_NPC1029_weather_004","title":"Жарко","description":"Так жарко… мои медузы совсем разомлели. Давай отдохнём в теньке.","language":"Английский","audioUrl":"/nte-meta/game-audio/c6716b0fc32e65b6c620.ogg"},{"id":"en-Play_Vo_Char_NPC1029_windfall_003","title":"Неожиданная добыча III","description":"Выглядит как что-то годное.","language":"Английский","audioUrl":"/nte-meta/game-audio/8b2c6a7f6b62ea37f4e6.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_aoe_UI_003","title":"Сверхспособность III","description":"Пусть мелодия расправит крылья!","language":"Корейский","audioUrl":"/nte-meta/game-audio/6341561e10ee4459b264.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Хорошо поспал? Доброе утро! Хорошо поспала?","language":"Корейский","audioUrl":"/nte-meta/game-audio/0c13fb29c6b20e42201c.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_weather_001","title":"Солнечно","description":"Опять отличный день! Солнышко светит ярко, и у меня на душе тоже светло!","language":"Корейский","audioUrl":"/nte-meta/game-audio/ed2b0e94a00a54890b93.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_ug_001","title":"Вознесение персонажа I","description":"Освежает, как морской бриз!","language":"Китайский","audioUrl":"/nte-meta/game-audio/5fa3f73f7889dbd5e683.ogg"},{"id":"en-Play_Vo_Char_NPC1029_about_001_01","title":"Об Аканэ","description":"Спасибо, что поддержал возвращение Аканэ на сцену. Для меня это тоже очень много значит. Ты ведь и сам барабанщик, так что наверняка понимаешь. Когда я смотрю на Аканэ со спины, она на сцене буквально сияет — будто рождена выступать… Отныне я буду болеть за «Кошачий концерт»!!!! ещё сильнее. И не забывай — я твоя фанатка номер один с самого первого концерта! Спасибо, что поддержала возвращение Аканэ на сцену. Для меня это тоже очень много значит. Ты ведь и сама барабанщица, так что наверняка понимаешь. Когда я смотрю на Аканэ со спины, она на сцене буквально сияет — будто рождена выступать… Отныне я буду болеть за «Кошачий концерт»!!!! ещё сильнее. И не забывай — я твоя фанатка номер один с самого первого концерта!","language":"Английский","audioUrl":"/nte-meta/game-audio/d1047f10f3c3d9c936f7.ogg"},{"id":"en-Play_Vo_Char_NPC1029_Switch_003","title":"Переключение III","description":"Мы с этим справимся.","language":"Английский","audioUrl":"/nte-meta/game-audio/4a8d9e14518d6c2ce9ed.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_weather_004","title":"Жарко","description":"Так жарко… мои медузы совсем разомлели. Давай отдохнём в теньке.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5f8aa67df2a3f2749823.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_windfall_001","title":"Неожиданная добыча I","description":"Вполне неплохо.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e88fadc157f4d0e66f0b.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_Switch_003","title":"Переключение III","description":"Мы с этим справимся.","language":"Китайский","audioUrl":"/nte-meta/game-audio/648fb5f46e387875336a.ogg"},{"id":"en-Play_Vo_Char_NPC1029_chat_001","title":"Чат: совет","description":"Никогда не надевай широкие штаны, если садишься за барабаны! Если сильно ударишь по педали, штанина может легко запутаться в колотушке бас-бочки…","language":"Английский","audioUrl":"/nte-meta/game-audio/642f460201629bc87569.ogg"},{"id":"en-Play_Vo_Char_NPC1029_dead_002","title":"Потеря сознания II","description":"Я так и не… научилась…","language":"Английский","audioUrl":"/nte-meta/game-audio/9d644ac7a03e3f9bae48.ogg"},{"id":"en-Play_Vo_Char_NPC1029_gift_003","title":"Подарок получен III","description":"Спасибо! Я тоже подарок приготовлю — тебе точно понравится!","language":"Английский","audioUrl":"/nte-meta/game-audio/db4885e691d92bcdd89f.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_hstruck_001","title":"Сильный урон I","description":"Всё в порядке… мне не больно.","language":"Японский","audioUrl":"/nte-meta/game-audio/368e6bef02a4495921f5.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_hstruck_001","title":"Сильный урон I","description":"Всё в порядке… мне не больно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a5be81ae744fa22b520c.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_TeammateDown_001","title":"Поражён товарищ по команде – Аканэ","description":"Тебе не нужно справляться с этим в одиночку — позволь мне помочь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e7cbda02416d4f145ccd.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_QTE_003","title":"Атака на входе III","description":"Все в унисон!","language":"Китайский","audioUrl":"/nte-meta/game-audio/539e1d01da5013de59de.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_struck_002","title":"Урон II","description":"Да это всего лишь царапина.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6aead5adab0e93d744a8.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_talk_003","title":"Тема: аномалия","description":"Если бы я тогда не взялась за задание по нуллификации Парусника, возможно, ничего этого бы не случилось. Та аномалия была настолько же опасна, насколько прекрасна… Я знаю, что ты очень способный охотник за аномалиями, но, пожалуйста, береги себя. Не только ради себя, но и ради тех, кто тебя любит и за тебя переживает.Если бы я тогда не взялась за задание по нуллификации Парусника, возможно, ничего этого бы не случилось. Та аномалия была настолько же опасна, насколько прекрасна… Я знаю, что ты очень способная охотница за аномалиями, но, пожалуйста, береги себя. Не только ради себя, но и ради тех, кто тебя любит и за тебя переживает.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5627faa0f94ab7ccc8e2.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_windfall_006","title":"Неожиданная добыча VI","description":"Памятный знак на сегодня.","language":"Японский","audioUrl":"/nte-meta/game-audio/2bf2e306dc3070741cb8.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_talk_001","title":"Тема: медузы","description":"Время от времени на берегу можно найти медуз, которых выбросило отступающим приливом, — может, они тоже сбились с пути… Если увидишь медузу на пляже, пожалуйста, не трогай её. Они могут казаться мягкими и безобидными, но многие из них ядовиты. Ой, но те, что со мной, совершенно безобидные, так что не переживай!","language":"Корейский","audioUrl":"/nte-meta/game-audio/4c4c7b3ca574df8c3cf3.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_about_001_02","title":"О «ЛИНИЯХ»","description":"Правда в том, что группа «ЛИНИИ» появилась не из желания играть музыку. Я просто хотела найти причину, чтобы мы трое не расставались после выпуска. Наверное, поэтому, когда я больше не могла играть, группа просто распалась… Но связи между людьми — это не только прямые линии — даже если одна точка пересечения исчезает, у нас всё равно остаётся шанс встретиться снова. Жаль, что я не поняла этого раньше… но даже сейчас ещё не слишком поздно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/623b945bbe8e01c6d634.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_containment_002","title":"Сдерживание II","description":"Оставайся в контейнере.","language":"Китайский","audioUrl":"/nte-meta/game-audio/347618da8b2eac3b33f1.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_DodgeCombo_002","title":"Серия критических уклонений II","description":"Идеальный ритм!","language":"Китайский","audioUrl":"/nte-meta/game-audio/5ac1b0d5ade7a7fa89ac.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_weather_004","title":"Жарко","description":"Так жарко… мои медузы совсем разомлели. Давай отдохнём в теньке.","language":"Китайский","audioUrl":"/nte-meta/game-audio/25394898aecc123c2b1f.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_QTE_002","title":"Атака на входе II","description":"Занять позиции!","language":"Китайский","audioUrl":"/nte-meta/game-audio/187f0514b1b7948b2632.ogg"},{"id":"en-Play_Vo_Char_NPC1029_aoe_UI_001","title":"Сверхспособность I","description":"Кружись в полёте галактик.","language":"Английский","audioUrl":"/nte-meta/game-audio/0fecea2e7b5e5a059289.ogg"},{"id":"en-Play_Vo_Char_NPC1029_kill_002","title":"Убийство II","description":"Не недооценивай меня!","language":"Английский","audioUrl":"/nte-meta/game-audio/51478f862431be31d9d5.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_greet_002","title":"Дневное приветствие","description":"Хе-хе, я сама испекла этот торт! Разве он не прелесть? Давай я отрежу тебе кусочек!","language":"Японский","audioUrl":"/nte-meta/game-audio/d2c8b744b1ceb4f647bf.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_vexation_001","title":"Проблемы","description":"Мой привычный навигатор в последнее время постоянно обновляется и жутко глючит. В итоге я теперь всё время теряюсь. На этой неделе я уже несколько раз опаздывала на подработку… Моя добрая начальница не стала вычитать это из зарплаты, но мне всё равно неловко… Наверное, стоит купить бумажную карту, пока приложение не починят.","language":"Корейский","audioUrl":"/nte-meta/game-audio/0910b41817201ff21ac5.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_dead_002","title":"Потеря сознания II","description":"Я так и не… научилась…","language":"Китайский","audioUrl":"/nte-meta/game-audio/73a1cb425a0cd100497a.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_greet_004","title":"Спокойной ночи","description":"Чтобы хорошо провести день, нужно хорошо выспаться. Ложись пораньше, увидимся завтра.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3f6ed9942895d4f5560e.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_vexation_001","title":"Проблемы","description":"Мой привычный навигатор в последнее время постоянно обновляется и жутко глючит. В итоге я теперь всё время теряюсь. На этой неделе я уже несколько раз опаздывала на подработку… Моя добрая начальница не стала вычитать это из зарплаты, но мне всё равно неловко… Наверное, стоит купить бумажную карту, пока приложение не починят.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2ef3a829917c9c455868.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_gift_002","title":"Подарок получен II","description":"Ох, как раз то, что я хотела! Ты что, фея, исполняющая желания?","language":"Японский","audioUrl":"/nte-meta/game-audio/5175afaac30586817b92.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_containment_002","title":"Сдерживание II","description":"Оставайся в контейнере.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e92d8def3f42fdfc239d.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_hp_003","title":"Низкий уровень здоровья III","description":"Уф… нельзя… проигрывать.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b0cac4c44dbf075c0a87.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_chat_003","title":"Чат: музыка","description":"У каждого музыкального жанра своё очарование, и каждая песня несёт в себе уникальные эмоции её автора. Но если ты спросишь про мою любимую группу… я не смогу выбрать какую-то одну. Давай я лучше составлю для тебя целый плейлист!","language":"Китайский","audioUrl":"/nte-meta/game-audio/4b36d976e13fbfd7408c.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_meet_001","title":"Первая встреча","description":"Привет, меня зовут Аурелия… Ой, моя медуза тебя пугает? Прости, она просто так радуется встрече с новым другом… Надеюсь, ты не против. Хм? Тебе совсем не страшно? Вот и славно! Привет, меня зовут Аурелия… Ой, моя медуза тебя пугает? Прости, она просто так радуется встрече с новой подругой… Надеюсь, ты не против. Хм? Тебе совсем не страшно? Вот и славно!","language":"Китайский","audioUrl":"/nte-meta/game-audio/d03488a4aa8fe8bc3618.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_weather_001","title":"Солнечно","description":"Опять отличный день! Солнышко светит ярко, и у меня на душе тоже светло!","language":"Китайский","audioUrl":"/nte-meta/game-audio/cf9d627d14271cee0961.ogg"},{"id":"en-Play_Vo_Char_NPC1029_anomaly_004","title":"Нуллификация II","description":"Миссия выполнена. Спасибо за помощь!","language":"Английский","audioUrl":"/nte-meta/game-audio/f56b8c7f806984fb5a04.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_deploy_001","title":"Отправка I","description":"По твоей команде.","language":"Японский","audioUrl":"/nte-meta/game-audio/d943174cc8bada714f62.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_kill_001","title":"Убийство I","description":"Фух, справилась!","language":"Японский","audioUrl":"/nte-meta/game-audio/fd8041d8bfabaed553d5.ogg"},{"id":"ja-Play_Vo_Char_NPC1029_Parry_001","title":"Парирование I","description":"Уф, пронесло!","language":"Японский","audioUrl":"/nte-meta/game-audio/f7fed3c0661857416406.ogg"},{"id":"ko-Play_Vo_Char_NPC1029_Switch_003","title":"Переключение III","description":"Мы с этим справимся.","language":"Корейский","audioUrl":"/nte-meta/game-audio/87c81bc0d8feafd4ab69.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_chat_001","title":"Чат: совет","description":"Никогда не надевай широкие штаны, если садишься за барабаны! Если сильно ударишь по педали, штанина может легко запутаться в колотушке бас-бочки…","language":"Китайский","audioUrl":"/nte-meta/game-audio/bfac2208be4d66c91132.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_Switch_001","title":"Переключение I","description":"Безопасность прежде всего. Отдохни.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3b40caf5979f1b58d05d.ogg"},{"id":"zh-Play_Vo_Char_NPC1029_talk_002","title":"Тема: опасное вождение","description":"Эта медуза просто слишком большая, чтобы поместиться в большинстве видов транспорта. К счастью, она быстрая, так что даже если случится что-то срочное — не будет проблемы из-за того, что не смогу в машину сесть… Хм? Хочешь знать, насколько она быстрая? Ну… скажем так: недостаточно быстрая, чтобы офицер Усатик выписал мне штраф за превышение скорости при езде на медузе по городу.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0d46d7015d4920e17897.ogg"},{"id":"en-Play_Vo_Char_NPC1029_aoe_UI_002","title":"Сверхспособность II","description":"Утяни приливы в саму ночь.","language":"Английский","audioUrl":"/nte-meta/game-audio/1253e5c7244492f5663c.ogg"},{"id":"en-Play_Vo_Char_NPC1029_skill_002","title":"Навык перенаправления II","description":"Пусть зазвучит гимн океана!","language":"Английский","audioUrl":"/nte-meta/game-audio/1e25264d5967450c1db6.ogg"},{"id":"en-Play_Vo_Char_NPC1029_windfall_006","title":"Неожиданная добыча VI","description":"Памятный знак на сегодня.","language":"Английский","audioUrl":"/nte-meta/game-audio/cac1df3799a11d5d0be9.ogg"}]'))) WHERE character_id='aurelia' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:07:15');

UPDATE character_profiles SET abilities_json=json('[{"id":"361190aa-af9a-46ae-9f64-ee1f8f3a87af","name":"Капелла","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/6b5629efd1a4f06459b1.webp","description":"Техника вокала — ключевое умение для любого дирижёра, так что я продолжаю тренироваться. Включи корпус, расслабь челюсть, позволь звуку течь из задней части головы и выходить наружу через лоб… «А-а-а-а…» …Почему мне кажется, что даже мой собственный голос ускользает?","attributes":[{"id":"parameter-0","label":"Множитель урона 1-го удара","value":"1: 34.7 % · 2: 37.5 % · 3: 40.5 % · 4: 43.7 % · 5: 47.2 % · 6: 51 % · 7: 55.1 % · 8: 59.5 % · 9: 64.2 % · 10: 69.4 % · 11: 74.9 % · 12: 80.9 % · 13: 87.4 %"},{"id":"parameter-1","label":"Множитель урона 2-го удара","value":"1: 63 % · 2: 68 % · 3: 73.5 % · 4: 79.4 % · 5: 85.7 % · 6: 92.6 % · 7: 100 % · 8: 108 % · 9: 116.6 % · 10: 125.9 % · 11: 136 % · 12: 146.9 % · 13: 158.6 %"},{"id":"parameter-2","label":"Множитель урона снаряда 3-го удара","value":"1: 30 % *3 · 2: 32.4 % *3 · 3: 35 % *3 · 4: 37.8 % *3 · 5: 40.8 % *3 · 6: 44.1 % *3 · 7: 47.6 % *3 · 8: 51.4 % *3 · 9: 55.5 % *3 · 10: 60 % *3 · 11: 64.8 % *3 · 12: 69.9 % *3 · 13: 75.5 % *3"},{"id":"parameter-3","label":"Множитель урона 4-го удара","value":"1: 9.9 % *4 · 2: 10.7 % *4 · 3: 11.5 % *4 · 4: 12.5 % *4 · 5: 13.5 % *4 · 6: 14.5 % *4 · 7: 15.7 % *4 · 8: 17 % *4 · 9: 18.3 % *4 · 10: 19.8 % *4 · 11: 21.4 % *4 · 12: 23.1 % *4 · 13: 24.9 % *4"},{"id":"parameter-4","label":"Множитель урона атаки в падении","value":"1: 130 % · 2: 140.4 % · 3: 151.6 % · 4: 163.8 % · 5: 176.9 % · 6: 191 % · 7: 206.3 % · 8: 222.8 % · 9: 240.6 % · 10: 259.9 % · 11: 280.7 % · 12: 303.1 % · 13: 327.4 %"},{"id":"parameter-5","label":"Удерживание уклонения: множитель урона снаряда","value":"1: 25.8 % · 2: 27.9 % · 3: 30.1 % · 4: 32.5 % · 5: 35.1 % · 6: 37.9 % · 7: 40.9 % · 8: 44.2 % · 9: 47.8 % · 10: 51.6 % · 11: 55.7 % · 12: 60.2 % · 13: 65 %"},{"id":"parameter-6","label":"Множитель урона критического контрудара","value":"1: 195 % · 2: 210.6 % · 3: 227.4 % · 4: 245.6 % · 5: 265.3 % · 6: 286.5 % · 7: 309.4 % · 8: 334.2 % · 9: 360.9 % · 10: 389.8 % · 11: 421 % · 12: 454.7 % · 13: 491 %"},{"id":"parameter-7","label":"Множитель урона снаряда особого критического контрудара","value":"1: 40 % ×4 · 2: 43.2 % ×4 · 3: 46.7 % ×4 · 4: 50.4 % ×4 · 5: 54.4 % ×4 · 6: 58.8 % ×4 · 7: 63.5 % ×4 · 8: 68.6 % ×4 · 9: 74 % ×4 · 10: 80 % ×4 · 11: 86.4 % ×4 · 12: 93.3 % ×4 · 13: 100.7 % ×4"}]},{"id":"fe0a3325-d9dc-4a5f-b7db-2ec9179cc467","name":"Виртуозная ария","type":"Навык","iconUrl":"/nte-meta/game-assets/2e1949c96a85c8397f8e.webp","description":"Преврати повседневность в радужную мелодию и позволь ей греметь над горизонтом. Наносит 1 экземпляр урона психики по области и входит в состояние Каденции на 12 сек.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 100 % · 2: 108 % · 3: 116.6 % · 4: 126 % · 5: 136 % · 6: 146.9 % · 7: 158.7 % · 8: 171.4 % · 9: 185.1 % · 10: 199.9 % · 11: 215.9 % · 12: 233.2 % · 13: 251.8 %"}]},{"id":"c8484efe-f374-483b-9f9f-767d697ad8e0","name":"Канонический хор","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/03c74e1ae631107b41c1.webp","description":"Споём следующий куплет вместе! Собирает ближайших медуз, нанося Урон психики 6 раз по области и слегка стягивая противников друг к другу.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 89 % *5 + 55.2 % · 2: 96.1 % *5 + 59.6 % · 3: 103.8 % *5 + 64.4 % · 4: 112.1 % *5 + 69.5 % · 5: 121.1 % *5 + 75.1 % · 6: 130.8 % *5 + 81.1 % · 7: 141.2 % *5 + 87.6 % · 8: 152.5 % *5 + 94.6 % · 9: 164.7 % *5 + 102.2 % · 10: 177.9 % *5 + 110.3 % · 11: 192.1 % *5 + 119.2 % · 12: 207.5 % *5 + 128.7 % · 13: 224.1 % *5 + 139 %"}]},{"id":"7b452adc-7b61-4a6d-88bc-ac6571891530","name":"Диссонанс","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/fb378111668fcb4d3c56.webp","description":"Истинное мастерство есть безупречное чувство времени. Приказывает медузе атаковать, нанося Урон психики по области.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"GA_Mitsuki_Passive1","name":"Гармоника","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/a691cb66c16bf1601e70.webp","description":"Усиление Новы: после завершения состояния «Новы» наносит цели Урон психики 3 раза, каждый раз в размере 50 % от АТК.\n\nКак доказать, что звук — это волна? Брось камень в воду — увидишь расходящиеся круги; брось камень в кого-нибудь — услышишь волну за волной шума.\n\n«…Мне нужно смеяться?»\n\n«Шутки Аурелии совсем не смешные…»\n\n«Да ладно! Раньше люди это на ура принимали… у вас, молодёжи, просто слишком высокие стандарты юмора».","attributes":[]},{"id":"GA_Mitsuki_Passive2","name":"Крещендо","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/0935478ec1e4e9b66365.webp","description":"Когда медузный взрыв поражает цель, АТК Аурелии повышается на 1 % на 5 сек., складывается до 10 раз.\n\nСильнее… ещё сильнее… Суперзвук… Предельный звук! Хочешь ещё громче? Тогда барабанщику придётся броситься на барабан головой вперёд!","attributes":[]},{"id":"GA_Mitsuki_Passive3","name":"Безграничный звук","type":"Черта персонажа","iconUrl":"/nte-meta/game-assets/031511d9211a16247958.webp","description":"Аурелия верхом на медузе плавно скользит по городским улицам и переулкам. Она не может карабкаться или преодолевать препятствия, но её прыжок выше, и она получает особые способности к планированию и плаванию.\n\nНевозможность сделать шаг не значит, что нельзя продолжать двигаться вперёд. Позволь своему сердцу быть таким же свободным и безграничным, как мир — как только отправишься в путь, нет места, куда ты не сможешь добраться.","attributes":[]},{"id":"City_Ability_Mitsuki_01","name":"Идеально сидит","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/3fe430be6064658fec5c.webp","description":"Аурелия дополнительно увеличивает цены блюд на 0,12 фонса.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Аурелия дополнительно увеличивает цены блюд на 0,12 фонса."},{"id":"city-1","label":"Уровень 2","value":"Если Аурелия работает в магазине, а выставленные на продажу блюда имеют 2 метки напитка, поток дополнительно увеличивается на 1 %."},{"id":"city-2","label":"Уровень 3","value":"В режиме подборки владельца клиенты оставляют дополнительные чаевые при уходе."},{"id":"city-3","label":"Уровень 4","value":"Аурелия снижает скорость расхода ингредиентов на 1 %."},{"id":"city-4","label":"Уровень 5","value":"Если Аурелия работает в магазине, а выставленные на продажу блюда имеют 2 метки напитка, поток дополнительно увеличивается на 1,5 %."}]}]') WHERE character_id='aurelia' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:07:15');

UPDATE character_profiles SET updated_at=CURRENT_TIMESTAMP WHERE character_id='aurelia' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-27 10:07:15');

UPDATE character_profiles SET voice_actors_json=json('[{"language":"Китайский","name":"桑毓泽"},{"language":"Английский","name":"Griffin Burns"},{"language":"Японский","name":"中村悠一"},{"language":"Корейский","name":"심규혁"},{"language":"Китайский","name":"Sang Yuze (桑毓泽)"},{"language":"Японский","name":"Юичи Накамура (中村 悠一)"},{"language":"Корейский","name":"Shim Kyu-hyeok (심규혁)"}]') WHERE character_id='baicang' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-01 09:11:10');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"zh-Play_Vo_Char_NPC006_about_004","title":"О Лакримозе","description":"Моза невероятно талантлива, но она все ещё ребенок, который почти ничего не знает о мире. Как взрослый я должен присматривать за ней. Эх, и почему она меня так ненавидит? Это разбивает мне сердце…","language":"Китайский","audioUrl":"/nte-meta/game-audio/4e566fec96709a71cfa1.ogg"},{"id":"zh-Play_Vo_Char_NPC006_TeammateDown_002","title":"Поражен товарищ по команде – Фадия","description":"Неожиданный финал, не так ли?","language":"Китайский","audioUrl":"/nte-meta/game-audio/92a3395a3a26f76f31bb.ogg"},{"id":"en-Play_Vo_Char_NPC006_chat_001","title":"Чат: расслабление","description":"Серьезность — это достоинство, но постоянное напряжение чрезмерно выматывает! Прими дружеский совет — иногда нужно расслабляться!","language":"Английский","audioUrl":"/nte-meta/game-audio/3b5c04722062589883e9.ogg"},{"id":"en-Play_Vo_Char_NPC006_windfall_001","title":"Неожиданная добыча I","description":"Буду считать это платой за переработку.","language":"Английский","audioUrl":"/nte-meta/game-audio/b82305cd69acc52d3445.ogg"},{"id":"ja-Play_Vo_Char_NPC006_about_005","title":"О Хотори","description":"Иногда она напоминает мне Директора — её так же сложно понять… Хотя, кажется, сейчас она уже не та, что в прошлом? Может быть слишком много пьет?","language":"Японский","audioUrl":"/nte-meta/game-audio/c68c909c3cd289601290.ogg"},{"id":"ja-Play_Vo_Char_NPC006_ug_001","title":"Вознесение персонажа I","description":"Время от времени стоит делать шаг вперед.","language":"Японский","audioUrl":"/nte-meta/game-audio/cc42233c1083bf1f5c8b.ogg"},{"id":"ko-Play_Vo_Char_NPC006_hstruck_002","title":"Сильный урон II","description":"…Я стал небрежным.","language":"Корейский","audioUrl":"/nte-meta/game-audio/952f59e0ffe47bfe213b.ogg"},{"id":"zh-Play_Vo_Char_NPC006_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Такой прекрасный день, идеален для отдыха… А, хотя лучше, чтобы они меня не нашли. Пока.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e1472b556b953a06734b.ogg"},{"id":"zh-Play_Vo_Char_NPC006_weather_001","title":"Солнечно","description":"Обидно провести такой прекрасный день в душном офисе, перекладывая бумажки. Да! Займусь этим позже.","language":"Китайский","audioUrl":"/nte-meta/game-audio/591a9bbc6124b125cc73.ogg"},{"id":"en-Play_Vo_Char_NPC006_QTE_003","title":"Атака на входе III","description":"Эй, полегче. Сильно не бей.","language":"Английский","audioUrl":"/nte-meta/game-audio/e737abfaa66d7253de1c.ogg"},{"id":"en-Play_Vo_Char_NPC006_self_001","title":"Обо мне: способности эспера","description":"Слова обладают гораздо большей силой, чем думают люди. Страшно, да? Ха-ха… При желании даже самые простые слова с легкостью принесут страдание или счастье. Но, уверен, ты знаешь, как пользоваться этой силой с умом.","language":"Английский","audioUrl":"/nte-meta/game-audio/1769d529bf514303fef3.ogg"},{"id":"ja-Play_Vo_Char_NPC006_aoe_UI_003","title":"Сверхспособность III","description":"Что это — благословение или… проклятие?","language":"Японский","audioUrl":"/nte-meta/game-audio/67acb2816c6181dbb1de.ogg"},{"id":"ko-Play_Vo_Char_NPC006_skill_003","title":"Навык перенаправления III","description":"Ш-ш-ш… тихо.","language":"Корейский","audioUrl":"/nte-meta/game-audio/def565be57845ddd6fdf.ogg"},{"id":"ko-Play_Vo_Char_NPC006_TeammateDown_002","title":"Поражен товарищ по команде – Фадия","description":"Неожиданный финал, не так ли?","language":"Корейский","audioUrl":"/nte-meta/game-audio/999a3966c54aad1080a5.ogg"},{"id":"ko-Play_Vo_Char_NPC006_weather_004","title":"Жарко","description":"Я хочу наградить себя за прилежную работу в такую жару! Планирую отклониться от маршрута и купить мороженое в «Снежке». Ш-ш-ш, не говори Скии… Хм? Эй, это не безделье! Но в благодарность за хранение тайны я возьму одно и для тебя! Так что, с каким вкусом ты любишь?","language":"Корейский","audioUrl":"/nte-meta/game-audio/7bba2535e7dfeb0fb545.ogg"},{"id":"zh-Play_Vo_Char_NPC006_about_006","title":"О Бюро по борьбе с аномалиями","description":"В Бюро было бы неплохо без кучи замысловатых правил и чопорных традиционалистов. Хотя, если убрать их, наверное, мало что останется, да?","language":"Китайский","audioUrl":"/nte-meta/game-audio/32a3ba1195b55e4d2fef.ogg"},{"id":"zh-Play_Vo_Char_NPC006_containment_001","title":"Сдерживание I","description":"Добро пожаловать домой!","language":"Китайский","audioUrl":"/nte-meta/game-audio/1f10bd500731b0e8402e.ogg"},{"id":"en-Play_Vo_Char_NPC006_TeammateDown_001","title":"Поражен товарищ по команде – Ския","description":"Лейтенант пал — и это всё, на что способен Отряд 4? Соберитесь!","language":"Английский","audioUrl":"/nte-meta/game-audio/a0338b681e7a33594b5c.ogg"},{"id":"en-Play_Vo_Char_NPC006_weather_003","title":"Холодно","description":"Я предложил ввести для своего отряда «отгулы из-за холодной погоды». Все проголосовали «за»… кроме Скии. И наша любимая директор отклонила мое предложение. Что ж, если там, откуда ты родом, есть «отгулы из-за холодной погоды» или «зимние каникулы», насладись ими и за меня тоже.","language":"Английский","audioUrl":"/nte-meta/game-audio/8c6d88554b635ee5b5f9.ogg"},{"id":"ja-Play_Vo_Char_NPC006_windfall_001","title":"Неожиданная добыча I","description":"Буду считать это платой за переработку.","language":"Японский","audioUrl":"/nte-meta/game-audio/20e1ea0a6312d3476954.ogg"},{"id":"ko-Play_Vo_Char_NPC006_aoe_UI_002","title":"Сверхспособность II","description":"Произнесенное вслух требует уважения.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a36c37d4947aead6873a.ogg"},{"id":"zh-Play_Vo_Char_NPC006_dead_002","title":"Потеря сознания II","description":"Этот день… пришел быстрее, чем я думал…","language":"Китайский","audioUrl":"/nte-meta/game-audio/d6c2d32cafc29d4630b0.ogg"},{"id":"zh-Play_Vo_Char_NPC006_DodgeCombo_001","title":"Серия критических уклонений I","description":"Фух… это было близко!","language":"Китайский","audioUrl":"/nte-meta/game-audio/41942424f4a5a5075232.ogg"},{"id":"en-Play_Vo_Char_NPC006_about_004","title":"О Лакримозе","description":"Моза невероятно талантлива, но она все ещё ребенок, который почти ничего не знает о мире. Как взрослый я должен присматривать за ней. Эх, и почему она меня так ненавидит? Это разбивает мне сердце…","language":"Английский","audioUrl":"/nte-meta/game-audio/d06c6bd3c6f94af2830d.ogg"},{"id":"ja-Play_Vo_Char_NPC006_QTE_002","title":"Атака на входе II","description":"Мне бы не помешала разминка.","language":"Японский","audioUrl":"/nte-meta/game-audio/78fc5344a7a77c032dd9.ogg"},{"id":"ja-Play_Vo_Char_NPC006_Switch_002","title":"Переключение II","description":"Я? Ладно, тогда.","language":"Японский","audioUrl":"/nte-meta/game-audio/c7e3373d4240db5a1cef.ogg"},{"id":"zh-Play_Vo_Char_NPC006_Fly_002","title":"Планирование II","description":"Привет, птичка.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e41f15da0f9c99db6b85.ogg"},{"id":"ja-Play_Vo_Char_NPC006_containment_001","title":"Сдерживание I","description":"Добро пожаловать домой!","language":"Японский","audioUrl":"/nte-meta/game-audio/59d7819230e3472f8287.ogg"},{"id":"ja-Play_Vo_Char_NPC006_weather_002","title":"Дождливо","description":"Если хочешь скоротать время, понаблюдай за черепицей на крышах во время дождя. Это довольно увлекательно. Она так необычно мерцает, и капли дождя отскакивают от неё в разные стороны, создавая звуки разной частоты… как будто кто-то пытается что-то прошептать.","language":"Японский","audioUrl":"/nte-meta/game-audio/cca122516d57f5be905b.ogg"},{"id":"zh-Play_Vo_Char_NPC006_windfall_001","title":"Неожиданная добыча I","description":"Буду считать это платой за переработку.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e3e19bdec29c3584b69f.ogg"},{"id":"en-Play_Vo_Char_NPC006_about_006","title":"О Бюро по борьбе с аномалиями","description":"В Бюро было бы неплохо без кучи замысловатых правил и чопорных традиционалистов. Хотя, если убрать их, наверное, мало что останется, да?","language":"Английский","audioUrl":"/nte-meta/game-audio/becd7f6c31dbf3d23fd5.ogg"},{"id":"ko-Play_Vo_Char_NPC006_greet_002","title":"Дневное приветствие","description":"Ты вовремя. Я как раз хотел выпить чаю в перерыв на обед. Хочешь присоединиться?","language":"Корейский","audioUrl":"/nte-meta/game-audio/99b259b64c3f63d2ca85.ogg"},{"id":"ko-Play_Vo_Char_NPC006_SSC_004","title":"Особое переключение — Минт","description":"Надо устроить новичкам хорошее представление.","language":"Корейский","audioUrl":"/nte-meta/game-audio/3ae10107ce2a5ef9b791.ogg"},{"id":"zh-Play_Vo_Char_NPC006_dead_001","title":"Потеря сознания I","description":"Не здесь… и не где-либо еще…","language":"Китайский","audioUrl":"/nte-meta/game-audio/cee71bb5294199c501ad.ogg"},{"id":"zh-Play_Vo_Char_NPC006_QTE_002","title":"Атака на входе II","description":"Мне бы не помешала разминка.","language":"Китайский","audioUrl":"/nte-meta/game-audio/1747e307a22794dc60d1.ogg"},{"id":"en-Play_Vo_Char_NPC006_greet_002","title":"Дневное приветствие","description":"Ты вовремя. Я как раз хотел выпить чаю в перерыв на обед. Хочешь присоединиться?","language":"Английский","audioUrl":"/nte-meta/game-audio/566b72c6b9a6d28bb325.ogg"},{"id":"en-Play_Vo_Char_NPC006_greet_004","title":"Спокойной ночи","description":"Глаза слипаются? Ой… видимо, уже ночь. Я так заболтался с тобой, что прошло уже много времени, а я и не заметил. Виноват, виноват.","language":"Английский","audioUrl":"/nte-meta/game-audio/c258e59b6eb206c583e2.ogg"},{"id":"en-Play_Vo_Char_NPC006_Switch_002","title":"Переключение II","description":"Я? Ладно, тогда.","language":"Английский","audioUrl":"/nte-meta/game-audio/362278873dadf1cbbf41.ogg"},{"id":"ja-Play_Vo_Char_NPC006_Switch_003","title":"Переключение III","description":"Огонь по своим!","language":"Японский","audioUrl":"/nte-meta/game-audio/a8c50131b59ab326abc4.ogg"},{"id":"ja-Play_Vo_Char_NPC006_anomaly_004","title":"Нуллификация II","description":"Я просто… напишу что-нибудь в отчете о миссии.","language":"Японский","audioUrl":"/nte-meta/game-audio/da356b7cb6bd18673e19.ogg"},{"id":"ja-Play_Vo_Char_NPC006_aoe_UI_001","title":"Сверхспособность I","description":"Бесчестные слова недопустимы.","language":"Японский","audioUrl":"/nte-meta/game-audio/4b7a1aead03ed6635fba.ogg"},{"id":"ko-Play_Vo_Char_NPC006_TeammateDown_004","title":"Поражен товарищ по команде – Минт","description":"За такое нам точно положены выплаты за травмы.","language":"Корейский","audioUrl":"/nte-meta/game-audio/2a3dac0a8667e0f14ca2.ogg"},{"id":"zh-Play_Vo_Char_NPC006_about_005","title":"О Хотори","description":"Иногда она напоминает мне Директора — её так же сложно понять… Хотя, кажется, сейчас она уже не та, что в прошлом? Может быть слишком много пьет?","language":"Китайский","audioUrl":"/nte-meta/game-audio/f56537a4d79f67cee522.ogg"},{"id":"zh-Play_Vo_Char_NPC006_about_008","title":"О ТОИ-4","description":"Капитан Отряда 4 брошен в одиночестве членами его команды…? Кто это сказал? Это неправда! Мы известны во всём Бюро как образцовая команда с беспрецедентной сплочённостью… Стой, тебе довелось увидеть, как Моза, Фадия и Ския встретились на площади, чтобы вместе пойти за покупками и поужинать? А? Когда это было?","language":"Китайский","audioUrl":"/nte-meta/game-audio/e8661f0090cea9ff6eae.ogg"},{"id":"en-Play_Vo_Char_NPC006_windfall_003","title":"Неожиданная добыча III","description":"Если тебе это нужно, держи в кармане.","language":"Английский","audioUrl":"/nte-meta/game-audio/cc1f5c571a7c0ba4333b.ogg"},{"id":"ko-Play_Vo_Char_NPC006_dead_003","title":"Потеря сознания III","description":"Надеюсь… меня ждет приветственная церемония…","language":"Корейский","audioUrl":"/nte-meta/game-audio/c971d066c83a6fcac882.ogg"},{"id":"ko-Play_Vo_Char_NPC006_DodgeCombo_002","title":"Серия критических уклонений II","description":"Безупречное исполнение.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1982338205a558a82fb1.ogg"},{"id":"ko-Play_Vo_Char_NPC006_skill_002","title":"Навык перенаправления II","description":"Навостри уши.","language":"Корейский","audioUrl":"/nte-meta/game-audio/45b5a8e648582850e997.ogg"},{"id":"zh-Play_Vo_Char_NPC006_gift_001","title":"Подарок получен I","description":"Ага, похоже, у нас с тобой одинаковый утончённый вкус!","language":"Китайский","audioUrl":"/nte-meta/game-audio/5f09dde4253010789eeb.ogg"},{"id":"zh-Play_Vo_Char_NPC006_hp_001","title":"Низкий уровень здоровья I","description":"Ах… Сейчас было бы неплохо взять тайм-аут.","language":"Китайский","audioUrl":"/nte-meta/game-audio/9006525e36014ac15c9c.ogg"},{"id":"zh-Play_Vo_Char_NPC006_SSC_003","title":"Особое переключение — Лакримоза","description":"Эй! Нападай на того, кто твоего размера.","language":"Китайский","audioUrl":"/nte-meta/game-audio/4cec2863c5fd5ad9a7d5.ogg"},{"id":"en-Play_Vo_Char_NPC006_hp_001","title":"Низкий уровень здоровья I","description":"Ах… Сейчас было бы неплохо взять тайм-аут.","language":"Английский","audioUrl":"/nte-meta/game-audio/961faa756806d40d4150.ogg"},{"id":"ja-Play_Vo_Char_NPC006_gift_003","title":"Подарок получен III","description":"Подарок за подарок. Мой подарок тебе… дай-ка подумать.","language":"Японский","audioUrl":"/nte-meta/game-audio/3766ae40927cabb6f354.ogg"},{"id":"ja-Play_Vo_Char_NPC006_gift_004","title":"Подарок получен IV","description":"Тс-с! Бюро ни за что не позволит своим капитанам брать взятки!","language":"Японский","audioUrl":"/nte-meta/game-audio/c5f0e63ef6d322858081.ogg"},{"id":"ko-Play_Vo_Char_NPC006_self_003","title":"Обо мне: капитан","description":"Такие звания, как «Капитан», на самом деле мало что значат. Я не из тех, кто задирает нос, а моя команда? Они не станут больше уважать меня из-за какого-то звания. Честно говоря, быть капитаном — сплошная морока… кстати об этом, нужно придумать предлог, чтобы Ския смог прийти за меня на собрание Бюро завтра утром…","language":"Корейский","audioUrl":"/nte-meta/game-audio/43b9464b1a6c1651d69f.ogg"},{"id":"ko-Play_Vo_Char_NPC006_struck_001","title":"Урон I","description":"Т-с.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f1ca0af1291b8d5ee66b.ogg"},{"id":"zh-Play_Vo_Char_NPC006_about_002","title":"О Скии","description":"Пусть жуткое лицо Скии не обманывает тебя, он относится к работе очень серьезно. Ха-ха, с таким надежным Лейтенантом быть Капитаном значительно проще. Хотя было бы неплохо, если бы он не был так строг к моим мелким промахам.","language":"Китайский","audioUrl":"/nte-meta/game-audio/8e1bce5123ed63d641c4.ogg"},{"id":"zh-Play_Vo_Char_NPC006_Parry_002","title":"Парирование II","description":"Смотри и учись.","language":"Китайский","audioUrl":"/nte-meta/game-audio/4878bcf2ca62ecac452a.ogg"},{"id":"en-Play_Vo_Char_NPC006_anomaly_003","title":"Нуллификация I","description":"Спи крепко.","language":"Английский","audioUrl":"/nte-meta/game-audio/78175e605c3ecc2a872c.ogg"},{"id":"en-Play_Vo_Char_NPC006_dead_002","title":"Потеря сознания II","description":"Этот день… пришел быстрее, чем я думал…","language":"Английский","audioUrl":"/nte-meta/game-audio/6d55e681f215d688e337.ogg"},{"id":"ja-Play_Vo_Char_NPC006_chat_002","title":"Чат: шалости","description":"Интересно, почему я здесь? Ах… как видишь, Фадия и Моза заперли меня снаружи. Вздох… Как они могли так жестоко поступить с собственным капитаном… Хм? «Что ты сделал на этот раз?» Эй, это несправедливо ко мне, не находишь? Даже ты считаешь, что я виноват? Ну да, я нарисовал на лице Мозы усы, пока она спала… Но Фадия уже сравняла счёт! И всё равно они заперли меня снаружи! Несправедливый суд и незаслуженное наказание…","language":"Японский","audioUrl":"/nte-meta/game-audio/2e636025405045dbc5c4.ogg"},{"id":"ja-Play_Vo_Char_NPC006_chat_003","title":"Чат: приглашение","description":"Кажется, ты хорошо проводишь время в «Эйбоне». Видимо, ты ей нравишься. Но… если захочешь сменить обстановку, двери в ТОИ всегда открыты.","language":"Японский","audioUrl":"/nte-meta/game-audio/31ca6a343b1f5d32f500.ogg"},{"id":"ja-Play_Vo_Char_NPC006_DodgeCombo_001","title":"Серия критических уклонений I","description":"Фух… это было близко!","language":"Японский","audioUrl":"/nte-meta/game-audio/4b0b63f9881f8b89c5d2.ogg"},{"id":"ja-Play_Vo_Char_NPC006_hp_002","title":"Низкий уровень здоровья II","description":"Серьезно.","language":"Японский","audioUrl":"/nte-meta/game-audio/fae0848f5bd245d5bce1.ogg"},{"id":"ko-Play_Vo_Char_NPC006_talk_002","title":"Тема: выходной","description":"Отпуск — это возможность исполнить все свои прихоти и построить спонтанные планы! Для меня — потягивать чай, заглянуть в новую пекарню, обменяться советами по садоводству с флористом, встретиться со старыми друзьями… Ах, ещё прогуляться в прекрасном лесу около кладбища у подножия горы. Вечером, когда ветерок ласкает кожу… Это так приятно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/31f6544edc887323da1b.ogg"},{"id":"ja-Play_Vo_Char_NPC006_kill_001","title":"Убийство I","description":"Слишком сильно ударил?","language":"Японский","audioUrl":"/nte-meta/game-audio/1f2093e860a4b1872112.ogg"},{"id":"ko-Play_Vo_Char_NPC006_QTE_001","title":"Атака на входе I","description":"Эй, не отвлекайся!","language":"Корейский","audioUrl":"/nte-meta/game-audio/f8f6b52e718f07e0f099.ogg"},{"id":"zh-Play_Vo_Char_NPC006_struck_001","title":"Урон I","description":"Т-с.","language":"Китайский","audioUrl":"/nte-meta/game-audio/26e9d88b14c91e14c3d4.ogg"},{"id":"en-Play_Vo_Char_NPC006_meet_001","title":"Первая встреча","description":"Мы вместе прошли огонь и воду, так что давай обойдемся без формальностей, ладно? Хм-м… Хотя, если подумать, я так и не представился по-нормальному… Капитан ТОИ-4 Байканг. Будем и дальше ладить друг с другом, хорошо?","language":"Английский","audioUrl":"/nte-meta/game-audio/6042b4a4fa418323ae90.ogg"},{"id":"en-Play_Vo_Char_NPC006_weather_002","title":"Дождливо","description":"Если хочешь скоротать время, понаблюдай за черепицей на крышах во время дождя. Это довольно увлекательно. Она так необычно мерцает, и капли дождя отскакивают от неё в разные стороны, создавая звуки разной частоты… как будто кто-то пытается что-то прошептать.","language":"Английский","audioUrl":"/nte-meta/game-audio/22b246b6194a80efd57a.ogg"},{"id":"ko-Play_Vo_Char_NPC006_chat_003","title":"Чат: приглашение","description":"Кажется, ты хорошо проводишь время в «Эйбоне». Видимо, ты ей нравишься. Но… если захочешь сменить обстановку, двери в ТОИ всегда открыты.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ddc933aab77f56dd0e95.ogg"},{"id":"ko-Play_Vo_Char_NPC006_weather_002","title":"Дождливо","description":"Если хочешь скоротать время, понаблюдай за черепицей на крышах во время дождя. Это довольно увлекательно. Она так необычно мерцает, и капли дождя отскакивают от неё в разные стороны, создавая звуки разной частоты… как будто кто-то пытается что-то прошептать.","language":"Корейский","audioUrl":"/nte-meta/game-audio/7218a3c892a0abf7681b.ogg"},{"id":"zh-Play_Vo_Char_NPC006_about_007","title":"О ТОИ","description":"ТОИ — просто кучка непонятных личностей, которые делают, что хотят. В новостях они выглядят хорошо, но работать с ними — сплошная головная боль. Когда они собираются вместе, каждый изо всех сил старается продемонстрировать свой уникальный талант… больше похоже на цирк, чем на рабочее место. Хотя, признаю, бывает довольно забавно… «Ты — часть этого»? А-ха-ха, ну и ну, спасибо!","language":"Китайский","audioUrl":"/nte-meta/game-audio/5fccaf96c154782d1cb1.ogg"},{"id":"zh-Play_Vo_Char_NPC006_hp_002","title":"Низкий уровень здоровья II","description":"Серьезно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c7639b86b7e18af40404.ogg"},{"id":"ja-Play_Vo_Char_NPC006_Parry_002","title":"Парирование II","description":"Смотри и учись.","language":"Японский","audioUrl":"/nte-meta/game-audio/5878608120c5d001fd3b.ogg"},{"id":"ja-Play_Vo_Char_NPC006_weather_003","title":"Холодно","description":"Я предложил ввести для своего отряда «отгулы из-за холодной погоды». Все проголосовали «за»… кроме Скии. И наша любимая директор отклонила мое предложение. Что ж, если там, откуда ты родом, есть «отгулы из-за холодной погоды» или «зимние каникулы», насладись ими и за меня тоже.","language":"Японский","audioUrl":"/nte-meta/game-audio/95db2c6c5bdd7df807bf.ogg"},{"id":"ko-Play_Vo_Char_NPC006_aoe_UI_001","title":"Сверхспособность I","description":"Бесчестные слова недопустимы.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f159d127f880035abe95.ogg"},{"id":"ko-Play_Vo_Char_NPC006_chat_002","title":"Чат: шалости","description":"Интересно, почему я здесь? Ах… как видишь, Фадия и Моза заперли меня снаружи. Вздох… Как они могли так жестоко поступить с собственным капитаном… Хм? «Что ты сделал на этот раз?» Эй, это несправедливо ко мне, не находишь? Даже ты считаешь, что я виноват? Ну да, я нарисовал на лице Мозы усы, пока она спала… Но Фадия уже сравняла счёт! И всё равно они заперли меня снаружи! Несправедливый суд и незаслуженное наказание…","language":"Корейский","audioUrl":"/nte-meta/game-audio/0fc80299b12f5c40aeb4.ogg"},{"id":"zh-Play_Vo_Char_NPC006_deploy_001","title":"Отправка II","description":"Не волнуйся, я не сбегу посреди драки.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b89bf9bc63d325647ca0.ogg"},{"id":"zh-Play_Vo_Char_NPC006_self_002","title":"Обо мне: прошлое","description":"Прошлое? Редко встретишь кого-то столь же любопытного, как ты. Хм-м… с чего начать? Как насчет этого: однажды, давным-давно, молодой человек нашел на берегу моря создание, которое могло существовать только в мифах… Следующие поколения стали считать его самой первой аномалией в Этеро… Хм? Не то прошлое, которое тебя интересует?","language":"Китайский","audioUrl":"/nte-meta/game-audio/487933f2921fce75f104.ogg"},{"id":"ja-Play_Vo_Char_NPC006_hobby_001","title":"Хобби","description":"Как думаешь, какие у них будут лица, если я притворюсь мертвым в комнате отдыха в перерыв на обед? На самом деле, я собираюсь проверить. Может, ты станешь тем, кто обнаружит мое «тело»?","language":"Японский","audioUrl":"/nte-meta/game-audio/0091ca045b27670eba59.ogg"},{"id":"ja-Play_Vo_Char_NPC006_hp_001","title":"Низкий уровень здоровья I","description":"Ах… Сейчас было бы неплохо взять тайм-аут.","language":"Японский","audioUrl":"/nte-meta/game-audio/01d2a633c4ad960779fe.ogg"},{"id":"ja-Play_Vo_Char_NPC006_hp_003","title":"Низкий уровень здоровья III","description":"Снова? Серьёзно?","language":"Японский","audioUrl":"/nte-meta/game-audio/f44d2b2deef70e5f2d3c.ogg"},{"id":"ja-Play_Vo_Char_NPC006_self_001","title":"Обо мне: способности эспера","description":"Слова обладают гораздо большей силой, чем думают люди. Страшно, да? Ха-ха… При желании даже самые простые слова с легкостью принесут страдание или счастье. Но, уверен, ты знаешь, как пользоваться этой силой с умом.","language":"Японский","audioUrl":"/nte-meta/game-audio/3f1a43e67df0eb3b03e3.ogg"},{"id":"ko-Play_Vo_Char_NPC006_Parry_001","title":"Парирование I","description":"И это всё?","language":"Корейский","audioUrl":"/nte-meta/game-audio/533331e62dbd9ffd245b.ogg"},{"id":"zh-Play_Vo_Char_NPC006_talk_002","title":"Тема: выходной","description":"Отпуск — это возможность исполнить все свои прихоти и построить спонтанные планы! Для меня — потягивать чай, заглянуть в новую пекарню, обменяться советами по садоводству с флористом, встретиться со старыми друзьями… Ах, ещё прогуляться в прекрасном лесу около кладбища у подножия горы. Вечером, когда ветерок ласкает кожу… Это так приятно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/4f47517c00737e2558eb.ogg"},{"id":"zh-Play_Vo_Char_NPC006_windfall_002","title":"Неожиданная добыча II","description":"А? Выглядит отлично.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0ecf218db44c0612b906.ogg"},{"id":"en-Play_Vo_Char_NPC006_Fly_001","title":"Планирование I","description":"Ну что ж, вот это дальность.","language":"Английский","audioUrl":"/nte-meta/game-audio/88ed583a7f89dfd6ed41.ogg"},{"id":"ja-Play_Vo_Char_NPC006_aoe_UI_002","title":"Сверхспособность II","description":"Произнесенное вслух требует уважения.","language":"Японский","audioUrl":"/nte-meta/game-audio/5eac2cd411240133d76e.ogg"},{"id":"ja-Play_Vo_Char_NPC006_fh_001","title":"Исцеление I","description":"Хм-м… Ах! Гораздо лучше.","language":"Японский","audioUrl":"/nte-meta/game-audio/e221eac56d1f3f401478.ogg"},{"id":"ko-Play_Vo_Char_NPC006_fh_001","title":"Исцеление I","description":"Хм-м… Ах! Гораздо лучше.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b68ea9ece71c838393df.ogg"},{"id":"ja-Play_Vo_Char_NPC006_skill_003","title":"Навык перенаправления III","description":"Ш-ш-ш… тихо.","language":"Японский","audioUrl":"/nte-meta/game-audio/733ff4f9eb0c015bb875.ogg"},{"id":"ko-Play_Vo_Char_NPC006_containment_002","title":"Сдерживание II","description":"И-и-и-и рабочий день закончен.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5b328d84a2df7244d0cd.ogg"},{"id":"zh-Play_Vo_Char_NPC006_windfall_005","title":"Неожиданная добыча V","description":"Чем больше, тем веселее.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d78bec8e5cd1bf7cda90.ogg"},{"id":"ja-Play_Vo_Char_NPC006_chat_001","title":"Чат: расслабление","description":"Серьезность — это достоинство, но постоянное напряжение чрезмерно выматывает! Прими дружеский совет — иногда нужно расслабляться!","language":"Японский","audioUrl":"/nte-meta/game-audio/4ee0ddd079287fe9aec8.ogg"},{"id":"ja-Play_Vo_Char_NPC006_self_002","title":"Обо мне: прошлое","description":"Прошлое? Редко встретишь кого-то столь же любопытного, как ты. Хм-м… с чего начать? Как насчет этого: однажды, давным-давно, молодой человек нашел на берегу моря создание, которое могло существовать только в мифах… Следующие поколения стали считать его самой первой аномалией в Этеро… Хм? Не то прошлое, которое тебя интересует?","language":"Японский","audioUrl":"/nte-meta/game-audio/2fe763066157b6b3f6ce.ogg"},{"id":"ja-Play_Vo_Char_NPC006_windfall_003","title":"Неожиданная добыча III","description":"Если тебе это нужно, держи в кармане.","language":"Японский","audioUrl":"/nte-meta/game-audio/f76f7e426e383fe3b216.ogg"},{"id":"ja-Play_Vo_Char_NPC006_windfall_004","title":"Неожиданная добыча IV","description":"Проще простого!","language":"Японский","audioUrl":"/nte-meta/game-audio/f95e781ad35ad72f3701.ogg"},{"id":"ko-Play_Vo_Char_NPC006_dead_002","title":"Потеря сознания II","description":"Этот день… пришел быстрее, чем я думал…","language":"Корейский","audioUrl":"/nte-meta/game-audio/b9fd51303ec0bac983a5.ogg"},{"id":"ko-Play_Vo_Char_NPC006_DodgeCombo_001","title":"Серия критических уклонений I","description":"Фух… это было близко!","language":"Корейский","audioUrl":"/nte-meta/game-audio/da2b2d2704284e335804.ogg"},{"id":"zh-Play_Vo_Char_NPC006_TeammateDown_004","title":"Поражен товарищ по команде – Минт","description":"За такое нам точно положены выплаты за травмы.","language":"Китайский","audioUrl":"/nte-meta/game-audio/dc170f1f40f2470c3510.ogg"},{"id":"en-Play_Vo_Char_NPC006_hstruck_002","title":"Сильный урон II","description":"…Я стал небрежным.","language":"Английский","audioUrl":"/nte-meta/game-audio/9ff4d74a283bcee31daf.ogg"},{"id":"en-Play_Vo_Char_NPC006_Parry_002","title":"Парирование II","description":"Смотри и учись.","language":"Английский","audioUrl":"/nte-meta/game-audio/f71cf2cb2339be5d7dd7.ogg"},{"id":"en-Play_Vo_Char_NPC006_self_002","title":"Обо мне: прошлое","description":"Прошлое? Редко встретишь кого-то столь же любопытного, как ты. Хм-м… с чего начать? Как насчет этого: однажды, давным-давно, молодой человек нашел на берегу моря создание, которое могло существовать только в мифах… Следующие поколения стали считать его самой первой аномалией в Этеро… Хм? Не то прошлое, которое тебя интересует?","language":"Английский","audioUrl":"/nte-meta/game-audio/14a0f6d968e74fc1c80e.ogg"},{"id":"ja-Play_Vo_Char_NPC006_QTE_003","title":"Атака на входе III","description":"Эй, полегче. Сильно не бей.","language":"Японский","audioUrl":"/nte-meta/game-audio/1460b610d6b4bc61d81b.ogg"},{"id":"ko-Play_Vo_Char_NPC006_hp_003","title":"Низкий уровень здоровья III","description":"Снова? Серьёзно?","language":"Корейский","audioUrl":"/nte-meta/game-audio/96381e1afee4d08b53aa.ogg"},{"id":"ko-Play_Vo_Char_NPC006_windfall_006","title":"Неожиданная добыча VI","description":"О, классно!","language":"Корейский","audioUrl":"/nte-meta/game-audio/9310e6bf7c63a372ab22.ogg"},{"id":"en-Play_Vo_Char_NPC006_gift_004","title":"Подарок получен IV","description":"Тс-с! Бюро ни за что не позволит своим капитанам брать взятки!","language":"Английский","audioUrl":"/nte-meta/game-audio/2b31082d1eaee5196f4a.ogg"},{"id":"en-Play_Vo_Char_NPC006_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Такой прекрасный день, идеален для отдыха… А, хотя лучше, чтобы они меня не нашли. Пока.","language":"Английский","audioUrl":"/nte-meta/game-audio/fbbdadfd87064ae32a94.ogg"},{"id":"en-Play_Vo_Char_NPC006_SSC_003","title":"Особое переключение — Лакримоза","description":"Эй! Нападай на того, кто твоего размера.","language":"Английский","audioUrl":"/nte-meta/game-audio/33ef6b41a4808a7d4818.ogg"},{"id":"en-Play_Vo_Char_NPC006_ug_001","title":"Вознесение персонажа I","description":"Время от времени стоит делать шаг вперед.","language":"Английский","audioUrl":"/nte-meta/game-audio/48cf26fba8c4b0a7792c.ogg"},{"id":"ja-Play_Vo_Char_NPC006_greet_004","title":"Спокойной ночи","description":"Глаза слипаются? Ой… видимо, уже ночь. Я так заболтался с тобой, что прошло уже много времени, а я и не заметил. Виноват, виноват.","language":"Японский","audioUrl":"/nte-meta/game-audio/0f808eeae11c53e91756.ogg"},{"id":"ja-Play_Vo_Char_NPC006_talk_002","title":"Тема: выходной","description":"Отпуск — это возможность исполнить все свои прихоти и построить спонтанные планы! Для меня — потягивать чай, заглянуть в новую пекарню, обменяться советами по садоводству с флористом, встретиться со старыми друзьями… Ах, ещё прогуляться в прекрасном лесу около кладбища у подножия горы. Вечером, когда ветерок ласкает кожу… Это так приятно.","language":"Японский","audioUrl":"/nte-meta/game-audio/d15654da5bc01b3889b2.ogg"},{"id":"ko-Play_Vo_Char_NPC006_Fly_001","title":"Планирование I","description":"Ну что ж, вот это дальность.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6eba8c9619856f7b5ccf.ogg"},{"id":"ko-Play_Vo_Char_NPC006_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Такой прекрасный день, идеален для отдыха… А, хотя лучше, чтобы они меня не нашли. Пока.","language":"Корейский","audioUrl":"/nte-meta/game-audio/2119b0f7b359855e3e72.ogg"},{"id":"ja-Play_Vo_Char_NPC006_deploy_002","title":"Отправка I","description":"Эй, нужна помощь?","language":"Японский","audioUrl":"/nte-meta/game-audio/e3eb5e46f46c6e398b2a.ogg"},{"id":"zh-Play_Vo_Char_NPC006_aoe_UI_001","title":"Сверхспособность I","description":"Бесчестные слова недопустимы.","language":"Китайский","audioUrl":"/nte-meta/game-audio/9a2909aade724283dfeb.ogg"},{"id":"en-Play_Vo_Char_NPC006_hobby_001","title":"Хобби","description":"Как думаешь, какие у них будут лица, если я притворюсь мертвым в комнате отдыха в перерыв на обед? На самом деле, я собираюсь проверить. Может, ты станешь тем, кто обнаружит мое «тело»?","language":"Английский","audioUrl":"/nte-meta/game-audio/41aee42c89a0ad585bc6.ogg"},{"id":"ja-Play_Vo_Char_NPC006_dead_002","title":"Потеря сознания II","description":"Этот день… пришел быстрее, чем я думал…","language":"Японский","audioUrl":"/nte-meta/game-audio/669444196f50d3687835.ogg"},{"id":"ja-Play_Vo_Char_NPC006_gift_001","title":"Подарок получен I","description":"Ага, похоже, у нас с тобой одинаковый утончённый вкус!","language":"Японский","audioUrl":"/nte-meta/game-audio/5f619c6cffdb92c17e9f.ogg"},{"id":"ja-Play_Vo_Char_NPC006_gift_002","title":"Подарок получен II","description":"Подарок от друга — настоящее сокровище… Поставлю на видное место, чтобы все его видели! Подарок от подруги — настоящее сокровище… Поставлю на видное место, чтобы все его видели!","language":"Японский","audioUrl":"/nte-meta/game-audio/ab35e906415d133f39b8.ogg"},{"id":"ko-Play_Vo_Char_NPC006_gift_003","title":"Подарок получен III","description":"Подарок за подарок. Мой подарок тебе… дай-ка подумать.","language":"Корейский","audioUrl":"/nte-meta/game-audio/8e28d466e2fb950e5980.ogg"},{"id":"ko-Play_Vo_Char_NPC006_greet_003","title":"Вечернее приветствие","description":"Без приключений дожили до ужина… К сожалению, у меня появилось поручение… так что придется обойтись чем-то быстрым и простым.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d1feb2fefda993bc7985.ogg"},{"id":"ko-Play_Vo_Char_NPC006_SSC_003","title":"Особое переключение — Лакримоза","description":"Эй! Нападай на того, кто твоего размера.","language":"Корейский","audioUrl":"/nte-meta/game-audio/2b9f6562a604cb12db4e.ogg"},{"id":"ja-Play_Vo_Char_NPC006_about_008","title":"О ТОИ-4","description":"Капитан Отряда 4 брошен в одиночестве членами его команды…? Кто это сказал? Это неправда! Мы известны во всём Бюро как образцовая команда с беспрецедентной сплочённостью… Стой, тебе довелось увидеть, как Моза, Фадия и Ския встретились на площади, чтобы вместе пойти за покупками и поужинать? А? Когда это было?","language":"Японский","audioUrl":"/nte-meta/game-audio/8c1911a85bd4b87d7303.ogg"},{"id":"ja-Play_Vo_Char_NPC006_hstruck_002","title":"Сильный урон II","description":"…Я стал небрежным.","language":"Японский","audioUrl":"/nte-meta/game-audio/75b8d8341c23cd82cc5f.ogg"},{"id":"ja-Play_Vo_Char_NPC006_TeammateDown_004","title":"Поражен товарищ по команде – Минт","description":"За такое нам точно положены выплаты за травмы.","language":"Японский","audioUrl":"/nte-meta/game-audio/df7bd98debbd39d0a196.ogg"},{"id":"ko-Play_Vo_Char_NPC006_Parry_002","title":"Парирование II","description":"Смотри и учись.","language":"Корейский","audioUrl":"/nte-meta/game-audio/8dc28187ad2e9dab1777.ogg"},{"id":"ko-Play_Vo_Char_NPC006_windfall_002","title":"Неожиданная добыча II","description":"А? Выглядит отлично.","language":"Корейский","audioUrl":"/nte-meta/game-audio/aa0e1f988a39000adecd.ogg"},{"id":"zh-Play_Vo_Char_NPC006_QTE_001","title":"Атака на входе I","description":"Эй, не отвлекайся!","language":"Китайский","audioUrl":"/nte-meta/game-audio/e80cc63f968c9622b2e4.ogg"},{"id":"en-Play_Vo_Char_NPC006_aoe_UI_002","title":"Сверхспособность II","description":"Произнесенное вслух требует уважения.","language":"Английский","audioUrl":"/nte-meta/game-audio/156eec331715ec9e9a97.ogg"},{"id":"en-Play_Vo_Char_NPC006_kill_001","title":"Убийство I","description":"Слишком сильно ударил?","language":"Английский","audioUrl":"/nte-meta/game-audio/e6a906a57757927f4cd8.ogg"},{"id":"en-Play_Vo_Char_NPC006_windfall_004","title":"Неожиданная добыча IV","description":"Проще простого!","language":"Английский","audioUrl":"/nte-meta/game-audio/04384457a03e7b7b65c2.ogg"},{"id":"ko-Play_Vo_Char_NPC006_Switch_003","title":"Переключение III","description":"Огонь по своим!","language":"Корейский","audioUrl":"/nte-meta/game-audio/487a30a50dd583ec99ec.ogg"},{"id":"en-Play_Vo_Char_NPC006_SSC_004","title":"Особое переключение — Минт","description":"Надо устроить новичкам хорошее представление.","language":"Английский","audioUrl":"/nte-meta/game-audio/f9ff1de4a28f0307459d.ogg"},{"id":"en-Play_Vo_Char_NPC006_talk_001","title":"Тема: общение","description":"Говорят, язык — это сосуд для разума, но если люди хотят что-то сообщить, то всегда найдут способ самовыражения, с Вавилонской башней или без неё. Слова, действия, мимика… Разве не увлекательно их интерпретировать? К примеру, смотри — у Скии сейчас такое выражение лица… ага, он узнал, что вчера я прогулял работу…","language":"Английский","audioUrl":"/nte-meta/game-audio/0b924a81227d28975544.ogg"},{"id":"ja-Play_Vo_Char_NPC006_dead_001","title":"Потеря сознания I","description":"Не здесь… и не где-либо еще…","language":"Японский","audioUrl":"/nte-meta/game-audio/b0f19283e93a38899cdc.ogg"},{"id":"ja-Play_Vo_Char_NPC006_SSC_003","title":"Особое переключение — Лакримоза","description":"Эй! Нападай на того, кто твоего размера.","language":"Японский","audioUrl":"/nte-meta/game-audio/1877c078f8b1f3eb9e31.ogg"},{"id":"ko-Play_Vo_Char_NPC006_about_003","title":"О Фадии","description":"Никогда не связывайся с Фадией, если нет готовности к этому, поверь тому, кто знает лучше. Хотя, если есть уверенность в себе, — вперёд! Испытай удачу, но пообещай, что позволишь мне посмотреть! Любопытно, что случилось со мной? Хех… не будем об этом.","language":"Корейский","audioUrl":"/nte-meta/game-audio/7fa34a1c67cadee4ccd5.ogg"},{"id":"ko-Play_Vo_Char_NPC006_weather_001","title":"Солнечно","description":"Обидно провести такой прекрасный день в душном офисе, перекладывая бумажки. Да! Займусь этим позже.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6c1e71267ab08a4238e7.ogg"},{"id":"zh-Play_Vo_Char_NPC006_anomaly_003","title":"Нуллификация I","description":"Спи крепко.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0133dc3d25ee5bfbc029.ogg"},{"id":"en-Play_Vo_Char_NPC006_about_003","title":"О Фадии","description":"Никогда не связывайся с Фадией, если нет готовности к этому, поверь тому, кто знает лучше. Хотя, если есть уверенность в себе, — вперёд! Испытай удачу, но пообещай, что позволишь мне посмотреть! Любопытно, что случилось со мной? Хех… не будем об этом.","language":"Английский","audioUrl":"/nte-meta/game-audio/644eafc1baec1fc93987.ogg"},{"id":"en-Play_Vo_Char_NPC006_struck_002","title":"Урон II","description":"Никак не угомонишься?","language":"Английский","audioUrl":"/nte-meta/game-audio/03bc698b7f726874487f.ogg"},{"id":"en-Play_Vo_Char_NPC006_Switch_001","title":"Переключение I","description":"Пересменка.","language":"Английский","audioUrl":"/nte-meta/game-audio/b5e6d96cb20961cecaea.ogg"},{"id":"en-Play_Vo_Char_NPC006_windfall_006","title":"Неожиданная добыча VI","description":"О, классно!","language":"Английский","audioUrl":"/nte-meta/game-audio/2991c957978450b51636.ogg"},{"id":"ja-Play_Vo_Char_NPC006_DodgeCombo_002","title":"Серия критических уклонений II","description":"Безупречное исполнение.","language":"Японский","audioUrl":"/nte-meta/game-audio/257086930b84502424ee.ogg"},{"id":"ja-Play_Vo_Char_NPC006_self_003","title":"Обо мне: капитан","description":"Такие звания, как «Капитан», на самом деле мало что значат. Я не из тех, кто задирает нос, а моя команда? Они не станут больше уважать меня из-за какого-то звания. Честно говоря, быть капитаном — сплошная морока… кстати об этом, нужно придумать предлог, чтобы Ския смог прийти за меня на собрание Бюро завтра утром…","language":"Японский","audioUrl":"/nte-meta/game-audio/90964c2eb85dfa91e33c.ogg"},{"id":"ko-Play_Vo_Char_NPC006_QTE_002","title":"Атака на входе II","description":"Мне бы не помешала разминка.","language":"Корейский","audioUrl":"/nte-meta/game-audio/adafa6b7f3fbb7077129.ogg"},{"id":"zh-Play_Vo_Char_NPC006_weather_003","title":"Холодно","description":"Я предложил ввести для своего отряда «отгулы из-за холодной погоды». Все проголосовали «за»… кроме Скии. И наша любимая директор отклонила мое предложение. Что ж, если там, откуда ты родом, есть «отгулы из-за холодной погоды» или «зимние каникулы», насладись ими и за меня тоже.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d038f98bf5823a5a19e9.ogg"},{"id":"en-Play_Vo_Char_NPC006_gift_003","title":"Подарок получен III","description":"Подарок за подарок. Мой подарок тебе… дай-ка подумать.","language":"Английский","audioUrl":"/nte-meta/game-audio/d1b689d0ce4135d6f4d7.ogg"},{"id":"en-Play_Vo_Char_NPC006_greet_003","title":"Вечернее приветствие","description":"Без приключений дожили до ужина… К сожалению, у меня появилось поручение… так что придется обойтись чем-то быстрым и простым.","language":"Английский","audioUrl":"/nte-meta/game-audio/eb674f2d70b3372230f6.ogg"},{"id":"en-Play_Vo_Char_NPC006_SSC_002","title":"Особое переключение — Фадия","description":"Игра в кошки-мышки ещё не окончена.","language":"Английский","audioUrl":"/nte-meta/game-audio/b3f5af43cbb74f20d332.ogg"},{"id":"ko-Play_Vo_Char_NPC006_chat_001","title":"Чат: расслабление","description":"Серьезность — это достоинство, но постоянное напряжение чрезмерно выматывает! Прими дружеский совет — иногда нужно расслабляться!","language":"Корейский","audioUrl":"/nte-meta/game-audio/b0af004ca28603184f25.ogg"},{"id":"ko-Play_Vo_Char_NPC006_hp_002","title":"Низкий уровень здоровья II","description":"Серьезно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/cdab5703309c3bb8c885.ogg"},{"id":"zh-Play_Vo_Char_NPC006_aoe_UI_003","title":"Сверхспособность III","description":"Что это — благословение или… проклятие?","language":"Китайский","audioUrl":"/nte-meta/game-audio/449cfc1154ed66db5d5f.ogg"},{"id":"en-Play_Vo_Char_NPC006_ug_003","title":"Вознесение персонажа III","description":"Ну что, впереди ещё один тяжёлый рабочий день.","language":"Английский","audioUrl":"/nte-meta/game-audio/a82e4521fc2f3282c427.ogg"},{"id":"ko-Play_Vo_Char_NPC006_aoe_UI_003","title":"Сверхспособность III","description":"Что это — благословение или… проклятие?","language":"Корейский","audioUrl":"/nte-meta/game-audio/0d78ecc8455ba228e2cf.ogg"},{"id":"zh-Play_Vo_Char_NPC006_greet_003","title":"Вечернее приветствие","description":"Без приключений дожили до ужина… К сожалению, у меня появилось поручение… так что придется обойтись чем-то быстрым и простым.","language":"Китайский","audioUrl":"/nte-meta/game-audio/6f3c44db68dcadeb6458.ogg"},{"id":"zh-Play_Vo_Char_NPC006_talk_003","title":"Тема: сожаления","description":"Иногда я думаю, если все, что ушло, лишится истории и имени, что останется? Их идеи, их эмоции… Куда все уходит? Стоит ли запоздалому солнцу извиняться перед увядшим подсолнухом…?","language":"Китайский","audioUrl":"/nte-meta/game-audio/0520aabdb72fa25945c2.ogg"},{"id":"zh-Play_Vo_Char_NPC006_greet_002","title":"Дневное приветствие","description":"Ты вовремя. Я как раз хотел выпить чаю в перерыв на обед. Хочешь присоединиться?","language":"Китайский","audioUrl":"/nte-meta/game-audio/cf8f36d332619b299074.ogg"},{"id":"zh-Play_Vo_Char_NPC006_Switch_001","title":"Переключение I","description":"Пересменка.","language":"Китайский","audioUrl":"/nte-meta/game-audio/dcf9ca7877bb4bb1771e.ogg"},{"id":"en-Play_Vo_Char_NPC006_about_005","title":"О Хотори","description":"Иногда она напоминает мне Директора — её так же сложно понять… Хотя, кажется, сейчас она уже не та, что в прошлом? Может быть слишком много пьет?","language":"Английский","audioUrl":"/nte-meta/game-audio/0fddacc634882415f879.ogg"},{"id":"en-Play_Vo_Char_NPC006_Parry_001","title":"Парирование I","description":"И это всё?","language":"Английский","audioUrl":"/nte-meta/game-audio/21055eb5cc676db696a8.ogg"},{"id":"ja-Play_Vo_Char_NPC006_Fly_001","title":"Планирование I","description":"Ну что ж, вот это дальность.","language":"Японский","audioUrl":"/nte-meta/game-audio/5660bed568084717dabc.ogg"},{"id":"ko-Play_Vo_Char_NPC006_gift_004","title":"Подарок получен IV","description":"Тс-с! Бюро ни за что не позволит своим капитанам брать взятки!","language":"Корейский","audioUrl":"/nte-meta/game-audio/5745af0a6b4893222b4d.ogg"},{"id":"ko-Play_Vo_Char_NPC006_talk_003","title":"Тема: сожаления","description":"Иногда я думаю, если все, что ушло, лишится истории и имени, что останется? Их идеи, их эмоции… Куда все уходит? Стоит ли запоздалому солнцу извиняться перед увядшим подсолнухом…?","language":"Корейский","audioUrl":"/nte-meta/game-audio/f22b7bddc6645949656a.ogg"},{"id":"ko-Play_Vo_Char_NPC006_ug_002","title":"Вознесение персонажа II","description":"Кажется, мои безмятежные дни подходят к концу!","language":"Корейский","audioUrl":"/nte-meta/game-audio/83e5ff1e43f5b40113f7.ogg"},{"id":"en-Play_Vo_Char_NPC006_gift_002","title":"Подарок получен II","description":"Подарок от друга — настоящее сокровище… Поставлю на видное место, чтобы все его видели! Подарок от подруги — настоящее сокровище… Поставлю на видное место, чтобы все его видели!","language":"Английский","audioUrl":"/nte-meta/game-audio/6b6ee668433ffccbfc74.ogg"},{"id":"en-Play_Vo_Char_NPC006_Switch_003","title":"Переключение III","description":"Огонь по своим!","language":"Английский","audioUrl":"/nte-meta/game-audio/fad921841578060bd8f2.ogg"},{"id":"ko-Play_Vo_Char_NPC006_hobby_001","title":"Хобби","description":"Как думаешь, какие у них будут лица, если я притворюсь мертвым в комнате отдыха в перерыв на обед? На самом деле, я собираюсь проверить. Может, ты станешь тем, кто обнаружит мое «тело»?","language":"Корейский","audioUrl":"/nte-meta/game-audio/de98c129fb0fc39efc63.ogg"},{"id":"ko-Play_Vo_Char_NPC006_kill_002","title":"Убийство II","description":"Мне нужно уйти с работы! Прости!","language":"Корейский","audioUrl":"/nte-meta/game-audio/b1da8d513ce7f33e5284.ogg"},{"id":"ko-Play_Vo_Char_NPC006_windfall_003","title":"Неожиданная добыча III","description":"Если тебе это нужно, держи в кармане.","language":"Корейский","audioUrl":"/nte-meta/game-audio/441201564e73d91526d2.ogg"},{"id":"zh-Play_Vo_Char_NPC006_SSC_002","title":"Особое переключение — Фадия","description":"Игра в кошки-мышки ещё не окончена.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7b8b44117aa578d816d7.ogg"},{"id":"zh-Play_Vo_Char_NPC006_Switch_002","title":"Переключение II","description":"Я? Ладно, тогда.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3c44da4b29f887642e52.ogg"},{"id":"en-Play_Vo_Char_NPC006_containment_001","title":"Сдерживание I","description":"Добро пожаловать домой!","language":"Английский","audioUrl":"/nte-meta/game-audio/2a004761241a771511ee.ogg"},{"id":"ja-Play_Vo_Char_NPC006_windfall_005","title":"Неожиданная добыча V","description":"Чем больше, тем веселее.","language":"Японский","audioUrl":"/nte-meta/game-audio/27f0d32f136a33c4bbb6.ogg"},{"id":"zh-Play_Vo_Char_NPC006_struck_002","title":"Урон II","description":"Никак не угомонишься?","language":"Китайский","audioUrl":"/nte-meta/game-audio/3a4fa7fc9db79cdd713b.ogg"},{"id":"en-Play_Vo_Char_NPC006_deploy_002","title":"Отправка I","description":"Эй, нужна помощь?","language":"Английский","audioUrl":"/nte-meta/game-audio/c85b40af93928a192b4d.ogg"},{"id":"en-Play_Vo_Char_NPC006_hp_003","title":"Низкий уровень здоровья III","description":"Снова? Серьёзно?","language":"Английский","audioUrl":"/nte-meta/game-audio/05f3d70c0cc4786e3312.ogg"},{"id":"ko-Play_Vo_Char_NPC006_deploy_002","title":"Отправка I","description":"Эй, нужна помощь?","language":"Корейский","audioUrl":"/nte-meta/game-audio/38e5edaaee85a144542d.ogg"},{"id":"ko-Play_Vo_Char_NPC006_SSC_001","title":"Особое переключение — Ския","description":"Отчёт по заданию напишу… потом.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c201f08064bde72d145e.ogg"},{"id":"ko-Play_Vo_Char_NPC006_Switch_001","title":"Переключение I","description":"Пересменка.","language":"Корейский","audioUrl":"/nte-meta/game-audio/30e0e7f718995f2634cd.ogg"},{"id":"zh-Play_Vo_Char_NPC006_about_001","title":"Об Альфарде","description":"Если директор продолжит урезать мне зарплату… Рано или поздно придется взять кредит, просто чтобы прийти на работу. Ах… Даже интересно, когда она все-таки меня выгонит.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d375f184343eae4d7c39.ogg"},{"id":"zh-Play_Vo_Char_NPC006_anomaly_004","title":"Нуллификация II","description":"Я просто… напишу что-нибудь в отчете о миссии.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b06398aeff4c1034987d.ogg"},{"id":"zh-Play_Vo_Char_NPC006_windfall_006","title":"Неожиданная добыча VI","description":"О, классно!","language":"Китайский","audioUrl":"/nte-meta/game-audio/ab43e1cdb8dafec5ed9b.ogg"}]') WHERE character_id='baicang' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-01 09:11:10');

UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT value FROM json_each('[{"id":"en-Play_Vo_Char_NPC006_chat_002","title":"Чат: шалости","description":"Интересно, почему я здесь? Ах… как видишь, Фадия и Моза заперли меня снаружи. Вздох… Как они могли так жестоко поступить с собственным капитаном… Хм? «Что ты сделал на этот раз?» Эй, это несправедливо ко мне, не находишь? Даже ты считаешь, что я виноват? Ну да, я нарисовал на лице Мозы усы, пока она спала… Но Фадия уже сравняла счёт! И всё равно они заперли меня снаружи! Несправедливый суд и незаслуженное наказание…","language":"Английский","audioUrl":"/nte-meta/game-audio/cae36c67591fc880ce68.ogg"},{"id":"en-Play_Vo_Char_NPC006_vexation_001","title":"Проблемы","description":"Меньше забот, меньше хлопот! Хах, не смотри на меня так! Я никогда не говорил, что мне не о чем волноваться. Позволь мне пока оставить некоторые секреты при себе, ладно?","language":"Английский","audioUrl":"/nte-meta/game-audio/c8dca8f96128d48d96ff.ogg"},{"id":"ja-Play_Vo_Char_NPC006_talk_001","title":"Тема: общение","description":"Говорят, язык — это сосуд для разума, но если люди хотят что-то сообщить, то всегда найдут способ самовыражения, с Вавилонской башней или без неё. Слова, действия, мимика… Разве не увлекательно их интерпретировать? К примеру, смотри — у Скии сейчас такое выражение лица… ага, он узнал, что вчера я прогулял работу…","language":"Японский","audioUrl":"/nte-meta/game-audio/d633e702ab8a24ed6350.ogg"},{"id":"ja-Play_Vo_Char_NPC006_TeammateDown_001","title":"Поражен товарищ по команде – Ския","description":"Лейтенант пал — и это всё, на что способен Отряд 4? Соберитесь!","language":"Японский","audioUrl":"/nte-meta/game-audio/f70c8b035456c7ca841d.ogg"},{"id":"zh-Play_Vo_Char_NPC006_fh_002","title":"Исцеление II","description":"Разберемся с этим побыстрее.","language":"Китайский","audioUrl":"/nte-meta/game-audio/fb665bf85d961ac7c536.ogg"},{"id":"zh-Play_Vo_Char_NPC006_kill_001","title":"Убийство I","description":"Слишком сильно ударил?","language":"Китайский","audioUrl":"/nte-meta/game-audio/fca70c6dfa514bc12ea9.ogg"},{"id":"en-Play_Vo_Char_NPC006_DodgeCombo_001","title":"Серия критических уклонений I","description":"Фух… это было близко!","language":"Английский","audioUrl":"/nte-meta/game-audio/44cb06d0ec55badd0827.ogg"},{"id":"en-Play_Vo_Char_NPC006_skill_002","title":"Навык перенаправления II","description":"Навостри уши.","language":"Английский","audioUrl":"/nte-meta/game-audio/15e58ebc221b0605ce99.ogg"},{"id":"ko-Play_Vo_Char_NPC006_kill_001","title":"Убийство I","description":"Слишком сильно ударил?","language":"Корейский","audioUrl":"/nte-meta/game-audio/ab0d0922ed4966b2f775.ogg"},{"id":"ko-Play_Vo_Char_NPC006_windfall_004","title":"Неожиданная добыча IV","description":"Проще простого!","language":"Корейский","audioUrl":"/nte-meta/game-audio/a757b68b5ed49f41d53f.ogg"},{"id":"zh-Play_Vo_Char_NPC006_meet_001","title":"Первая встреча","description":"Мы вместе прошли огонь и воду, так что давай обойдемся без формальностей, ладно? Хм-м… Хотя, если подумать, я так и не представился по-нормальному… Капитан ТОИ-4 Байканг. Будем и дальше ладить друг с другом, хорошо?","language":"Китайский","audioUrl":"/nte-meta/game-audio/853e1dd66648c75731dd.ogg"},{"id":"zh-Play_Vo_Char_NPC006_self_001","title":"Обо мне: способности эспера","description":"Слова обладают гораздо большей силой, чем думают люди. Страшно, да? Ха-ха… При желании даже самые простые слова с легкостью принесут страдание или счастье. Но, уверен, ты знаешь, как пользоваться этой силой с умом.","language":"Китайский","audioUrl":"/nte-meta/game-audio/55a8152eace944cf4197.ogg"},{"id":"zh-Play_Vo_Char_NPC006_windfall_003","title":"Неожиданная добыча III","description":"Если тебе это нужно, держи в кармане.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c2434a93ee4fd78cfe74.ogg"},{"id":"ko-Play_Vo_Char_NPC006_self_002","title":"Обо мне: прошлое","description":"Прошлое? Редко встретишь кого-то столь же любопытного, как ты. Хм-м… с чего начать? Как насчет этого: однажды, давным-давно, молодой человек нашел на берегу моря создание, которое могло существовать только в мифах… Следующие поколения стали считать его самой первой аномалией в Этеро… Хм? Не то прошлое, которое тебя интересует?","language":"Корейский","audioUrl":"/nte-meta/game-audio/e24cb495877211f8b958.ogg"},{"id":"zh-Play_Vo_Char_NPC006_hp_003","title":"Низкий уровень здоровья III","description":"Снова? Серьёзно?","language":"Китайский","audioUrl":"/nte-meta/game-audio/e9505166c69fceb777d4.ogg"},{"id":"zh-Play_Vo_Char_NPC006_SSC_004","title":"Особое переключение — Минт","description":"Надо устроить новичкам хорошее представление.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5e2c61e771672b1be899.ogg"},{"id":"en-Play_Vo_Char_NPC006_talk_002","title":"Тема: выходной","description":"Отпуск — это возможность исполнить все свои прихоти и построить спонтанные планы! Для меня — потягивать чай, заглянуть в новую пекарню, обменяться советами по садоводству с флористом, встретиться со старыми друзьями… Ах, ещё прогуляться в прекрасном лесу около кладбища у подножия горы. Вечером, когда ветерок ласкает кожу… Это так приятно.","language":"Английский","audioUrl":"/nte-meta/game-audio/9f78be4b9d934e705dcc.ogg"},{"id":"en-Play_Vo_Char_NPC006_TeammateDown_004","title":"Поражен товарищ по команде – Минт","description":"За такое нам точно положены выплаты за травмы.","language":"Английский","audioUrl":"/nte-meta/game-audio/dd6bcf184c7fb1ad6aab.ogg"},{"id":"ja-Play_Vo_Char_NPC006_greet_003","title":"Вечернее приветствие","description":"Без приключений дожили до ужина… К сожалению, у меня появилось поручение… так что придется обойтись чем-то быстрым и простым.","language":"Японский","audioUrl":"/nte-meta/game-audio/cc9289b71bacb7a6a27b.ogg"},{"id":"ko-Play_Vo_Char_NPC006_gift_001","title":"Подарок получен I","description":"Ага, похоже, у нас с тобой одинаковый утончённый вкус!","language":"Корейский","audioUrl":"/nte-meta/game-audio/774b818e65922c5ed45b.ogg"},{"id":"ko-Play_Vo_Char_NPC006_ug_003","title":"Вознесение персонажа III","description":"Ну что, впереди ещё один тяжёлый рабочий день.","language":"Корейский","audioUrl":"/nte-meta/game-audio/476f71dac329f824af0d.ogg"},{"id":"ko-Play_Vo_Char_NPC006_vexation_001","title":"Проблемы","description":"Меньше забот, меньше хлопот! Хах, не смотри на меня так! Я никогда не говорил, что мне не о чем волноваться. Позволь мне пока оставить некоторые секреты при себе, ладно?","language":"Корейский","audioUrl":"/nte-meta/game-audio/610db24cbd629908b037.ogg"},{"id":"ko-Play_Vo_Char_NPC006_windfall_005","title":"Неожиданная добыча V","description":"Чем больше, тем веселее.","language":"Корейский","audioUrl":"/nte-meta/game-audio/0dc6592488b909c452ca.ogg"},{"id":"zh-Play_Vo_Char_NPC006_hobby_001","title":"Хобби","description":"Как думаешь, какие у них будут лица, если я притворюсь мертвым в комнате отдыха в перерыв на обед? На самом деле, я собираюсь проверить. Может, ты станешь тем, кто обнаружит мое «тело»?","language":"Китайский","audioUrl":"/nte-meta/game-audio/9423b75a6364bdc2d29d.ogg"},{"id":"zh-Play_Vo_Char_NPC006_talk_001","title":"Тема: общение","description":"Говорят, язык — это сосуд для разума, но если люди хотят что-то сообщить, то всегда найдут способ самовыражения, с Вавилонской башней или без неё. Слова, действия, мимика… Разве не увлекательно их интерпретировать? К примеру, смотри — у Скии сейчас такое выражение лица… ага, он узнал, что вчера я прогулял работу…","language":"Китайский","audioUrl":"/nte-meta/game-audio/9e0f585b323e3b594d17.ogg"},{"id":"en-Play_Vo_Char_NPC006_containment_002","title":"Сдерживание II","description":"И-и-и-и рабочий день закончен.","language":"Английский","audioUrl":"/nte-meta/game-audio/8b22f5e7ba72723bc34e.ogg"},{"id":"en-Play_Vo_Char_NPC006_hstruck_001","title":"Сильный урон I","description":"Неплохо.","language":"Английский","audioUrl":"/nte-meta/game-audio/567e5f25947b9aad6130.ogg"},{"id":"ja-Play_Vo_Char_NPC006_skill_001","title":"Навык перенаправления I","description":"Эй, болтовня окончена.","language":"Японский","audioUrl":"/nte-meta/game-audio/395c0da5c4c933657a7e.ogg"},{"id":"ja-Play_Vo_Char_NPC006_skill_002","title":"Навык перенаправления II","description":"Навостри уши.","language":"Японский","audioUrl":"/nte-meta/game-audio/63148b47de877ae59593.ogg"},{"id":"ja-Play_Vo_Char_NPC006_weather_001","title":"Солнечно","description":"Обидно провести такой прекрасный день в душном офисе, перекладывая бумажки. Да! Займусь этим позже.","language":"Японский","audioUrl":"/nte-meta/game-audio/24b57d63ea4e3103a570.ogg"},{"id":"en-Play_Vo_Char_NPC006_skill_003","title":"Навык перенаправления III","description":"Ш-ш-ш… тихо.","language":"Английский","audioUrl":"/nte-meta/game-audio/275cadde406c0ab385d9.ogg"},{"id":"ko-Play_Vo_Char_NPC006_dead_001","title":"Потеря сознания I","description":"Не здесь… и не где-либо еще…","language":"Корейский","audioUrl":"/nte-meta/game-audio/bea1e924b91667dcb8bf.ogg"},{"id":"ko-Play_Vo_Char_NPC006_hstruck_001","title":"Сильный урон I","description":"Неплохо.","language":"Корейский","audioUrl":"/nte-meta/game-audio/dc0b16ac1610aa15bbe8.ogg"},{"id":"ja-Play_Vo_Char_NPC006_about_007","title":"О ТОИ","description":"ТОИ — просто кучка непонятных личностей, которые делают, что хотят. В новостях они выглядят хорошо, но работать с ними — сплошная головная боль. Когда они собираются вместе, каждый изо всех сил старается продемонстрировать свой уникальный талант… больше похоже на цирк, чем на рабочее место. Хотя, признаю, бывает довольно забавно… «Ты — часть этого»? А-ха-ха, ну и ну, спасибо!","language":"Японский","audioUrl":"/nte-meta/game-audio/b4d139e79d645c14346a.ogg"},{"id":"zh-Play_Vo_Char_NPC006_fh_001","title":"Исцеление I","description":"Хм-м… Ах! Гораздо лучше.","language":"Китайский","audioUrl":"/nte-meta/game-audio/87baf4ef945b362bbd3f.ogg"},{"id":"zh-Play_Vo_Char_NPC006_gift_002","title":"Подарок получен II","description":"Подарок от друга — настоящее сокровище… Поставлю на видное место, чтобы все его видели! Подарок от подруги — настоящее сокровище… Поставлю на видное место, чтобы все его видели!","language":"Китайский","audioUrl":"/nte-meta/game-audio/2efea6c1494cf0e40e54.ogg"},{"id":"zh-Play_Vo_Char_NPC006_windfall_004","title":"Неожиданная добыча IV","description":"Проще простого!","language":"Китайский","audioUrl":"/nte-meta/game-audio/0ee2aa8b93354854eb32.ogg"},{"id":"en-Play_Vo_Char_NPC006_about_007","title":"О ТОИ","description":"ТОИ — просто кучка непонятных личностей, которые делают, что хотят. В новостях они выглядят хорошо, но работать с ними — сплошная головная боль. Когда они собираются вместе, каждый изо всех сил старается продемонстрировать свой уникальный талант… больше похоже на цирк, чем на рабочее место. Хотя, признаю, бывает довольно забавно… «Ты — часть этого»? А-ха-ха, ну и ну, спасибо!","language":"Английский","audioUrl":"/nte-meta/game-audio/9edcacaf46ea4e0f6d42.ogg"},{"id":"en-Play_Vo_Char_NPC006_DodgeCombo_002","title":"Серия критических уклонений II","description":"Безупречное исполнение.","language":"Английский","audioUrl":"/nte-meta/game-audio/21ef3b89ab2eb3872726.ogg"},{"id":"en-Play_Vo_Char_NPC006_windfall_002","title":"Неожиданная добыча II","description":"А? Выглядит отлично.","language":"Английский","audioUrl":"/nte-meta/game-audio/3d0a432df8b35b9cb6e3.ogg"},{"id":"ja-Play_Vo_Char_NPC006_fh_002","title":"Исцеление II","description":"Разберемся с этим побыстрее.","language":"Японский","audioUrl":"/nte-meta/game-audio/be3f2f8e518ece57998c.ogg"},{"id":"ja-Play_Vo_Char_NPC006_greet_002","title":"Дневное приветствие","description":"Ты вовремя. Я как раз хотел выпить чаю в перерыв на обед. Хочешь присоединиться?","language":"Японский","audioUrl":"/nte-meta/game-audio/a69ae8d0e1ad308a8c36.ogg"},{"id":"ko-Play_Vo_Char_NPC006_about_008","title":"О ТОИ-4","description":"Капитан Отряда 4 брошен в одиночестве членами его команды…? Кто это сказал? Это неправда! Мы известны во всём Бюро как образцовая команда с беспрецедентной сплочённостью… Стой, тебе довелось увидеть, как Моза, Фадия и Ския встретились на площади, чтобы вместе пойти за покупками и поужинать? А? Когда это было?","language":"Корейский","audioUrl":"/nte-meta/game-audio/e420cfd3debd8c76f144.ogg"},{"id":"ko-Play_Vo_Char_NPC006_hp_001","title":"Низкий уровень здоровья I","description":"Ах… Сейчас было бы неплохо взять тайм-аут.","language":"Корейский","audioUrl":"/nte-meta/game-audio/8ad9c8e2c5dd4fa5ab88.ogg"},{"id":"zh-Play_Vo_Char_NPC006_hstruck_002","title":"Сильный урон II","description":"…Я стал небрежным.","language":"Китайский","audioUrl":"/nte-meta/game-audio/52c675cb70ce4662e024.ogg"},{"id":"zh-Play_Vo_Char_NPC006_Parry_001","title":"Парирование I","description":"И это всё?","language":"Китайский","audioUrl":"/nte-meta/game-audio/882bb31357f3207b6511.ogg"},{"id":"zh-Play_Vo_Char_NPC006_TeammateDown_001","title":"Поражен товарищ по команде – Ския","description":"Лейтенант пал — и это всё, на что способен Отряд 4? Соберитесь!","language":"Китайский","audioUrl":"/nte-meta/game-audio/b1ef68416c5cb6847740.ogg"},{"id":"ja-Play_Vo_Char_NPC006_Switch_001","title":"Переключение I","description":"Пересменка.","language":"Японский","audioUrl":"/nte-meta/game-audio/b206629baf2e8020dbca.ogg"},{"id":"ko-Play_Vo_Char_NPC006_fh_002","title":"Исцеление II","description":"Разберемся с этим побыстрее.","language":"Корейский","audioUrl":"/nte-meta/game-audio/32f7ed5d30a706e4ab74.ogg"},{"id":"zh-Play_Vo_Char_NPC006_containment_002","title":"Сдерживание II","description":"И-и-и-и рабочий день закончен.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5f374add4636e3ac07c6.ogg"},{"id":"zh-Play_Vo_Char_NPC006_SSC_001","title":"Особое переключение — Ския","description":"Отчёт по заданию напишу… потом.","language":"Китайский","audioUrl":"/nte-meta/game-audio/1745e8814b6eeca66cd4.ogg"},{"id":"en-Play_Vo_Char_NPC006_fh_002","title":"Исцеление II","description":"Разберемся с этим побыстрее.","language":"Английский","audioUrl":"/nte-meta/game-audio/eea856d935d9cdd7c791.ogg"},{"id":"en-Play_Vo_Char_NPC006_QTE_001","title":"Атака на входе I","description":"Эй, не отвлекайся!","language":"Английский","audioUrl":"/nte-meta/game-audio/6631572f796fbe55bf29.ogg"},{"id":"ja-Play_Vo_Char_NPC006_vexation_001","title":"Проблемы","description":"Меньше забот, меньше хлопот! Хах, не смотри на меня так! Я никогда не говорил, что мне не о чем волноваться. Позволь мне пока оставить некоторые секреты при себе, ладно?","language":"Японский","audioUrl":"/nte-meta/game-audio/943936f64787e8ff5eb9.ogg"},{"id":"ko-Play_Vo_Char_NPC006_containment_001","title":"Сдерживание I","description":"Добро пожаловать домой!","language":"Корейский","audioUrl":"/nte-meta/game-audio/e2ddb8d09e3674d139fa.ogg"},{"id":"ko-Play_Vo_Char_NPC006_greet_004","title":"Спокойной ночи","description":"Глаза слипаются? Ой… видимо, уже ночь. Я так заболтался с тобой, что прошло уже много времени, а я и не заметил. Виноват, виноват.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ce25eb1c63db81c5879c.ogg"},{"id":"zh-Play_Vo_Char_NPC006_kill_002","title":"Убийство II","description":"Мне нужно уйти с работы! Прости!","language":"Китайский","audioUrl":"/nte-meta/game-audio/db940e93d3426d6394e7.ogg"},{"id":"zh-Play_Vo_Char_NPC006_skill_002","title":"Навык перенаправления II","description":"Навостри уши.","language":"Китайский","audioUrl":"/nte-meta/game-audio/16a49d8e2a9a6c0cb939.ogg"},{"id":"zh-Play_Vo_Char_NPC006_skill_003","title":"Навык перенаправления III","description":"Ш-ш-ш… тихо.","language":"Китайский","audioUrl":"/nte-meta/game-audio/208ffc15758260813673.ogg"},{"id":"zh-Play_Vo_Char_NPC006_ug_003","title":"Вознесение персонажа III","description":"Ну что, впереди ещё один тяжёлый рабочий день.","language":"Китайский","audioUrl":"/nte-meta/game-audio/85ca158c23b32aa87a0e.ogg"},{"id":"en-Play_Vo_Char_NPC006_struck_001","title":"Урон I","description":"Т-с.","language":"Английский","audioUrl":"/nte-meta/game-audio/5e80da9709a16ea788ec.ogg"},{"id":"ja-Play_Vo_Char_NPC006_SSC_001","title":"Особое переключение — Ския","description":"Отчёт по заданию напишу… потом.","language":"Японский","audioUrl":"/nte-meta/game-audio/a43be7460502b5faf170.ogg"},{"id":"en-Play_Vo_Char_NPC006_dead_001","title":"Потеря сознания I","description":"Не здесь… и не где-либо еще…","language":"Английский","audioUrl":"/nte-meta/game-audio/6704ee7380fcd50735de.ogg"},{"id":"ja-Play_Vo_Char_NPC006_about_001","title":"Об Альфарде","description":"Если директор продолжит урезать мне зарплату… Рано или поздно придется взять кредит, просто чтобы прийти на работу. Ах… Даже интересно, когда она все-таки меня выгонит.","language":"Японский","audioUrl":"/nte-meta/game-audio/2c5fc2da0cc4bd10032e.ogg"},{"id":"ko-Play_Vo_Char_NPC006_windfall_001","title":"Неожиданная добыча I","description":"Буду считать это платой за переработку.","language":"Корейский","audioUrl":"/nte-meta/game-audio/21ae1d656831d1222613.ogg"},{"id":"zh-Play_Vo_Char_NPC006_gift_004","title":"Подарок получен IV","description":"Тс-с! Бюро ни за что не позволит своим капитанам брать взятки!","language":"Китайский","audioUrl":"/nte-meta/game-audio/50772aa37a48621a49e2.ogg"},{"id":"zh-Play_Vo_Char_NPC006_Switch_003","title":"Переключение III","description":"Огонь по своим!","language":"Китайский","audioUrl":"/nte-meta/game-audio/ca2f3e8a67e5a688ae87.ogg"},{"id":"ja-Play_Vo_Char_NPC006_containment_002","title":"Сдерживание II","description":"И-и-и-и рабочий день закончен.","language":"Японский","audioUrl":"/nte-meta/game-audio/e53a4012bbe6953a8b32.ogg"},{"id":"ko-Play_Vo_Char_NPC006_about_007","title":"О ТОИ","description":"ТОИ — просто кучка непонятных личностей, которые делают, что хотят. В новостях они выглядят хорошо, но работать с ними — сплошная головная боль. Когда они собираются вместе, каждый изо всех сил старается продемонстрировать свой уникальный талант… больше похоже на цирк, чем на рабочее место. Хотя, признаю, бывает довольно забавно… «Ты — часть этого»? А-ха-ха, ну и ну, спасибо!","language":"Корейский","audioUrl":"/nte-meta/game-audio/240125c08e08d06a3f4f.ogg"},{"id":"zh-Play_Vo_Char_NPC006_aoe_UI_002","title":"Сверхспособность II","description":"Произнесенное вслух требует уважения.","language":"Китайский","audioUrl":"/nte-meta/game-audio/48b15c148d349717b96b.ogg"},{"id":"zh-Play_Vo_Char_NPC006_TeammateDown_003","title":"Поражен товарищ по команде – Лакримоза","description":"Моза, поспишь, когда доберёмся до дома.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b10974304890e3d90c52.ogg"},{"id":"en-Play_Vo_Char_NPC006_SSC_001","title":"Особое переключение — Ския","description":"Отчёт по заданию напишу… потом.","language":"Английский","audioUrl":"/nte-meta/game-audio/96322cd9b84343e17ef0.ogg"},{"id":"ko-Play_Vo_Char_NPC006_deploy_001","title":"Отправка II","description":"Не волнуйся, я не сбегу посреди драки.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b7f57e007bbcb437df87.ogg"},{"id":"ko-Play_Vo_Char_NPC006_self_001","title":"Обо мне: способности эспера","description":"Слова обладают гораздо большей силой, чем думают люди. Страшно, да? Ха-ха… При желании даже самые простые слова с легкостью принесут страдание или счастье. Но, уверен, ты знаешь, как пользоваться этой силой с умом.","language":"Корейский","audioUrl":"/nte-meta/game-audio/bfba3112fb1d49634045.ogg"},{"id":"ko-Play_Vo_Char_NPC006_struck_002","title":"Урон II","description":"Никак не угомонишься?","language":"Корейский","audioUrl":"/nte-meta/game-audio/8322c347aec1847bcad1.ogg"},{"id":"en-Play_Vo_Char_NPC006_Fly_002","title":"Планирование II","description":"Привет, птичка.","language":"Английский","audioUrl":"/nte-meta/game-audio/72ce816e77e53d6889a3.ogg"},{"id":"en-Play_Vo_Char_NPC006_QTE_002","title":"Атака на входе II","description":"Мне бы не помешала разминка.","language":"Английский","audioUrl":"/nte-meta/game-audio/1cde6439993f9a0586e1.ogg"},{"id":"ja-Play_Vo_Char_NPC006_deploy_001","title":"Отправка II","description":"Не волнуйся, я не сбегу посреди драки.","language":"Японский","audioUrl":"/nte-meta/game-audio/260d62ac94f72fa5eeaa.ogg"},{"id":"zh-Play_Vo_Char_NPC006_dead_003","title":"Потеря сознания III","description":"Надеюсь… меня ждет приветственная церемония…","language":"Китайский","audioUrl":"/nte-meta/game-audio/5f2c2b4c0455586d0336.ogg"},{"id":"zh-Play_Vo_Char_NPC006_DodgeCombo_002","title":"Серия критических уклонений II","description":"Безупречное исполнение.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e9733400379195fb6f77.ogg"},{"id":"en-Play_Vo_Char_NPC006_gift_001","title":"Подарок получен I","description":"Ага, похоже, у нас с тобой одинаковый утончённый вкус!","language":"Английский","audioUrl":"/nte-meta/game-audio/174e1c29d62eaacb4ba1.ogg"},{"id":"en-Play_Vo_Char_NPC006_TeammateDown_003","title":"Поражен товарищ по команде – Лакримоза","description":"Моза, поспишь, когда доберёмся до дома.","language":"Английский","audioUrl":"/nte-meta/game-audio/a86fac76e681f09bc75f.ogg"},{"id":"ja-Play_Vo_Char_NPC006_anomaly_003","title":"Нуллификация I","description":"Спи крепко.","language":"Японский","audioUrl":"/nte-meta/game-audio/47d93c5536015d51831a.ogg"},{"id":"ja-Play_Vo_Char_NPC006_struck_002","title":"Урон II","description":"Никак не угомонишься?","language":"Японский","audioUrl":"/nte-meta/game-audio/747a86084bca6d36406a.ogg"},{"id":"ja-Play_Vo_Char_NPC006_talk_003","title":"Тема: сожаления","description":"Иногда я думаю, если все, что ушло, лишится истории и имени, что останется? Их идеи, их эмоции… Куда все уходит? Стоит ли запоздалому солнцу извиняться перед увядшим подсолнухом…?","language":"Японский","audioUrl":"/nte-meta/game-audio/07762fb7956ecb2fc817.ogg"},{"id":"zh-Play_Vo_Char_NPC006_ug_001","title":"Вознесение персонажа I","description":"Время от времени стоит делать шаг вперед.","language":"Китайский","audioUrl":"/nte-meta/game-audio/190d7ab108533b6e645c.ogg"},{"id":"zh-Play_Vo_Char_NPC006_weather_004","title":"Жарко","description":"Я хочу наградить себя за прилежную работу в такую жару! Планирую отклониться от маршрута и купить мороженое в «Снежке». Ш-ш-ш, не говори Скии… Хм? Эй, это не безделье! Но в благодарность за хранение тайны я возьму одно и для тебя! Так что, с каким вкусом ты любишь?","language":"Китайский","audioUrl":"/nte-meta/game-audio/a594202754a764a81f31.ogg"},{"id":"en-Play_Vo_Char_NPC006_about_002","title":"О Скии","description":"Пусть жуткое лицо Скии не обманывает тебя, он относится к работе очень серьезно. Ха-ха, с таким надежным Лейтенантом быть Капитаном значительно проще. Хотя было бы неплохо, если бы он не был так строг к моим мелким промахам.","language":"Английский","audioUrl":"/nte-meta/game-audio/1ba897a68200e92c2f61.ogg"},{"id":"en-Play_Vo_Char_NPC006_aoe_UI_001","title":"Сверхспособность I","description":"Бесчестные слова недопустимы.","language":"Английский","audioUrl":"/nte-meta/game-audio/bd662dd18dbfd90aa9d1.ogg"},{"id":"zh-Play_Vo_Char_NPC006_self_003","title":"Обо мне: капитан","description":"Такие звания, как «Капитан», на самом деле мало что значат. Я не из тех, кто задирает нос, а моя команда? Они не станут больше уважать меня из-за какого-то звания. Честно говоря, быть капитаном — сплошная морока… кстати об этом, нужно придумать предлог, чтобы Ския смог прийти за меня на собрание Бюро завтра утром…","language":"Китайский","audioUrl":"/nte-meta/game-audio/9963aca36f02cd78348a.ogg"},{"id":"en-Play_Vo_Char_NPC006_TeammateDown_002","title":"Поражен товарищ по команде – Фадия","description":"Неожиданный финал, не так ли?","language":"Английский","audioUrl":"/nte-meta/game-audio/b5e8162e375fa9994d8b.ogg"},{"id":"en-Play_Vo_Char_NPC006_weather_004","title":"Жарко","description":"Я хочу наградить себя за прилежную работу в такую жару! Планирую отклониться от маршрута и купить мороженое в «Снежке». Ш-ш-ш, не говори Скии… Хм? Эй, это не безделье! Но в благодарность за хранение тайны я возьму одно и для тебя! Так что, с каким вкусом ты любишь?","language":"Английский","audioUrl":"/nte-meta/game-audio/3b633ac7f463978917b7.ogg"},{"id":"ja-Play_Vo_Char_NPC006_weather_004","title":"Жарко","description":"Я хочу наградить себя за прилежную работу в такую жару! Планирую отклониться от маршрута и купить мороженое в «Снежке». Ш-ш-ш, не говори Скии… Хм? Эй, это не безделье! Но в благодарность за хранение тайны я возьму одно и для тебя! Так что, с каким вкусом ты любишь?","language":"Японский","audioUrl":"/nte-meta/game-audio/87b1635aef2a0c1b84df.ogg"},{"id":"ja-Play_Vo_Char_NPC006_windfall_006","title":"Неожиданная добыча VI","description":"О, классно!","language":"Японский","audioUrl":"/nte-meta/game-audio/59314e6d90ed4ff0dbe8.ogg"},{"id":"zh-Play_Vo_Char_NPC006_vexation_001","title":"Проблемы","description":"Меньше забот, меньше хлопот! Хах, не смотри на меня так! Я никогда не говорил, что мне не о чем волноваться. Позволь мне пока оставить некоторые секреты при себе, ладно?","language":"Китайский","audioUrl":"/nte-meta/game-audio/57dcb7bdcb53cff6554b.ogg"},{"id":"en-Play_Vo_Char_NPC006_kill_002","title":"Убийство II","description":"Мне нужно уйти с работы! Прости!","language":"Английский","audioUrl":"/nte-meta/game-audio/2206d02ef8c892a8c8df.ogg"},{"id":"ja-Play_Vo_Char_NPC006_struck_001","title":"Урон I","description":"Т-с.","language":"Японский","audioUrl":"/nte-meta/game-audio/6843619496ea69f69e84.ogg"},{"id":"ko-Play_Vo_Char_NPC006_TeammateDown_003","title":"Поражен товарищ по команде – Лакримоза","description":"Моза, поспишь, когда доберёмся до дома.","language":"Корейский","audioUrl":"/nte-meta/game-audio/705748a8fdec0b774d5e.ogg"},{"id":"zh-Play_Vo_Char_NPC006_ug_002","title":"Вознесение персонажа II","description":"Кажется, мои безмятежные дни подходят к концу!","language":"Китайский","audioUrl":"/nte-meta/game-audio/0f1dd03b009eb15075bc.ogg"},{"id":"en-Play_Vo_Char_NPC006_about_008","title":"О ТОИ-4","description":"Капитан Отряда 4 брошен в одиночестве членами его команды…? Кто это сказал? Это неправда! Мы известны во всём Бюро как образцовая команда с беспрецедентной сплочённостью… Стой, тебе довелось увидеть, как Моза, Фадия и Ския встретились на площади, чтобы вместе пойти за покупками и поужинать? А? Когда это было?","language":"Английский","audioUrl":"/nte-meta/game-audio/6865417c0ed12b2283ea.ogg"},{"id":"en-Play_Vo_Char_NPC006_windfall_005","title":"Неожиданная добыча V","description":"Чем больше, тем веселее.","language":"Английский","audioUrl":"/nte-meta/game-audio/3873bba4bb031be9a353.ogg"},{"id":"ja-Play_Vo_Char_NPC006_about_006","title":"О Бюро по борьбе с аномалиями","description":"В Бюро было бы неплохо без кучи замысловатых правил и чопорных традиционалистов. Хотя, если убрать их, наверное, мало что останется, да?","language":"Японский","audioUrl":"/nte-meta/game-audio/79d60ccda2adbffc48f1.ogg"},{"id":"ja-Play_Vo_Char_NPC006_TeammateDown_003","title":"Поражен товарищ по команде – Лакримоза","description":"Моза, поспишь, когда доберёмся до дома.","language":"Японский","audioUrl":"/nte-meta/game-audio/5c47526be8f04687d5f3.ogg"},{"id":"ko-Play_Vo_Char_NPC006_about_001","title":"Об Альфарде","description":"Если директор продолжит урезать мне зарплату… Рано или поздно придется взять кредит, просто чтобы прийти на работу. Ах… Даже интересно, когда она все-таки меня выгонит.","language":"Корейский","audioUrl":"/nte-meta/game-audio/390c5d04f5ddefeee0a4.ogg"},{"id":"ko-Play_Vo_Char_NPC006_weather_003","title":"Холодно","description":"Я предложил ввести для своего отряда «отгулы из-за холодной погоды». Все проголосовали «за»… кроме Скии. И наша любимая директор отклонила мое предложение. Что ж, если там, откуда ты родом, есть «отгулы из-за холодной погоды» или «зимние каникулы», насладись ими и за меня тоже.","language":"Корейский","audioUrl":"/nte-meta/game-audio/2c7d7822bfcbe4ece8da.ogg"},{"id":"zh-Play_Vo_Char_NPC006_chat_001","title":"Чат: расслабление","description":"Серьезность — это достоинство, но постоянное напряжение чрезмерно выматывает! Прими дружеский совет — иногда нужно расслабляться!","language":"Китайский","audioUrl":"/nte-meta/game-audio/c918850f43606b7f6bae.ogg"},{"id":"en-Play_Vo_Char_NPC006_fh_001","title":"Исцеление I","description":"Хм-м… Ах! Гораздо лучше.","language":"Английский","audioUrl":"/nte-meta/game-audio/90a0672cbc6c5b0c58e1.ogg"},{"id":"ja-Play_Vo_Char_NPC006_greet_001","title":"Утреннее приветствие","description":"Доброе утро! Такой прекрасный день, идеален для отдыха… А, хотя лучше, чтобы они меня не нашли. Пока.","language":"Японский","audioUrl":"/nte-meta/game-audio/e80ea4fdf5ddd58b23ae.ogg"},{"id":"ko-Play_Vo_Char_NPC006_about_004","title":"О Лакримозе","description":"Моза невероятно талантлива, но она все ещё ребенок, который почти ничего не знает о мире. Как взрослый я должен присматривать за ней. Эх, и почему она меня так ненавидит? Это разбивает мне сердце…","language":"Корейский","audioUrl":"/nte-meta/game-audio/37c1d966834531b056a9.ogg"},{"id":"ko-Play_Vo_Char_NPC006_about_005","title":"О Хотори","description":"Иногда она напоминает мне Директора — её так же сложно понять… Хотя, кажется, сейчас она уже не та, что в прошлом? Может быть слишком много пьет?","language":"Корейский","audioUrl":"/nte-meta/game-audio/25cd6ef1dadc27ce4f61.ogg"},{"id":"en-Play_Vo_Char_NPC006_anomaly_004","title":"Нуллификация II","description":"Я просто… напишу что-нибудь в отчете о миссии.","language":"Английский","audioUrl":"/nte-meta/game-audio/11cae6008348e8ca8536.ogg"},{"id":"en-Play_Vo_Char_NPC006_weather_001","title":"Солнечно","description":"Обидно провести такой прекрасный день в душном офисе, перекладывая бумажки. Да! Займусь этим позже.","language":"Английский","audioUrl":"/nte-meta/game-audio/036c5bb60c794d8c9b47.ogg"},{"id":"ko-Play_Vo_Char_NPC006_about_002","title":"О Скии","description":"Пусть жуткое лицо Скии не обманывает тебя, он относится к работе очень серьезно. Ха-ха, с таким надежным Лейтенантом быть Капитаном значительно проще. Хотя было бы неплохо, если бы он не был так строг к моим мелким промахам.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ea74cd2e675f610ef500.ogg"},{"id":"ko-Play_Vo_Char_NPC006_about_006","title":"О Бюро по борьбе с аномалиями","description":"В Бюро было бы неплохо без кучи замысловатых правил и чопорных традиционалистов. Хотя, если убрать их, наверное, мало что останется, да?","language":"Корейский","audioUrl":"/nte-meta/game-audio/9cfa00e6d8752b01b8a4.ogg"},{"id":"zh-Play_Vo_Char_NPC006_chat_002","title":"Чат: шалости","description":"Интересно, почему я здесь? Ах… как видишь, Фадия и Моза заперли меня снаружи. Вздох… Как они могли так жестоко поступить с собственным капитаном… Хм? «Что ты сделал на этот раз?» Эй, это несправедливо ко мне, не находишь? Даже ты считаешь, что я виноват? Ну да, я нарисовал на лице Мозы усы, пока она спала… Но Фадия уже сравняла счёт! И всё равно они заперли меня снаружи! Несправедливый суд и незаслуженное наказание…","language":"Китайский","audioUrl":"/nte-meta/game-audio/8223acf59b74482b4ba4.ogg"},{"id":"ja-Play_Vo_Char_NPC006_SSC_004","title":"Особое переключение — Минт","description":"Надо устроить новичкам хорошее представление.","language":"Японский","audioUrl":"/nte-meta/game-audio/ff8425b7e0ae6b8db1fb.ogg"},{"id":"ko-Play_Vo_Char_NPC006_TeammateDown_001","title":"Поражен товарищ по команде – Ския","description":"Лейтенант пал — и это всё, на что способен Отряд 4? Соберитесь!","language":"Корейский","audioUrl":"/nte-meta/game-audio/93cd70b8e4012ddbcff2.ogg"},{"id":"en-Play_Vo_Char_NPC006_chat_003","title":"Чат: приглашение","description":"Кажется, ты хорошо проводишь время в «Эйбоне». Видимо, ты ей нравишься. Но… если захочешь сменить обстановку, двери в ТОИ всегда открыты.","language":"Английский","audioUrl":"/nte-meta/game-audio/021e2ca2e4f6aa56d53d.ogg"},{"id":"en-Play_Vo_Char_NPC006_talk_003","title":"Тема: сожаления","description":"Иногда я думаю, если все, что ушло, лишится истории и имени, что останется? Их идеи, их эмоции… Куда все уходит? Стоит ли запоздалому солнцу извиняться перед увядшим подсолнухом…?","language":"Английский","audioUrl":"/nte-meta/game-audio/bc62443a102480877a91.ogg"},{"id":"ja-Play_Vo_Char_NPC006_hstruck_001","title":"Сильный урон I","description":"Неплохо.","language":"Японский","audioUrl":"/nte-meta/game-audio/1d89dbac812c7760420f.ogg"},{"id":"ja-Play_Vo_Char_NPC006_SSC_002","title":"Особое переключение — Фадия","description":"Игра в кошки-мышки ещё не окончена.","language":"Японский","audioUrl":"/nte-meta/game-audio/aec7b57158ea2b8e63e5.ogg"},{"id":"ko-Play_Vo_Char_NPC006_skill_001","title":"Навык перенаправления I","description":"Эй, болтовня окончена.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6bb1c52295d7f8929c4e.ogg"},{"id":"zh-Play_Vo_Char_NPC006_deploy_002","title":"Отправка I","description":"Эй, нужна помощь?","language":"Китайский","audioUrl":"/nte-meta/game-audio/f6001b24f16cd2389f7c.ogg"},{"id":"zh-Play_Vo_Char_NPC006_skill_001","title":"Навык перенаправления I","description":"Эй, болтовня окончена.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3c9573a57afa5443c112.ogg"},{"id":"en-Play_Vo_Char_NPC006_dead_003","title":"Потеря сознания III","description":"Надеюсь… меня ждет приветственная церемония…","language":"Английский","audioUrl":"/nte-meta/game-audio/a3acff53274e6d36ae74.ogg"},{"id":"en-Play_Vo_Char_NPC006_hp_002","title":"Низкий уровень здоровья II","description":"Серьезно.","language":"Английский","audioUrl":"/nte-meta/game-audio/f096296e773122cd93ae.ogg"},{"id":"ja-Play_Vo_Char_NPC006_about_002","title":"О Скии","description":"Пусть жуткое лицо Скии не обманывает тебя, он относится к работе очень серьезно. Ха-ха, с таким надежным Лейтенантом быть Капитаном значительно проще. Хотя было бы неплохо, если бы он не был так строг к моим мелким промахам.","language":"Японский","audioUrl":"/nte-meta/game-audio/939e5e64f94ff1b89a05.ogg"},{"id":"ja-Play_Vo_Char_NPC006_about_004","title":"О Лакримозе","description":"Моза невероятно талантлива, но она все ещё ребенок, который почти ничего не знает о мире. Как взрослый я должен присматривать за ней. Эх, и почему она меня так ненавидит? Это разбивает мне сердце…","language":"Японский","audioUrl":"/nte-meta/game-audio/40a7de1d1aa052106719.ogg"},{"id":"zh-Play_Vo_Char_NPC006_about_003","title":"О Фадии","description":"Никогда не связывайся с Фадией, если нет готовности к этому, поверь тому, кто знает лучше. Хотя, если есть уверенность в себе, — вперёд! Испытай удачу, но пообещай, что позволишь мне посмотреть! Любопытно, что случилось со мной? Хех… не будем об этом.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c2aae751698b9eb3f796.ogg"},{"id":"zh-Play_Vo_Char_NPC006_hstruck_001","title":"Сильный урон I","description":"Неплохо.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0d4e7f4fbb8bb87231cb.ogg"},{"id":"ja-Play_Vo_Char_NPC006_Fly_002","title":"Планирование II","description":"Привет, птичка.","language":"Японский","audioUrl":"/nte-meta/game-audio/bd9a0c87ab34f3196618.ogg"},{"id":"ja-Play_Vo_Char_NPC006_ug_002","title":"Вознесение персонажа II","description":"Кажется, мои безмятежные дни подходят к концу!","language":"Японский","audioUrl":"/nte-meta/game-audio/dbee636d5343226aa838.ogg"},{"id":"en-Play_Vo_Char_NPC006_self_003","title":"Обо мне: капитан","description":"Такие звания, как «Капитан», на самом деле мало что значат. Я не из тех, кто задирает нос, а моя команда? Они не станут больше уважать меня из-за какого-то звания. Честно говоря, быть капитаном — сплошная морока… кстати об этом, нужно придумать предлог, чтобы Ския смог прийти за меня на собрание Бюро завтра утром…","language":"Английский","audioUrl":"/nte-meta/game-audio/a3e2d5f243106430b687.ogg"},{"id":"en-Play_Vo_Char_NPC006_ug_002","title":"Вознесение персонажа II","description":"Кажется, мои безмятежные дни подходят к концу!","language":"Английский","audioUrl":"/nte-meta/game-audio/3cd4ef22fe58e61d9789.ogg"},{"id":"ja-Play_Vo_Char_NPC006_meet_001","title":"Первая встреча","description":"Мы вместе прошли огонь и воду, так что давай обойдемся без формальностей, ладно? Хм-м… Хотя, если подумать, я так и не представился по-нормальному… Капитан ТОИ-4 Байканг. Будем и дальше ладить друг с другом, хорошо?","language":"Японский","audioUrl":"/nte-meta/game-audio/a2b4f64aadd2761199c9.ogg"},{"id":"zh-Play_Vo_Char_NPC006_weather_002","title":"Дождливо","description":"Если хочешь скоротать время, понаблюдай за черепицей на крышах во время дождя. Это довольно увлекательно. Она так необычно мерцает, и капли дождя отскакивают от неё в разные стороны, создавая звуки разной частоты… как будто кто-то пытается что-то прошептать.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7c2536d526b67577fdc7.ogg"},{"id":"en-Play_Vo_Char_NPC006_deploy_001","title":"Отправка II","description":"Не волнуйся, я не сбегу посреди драки.","language":"Английский","audioUrl":"/nte-meta/game-audio/d79de699a8a50cef355d.ogg"},{"id":"ja-Play_Vo_Char_NPC006_ug_003","title":"Вознесение персонажа III","description":"Ну что, впереди ещё один тяжёлый рабочий день.","language":"Японский","audioUrl":"/nte-meta/game-audio/914badb07a2124fdcedf.ogg"},{"id":"ja-Play_Vo_Char_NPC006_windfall_002","title":"Неожиданная добыча II","description":"А? Выглядит отлично.","language":"Японский","audioUrl":"/nte-meta/game-audio/7d4d8052f7d1d836f685.ogg"},{"id":"ko-Play_Vo_Char_NPC006_gift_002","title":"Подарок получен II","description":"Подарок от друга — настоящее сокровище… Поставлю на видное место, чтобы все его видели! Подарок от подруги — настоящее сокровище… Поставлю на видное место, чтобы все его видели!","language":"Корейский","audioUrl":"/nte-meta/game-audio/e76ee90cd12eb2589418.ogg"},{"id":"ko-Play_Vo_Char_NPC006_meet_001","title":"Первая встреча","description":"Мы вместе прошли огонь и воду, так что давай обойдемся без формальностей, ладно? Хм-м… Хотя, если подумать, я так и не представился по-нормальному… Капитан ТОИ-4 Байканг. Будем и дальше ладить друг с другом, хорошо?","language":"Корейский","audioUrl":"/nte-meta/game-audio/0f70a46b83a41042a1b2.ogg"},{"id":"ko-Play_Vo_Char_NPC006_Switch_002","title":"Переключение II","description":"Я? Ладно, тогда.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a5badcc1bb399aa4c889.ogg"},{"id":"ko-Play_Vo_Char_NPC006_ug_001","title":"Вознесение персонажа I","description":"Время от времени стоит делать шаг вперед.","language":"Корейский","audioUrl":"/nte-meta/game-audio/26beeac3034e95537ba3.ogg"},{"id":"zh-Play_Vo_Char_NPC006_greet_004","title":"Спокойной ночи","description":"Глаза слипаются? Ой… видимо, уже ночь. Я так заболтался с тобой, что прошло уже много времени, а я и не заметил. Виноват, виноват.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2e04621370597b1a0818.ogg"},{"id":"en-Play_Vo_Char_NPC006_about_001","title":"Об Альфарде","description":"Если директор продолжит урезать мне зарплату… Рано или поздно придется взять кредит, просто чтобы прийти на работу. Ах… Даже интересно, когда она все-таки меня выгонит.","language":"Английский","audioUrl":"/nte-meta/game-audio/91834dd6d265f2fe15d8.ogg"},{"id":"en-Play_Vo_Char_NPC006_aoe_UI_003","title":"Сверхспособность III","description":"Что это — благословение или… проклятие?","language":"Английский","audioUrl":"/nte-meta/game-audio/1e960d0c905465bf1d50.ogg"},{"id":"ko-Play_Vo_Char_NPC006_anomaly_004","title":"Нуллификация II","description":"Я просто… напишу что-нибудь в отчете о миссии.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4d97600be9afec244687.ogg"},{"id":"ko-Play_Vo_Char_NPC006_talk_001","title":"Тема: общение","description":"Говорят, язык — это сосуд для разума, но если люди хотят что-то сообщить, то всегда найдут способ самовыражения, с Вавилонской башней или без неё. Слова, действия, мимика… Разве не увлекательно их интерпретировать? К примеру, смотри — у Скии сейчас такое выражение лица… ага, он узнал, что вчера я прогулял работу…","language":"Корейский","audioUrl":"/nte-meta/game-audio/10455f974bbb2123dda5.ogg"},{"id":"zh-Play_Vo_Char_NPC006_QTE_003","title":"Атака на входе III","description":"Эй, полегче. Сильно не бей.","language":"Китайский","audioUrl":"/nte-meta/game-audio/22a8033f474fe9bdafa4.ogg"},{"id":"en-Play_Vo_Char_NPC006_skill_001","title":"Навык перенаправления I","description":"Эй, болтовня окончена.","language":"Английский","audioUrl":"/nte-meta/game-audio/02e717fcbb5fe4e8f6d5.ogg"},{"id":"ja-Play_Vo_Char_NPC006_Parry_001","title":"Парирование I","description":"И это всё?","language":"Японский","audioUrl":"/nte-meta/game-audio/835cebe2a787b19295ad.ogg"},{"id":"ko-Play_Vo_Char_NPC006_QTE_003","title":"Атака на входе III","description":"Эй, полегче. Сильно не бей.","language":"Корейский","audioUrl":"/nte-meta/game-audio/64462afc71746e0491e1.ogg"},{"id":"ko-Play_Vo_Char_NPC006_SSC_002","title":"Особое переключение — Фадия","description":"Игра в кошки-мышки ещё не окончена.","language":"Корейский","audioUrl":"/nte-meta/game-audio/2d92215957a42a54491b.ogg"},{"id":"zh-Play_Vo_Char_NPC006_chat_003","title":"Чат: приглашение","description":"Кажется, ты хорошо проводишь время в «Эйбоне». Видимо, ты ей нравишься. Но… если захочешь сменить обстановку, двери в ТОИ всегда открыты.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5f9b9c9a493595cea4c1.ogg"},{"id":"zh-Play_Vo_Char_NPC006_Fly_001","title":"Планирование I","description":"Ну что ж, вот это дальность.","language":"Китайский","audioUrl":"/nte-meta/game-audio/8704d611fda540429dcb.ogg"},{"id":"zh-Play_Vo_Char_NPC006_gift_003","title":"Подарок получен III","description":"Подарок за подарок. Мой подарок тебе… дай-ка подумать.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b5ca49d3366bcfb503ba.ogg"},{"id":"ja-Play_Vo_Char_NPC006_about_003","title":"О Фадии","description":"Никогда не связывайся с Фадией, если нет готовности к этому, поверь тому, кто знает лучше. Хотя, если есть уверенность в себе, — вперёд! Испытай удачу, но пообещай, что позволишь мне посмотреть! Любопытно, что случилось со мной? Хех… не будем об этом.","language":"Японский","audioUrl":"/nte-meta/game-audio/079d7be59186ae9efadc.ogg"},{"id":"ja-Play_Vo_Char_NPC006_dead_003","title":"Потеря сознания III","description":"Надеюсь… меня ждет приветственная церемония…","language":"Японский","audioUrl":"/nte-meta/game-audio/12a784c06e7d29770089.ogg"},{"id":"ja-Play_Vo_Char_NPC006_kill_002","title":"Убийство II","description":"Мне нужно уйти с работы! Прости!","language":"Японский","audioUrl":"/nte-meta/game-audio/28d801a0f9d1d74f7341.ogg"},{"id":"ja-Play_Vo_Char_NPC006_QTE_001","title":"Атака на входе I","description":"Эй, не отвлекайся!","language":"Японский","audioUrl":"/nte-meta/game-audio/ff82742e27569e8a61c3.ogg"},{"id":"ja-Play_Vo_Char_NPC006_TeammateDown_002","title":"Поражен товарищ по команде – Фадия","description":"Неожиданный финал, не так ли?","language":"Японский","audioUrl":"/nte-meta/game-audio/15bc4cf96620847948c4.ogg"},{"id":"ko-Play_Vo_Char_NPC006_anomaly_003","title":"Нуллификация I","description":"Спи крепко.","language":"Корейский","audioUrl":"/nte-meta/game-audio/3615b72aeca0941c11c6.ogg"},{"id":"ko-Play_Vo_Char_NPC006_Fly_002","title":"Планирование II","description":"Привет, птичка.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1d56e3e902333725cd8e.ogg"}]'))) WHERE character_id='baicang' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-01 09:11:10');

UPDATE character_profiles SET abilities_json=json('[{"id":"e9af5a88-e556-4d35-8e9b-514069b321f3","name":"Слово и действие","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/e5c07492df3343aae384.webp","description":"Применяет мастерство боевых искусств, чтобы провести до 5 последовательных атак, наносящих урон от чар.\n\nБазовые значения:\nКоэфф. 1-го экземпляра: 47.5％\\nКоэфф. 2-го экземпляра: 42.3％\\nКоэфф. 3-го экземпляра: 119％\\nКоэфф. 4-го экземпляра: 25.1％×3\\nКоэфф. 5-го экземпляра: 86.3％\\nКоэфф. урона отбрасывания «Бесформенных слов»: 66％\\nКоэфф. урона взрыва «Бесформенных слов»: 22％\\nКоэфф. урона отбрасывания «Необузданных слов»: 66％\\nКоэфф. урона взрыва «Необузданных слов»: 22％\\nКоэфф. урона «На ветру»: 41.8％\\nКоэфф. урона «Разоблаченной истины»: 144％\\nЭнергия циклов: 29","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 47.5 % · 2: 51.3 % · 3: 55.4 % · 4: 59.8 % · 5: 64.6 % · 6: 69.8 % · 7: 75.4 % · 8: 81.4 % · 9: 87.9 % · 10: 95 % · 11: 102.5 % · 12: 110.8 % · 13: 119.6 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 42.3 % · 2: 45.7 % · 3: 49.3 % · 4: 53.3 % · 5: 57.5 % · 6: 62.2 % · 7: 67.1 % · 8: 72.5 % · 9: 78.3 % · 10: 84.6 % · 11: 91.3 % · 12: 98.6 % · 13: 106.5 %"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 119 % · 2: 128.5 % · 3: 138.8 % · 4: 149.9 % · 5: 161.9 % · 6: 174.9 % · 7: 188.8 % · 8: 203.9 % · 9: 220.3 % · 10: 237.9 % · 11: 256.9 % · 12: 277.5 % · 13: 299.7 %"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 25.1 %*3 · 2: 27.1 %*3 · 3: 29.3 %*3 · 4: 31.6 %*3 · 5: 34.1 %*3 · 6: 36.9 %*3 · 7: 39.8 %*3 · 8: 43 %*3 · 9: 46.5 %*3 · 10: 50.2 %*3 · 11: 54.2 %*3 · 12: 58.5 %*3 · 13: 63.2 %*3"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 86.3 % · 2: 93.2 % · 3: 100.7 % · 4: 108.7 % · 5: 117.4 % · 6: 126.8 % · 7: 136.9 % · 8: 147.9 % · 9: 159.7 % · 10: 172.5 % · 11: 186.3 % · 12: 201.2 % · 13: 217.3 %"},{"id":"parameter-5","label":"Множитель урона отбрасывания «Бесформенных слов»","value":"1: 66 % · 2: 71.3 % · 3: 77 % · 4: 83.1 % · 5: 89.8 % · 6: 97 % · 7: 104.7 % · 8: 113.1 % · 9: 122.2 % · 10: 131.9 % · 11: 142.5 % · 12: 153.9 % · 13: 166.2 %"},{"id":"parameter-6","label":"Множитель урона взрыва «Бесформенных слов»","value":"1: 22 % · 2: 23.8 % · 3: 25.7 % · 4: 27.7 % · 5: 29.9 % · 6: 32.3 % · 7: 34.9 % · 8: 37.7 % · 9: 40.7 % · 10: 44 % · 11: 47.5 % · 12: 51.3 % · 13: 55.4 %"},{"id":"parameter-7","label":"Множитель урона отбрасывания «Необузданных слов»","value":"1: 66 % · 2: 71.3 % · 3: 77 % · 4: 83.1 % · 5: 89.8 % · 6: 97 % · 7: 104.7 % · 8: 113.1 % · 9: 122.2 % · 10: 131.9 % · 11: 142.5 % · 12: 153.9 % · 13: 166.2 %"},{"id":"parameter-8","label":"Множитель урона взрыва «Необузданных слов»","value":"1: 22 % · 2: 23.8 % · 3: 25.7 % · 4: 27.7 % · 5: 29.9 % · 6: 32.3 % · 7: 34.9 % · 8: 37.7 % · 9: 40.7 % · 10: 44 % · 11: 47.5 % · 12: 51.3 % · 13: 55.4 %"},{"id":"parameter-9","label":"Множитель урона «На ветру»","value":"1: 41.8 % · 2: 45.1 % · 3: 48.8 % · 4: 52.7 % · 5: 56.9 % · 6: 61.4 % · 7: 66.3 % · 8: 71.6 % · 9: 77.4 % · 10: 83.6 % · 11: 90.2 % · 12: 97.5 % · 13: 105.3 %"},{"id":"parameter-10","label":"Множитель урона «Разоблаченной истины»","value":"1: 144 % · 2: 155.5 % · 3: 168 % · 4: 181.4 % · 5: 195.9 % · 6: 211.6 % · 7: 228.5 % · 8: 246.8 % · 9: 266.5 % · 10: 287.9 % · 11: 310.9 % · 12: 335.8 % · 13: 362.6 %"}]},{"id":"b0446caf-d444-4dc1-a60f-2b92f30e325e","name":"Щедрое руководство","type":"Навык","iconUrl":"/nte-meta/game-assets/6ee79cf098f8286a76ee.webp","description":"Слова и текст появляются из невидимых лучей, сходятся в целевой точке и начинают атаку.\n\nБазовые значения:\nКоэфф. урона «Сердца неба и земли»: 120％\\nКоэфф. урона ракеты «Заглушенной мысли»: 100％×3\\nКоэфф. урона взрыва «Заглушенной мысли»: 120％\\nКоэфф. урона «Такого преступления»: 280％\\nВзаимная ПЗ «Заглушенной мысли» / «Такого преступления»: 14сек.\\nЭнергия циклов: 6","attributes":[{"id":"parameter-0","label":"Множитель урона «Сердца неба и земли»","value":"1: 120 % · 2: 129.6 % · 3: 140 % · 4: 151.2 % · 5: 163.3 % · 6: 176.3 % · 7: 190.4 % · 8: 205.7 % · 9: 222.1 % · 10: 239.9 % · 11: 259.1 % · 12: 279.8 % · 13: 302.2 %"},{"id":"parameter-1","label":"Множитель урона ракеты «Заглушенной мысли»","value":"1: 100 %*3 · 2: 108 %*3 · 3: 116.6 %*3 · 4: 126 %*3 · 5: 136 %*3 · 6: 146.9 %*3 · 7: 158.7 %*3 · 8: 171.4 %*3 · 9: 185.1 %*3 · 10: 199.9 %*3 · 11: 215.9 %*3 · 12: 233.2 %*3 · 13: 251.8 %*3"},{"id":"parameter-2","label":"Множитель урона взрыва «Заглушенной мысли»","value":"1: 120 % · 2: 129.6 % · 3: 140 % · 4: 151.2 % · 5: 163.3 % · 6: 176.3 % · 7: 190.4 % · 8: 205.7 % · 9: 222.1 % · 10: 239.9 % · 11: 259.1 % · 12: 279.8 % · 13: 302.2 %"},{"id":"parameter-3","label":"Множитель урона «Такого преступления»","value":"1: 280 % · 2: 302.4 % · 3: 326.6 % · 4: 352.7 % · 5: 380.9 % · 6: 411.4 % · 7: 444.3 % · 8: 479.9 % · 9: 518.3 % · 10: 559.7 % · 11: 604.5 % · 12: 652.9 % · 13: 705.1 %"}]},{"id":"84ed6e05-1153-4d46-905c-9cc86a96cb2a","name":"Суд осени","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/1134c1b8fdb6a0846569.webp","description":"Возведи очи и устремись в полярную бездну. Создает область и переходит в состояние Слова силы, нанося целям растянутый по времени урон от чар.\\nКогда ОЗ цели опускается ниже 10 % (ОЗ босса — ниже 5 %), Байканг немедленно побеждает ее.\\nВо время «Суда осени» Байканг временно получает иммунитет к одному смертельному удару и фиксирует полученный урон. После срабатывания иммунитета область исчезает через 3 сек., а полученный урон наносится постепенно в течение 10 сек. \\nВ пределах области: активация «Тишины» наносит высокий урон по одной цели; активация «Упрека» наносит урон по области; активация «Одарения» наносит урон одной цели и восстанавливает 5 % от макс. ОЗ Байканга.\n\nБазовые значения:\nКоэффициент урона расширения «Суда осени»: 400％\\nКоэффициент урона со временем «Суда осени»: 40％\\nДлительность «Суда осени»: 12 сек.\\nИнтервал урона со временем: 2сек.\\nКоэфф. урона «Тишины»: 300％\\nКоэфф. урона «Упрека»: 200％\\nКоэфф. урона взрыва «Одарения»: 30％\\nКоэфф. урона ракеты «Одарения»: 15％×2","attributes":[{"id":"parameter-0","label":"Множитель урона расширения «Суда осени»","value":"1: 400 % · 2: 432 % · 3: 466.6 % · 4: 503.9 % · 5: 544.2 % · 6: 587.7 % · 7: 634.7 % · 8: 685.5 % · 9: 740.4 % · 10: 799.6 % · 11: 863.6 % · 12: 932.7 % · 13: 1007.3 %"},{"id":"parameter-1","label":"Множитель периодического урона «Суда осени»","value":"1: 40 % · 2: 43.2 % · 3: 46.7 % · 4: 50.4 % · 5: 54.4 % · 6: 58.8 % · 7: 63.5 % · 8: 68.6 % · 9: 74 % · 10: 80 % · 11: 86.4 % · 12: 93.3 % · 13: 100.7 %"},{"id":"parameter-2","label":"Длительность «Суда осени»","value":"12 сек."},{"id":"parameter-3","label":"Интервал периодического урона","value":"2 сек."},{"id":"parameter-4","label":"Множитель урона «Тишины»","value":"1: 300 % · 2: 324 % · 3: 349.9 % · 4: 377.9 % · 5: 408.1 % · 6: 440.8 % · 7: 476.1 % · 8: 514.1 % · 9: 555.3 % · 10: 599.7 % · 11: 647.7 % · 12: 699.5 % · 13: 755.5 %"},{"id":"parameter-5","label":"Множитель урона «Упрека»","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"},{"id":"parameter-6","label":"Множитель урона взрыва «Одарения»","value":"1: 30 % · 2: 32.4 % · 3: 35 % · 4: 37.8 % · 5: 40.8 % · 6: 44.1 % · 7: 47.6 % · 8: 51.4 % · 9: 55.5 % · 10: 60 % · 11: 64.8 % · 12: 69.9 % · 13: 75.5 %"},{"id":"parameter-7","label":"Множитель урона ракеты «Одарения»","value":"1: 15 %*2 · 2: 16.2 %*2 · 3: 17.5 %*2 · 4: 18.9 %*2 · 5: 20.4 %*2 · 6: 22 %*2 · 7: 23.8 %*2 · 8: 25.7 %*2 · 9: 27.8 %*2 · 10: 30 %*2 · 11: 32.4 %*2 · 12: 35 %*2 · 13: 37.8 %*2"}]},{"id":"4e3921fd-a655-4fd7-87ce-daf923378729","name":"Перерыв окончен","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/1dbc48cc38cbeb87dfb0.webp","description":"Узрите силу, дарованную словом. Ненадолго сосредотачивается и создает команды чар, которые поражают врагов, нанося 1 экземпляр урона от чар по области. При попадании создает на цели 1 слово силы «Тишина».\n\nБазовые значения:\nКоэфф. урона: 200％","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"ea4bb21f-9815-42fd-8892-bc4890c9ec61","name":"Умеренное озорство","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/e79d930a6453a28a758e.webp","description":"Усиление ожога: когда на цели, пораженной ожогом, генерируется слово силы, накладывает ещё один экземпляр ожога с тем же эффектом, что и существующий.","attributes":[]},{"id":"703b189f-b0d2-4584-915b-d46b276e8ad0","name":"Умеренная работа","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/57a114ce9500b1f796d0.webp","description":"Атака Байканга увеличивается на 20 %.\\nКогда в команде есть члены ТОИ-4, Байканг может атаковать совместно с товарищами по команде.\\nЕсли во время боя переключиться на Байканга, пока Ския невидим, Байканг немедленно атакует и генерирует на цели слово силы «Тишина». ПЗ: 1 сек.\\nВо время боя, если ОЗ Фадии падают ниже 1 %, Байканг выходит на поле, чтобы один раз атаковать врагов, один раз вылечить Фадию и сгенерировать на цели 30 слово силы «Тишина». ПЗ: 20 сек.\\nПереключившись на Байканга, пока Лакримоза в облике летучей мыши, можно вызвать суперпрыжок Байканга один раз.","attributes":[]},{"id":"3a1d0d50-6417-46c0-9ba8-68706b5d3e0a","name":"Цветение в зените","type":"Повседневный навык","iconUrl":"/nte-meta/game-assets/42a168618b4b057d3e80.webp","description":"Байканг увеличивает поток на 18.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Байканг увеличивает поток на 18."},{"id":"city-1","label":"Уровень 2","value":"Байканг снижает скорость расхода ингредиентов на 1 %."},{"id":"city-2","label":"Уровень 3","value":"В режиме подборки владельца комбо сохраняются, когда клиенты теряют терпение или получают удары молотками."},{"id":"city-3","label":"Уровень 4","value":"Байканг снижает скорость расхода ингредиентов на 1 %."},{"id":"city-4","label":"Уровень 5","value":"Байканг увеличивает поток на 27."}]}]') WHERE character_id='baicang' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-01 09:11:10');

UPDATE character_profiles SET updated_at=CURRENT_TIMESTAMP WHERE character_id='baicang' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-01 09:11:10');

UPDATE character_profiles SET voice_actors_json=json('[{"language":"Китайский","name":"井琉"},{"language":"Английский","name":"Xanthe Huynh"},{"language":"Японский","name":"能登麻美子"},{"language":"Корейский","name":"문유정"},{"language":"Китайский","name":"井琉 (Jing Liu)"},{"language":"Японский","name":"能登 麻美子（Noto Mamiko）"},{"language":"Корейский","name":"문유정（Moon Yoo-jeong）"}]') WHERE character_id='blackbird' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-22 22:24:48');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"zh-Play_Vo_Char_NPC021_anomaly_004","title":"Нуллификация II","description":"У всего есть своя судьба.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c96b6cd1307ffd0aa46a.ogg"},{"id":"zh-Play_Vo_Char_NPC021_chat_002","title":"Чат: коллекция","description":"Я обожаю собирать всякий антиквариат. И чем причудливее его дизайн, тем больше он мне нравится… Моя коллекция? У меня куда больше вещей, чем кажется на первый взгляд. Я даже выделила для них целую комнату. Если интересно — заглядывай как-нибудь, посмотришь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b34be3d17f4321ba6d54.ogg"},{"id":"zh-Play_Vo_Char_NPC021_QTE_SE_003","title":"Атака на входе VI","description":"Да очистятся души ваши…","language":"Китайский","audioUrl":"/nte-meta/game-audio/d5add21f12d4ef857020.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill01_002","title":"Навык перенаправления II","description":"Тишина.","language":"Китайский","audioUrl":"/nte-meta/game-audio/bbc76f94ce90bd868aea.ogg"},{"id":"en-Play_Vo_Char_NPC021_gift_001","title":"Подарок получен I","description":"Ценен не только сам подарок… но и чувства, которые за ним стоят.","language":"Английский","audioUrl":"/nte-meta/game-audio/f64c286eb5f2c2c7edce.ogg"},{"id":"en-Play_Vo_Char_NPC021_kill_001","title":"Убийство I","description":"Приговор судьбы.","language":"Английский","audioUrl":"/nte-meta/game-audio/3f1981d025ee04d71a42.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill02_001","title":"Навык перенаправления VII","description":"Дрожите?","language":"Английский","audioUrl":"/nte-meta/game-audio/0360417bd5b883cfd397.ogg"},{"id":"ja-Play_Vo_Char_NPC021_containment_002","title":"Сдерживание II","description":"Спи. Больше ни о чём не тревожься…","language":"Японский","audioUrl":"/nte-meta/game-audio/cbeac512704a3bf2f226.ogg"},{"id":"ko-Play_Vo_Char_NPC021_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Отдохни. Я тебя подменю.","language":"Корейский","audioUrl":"/nte-meta/game-audio/7183f56051a7ea79cb0b.ogg"},{"id":"ko-Play_Vo_Char_NPC021_ug_001","title":"Вознесение персонажа I","description":"Я разгадала скрытые послания пророчества.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c6bab45ce76aab57c9a4.ogg"},{"id":"ko-Play_Vo_Char_NPC021_windfall_002","title":"Неожиданная добыча II","description":"Приятный сюрприз.","language":"Корейский","audioUrl":"/nte-meta/game-audio/48a548ea9984d946514b.ogg"},{"id":"zh-Play_Vo_Char_NPC021_greet_003","title":"Вечернее приветствие","description":"Давай вместе найдём наши две звезды на ночном небе.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c9dfdf7ecd200437cc33.ogg"},{"id":"zh-Play_Vo_Char_NPC021_Parry_001","title":"Парирование I","description":"Как раз вовремя.","language":"Китайский","audioUrl":"/nte-meta/game-audio/90be6009f19217540fca.ogg"},{"id":"zh-Play_Vo_Char_NPC021_windfall_003","title":"Неожиданная добыча III","description":"Знак удачи.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5136476dfbc011fe11fd.ogg"},{"id":"ja-Play_Vo_Char_NPC021_about_004","title":"О Меруле","description":"Чем ближе я становлюсь к ней, тем сильнее ощущаю неведомый мне прежде покой, словно… я вернулась в объятия матери. Я не была хорошим ребёнком. Я скиталась веками, не зная её. Но ещё не поздно. Её кровь всё ещё горяча, её глаза видят этот новый мир через мои, и каждое мгновение, что потеряла Мерула, я верну ей.","language":"Японский","audioUrl":"/nte-meta/game-audio/b9ae5dd335296f67975f.ogg"},{"id":"ja-Play_Vo_Char_NPC021_hobby_001","title":"Хобби","description":"Умение покупать товары со скидкой по самой выгодной цене — это целое искусство! Нужно знать точное время акций, размер максимальных скидок, какие именно товары распродают, и распланировать бюджет ещё до выхода из дома… Е-если тебе интересно, я могла бы поделиться с тобой своей тактикой закупок…","language":"Японский","audioUrl":"/nte-meta/game-audio/81685f3993acd10e590f.ogg"},{"id":"ja-Play_Vo_Char_NPC021_struck_001","title":"Урон I","description":"Сосредоточься… Со мной всё в порядке.","language":"Японский","audioUrl":"/nte-meta/game-audio/570b9b4a3c90d0cad4b3.ogg"},{"id":"zh-Play_Vo_Char_NPC021_chat_001","title":"Чат: самообладание","description":"«В зеркале вижу я все судьбы. Открыта мне вся правда, которую ты ищешь…» Ну как, прозвучало таинственно и внушительно? Хе-хе, поддерживать такой образ — та ещё работа. Я довольно часто репетирую, знаешь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/32cc41733e35798d75f5.ogg"},{"id":"en-Play_Vo_Char_NPC021_chat_001","title":"Чат: самообладание","description":"«В зеркале вижу я все судьбы. Открыта мне вся правда, которую ты ищешь…» Ну как, прозвучало таинственно и внушительно? Хе-хе, поддерживать такой образ — та ещё работа. Я довольно часто репетирую, знаешь.","language":"Английский","audioUrl":"/nte-meta/game-audio/37bd9889d3594ce1cbe5.ogg"},{"id":"en-Play_Vo_Char_NPC021_DodgeCombo_001","title":"Серия критических уклонений I","description":"Как и ожидалось.","language":"Английский","audioUrl":"/nte-meta/game-audio/35fad6898d4c5a8c3235.ogg"},{"id":"ja-Play_Vo_Char_NPC021_Switch_001","title":"Переключение I","description":"Что-то случилось?","language":"Японский","audioUrl":"/nte-meta/game-audio/be3c45f92b4f391cbcae.ogg"},{"id":"ko-Play_Vo_Char_NPC021_kill_001","title":"Убийство I","description":"Приговор судьбы.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f5335cf51957cb775b49.ogg"},{"id":"ko-Play_Vo_Char_NPC021_ultraskill_SE_UI_002","title":"Сверхспособность V","description":"Вот и настал ваш последний миг…","language":"Корейский","audioUrl":"/nte-meta/game-audio/517ca9f391eb382b6125.ogg"},{"id":"ja-Play_Vo_Char_NPC021_Parry_001","title":"Парирование I","description":"Как раз вовремя.","language":"Японский","audioUrl":"/nte-meta/game-audio/f30d055453e60fc35720.ogg"},{"id":"ko-Play_Vo_Char_NPC021_chat_001","title":"Чат: самообладание","description":"«В зеркале вижу я все судьбы. Открыта мне вся правда, которую ты ищешь…» Ну как, прозвучало таинственно и внушительно? Хе-хе, поддерживать такой образ — та ещё работа. Я довольно часто репетирую, знаешь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d9df60f5c763394caa8d.ogg"},{"id":"ko-Play_Vo_Char_NPC021_ultraskill_UI_001","title":"Сверхспособность I","description":"Все судьбы — в забвение.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f85788ce4d2156eced59.ogg"},{"id":"ko-Play_Vo_Char_NPC021_windfall_003","title":"Неожиданная добыча III","description":"Знак удачи.","language":"Корейский","audioUrl":"/nte-meta/game-audio/991fd22b7f07e380b3b4.ogg"},{"id":"zh-Play_Vo_Char_NPC021_hp_003","title":"Низкий уровень здоровья III","description":"Мне нужно отдохнуть…","language":"Китайский","audioUrl":"/nte-meta/game-audio/fa450a37738b50d45f22.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill02_SE_003","title":"Навык перенаправления XII","description":"Возрождённая в огне…","language":"Китайский","audioUrl":"/nte-meta/game-audio/88f927844a1285525089.ogg"},{"id":"zh-Play_Vo_Char_NPC021_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Отдохни. Я тебя подменю.","language":"Китайский","audioUrl":"/nte-meta/game-audio/05c61abcf17287fb3c29.ogg"},{"id":"zh-Play_Vo_Char_NPC021_ultraskill_SE_UI_003","title":"Сверхспособность VI","description":"Погибель ваша близка…","language":"Китайский","audioUrl":"/nte-meta/game-audio/6123235a19a4d5631411.ogg"},{"id":"zh-Play_Vo_Char_NPC021_ultraskill_UI_002","title":"Сверхспособность II","description":"Внемлите отголоскам погибели.","language":"Китайский","audioUrl":"/nte-meta/game-audio/530c5875054d2187ec0a.ogg"},{"id":"en-Play_Vo_Char_NPC021_TeammateDown_001","title":"Поражен товарищ по команде – Ноль","description":"Оценщик!.. Неужели это тоже… воля судьбы?..Оценщица!.. Неужели это тоже… воля судьбы?..","language":"Английский","audioUrl":"/nte-meta/game-audio/48e01ef2e20cfb7b4473.ogg"},{"id":"en-Play_Vo_Char_NPC021_windfall_002","title":"Неожиданная добыча II","description":"Приятный сюрприз.","language":"Английский","audioUrl":"/nte-meta/game-audio/d3fec5a35837858e177e.ogg"},{"id":"ko-Play_Vo_Char_NPC021_meet_001","title":"Первая встреча","description":"Хрусталь направляет меня, птица взывает ко мне. Я здесь, и наши судьбы сплелись в единый клубок…","language":"Корейский","audioUrl":"/nte-meta/game-audio/4bf49beba3fb64703255.ogg"},{"id":"en-Play_Vo_Char_NPC021_weather_003","title":"Холодно","description":"Холод — злейший враг птиц.","language":"Английский","audioUrl":"/nte-meta/game-audio/4f57e414b4d7ee83cff5.ogg"},{"id":"ja-Play_Vo_Char_NPC021_Fly_001","title":"Планирование I","description":"Всё как обычно.","language":"Японский","audioUrl":"/nte-meta/game-audio/fd2cee52dd8072e7481a.ogg"},{"id":"ja-Play_Vo_Char_NPC021_kill_001","title":"Убийство I","description":"Приговор судьбы.","language":"Японский","audioUrl":"/nte-meta/game-audio/a3e2dec97ee912eec0c1.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill01_SE_002","title":"Навык перенаправления V","description":"Молитесь мне…","language":"Японский","audioUrl":"/nte-meta/game-audio/f5e279c8f149ed4f4a7b.ogg"},{"id":"ja-Play_Vo_Char_NPC021_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Отдохни. Я тебя подменю.","language":"Японский","audioUrl":"/nte-meta/game-audio/89bca7deeb6495c4fa99.ogg"},{"id":"zh-Play_Vo_Char_NPC021_containment_002","title":"Сдерживание II","description":"Спи. Больше ни о чём не тревожься…","language":"Китайский","audioUrl":"/nte-meta/game-audio/2d87a19d011eabfd584b.ogg"},{"id":"zh-Play_Vo_Char_NPC021_struck_001","title":"Урон I","description":"Сосредоточься… Со мной всё в порядке.","language":"Китайский","audioUrl":"/nte-meta/game-audio/cd91546d3e3b2eb66538.ogg"},{"id":"en-Play_Vo_Char_NPC021_anomaly_004","title":"Нуллификация II","description":"У всего есть своя судьба.","language":"Английский","audioUrl":"/nte-meta/game-audio/0eff9e8960d06a8453bb.ogg"},{"id":"en-Play_Vo_Char_NPC021_Parry_001","title":"Парирование I","description":"Как раз вовремя.","language":"Английский","audioUrl":"/nte-meta/game-audio/11266326fcbf5b8ceaca.ogg"},{"id":"en-Play_Vo_Char_NPC021_QTE_002","title":"Атака на входе II","description":"Покайтесь.","language":"Английский","audioUrl":"/nte-meta/game-audio/1425ccada871e05bfd97.ogg"},{"id":"ko-Play_Vo_Char_NPC021_about_001","title":"О Лавинии","description":"Лавиния — специалистка, которую Двор Иггаша направил в «Дом ведьмы». Она моя надсмотрщица, но в то же время и подруга. Не позволяй её серьёзному лицу обмануть тебя, она готовит лучше всех, кого я знаю. Любое её блюдо получается безумно вкусным. Хм, может, она накладывает какое-то заклинание, чтобы еда была вкуснее, кто знает…","language":"Корейский","audioUrl":"/nte-meta/game-audio/576e24fda24c449e5064.ogg"},{"id":"ko-Play_Vo_Char_NPC021_deploy_002","title":"Отправка II","description":"Я тебя ждала.","language":"Корейский","audioUrl":"/nte-meta/game-audio/8819a88bbd774bd95ec9.ogg"},{"id":"zh-Play_Vo_Char_NPC021_windfall_001","title":"Неожиданная добыча I","description":"Добрый знак.","language":"Китайский","audioUrl":"/nte-meta/game-audio/1ce08c2a40ec65d1ad9a.ogg"},{"id":"ja-Play_Vo_Char_NPC021_DodgeCombo_002","title":"Серия критических уклонений II","description":"Фортуна меня хранит.","language":"Японский","audioUrl":"/nte-meta/game-audio/e84c3ab426ecc51aeb34.ogg"},{"id":"ja-Play_Vo_Char_NPC021_windfall_001","title":"Неожиданная добыча I","description":"Добрый знак.","language":"Японский","audioUrl":"/nte-meta/game-audio/0af47240978ed01b545d.ogg"},{"id":"ko-Play_Vo_Char_NPC021_about_004","title":"О Меруле","description":"Чем ближе я становлюсь к ней, тем сильнее ощущаю неведомый мне прежде покой, словно… я вернулась в объятия матери. Я не была хорошим ребёнком. Я скиталась веками, не зная её. Но ещё не поздно. Её кровь всё ещё горяча, её глаза видят этот новый мир через мои, и каждое мгновение, что потеряла Мерула, я верну ей.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ac99b67323853f15579b.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill01_SE_002","title":"Навык перенаправления V","description":"Молитесь мне…","language":"Английский","audioUrl":"/nte-meta/game-audio/48dbf706ebc7b2c1eb20.ogg"},{"id":"en-Play_Vo_Char_NPC021_windfall_005","title":"Неожиданная добыча V","description":"Хорошая вещица. Тебе нравится?","language":"Английский","audioUrl":"/nte-meta/game-audio/4afef0791e6cd2f41794.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill02_SE_001","title":"Навык перенаправления X","description":"Час суда настал.","language":"Японский","audioUrl":"/nte-meta/game-audio/ff972a387b801692cc45.ogg"},{"id":"zh-Play_Vo_Char_NPC021_dead_003","title":"Потеря сознания III","description":"Пламя… пожирает меня…","language":"Китайский","audioUrl":"/nte-meta/game-audio/7a8601e2cd8629d4c571.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill02_SE_001","title":"Навык перенаправления X","description":"Час суда настал.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3b0b133cec5edad8985f.ogg"},{"id":"en-Play_Vo_Char_NPC021_windfall_004","title":"Неожиданная добыча IV","description":"Вот, пожалуйста. Это твоё.","language":"Английский","audioUrl":"/nte-meta/game-audio/c524c052d155e5eeac1c.ogg"},{"id":"ja-Play_Vo_Char_NPC021_deploy_002","title":"Отправка II","description":"Я тебя ждала.","language":"Японский","audioUrl":"/nte-meta/game-audio/c63a191e789c49dca8bb.ogg"},{"id":"ko-Play_Vo_Char_NPC021_self_003","title":"Обо мне: шляпа","description":"Я передала этой шляпе часть своих сил. Даже когда меня нет рядом, я могу чувствовать, что происходит возле неё. И когда мне не хочется никого видеть, я использую её как рупор, а сама уютно устраиваюсь на чердаке… Я-я вовсе не бездельничаю, конечно! Я всё ещё гадаю для своих клиентов, честно…","language":"Корейский","audioUrl":"/nte-meta/game-audio/68fed56ec5b68e75b4e8.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill02_001","title":"Навык перенаправления VII","description":"Дрожите?","language":"Корейский","audioUrl":"/nte-meta/game-audio/696a06027cd97a2d2f8b.ogg"},{"id":"ko-Play_Vo_Char_NPC021_Switch_001","title":"Переключение I","description":"Что-то случилось?","language":"Корейский","audioUrl":"/nte-meta/game-audio/13ce8c5c76885ab7fda1.ogg"},{"id":"zh-Play_Vo_Char_NPC021_ug_002","title":"Вознесение персонажа II","description":"Я сыграю фугу судьбы.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e1cc03f04bddfb5a2254.ogg"},{"id":"en-Play_Vo_Char_NPC021_containment_002","title":"Сдерживание II","description":"Спи. Больше ни о чём не тревожься…","language":"Английский","audioUrl":"/nte-meta/game-audio/8230e2ea36eaa511c8e4.ogg"},{"id":"ja-Play_Vo_Char_NPC021_talk_001","title":"Тема: аномалия","description":"Прорицатель не может видеть собственную судьбу: ни будущего, ни прошлого. Но почему-то я не вижу и твоего прошлого тоже. Оно словно скрыто по ту сторону звёзд, и я не могу разглядеть даже его очертания… Неужели хрустальный шар обманывает меня? Какая судьба тебя ждёт? Мне так любопытно… Хотя нет, неважно…","language":"Японский","audioUrl":"/nte-meta/game-audio/de03f8c9a35cfa28ac04.ogg"},{"id":"ko-Play_Vo_Char_NPC021_chat_003","title":"Чат: вне дома","description":"В «Доме ведьмы» так тихо и спокойно, и у меня есть всё необходимое: закуски, комиксы и мой хрустальный шар… Зачем мне вообще выходить наружу? О, ты пойдёшь со мной? Эх… сорвался мой план посидеть дома…","language":"Корейский","audioUrl":"/nte-meta/game-audio/a9d6613702335dae447d.ogg"},{"id":"ko-Play_Vo_Char_NPC021_self_001","title":"Обо мне: способности аномалии","description":"Мои силы позволяют мне читать судьбы и очищать Камни оракула. Я не знаю, почему мне были дарованы такие могущественные способности… Вернее, я даже не знаю, почему вообще существую в этом мире. Я прочла судьбы бесчисленного множества людей, но моя собственная скрыта за туманом, клубящимся внутри хрустального шара. Эсперы всегда платят свою цену за дар, и, возможно, мои силы как аномалии просто ограничены в этом плане… Какой бы ни оказалась правда о моей судьбе, я с радостью приму её.","language":"Корейский","audioUrl":"/nte-meta/game-audio/3648fb2c0731a479423d.ogg"},{"id":"zh-Play_Vo_Char_NPC021_ultraskill_UI_001","title":"Сверхспособность I","description":"Все судьбы — в забвение.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e1a52e3f41d4fb88135f.ogg"},{"id":"zh-Play_Vo_Char_NPC021_windfall_004","title":"Неожиданная добыча IV","description":"Вот, пожалуйста. Это твоё.","language":"Китайский","audioUrl":"/nte-meta/game-audio/cc661bd180a4f649bb2a.ogg"},{"id":"en-Play_Vo_Char_NPC021_gift_003","title":"Подарок получен III","description":"Это… мне? Спасибо, мне очень приятно.","language":"Английский","audioUrl":"/nte-meta/game-audio/fc79c7b41940f3a02935.ogg"},{"id":"en-Play_Vo_Char_NPC021_self_001","title":"Обо мне: способности аномалии","description":"Мои силы позволяют мне читать судьбы и очищать Камни оракула. Я не знаю, почему мне были дарованы такие могущественные способности… Вернее, я даже не знаю, почему вообще существую в этом мире. Я прочла судьбы бесчисленного множества людей, но моя собственная скрыта за туманом, клубящимся внутри хрустального шара. Эсперы всегда платят свою цену за дар, и, возможно, мои силы как аномалии просто ограничены в этом плане… Какой бы ни оказалась правда о моей судьбе, я с радостью приму её.","language":"Английский","audioUrl":"/nte-meta/game-audio/1eae197a4888add23389.ogg"},{"id":"en-Play_Vo_Char_NPC021_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Отдохни. Я тебя подменю.","language":"Английский","audioUrl":"/nte-meta/game-audio/d23612f7c59d94f06310.ogg"},{"id":"ja-Play_Vo_Char_NPC021_DodgeCombo_001","title":"Серия критических уклонений I","description":"Как и ожидалось.","language":"Японский","audioUrl":"/nte-meta/game-audio/00e45e3fb721be4f372e.ogg"},{"id":"ja-Play_Vo_Char_NPC021_hp_002","title":"Низкий уровень здоровья II","description":"В глазах… всё плывёт…","language":"Японский","audioUrl":"/nte-meta/game-audio/a7fec4ccc2528ba6c6f9.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill01_002","title":"Навык перенаправления II","description":"Тишина.","language":"Корейский","audioUrl":"/nte-meta/game-audio/9f037e5028b74f21748b.ogg"},{"id":"ko-Play_Vo_Char_NPC021_Switch_003","title":"Переключение III","description":"Прислушиваясь к зову судьбы.","language":"Корейский","audioUrl":"/nte-meta/game-audio/185e4ca84f5b40229b29.ogg"},{"id":"zh-Play_Vo_Char_NPC021_self_001","title":"Обо мне: способности аномалии","description":"Мои силы позволяют мне читать судьбы и очищать Камни оракула. Я не знаю, почему мне были дарованы такие могущественные способности… Вернее, я даже не знаю, почему вообще существую в этом мире. Я прочла судьбы бесчисленного множества людей, но моя собственная скрыта за туманом, клубящимся внутри хрустального шара. Эсперы всегда платят свою цену за дар, и, возможно, мои силы как аномалии просто ограничены в этом плане… Какой бы ни оказалась правда о моей судьбе, я с радостью приму её.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f09bec1123497fa32510.ogg"},{"id":"en-Play_Vo_Char_NPC021_talk_001","title":"Тема: аномалия","description":"Прорицатель не может видеть собственную судьбу: ни будущего, ни прошлого. Но почему-то я не вижу и твоего прошлого тоже. Оно словно скрыто по ту сторону звёзд, и я не могу разглядеть даже его очертания… Неужели хрустальный шар обманывает меня? Какая судьба тебя ждёт? Мне так любопытно… Хотя нет, неважно…","language":"Английский","audioUrl":"/nte-meta/game-audio/1ecd72f64d9df1f8a96c.ogg"},{"id":"en-Play_Vo_Char_NPC021_talk_002","title":"Тема: «Ведьма»","description":"Если честно, никакая я не ведьма. Кроме своих аномальных способностей, я не знаю никаких заклинаний. У меня никогда не было чёрной кошки, и я даже не человек в полном смысле этого слова… Но я уже давно смирилась с тем, что все называют меня «ведьмой». Так мне не приходится многого объяснять. Конечно, любой бы подумал, что в «Доме ведьмы» живёт ведьма, разве нет?","language":"Английский","audioUrl":"/nte-meta/game-audio/40bcef1de60874cf3780.ogg"},{"id":"ja-Play_Vo_Char_NPC021_greet_004","title":"Спокойной ночи","description":"Глубокая ночь — идеальное время для фильма ужасов…","language":"Японский","audioUrl":"/nte-meta/game-audio/47624556b8b612904fa9.ogg"},{"id":"ja-Play_Vo_Char_NPC021_hstruck_001","title":"Сильный урон I","description":"Больно…","language":"Японский","audioUrl":"/nte-meta/game-audio/e46dee59438c1641f7e8.ogg"},{"id":"ja-Play_Vo_Char_NPC021_QTE_003","title":"Атака на входе III","description":"Непростительно.","language":"Японский","audioUrl":"/nte-meta/game-audio/ca6696e782a70cce37f3.ogg"},{"id":"ja-Play_Vo_Char_NPC021_ug_002","title":"Вознесение персонажа II","description":"Я сыграю фугу судьбы.","language":"Японский","audioUrl":"/nte-meta/game-audio/a436cb9ae111e4fac095.ogg"},{"id":"ja-Play_Vo_Char_NPC021_windfall_003","title":"Неожиданная добыча III","description":"Знак удачи.","language":"Японский","audioUrl":"/nte-meta/game-audio/54465a60fe4eea56dfd1.ogg"},{"id":"ko-Play_Vo_Char_NPC021_weather_004","title":"Жарко","description":"Уф… Терпеть не могу такую погоду. Пойдём домой.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f9184f1e405c34c02fea.ogg"},{"id":"ko-Play_Vo_Char_NPC021_windfall_004","title":"Неожиданная добыча IV","description":"Вот, пожалуйста. Это твоё.","language":"Корейский","audioUrl":"/nte-meta/game-audio/0c2dda18fcef1191d3fc.ogg"},{"id":"en-Play_Vo_Char_NPC021_windfall_006","title":"Неожиданная добыча VI","description":"Подарок судьбы.","language":"Английский","audioUrl":"/nte-meta/game-audio/49b2a2ae073e1769e95d.ogg"},{"id":"ko-Play_Vo_Char_NPC021_weather_003","title":"Холодно","description":"Холод — злейший враг птиц.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6e7c1694ea3080d21530.ogg"},{"id":"en-Play_Vo_Char_NPC021_ug_002","title":"Вознесение персонажа II","description":"Я сыграю фугу судьбы.","language":"Английский","audioUrl":"/nte-meta/game-audio/44f5b605c6aaf2c5f716.ogg"},{"id":"ja-Play_Vo_Char_NPC021_gift_001","title":"Подарок получен I","description":"Ценен не только сам подарок… но и чувства, которые за ним стоят.","language":"Японский","audioUrl":"/nte-meta/game-audio/47ddd4b7e83a93818317.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill01_001","title":"Навык перенаправления I","description":"Бесполезно.","language":"Японский","audioUrl":"/nte-meta/game-audio/b71640adc4435580108f.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill02_001","title":"Навык перенаправления VII","description":"Дрожите?","language":"Японский","audioUrl":"/nte-meta/game-audio/f5efe517425ab1f423e4.ogg"},{"id":"ko-Play_Vo_Char_NPC021_QTE_SE_002","title":"Атака на входе V","description":"Да будут прощены грехи ваши…","language":"Корейский","audioUrl":"/nte-meta/game-audio/c824ce66f90fdda53cf6.ogg"},{"id":"zh-Play_Vo_Char_NPC021_chat_003","title":"Чат: вне дома","description":"В «Доме ведьмы» так тихо и спокойно, и у меня есть всё необходимое: закуски, комиксы и мой хрустальный шар… Зачем мне вообще выходить наружу? О, ты пойдёшь со мной? Эх… сорвался мой план посидеть дома…","language":"Китайский","audioUrl":"/nte-meta/game-audio/5ff887bb25df0d2f4e2d.ogg"},{"id":"zh-Play_Vo_Char_NPC021_gift_004","title":"Подарок получен IV","description":"Мне очень нравится. Такой продуманный подарок.","language":"Китайский","audioUrl":"/nte-meta/game-audio/fadf9294adfd3368564b.ogg"},{"id":"zh-Play_Vo_Char_NPC021_QTE_SE_001","title":"Атака на входе IV","description":"Да утихнет ваша обида…","language":"Китайский","audioUrl":"/nte-meta/game-audio/2184996f7f1da3f8a1dd.ogg"},{"id":"en-Play_Vo_Char_NPC021_deploy_001","title":"Отправка I","description":"Если ты этого хочешь…","language":"Английский","audioUrl":"/nte-meta/game-audio/42e20a5d886321d39cb2.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill01_003","title":"Навык перенаправления III","description":"Вспышка тени.","language":"Английский","audioUrl":"/nte-meta/game-audio/b9148d8becfc2d0980f8.ogg"},{"id":"ja-Play_Vo_Char_NPC021_containment_001","title":"Сдерживание I","description":"Отправляйся туда, где тебе место.","language":"Японский","audioUrl":"/nte-meta/game-audio/014d898320e244d349b8.ogg"},{"id":"ja-Play_Vo_Char_NPC021_greet_003","title":"Вечернее приветствие","description":"Давай вместе найдём наши две звезды на ночном небе.","language":"Японский","audioUrl":"/nte-meta/game-audio/86e772e3dcbbe0ab9d64.ogg"},{"id":"ko-Play_Vo_Char_NPC021_kill_002","title":"Убийство II","description":"Что посеешь, то и пожнёшь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f069b4de2b2013a9092c.ogg"},{"id":"ko-Play_Vo_Char_NPC021_struck_002","title":"Урон II","description":"Всего лишь царапина.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1dc011563be466ffe148.ogg"},{"id":"ko-Play_Vo_Char_NPC021_weather_002","title":"Дождливо","description":"Пусть дождь смоет всю боль этого мира.","language":"Корейский","audioUrl":"/nte-meta/game-audio/40d2c7ac8926ac0a9565.ogg"},{"id":"zh-Play_Vo_Char_NPC021_deploy_002","title":"Отправка II","description":"Я тебя ждала.","language":"Китайский","audioUrl":"/nte-meta/game-audio/bdd272d137ebec754414.ogg"},{"id":"zh-Play_Vo_Char_NPC021_DodgeCombo_002","title":"Серия критических уклонений II","description":"Фортуна меня хранит.","language":"Китайский","audioUrl":"/nte-meta/game-audio/cf24de8b58185199b09f.ogg"},{"id":"zh-Play_Vo_Char_NPC021_fh_002","title":"Исцеление II","description":"Так гораздо лучше.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b443a964cb8bb53a987d.ogg"},{"id":"zh-Play_Vo_Char_NPC021_ug_001","title":"Вознесение персонажа I","description":"Я разгадала скрытые послания пророчества.","language":"Китайский","audioUrl":"/nte-meta/game-audio/dc47ec9d667c7a9b2066.ogg"},{"id":"en-Play_Vo_Char_NPC021_greet_002","title":"Дневное приветствие","description":"Лавиния приготовила на обед равиоли. Тебе тоже оставила порцию.","language":"Английский","audioUrl":"/nte-meta/game-audio/6181611ae9779de4e34f.ogg"},{"id":"en-Play_Vo_Char_NPC021_ultraskill_UI_001","title":"Сверхспособность I","description":"Все судьбы — в забвение.","language":"Английский","audioUrl":"/nte-meta/game-audio/178772374c7bebc0b731.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill02_003","title":"Навык перенаправления IX","description":"Чахните и увядайте.","language":"Корейский","audioUrl":"/nte-meta/game-audio/17f525d128d424f2b948.ogg"},{"id":"zh-Play_Vo_Char_NPC021_dead_001","title":"Потеря сознания I","description":"Это… моя судьба…","language":"Китайский","audioUrl":"/nte-meta/game-audio/8ccc5542e08a6e2ca92f.ogg"},{"id":"en-Play_Vo_Char_NPC021_about_001","title":"О Лавинии","description":"Лавиния — специалистка, которую Двор Иггаша направил в «Дом ведьмы». Она моя надсмотрщица, но в то же время и подруга. Не позволяй её серьёзному лицу обмануть тебя, она готовит лучше всех, кого я знаю. Любое её блюдо получается безумно вкусным. Хм, может, она накладывает какое-то заклинание, чтобы еда была вкуснее, кто знает…","language":"Английский","audioUrl":"/nte-meta/game-audio/7fac0ead6e5e36bc580a.ogg"},{"id":"en-Play_Vo_Char_NPC021_greet_003","title":"Вечернее приветствие","description":"Давай вместе найдём наши две звезды на ночном небе.","language":"Английский","audioUrl":"/nte-meta/game-audio/8afbb81bb557c207951d.ogg"},{"id":"en-Play_Vo_Char_NPC021_QTE_003","title":"Атака на входе III","description":"Непростительно.","language":"Английский","audioUrl":"/nte-meta/game-audio/3644446ae275aacca7ae.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill01_001","title":"Навык перенаправления I","description":"Бесполезно.","language":"Английский","audioUrl":"/nte-meta/game-audio/e247c3f1678bc73d12ba.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill02_SE_003","title":"Навык перенаправления XII","description":"Возрождённая в огне…","language":"Английский","audioUrl":"/nte-meta/game-audio/06d25ddf14858bcc32f0.ogg"},{"id":"ja-Play_Vo_Char_NPC021_about_003","title":"О Линко","description":"Линки — отличная напарница для просмотра фильмов. В свои выходные она иногда приходит с целой кучей DVD, чтобы всю ночь напролёт смотреть со мной фильмы ужасов. Каждый раз, когда она и Сяочжэнь приходят, «Дом ведьмы» прямо оживает. Не ведись на её миниатюрный вид: я до сих пор понятия не имею, какие безумные мысли роятся в этой маленькой розовой головке. (*Хихикает*) Эту девчушку ждёт будущее, полное приключений и чудес.","language":"Японский","audioUrl":"/nte-meta/game-audio/38b28e40936bdf25d0ee.ogg"},{"id":"ja-Play_Vo_Char_NPC021_ultraskill_UI_001","title":"Сверхспособность I","description":"Все судьбы — в забвение.","language":"Японский","audioUrl":"/nte-meta/game-audio/02908dbf0f86b995dc0c.ogg"},{"id":"ko-Play_Vo_Char_NPC021_about_005","title":"О «Дворе Иггаш»","description":"Когда я скиталась по свету и мои крылья начали тяжелеть, Двор Иггаша нашёл меня и заключил со мной контракт. С тех пор у меня появилось место, которое я могу назвать «домом», но пока вся «работа» не будет выполнена, я не могу скрыться от их взора… Дары судьбы и её цена всегда равны. И это справедливо.","language":"Корейский","audioUrl":"/nte-meta/game-audio/81ba881157499b2802f9.ogg"},{"id":"ko-Play_Vo_Char_NPC021_anomaly_004","title":"Нуллификация II","description":"У всего есть своя судьба.","language":"Корейский","audioUrl":"/nte-meta/game-audio/37f8e083149b0dc4d190.ogg"},{"id":"ko-Play_Vo_Char_NPC021_gift_004","title":"Подарок получен IV","description":"Мне очень нравится. Такой продуманный подарок.","language":"Корейский","audioUrl":"/nte-meta/game-audio/2f86fba7071676e29d9d.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill01_SE_003","title":"Навык перенаправления VI","description":"Какая жалость…","language":"Английский","audioUrl":"/nte-meta/game-audio/a8f67e5390ad891fdb2b.ogg"},{"id":"en-Play_Vo_Char_NPC021_talk_003","title":"Тема: звёздное небо","description":"Когда мир ещё не обрёл форму, звёзды уже записали судьбу всего сущего. Над завесой ночи каждая нить звёздного света — видимая и незримая, — каждое мерцание, каждая пылинка шепчут о сокрытом. Именно в них таятся разгадки судеб всего живого.","language":"Английский","audioUrl":"/nte-meta/game-audio/a4a7949c94089a665d77.ogg"},{"id":"ja-Play_Vo_Char_NPC021_about_002","title":"О Хотори","description":"Несколько раз, когда я была на мели, я наугад брала кое-какие вещи из своей коллекции и пыталась продать их владелице того антикварного магазина. Думала, она будет хитрой деловой женщиной, но она оказалась на удивление сговорчивой и щедрой. Каждый раз предлагала такую цену, что даже я удивлялась… Не слишком ли легко её обвести вокруг пальца?","language":"Японский","audioUrl":"/nte-meta/game-audio/08fa8741f7a5c4d6ef1c.ogg"},{"id":"ko-Play_Vo_Char_NPC021_DodgeCombo_002","title":"Серия критических уклонений II","description":"Фортуна меня хранит.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d36b75441b48c0a76db1.ogg"},{"id":"zh-Play_Vo_Char_NPC021_about_003","title":"О Линко","description":"Линки — отличная напарница для просмотра фильмов. В свои выходные она иногда приходит с целой кучей DVD, чтобы всю ночь напролёт смотреть со мной фильмы ужасов. Каждый раз, когда она и Сяочжэнь приходят, «Дом ведьмы» прямо оживает. Не ведись на её миниатюрный вид: я до сих пор понятия не имею, какие безумные мысли роятся в этой маленькой розовой головке. (*Хихикает*) Эту девчушку ждёт будущее, полное приключений и чудес.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5c1505fd907a654a8315.ogg"},{"id":"en-Play_Vo_Char_NPC021_weather_001","title":"Солнечно","description":"Солнце сияет ярко — прямо как твоё будущее.","language":"Английский","audioUrl":"/nte-meta/game-audio/e16c405e92dea99f9128.ogg"},{"id":"ko-Play_Vo_Char_NPC021_about_002","title":"О Хотори","description":"Несколько раз, когда я была на мели, я наугад брала кое-какие вещи из своей коллекции и пыталась продать их владелице того антикварного магазина. Думала, она будет хитрой деловой женщиной, но она оказалась на удивление сговорчивой и щедрой. Каждый раз предлагала такую цену, что даже я удивлялась… Не слишком ли легко её обвести вокруг пальца?","language":"Корейский","audioUrl":"/nte-meta/game-audio/ab167c81a229dfa6a4b0.ogg"},{"id":"ko-Play_Vo_Char_NPC021_hp_001","title":"Низкий уровень здоровья I","description":"Это дурной знак…","language":"Корейский","audioUrl":"/nte-meta/game-audio/3bc728d38585326c8fb5.ogg"},{"id":"ko-Play_Vo_Char_NPC021_talk_002","title":"Тема: «Ведьма»","description":"Если честно, никакая я не ведьма. Кроме своих аномальных способностей, я не знаю никаких заклинаний. У меня никогда не было чёрной кошки, и я даже не человек в полном смысле этого слова… Но я уже давно смирилась с тем, что все называют меня «ведьмой». Так мне не приходится многого объяснять. Конечно, любой бы подумал, что в «Доме ведьмы» живёт ведьма, разве нет?","language":"Корейский","audioUrl":"/nte-meta/game-audio/3f8c0796c56b4b376a11.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill01_SE_001","title":"Навык перенаправления IV","description":"Не нужно бояться…","language":"Китайский","audioUrl":"/nte-meta/game-audio/cfa2a9a32adc5072343a.ogg"},{"id":"ja-Play_Vo_Char_NPC021_weather_004","title":"Жарко","description":"Уф… Терпеть не могу такую погоду. Пойдём домой.","language":"Японский","audioUrl":"/nte-meta/game-audio/bb0e526ba74f903a275e.ogg"},{"id":"ko-Play_Vo_Char_NPC021_Fly_002","title":"Планирование II","description":"Знакомый ветерок…","language":"Корейский","audioUrl":"/nte-meta/game-audio/55a5d77396b1e5291c21.ogg"},{"id":"en-Play_Vo_Char_NPC021_struck_001","title":"Урон I","description":"Сосредоточься… Со мной всё в порядке.","language":"Английский","audioUrl":"/nte-meta/game-audio/cda8e2f2558d26b80e5e.ogg"},{"id":"ja-Play_Vo_Char_NPC021_chat_003","title":"Чат: вне дома","description":"В «Доме ведьмы» так тихо и спокойно, и у меня есть всё необходимое: закуски, комиксы и мой хрустальный шар… Зачем мне вообще выходить наружу? О, ты пойдёшь со мной? Эх… сорвался мой план посидеть дома…","language":"Японский","audioUrl":"/nte-meta/game-audio/917fe5bba57f91fce431.ogg"},{"id":"ja-Play_Vo_Char_NPC021_ultraskill_SE_UI_001","title":"Сверхспособность IV","description":"Пламя смерти вершит над вами суд!","language":"Японский","audioUrl":"/nte-meta/game-audio/3be3a57b73af4cff0113.ogg"},{"id":"ko-Play_Vo_Char_NPC021_DodgeCombo_001","title":"Серия критических уклонений I","description":"Как и ожидалось.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ba834e96470871fc7a72.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill01_001","title":"Навык перенаправления I","description":"Бесполезно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/20af1424907f67b8a8c5.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill01_SE_002","title":"Навык перенаправления V","description":"Молитесь мне…","language":"Корейский","audioUrl":"/nte-meta/game-audio/9eb8e7635040025bf9e6.ogg"},{"id":"zh-Play_Vo_Char_NPC021_hstruck_001","title":"Сильный урон I","description":"Больно…","language":"Китайский","audioUrl":"/nte-meta/game-audio/54ba9431c697641c3ce7.ogg"},{"id":"ja-Play_Vo_Char_NPC021_dead_003","title":"Потеря сознания III","description":"Пламя… пожирает меня…","language":"Японский","audioUrl":"/nte-meta/game-audio/f5b1fb76a7441681c2f8.ogg"},{"id":"ja-Play_Vo_Char_NPC021_Switch_003","title":"Переключение III","description":"Прислушиваясь к зову судьбы.","language":"Японский","audioUrl":"/nte-meta/game-audio/36787436ac8a4b2c1707.ogg"},{"id":"ja-Play_Vo_Char_NPC021_ug_001","title":"Вознесение персонажа I","description":"Я разгадала скрытые послания пророчества.","language":"Японский","audioUrl":"/nte-meta/game-audio/541171160d8c8521d995.ogg"},{"id":"ko-Play_Vo_Char_NPC021_deploy_001","title":"Отправка I","description":"Если ты этого хочешь…","language":"Корейский","audioUrl":"/nte-meta/game-audio/a041ce949ae35ef5940e.ogg"},{"id":"zh-Play_Vo_Char_NPC021_Fly_001","title":"Планирование I","description":"Всё как обычно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/1bdc90d44b7ec219993f.ogg"},{"id":"en-Play_Vo_Char_NPC021_weather_002","title":"Дождливо","description":"Пусть дождь смоет всю боль этого мира.","language":"Английский","audioUrl":"/nte-meta/game-audio/bb7ffdd2b66f6c28077f.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill01_SE_001","title":"Навык перенаправления IV","description":"Не нужно бояться…","language":"Японский","audioUrl":"/nte-meta/game-audio/f91ef214f68488c5d24a.ogg"},{"id":"ko-Play_Vo_Char_NPC021_QTE_SE_003","title":"Атака на входе VI","description":"Да очистятся души ваши…","language":"Корейский","audioUrl":"/nte-meta/game-audio/7c85b1c2598cbd6f3e79.ogg"},{"id":"zh-Play_Vo_Char_NPC021_hstruck_002","title":"Сильный урон II","description":"Где мои обезболивающие…","language":"Китайский","audioUrl":"/nte-meta/game-audio/a9b417d0e3f9198f2340.ogg"},{"id":"zh-Play_Vo_Char_NPC021_windfall_005","title":"Неожиданная добыча V","description":"Хорошая вещица. Тебе нравится?","language":"Китайский","audioUrl":"/nte-meta/game-audio/f49abc9a8ea75af9d412.ogg"},{"id":"en-Play_Vo_Char_NPC021_deploy_002","title":"Отправка II","description":"Я тебя ждала.","language":"Английский","audioUrl":"/nte-meta/game-audio/64dae9c24483ee89114d.ogg"},{"id":"en-Play_Vo_Char_NPC021_QTE_SE_002","title":"Атака на входе V","description":"Да будут прощены грехи ваши…","language":"Английский","audioUrl":"/nte-meta/game-audio/c58258b7503076619ab0.ogg"},{"id":"en-Play_Vo_Char_NPC021_ultraskill_SE_UI_003","title":"Сверхспособность VI","description":"Погибель ваша близка…","language":"Английский","audioUrl":"/nte-meta/game-audio/33b56d2b3161f2e7a3a2.ogg"},{"id":"ja-Play_Vo_Char_NPC021_about_001","title":"О Лавинии","description":"Лавиния — специалистка, которую Двор Иггаша направил в «Дом ведьмы». Она моя надсмотрщица, но в то же время и подруга. Не позволяй её серьёзному лицу обмануть тебя, она готовит лучше всех, кого я знаю. Любое её блюдо получается безумно вкусным. Хм, может, она накладывает какое-то заклинание, чтобы еда была вкуснее, кто знает…","language":"Японский","audioUrl":"/nte-meta/game-audio/928e60942f03b9c4dfa1.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill02_002","title":"Навык перенаправления VIII","description":"Падите в безмолвии.","language":"Корейский","audioUrl":"/nte-meta/game-audio/8877b4d3f6dbba50c21c.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill01_SE_002","title":"Навык перенаправления V","description":"Молитесь мне…","language":"Китайский","audioUrl":"/nte-meta/game-audio/53759e5f489811091745.ogg"},{"id":"zh-Play_Vo_Char_NPC021_Switch_003","title":"Переключение III","description":"Прислушиваясь к зову судьбы.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d6ae50d8b6faea3de802.ogg"},{"id":"ja-Play_Vo_Char_NPC021_hp_001","title":"Низкий уровень здоровья I","description":"Это дурной знак…","language":"Японский","audioUrl":"/nte-meta/game-audio/1c0e2b2cbc7fcc730117.ogg"},{"id":"ja-Play_Vo_Char_NPC021_Parry_002","title":"Парирование II","description":"Я это предвидела.","language":"Японский","audioUrl":"/nte-meta/game-audio/ce51498f912e688686f8.ogg"},{"id":"ko-Play_Vo_Char_NPC021_weather_001","title":"Солнечно","description":"Солнце сияет ярко — прямо как твоё будущее.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a31416002f6323fe0d97.ogg"},{"id":"ko-Play_Vo_Char_NPC021_windfall_005","title":"Неожиданная добыча V","description":"Хорошая вещица. Тебе нравится?","language":"Корейский","audioUrl":"/nte-meta/game-audio/ed0b084c6a75af3b0736.ogg"},{"id":"zh-Play_Vo_Char_NPC021_greet_002","title":"Дневное приветствие","description":"Лавиния приготовила на обед равиоли. Тебе тоже оставила порцию.","language":"Китайский","audioUrl":"/nte-meta/game-audio/96ce6583b1420399f098.ogg"},{"id":"en-Play_Vo_Char_NPC021_DodgeCombo_002","title":"Серия критических уклонений II","description":"Фортуна меня хранит.","language":"Английский","audioUrl":"/nte-meta/game-audio/e061911b6f27b0df779f.ogg"},{"id":"en-Play_Vo_Char_NPC021_Fly_002","title":"Планирование II","description":"Знакомый ветерок…","language":"Английский","audioUrl":"/nte-meta/game-audio/856aff99067eb3440f0e.ogg"},{"id":"en-Play_Vo_Char_NPC021_QTE_SE_001","title":"Атака на входе IV","description":"Да утихнет ваша обида…","language":"Английский","audioUrl":"/nte-meta/game-audio/9139e4734786146c1369.ogg"},{"id":"en-Play_Vo_Char_NPC021_windfall_001","title":"Неожиданная добыча I","description":"Добрый знак.","language":"Английский","audioUrl":"/nte-meta/game-audio/0681cbc06557fdd2a1ea.ogg"},{"id":"ja-Play_Vo_Char_NPC021_gift_002","title":"Подарок получен II","description":"Мне нравится… Спасибо, я буду всегда им дорожить…","language":"Японский","audioUrl":"/nte-meta/game-audio/7e5fc654e2c7e9438d87.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill01_003","title":"Навык перенаправления III","description":"Вспышка тени.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e21611f58de61c02a9e9.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill01_SE_003","title":"Навык перенаправления VI","description":"Какая жалость…","language":"Корейский","audioUrl":"/nte-meta/game-audio/a77f953c8e82c105139c.ogg"},{"id":"zh-Play_Vo_Char_NPC021_talk_002","title":"Тема: «Ведьма»","description":"Если честно, никакая я не ведьма. Кроме своих аномальных способностей, я не знаю никаких заклинаний. У меня никогда не было чёрной кошки, и я даже не человек в полном смысле этого слова… Но я уже давно смирилась с тем, что все называют меня «ведьмой». Так мне не приходится многого объяснять. Конечно, любой бы подумал, что в «Доме ведьмы» живёт ведьма, разве нет?","language":"Китайский","audioUrl":"/nte-meta/game-audio/b8e1f2c1f174f33dfceb.ogg"},{"id":"en-Play_Vo_Char_NPC021_chat_002","title":"Чат: коллекция","description":"Я обожаю собирать всякий антиквариат. И чем причудливее его дизайн, тем больше он мне нравится… Моя коллекция? У меня куда больше вещей, чем кажется на первый взгляд. Я даже выделила для них целую комнату. Если интересно — заглядывай как-нибудь, посмотришь.","language":"Английский","audioUrl":"/nte-meta/game-audio/3191a987709bce6b9448.ogg"},{"id":"en-Play_Vo_Char_NPC021_hstruck_001","title":"Сильный урон I","description":"Больно…","language":"Английский","audioUrl":"/nte-meta/game-audio/e2e698bdd59ce88eb911.ogg"},{"id":"en-Play_Vo_Char_NPC021_QTE_SE_003","title":"Атака на входе VI","description":"Да очистятся души ваши…","language":"Английский","audioUrl":"/nte-meta/game-audio/9233506d9a8354e3ffe1.ogg"},{"id":"ja-Play_Vo_Char_NPC021_chat_001","title":"Чат: самообладание","description":"«В зеркале вижу я все судьбы. Открыта мне вся правда, которую ты ищешь…» Ну как, прозвучало таинственно и внушительно? Хе-хе, поддерживать такой образ — та ещё работа. Я довольно часто репетирую, знаешь.","language":"Японский","audioUrl":"/nte-meta/game-audio/0352549961cce34ea9ba.ogg"},{"id":"ja-Play_Vo_Char_NPC021_fh_001","title":"Исцеление I","description":"Фух…","language":"Японский","audioUrl":"/nte-meta/game-audio/65db9324f765b5d849b4.ogg"},{"id":"ja-Play_Vo_Char_NPC021_fh_002","title":"Исцеление II","description":"Так гораздо лучше.","language":"Японский","audioUrl":"/nte-meta/game-audio/0032c0b797e5ae2201bb.ogg"},{"id":"ja-Play_Vo_Char_NPC021_gift_003","title":"Подарок получен III","description":"Это… мне? Спасибо, мне очень приятно.","language":"Японский","audioUrl":"/nte-meta/game-audio/1c8b654c7061979baab3.ogg"},{"id":"ja-Play_Vo_Char_NPC021_windfall_004","title":"Неожиданная добыча IV","description":"Вот, пожалуйста. Это твоё.","language":"Японский","audioUrl":"/nte-meta/game-audio/72659ac230bc0e3b6392.ogg"},{"id":"ko-Play_Vo_Char_NPC021_anomaly_003","title":"Нуллификация I","description":"Я буду молиться за тебя.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4ce168c9b0e29fc4d56a.ogg"},{"id":"ko-Play_Vo_Char_NPC021_Fly_001","title":"Планирование I","description":"Всё как обычно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/05fa71d4adba5a789ff1.ogg"},{"id":"ko-Play_Vo_Char_NPC021_hstruck_001","title":"Сильный урон I","description":"Больно…","language":"Корейский","audioUrl":"/nte-meta/game-audio/235de73ae213c2144a1d.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill02_SE_001","title":"Навык перенаправления X","description":"Час суда настал.","language":"Корейский","audioUrl":"/nte-meta/game-audio/346a92b37e716eadef02.ogg"},{"id":"zh-Play_Vo_Char_NPC021_weather_004","title":"Жарко","description":"Уф… Терпеть не могу такую погоду. Пойдём домой.","language":"Китайский","audioUrl":"/nte-meta/game-audio/eab178813f8b58398200.ogg"},{"id":"en-Play_Vo_Char_NPC021_about_003","title":"О Линко","description":"Линки — отличная напарница для просмотра фильмов. В свои выходные она иногда приходит с целой кучей DVD, чтобы всю ночь напролёт смотреть со мной фильмы ужасов. Каждый раз, когда она и Сяочжэнь приходят, «Дом ведьмы» прямо оживает. Не ведись на её миниатюрный вид: я до сих пор понятия не имею, какие безумные мысли роятся в этой маленькой розовой головке. (*Хихикает*) Эту девчушку ждёт будущее, полное приключений и чудес.","language":"Английский","audioUrl":"/nte-meta/game-audio/5bad287bfef3d6a916db.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill02_SE_002","title":"Навык перенаправления XI","description":"Бежать некуда.","language":"Японский","audioUrl":"/nte-meta/game-audio/4dad5eee7ea8c9f7beee.ogg"},{"id":"ja-Play_Vo_Char_NPC021_ug_003","title":"Вознесение персонажа III","description":"Я узрела тайны звёзд.","language":"Японский","audioUrl":"/nte-meta/game-audio/545f30b92cda2130af2e.ogg"},{"id":"ko-Play_Vo_Char_NPC021_QTE_001","title":"Атака на входе I","description":"Всё предрешено.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c58ece8319c0bf05bea2.ogg"},{"id":"zh-Play_Vo_Char_NPC021_Switch_002","title":"Переключение II","description":"Желаю всем вам удачи…","language":"Китайский","audioUrl":"/nte-meta/game-audio/e4aa41e3c78a71d94471.ogg"},{"id":"en-Play_Vo_Char_NPC021_about_002","title":"О Хотори","description":"Несколько раз, когда я была на мели, я наугад брала кое-какие вещи из своей коллекции и пыталась продать их владелице того антикварного магазина. Думала, она будет хитрой деловой женщиной, но она оказалась на удивление сговорчивой и щедрой. Каждый раз предлагала такую цену, что даже я удивлялась… Не слишком ли легко её обвести вокруг пальца?","language":"Английский","audioUrl":"/nte-meta/game-audio/45cda2fcb9651445b8b1.ogg"},{"id":"en-Play_Vo_Char_NPC021_fh_001","title":"Исцеление I","description":"Фух…","language":"Английский","audioUrl":"/nte-meta/game-audio/3814952a35e27d0205ec.ogg"},{"id":"en-Play_Vo_Char_NPC021_gift_004","title":"Подарок получен IV","description":"Мне очень нравится. Такой продуманный подарок.","language":"Английский","audioUrl":"/nte-meta/game-audio/10907a53d3925804b5b6.ogg"},{"id":"en-Play_Vo_Char_NPC021_greet_004","title":"Спокойной ночи","description":"Глубокая ночь — идеальное время для фильма ужасов…","language":"Английский","audioUrl":"/nte-meta/game-audio/0717f1fe302074b9664d.ogg"},{"id":"en-Play_Vo_Char_NPC021_kill_002","title":"Убийство II","description":"Что посеешь, то и пожнёшь.","language":"Английский","audioUrl":"/nte-meta/game-audio/7c72d1c381020980949f.ogg"},{"id":"ja-Play_Vo_Char_NPC021_QTE_SE_001","title":"Атака на входе IV","description":"Да утихнет ваша обида…","language":"Японский","audioUrl":"/nte-meta/game-audio/0534d330e2cd5a944105.ogg"},{"id":"ja-Play_Vo_Char_NPC021_weather_003","title":"Холодно","description":"Холод — злейший враг птиц.","language":"Японский","audioUrl":"/nte-meta/game-audio/a444b0c7282ce7f6f594.ogg"},{"id":"zh-Play_Vo_Char_NPC021_ultraskill_SE_UI_002","title":"Сверхспособность V","description":"Вот и настал ваш последний миг…","language":"Китайский","audioUrl":"/nte-meta/game-audio/b94f5dfc0cc380936fe2.ogg"},{"id":"en-Play_Vo_Char_NPC021_ultraskill_UI_003","title":"Сверхспособность III","description":"Примите благословение Ведьмы.","language":"Английский","audioUrl":"/nte-meta/game-audio/3e6f8cc91c9a7d57c8db.ogg"},{"id":"ja-Play_Vo_Char_NPC021_about_005","title":"О «Дворе Иггаш»","description":"Когда я скиталась по свету и мои крылья начали тяжелеть, Двор Иггаша нашёл меня и заключил со мной контракт. С тех пор у меня появилось место, которое я могу назвать «домом», но пока вся «работа» не будет выполнена, я не могу скрыться от их взора… Дары судьбы и её цена всегда равны. И это справедливо.","language":"Японский","audioUrl":"/nte-meta/game-audio/edb339af528b0977d7ce.ogg"},{"id":"ja-Play_Vo_Char_NPC021_ultraskill_UI_003","title":"Сверхспособность III","description":"Примите благословение Ведьмы.","language":"Японский","audioUrl":"/nte-meta/game-audio/96b2a8c92fff9298158e.ogg"}]') WHERE character_id='blackbird' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-22 22:24:48');

UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT value FROM json_each('[{"id":"ko-Play_Vo_Char_NPC021_chat_002","title":"Чат: коллекция","description":"Я обожаю собирать всякий антиквариат. И чем причудливее его дизайн, тем больше он мне нравится… Моя коллекция? У меня куда больше вещей, чем кажется на первый взгляд. Я даже выделила для них целую комнату. Если интересно — заглядывай как-нибудь, посмотришь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/05b13b2bc8672d909b9a.ogg"},{"id":"zh-Play_Vo_Char_NPC021_gift_003","title":"Подарок получен III","description":"Это… мне? Спасибо, мне очень приятно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f97055ab3e2ed55e55ca.ogg"},{"id":"zh-Play_Vo_Char_NPC021_kill_002","title":"Убийство II","description":"Что посеешь, то и пожнёшь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/8b8be3a049f2923c4b13.ogg"},{"id":"zh-Play_Vo_Char_NPC021_QTE_002","title":"Атака на входе II","description":"Покайтесь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a4b93ce209c021f6345a.ogg"},{"id":"en-Play_Vo_Char_NPC021_hp_002","title":"Низкий уровень здоровья II","description":"В глазах… всё плывёт…","language":"Английский","audioUrl":"/nte-meta/game-audio/4941b791caf429ea1560.ogg"},{"id":"en-Play_Vo_Char_NPC021_ultraskill_UI_002","title":"Сверхспособность II","description":"Внемлите отголоскам погибели.","language":"Английский","audioUrl":"/nte-meta/game-audio/70b9fb85187e8210e828.ogg"},{"id":"ja-Play_Vo_Char_NPC021_anomaly_004","title":"Нуллификация II","description":"У всего есть своя судьба.","language":"Японский","audioUrl":"/nte-meta/game-audio/04f8a85d4c026be0cefc.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill01_002","title":"Навык перенаправления II","description":"Тишина.","language":"Японский","audioUrl":"/nte-meta/game-audio/7df272d8093f36ac4b49.ogg"},{"id":"ja-Play_Vo_Char_NPC021_Switch_002","title":"Переключение II","description":"Желаю всем вам удачи…","language":"Японский","audioUrl":"/nte-meta/game-audio/e4b5ae1632a79fb0c763.ogg"},{"id":"ko-Play_Vo_Char_NPC021_gift_002","title":"Подарок получен II","description":"Мне нравится… Спасибо, я буду всегда им дорожить…","language":"Корейский","audioUrl":"/nte-meta/game-audio/e2021688c37cfcc5086b.ogg"},{"id":"zh-Play_Vo_Char_NPC021_talk_003","title":"Тема: звёздное небо","description":"Когда мир ещё не обрёл форму, звёзды уже записали судьбу всего сущего. Над завесой ночи каждая нить звёздного света — видимая и незримая, — каждое мерцание, каждая пылинка шепчут о сокрытом. Именно в них таятся разгадки судеб всего живого.","language":"Китайский","audioUrl":"/nte-meta/game-audio/954238b3a2c42f4c2f74.ogg"},{"id":"en-Play_Vo_Char_NPC021_Fly_001","title":"Планирование I","description":"Всё как обычно.","language":"Английский","audioUrl":"/nte-meta/game-audio/ebd2d21fcb53d77e59f7.ogg"},{"id":"en-Play_Vo_Char_NPC021_hobby_001","title":"Хобби","description":"Умение покупать товары со скидкой по самой выгодной цене — это целое искусство! Нужно знать точное время акций, размер максимальных скидок, какие именно товары распродают, и распланировать бюджет ещё до выхода из дома… Е-если тебе интересно, я могла бы поделиться с тобой своей тактикой закупок…","language":"Английский","audioUrl":"/nte-meta/game-audio/6c47ad8a4016d70e1564.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill01_SE_001","title":"Навык перенаправления IV","description":"Не нужно бояться…","language":"Английский","audioUrl":"/nte-meta/game-audio/c1de57e0e9ba0e6ed991.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill02_002","title":"Навык перенаправления VIII","description":"Падите в безмолвии.","language":"Английский","audioUrl":"/nte-meta/game-audio/354599f1450b7977ab29.ogg"},{"id":"ja-Play_Vo_Char_NPC021_hp_003","title":"Низкий уровень здоровья III","description":"Мне нужно отдохнуть…","language":"Японский","audioUrl":"/nte-meta/game-audio/871b147246d39140123d.ogg"},{"id":"ja-Play_Vo_Char_NPC021_meet_001","title":"Первая встреча","description":"Хрусталь направляет меня, птица взывает ко мне. Я здесь, и наши судьбы сплелись в единый клубок…","language":"Японский","audioUrl":"/nte-meta/game-audio/e1009c49bbe7d2b31408.ogg"},{"id":"ko-Play_Vo_Char_NPC021_fh_001","title":"Исцеление I","description":"Фух…","language":"Корейский","audioUrl":"/nte-meta/game-audio/67303cb805e0e61e925d.ogg"},{"id":"en-Play_Vo_Char_NPC021_anomaly_003","title":"Нуллификация I","description":"Я буду молиться за тебя.","language":"Английский","audioUrl":"/nte-meta/game-audio/9677abc7bc99620af812.ogg"},{"id":"en-Play_Vo_Char_NPC021_fh_002","title":"Исцеление II","description":"Так гораздо лучше.","language":"Английский","audioUrl":"/nte-meta/game-audio/78a85803a4aa87a3610b.ogg"},{"id":"en-Play_Vo_Char_NPC021_hstruck_002","title":"Сильный урон II","description":"Где мои обезболивающие…","language":"Английский","audioUrl":"/nte-meta/game-audio/60e2a27f5c1ac649ac26.ogg"},{"id":"en-Play_Vo_Char_NPC021_Parry_002","title":"Парирование II","description":"Я это предвидела.","language":"Английский","audioUrl":"/nte-meta/game-audio/201cfb3b68f2e5246b9c.ogg"},{"id":"ja-Play_Vo_Char_NPC021_greet_002","title":"Дневное приветствие","description":"Лавиния приготовила на обед равиоли. Тебе тоже оставила порцию.","language":"Японский","audioUrl":"/nte-meta/game-audio/a5c0b84fa493ebe9d809.ogg"},{"id":"ko-Play_Vo_Char_NPC021_containment_002","title":"Сдерживание II","description":"Спи. Больше ни о чём не тревожься…","language":"Корейский","audioUrl":"/nte-meta/game-audio/6461f6575f810e20bd35.ogg"},{"id":"ko-Play_Vo_Char_NPC021_hstruck_002","title":"Сильный урон II","description":"Где мои обезболивающие…","language":"Корейский","audioUrl":"/nte-meta/game-audio/5ad8af307768c3f40d27.ogg"},{"id":"ko-Play_Vo_Char_NPC021_TeammateDown_001","title":"Поражен товарищ по команде – Ноль","description":"Оценщик!.. Неужели это тоже… воля судьбы?..Оценщица!.. Неужели это тоже… воля судьбы?..","language":"Корейский","audioUrl":"/nte-meta/game-audio/ed71956672845e01e2dd.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill02_003","title":"Навык перенаправления IX","description":"Чахните и увядайте.","language":"Японский","audioUrl":"/nte-meta/game-audio/159cbcbc2b9127c55448.ogg"},{"id":"ko-Play_Vo_Char_NPC021_containment_001","title":"Сдерживание I","description":"Отправляйся туда, где тебе место.","language":"Корейский","audioUrl":"/nte-meta/game-audio/84fa9492117d93d15bc2.ogg"},{"id":"zh-Play_Vo_Char_NPC021_about_005","title":"О «Дворе Иггаш»","description":"Когда я скиталась по свету и мои крылья начали тяжелеть, Двор Иггаша нашёл меня и заключил со мной контракт. С тех пор у меня появилось место, которое я могу назвать «домом», но пока вся «работа» не будет выполнена, я не могу скрыться от их взора… Дары судьбы и её цена всегда равны. И это справедливо.","language":"Китайский","audioUrl":"/nte-meta/game-audio/4f5c5c1f612611511d06.ogg"},{"id":"zh-Play_Vo_Char_NPC021_DodgeCombo_001","title":"Серия критических уклонений I","description":"Как и ожидалось.","language":"Китайский","audioUrl":"/nte-meta/game-audio/32d28317d7b646e1aa01.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill02_001","title":"Навык перенаправления VII","description":"Дрожите?","language":"Китайский","audioUrl":"/nte-meta/game-audio/5860a07e91949f7dc91c.ogg"},{"id":"zh-Play_Vo_Char_NPC021_talk_001","title":"Тема: аномалия","description":"Прорицатель не может видеть собственную судьбу: ни будущего, ни прошлого. Но почему-то я не вижу и твоего прошлого тоже. Оно словно скрыто по ту сторону звёзд, и я не могу разглядеть даже его очертания… Неужели хрустальный шар обманывает меня? Какая судьба тебя ждёт? Мне так любопытно… Хотя нет, неважно…","language":"Китайский","audioUrl":"/nte-meta/game-audio/718ef11aed31c6cedad7.ogg"},{"id":"zh-Play_Vo_Char_NPC021_weather_003","title":"Холодно","description":"Холод — злейший враг птиц.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f7d47e8a1fee52b2a93e.ogg"},{"id":"en-Play_Vo_Char_NPC021_ug_001","title":"Вознесение персонажа I","description":"Я разгадала скрытые послания пророчества.","language":"Английский","audioUrl":"/nte-meta/game-audio/0e3f0346924734bf4de2.ogg"},{"id":"ja-Play_Vo_Char_NPC021_QTE_SE_002","title":"Атака на входе V","description":"Да будут прощены грехи ваши…","language":"Японский","audioUrl":"/nte-meta/game-audio/100217a8239f1adf3404.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill02_SE_003","title":"Навык перенаправления XII","description":"Возрождённая в огне…","language":"Японский","audioUrl":"/nte-meta/game-audio/1b9faed3600a2d200b02.ogg"},{"id":"ko-Play_Vo_Char_NPC021_Parry_001","title":"Парирование I","description":"Как раз вовремя.","language":"Корейский","audioUrl":"/nte-meta/game-audio/60e5155dee6efc3a74bf.ogg"},{"id":"ko-Play_Vo_Char_NPC021_ultraskill_UI_003","title":"Сверхспособность III","description":"Примите благословение Ведьмы.","language":"Корейский","audioUrl":"/nte-meta/game-audio/3fb3b79ec788b7f730a6.ogg"},{"id":"zh-Play_Vo_Char_NPC021_QTE_SE_002","title":"Атака на входе V","description":"Да будут прощены грехи ваши…","language":"Китайский","audioUrl":"/nte-meta/game-audio/694ef7c613710ec3667e.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill02_003","title":"Навык перенаправления IX","description":"Чахните и увядайте.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f890e86495dd68117ee4.ogg"},{"id":"ja-Play_Vo_Char_NPC021_deploy_001","title":"Отправка I","description":"Если ты этого хочешь…","language":"Японский","audioUrl":"/nte-meta/game-audio/a44c5c324840128bc249.ogg"},{"id":"ko-Play_Vo_Char_NPC021_talk_001","title":"Тема: аномалия","description":"Прорицатель не может видеть собственную судьбу: ни будущего, ни прошлого. Но почему-то я не вижу и твоего прошлого тоже. Оно словно скрыто по ту сторону звёзд, и я не могу разглядеть даже его очертания… Неужели хрустальный шар обманывает меня? Какая судьба тебя ждёт? Мне так любопытно… Хотя нет, неважно…","language":"Корейский","audioUrl":"/nte-meta/game-audio/a75ea9812284a3c04dde.ogg"},{"id":"zh-Play_Vo_Char_NPC021_hp_002","title":"Низкий уровень здоровья II","description":"В глазах… всё плывёт…","language":"Китайский","audioUrl":"/nte-meta/game-audio/434f43c633d62b14d761.ogg"},{"id":"zh-Play_Vo_Char_NPC021_QTE_003","title":"Атака на входе III","description":"Непростительно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e0d2eb169727e2a10d7d.ogg"},{"id":"zh-Play_Vo_Char_NPC021_vexation_001","title":"Проблемы","description":"Стоит мне взяться за работу, как сразу голова кругом. Я больше не могу удерживать человеческий облик…","language":"Китайский","audioUrl":"/nte-meta/game-audio/979b8f3082abf53523f4.ogg"},{"id":"en-Play_Vo_Char_NPC021_about_005","title":"О «Дворе Иггаш»","description":"Когда я скиталась по свету и мои крылья начали тяжелеть, Двор Иггаша нашёл меня и заключил со мной контракт. С тех пор у меня появилось место, которое я могу назвать «домом», но пока вся «работа» не будет выполнена, я не могу скрыться от их взора… Дары судьбы и её цена всегда равны. И это справедливо.","language":"Английский","audioUrl":"/nte-meta/game-audio/75310051219338df6dfc.ogg"},{"id":"en-Play_Vo_Char_NPC021_dead_003","title":"Потеря сознания III","description":"Пламя… пожирает меня…","language":"Английский","audioUrl":"/nte-meta/game-audio/2319ab6720535351ec57.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill01_002","title":"Навык перенаправления II","description":"Тишина.","language":"Английский","audioUrl":"/nte-meta/game-audio/ac6ec3a4504e122b5bb7.ogg"},{"id":"ja-Play_Vo_Char_NPC021_gift_004","title":"Подарок получен IV","description":"Мне очень нравится. Такой продуманный подарок.","language":"Японский","audioUrl":"/nte-meta/game-audio/75df834ccd371a828b20.ogg"},{"id":"ja-Play_Vo_Char_NPC021_kill_002","title":"Убийство II","description":"Что посеешь, то и пожнёшь.","language":"Японский","audioUrl":"/nte-meta/game-audio/43eb5c0577e28d00b7f9.ogg"},{"id":"ko-Play_Vo_Char_NPC021_ultraskill_SE_UI_001","title":"Сверхспособность IV","description":"Пламя смерти вершит над вами суд!","language":"Корейский","audioUrl":"/nte-meta/game-audio/adc82c173fea8bc8151c.ogg"},{"id":"zh-Play_Vo_Char_NPC021_greet_004","title":"Спокойной ночи","description":"Глубокая ночь — идеальное время для фильма ужасов…","language":"Китайский","audioUrl":"/nte-meta/game-audio/f4669b7176a557cfef87.ogg"},{"id":"zh-Play_Vo_Char_NPC021_QTE_001","title":"Атака на входе I","description":"Всё предрешено.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e397922b92d0246486de.ogg"},{"id":"zh-Play_Vo_Char_NPC021_weather_002","title":"Дождливо","description":"Пусть дождь смоет всю боль этого мира.","language":"Китайский","audioUrl":"/nte-meta/game-audio/179460c3b596ddde8a98.ogg"},{"id":"en-Play_Vo_Char_NPC021_Switch_002","title":"Переключение II","description":"Желаю всем вам удачи…","language":"Английский","audioUrl":"/nte-meta/game-audio/ab9d3e2eb651f33262c2.ogg"},{"id":"en-Play_Vo_Char_NPC021_ultraskill_SE_UI_001","title":"Сверхспособность IV","description":"Пламя смерти вершит над вами суд!","language":"Английский","audioUrl":"/nte-meta/game-audio/bef50f6afad2953826f8.ogg"},{"id":"en-Play_Vo_Char_NPC021_ultraskill_SE_UI_002","title":"Сверхспособность V","description":"Вот и настал ваш последний миг…","language":"Английский","audioUrl":"/nte-meta/game-audio/ea9a1cb14c91ff19d654.ogg"},{"id":"ja-Play_Vo_Char_NPC021_anomaly_003","title":"Нуллификация I","description":"Я буду молиться за тебя.","language":"Японский","audioUrl":"/nte-meta/game-audio/96c2eb5e3d40a8601e3e.ogg"},{"id":"ja-Play_Vo_Char_NPC021_QTE_001","title":"Атака на входе I","description":"Всё предрешено.","language":"Японский","audioUrl":"/nte-meta/game-audio/28b386a817dadba3595a.ogg"},{"id":"ja-Play_Vo_Char_NPC021_TeammateDown_001","title":"Поражен товарищ по команде – Ноль","description":"Оценщик!.. Неужели это тоже… воля судьбы?..Оценщица!.. Неужели это тоже… воля судьбы?..","language":"Японский","audioUrl":"/nte-meta/game-audio/42836b0a42fb791b4f7b.ogg"},{"id":"ko-Play_Vo_Char_NPC021_about_003","title":"О Линко","description":"Линки — отличная напарница для просмотра фильмов. В свои выходные она иногда приходит с целой кучей DVD, чтобы всю ночь напролёт смотреть со мной фильмы ужасов. Каждый раз, когда она и Сяочжэнь приходят, «Дом ведьмы» прямо оживает. Не ведись на её миниатюрный вид: я до сих пор понятия не имею, какие безумные мысли роятся в этой маленькой розовой головке. (*Хихикает*) Эту девчушку ждёт будущее, полное приключений и чудес.","language":"Корейский","audioUrl":"/nte-meta/game-audio/39c844bedfbd49234db8.ogg"},{"id":"en-Play_Vo_Char_NPC021_Switch_003","title":"Переключение III","description":"Прислушиваясь к зову судьбы.","language":"Английский","audioUrl":"/nte-meta/game-audio/53b4e9d032e945090031.ogg"},{"id":"en-Play_Vo_Char_NPC021_weather_004","title":"Жарко","description":"Уф… Терпеть не могу такую погоду. Пойдём домой.","language":"Английский","audioUrl":"/nte-meta/game-audio/f65e1edc10eee4f1b563.ogg"},{"id":"ja-Play_Vo_Char_NPC021_greet_001","title":"Утреннее приветствие","description":"Доброе утро, сегодня удача на твоей стороне.","language":"Японский","audioUrl":"/nte-meta/game-audio/b0b096de39818c513a35.ogg"},{"id":"ko-Play_Vo_Char_NPC021_Parry_002","title":"Парирование II","description":"Я это предвидела.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4b0e7a70c642e119b6a2.ogg"},{"id":"ko-Play_Vo_Char_NPC021_self_002","title":"Обо мне: Блэкбёрд","description":"Когда мне действительно нужно выйти наружу или когда мне не хочется работать, я превращаюсь в птицу. Это просто, не привлекает лишнего внимания, да и выглядит мило, правда ведь? Этот секрет известен только тебе и Лавинии. В следующий раз, когда мимо тебя пролетит птица, присмотрись получше — вдруг это я.","language":"Корейский","audioUrl":"/nte-meta/game-audio/f0fe095dc96fcc3ddddf.ogg"},{"id":"ko-Play_Vo_Char_NPC021_talk_003","title":"Тема: звёздное небо","description":"Когда мир ещё не обрёл форму, звёзды уже записали судьбу всего сущего. Над завесой ночи каждая нить звёздного света — видимая и незримая, — каждое мерцание, каждая пылинка шепчут о сокрытом. Именно в них таятся разгадки судеб всего живого.","language":"Корейский","audioUrl":"/nte-meta/game-audio/820d8ac753727630a0ab.ogg"},{"id":"zh-Play_Vo_Char_NPC021_about_001","title":"О Лавинии","description":"Лавиния — специалистка, которую Двор Иггаша направил в «Дом ведьмы». Она моя надсмотрщица, но в то же время и подруга. Не позволяй её серьёзному лицу обмануть тебя, она готовит лучше всех, кого я знаю. Любое её блюдо получается безумно вкусным. Хм, может, она накладывает какое-то заклинание, чтобы еда была вкуснее, кто знает…","language":"Китайский","audioUrl":"/nte-meta/game-audio/8da83c079f7af4cf8bbd.ogg"},{"id":"zh-Play_Vo_Char_NPC021_windfall_006","title":"Неожиданная добыча VI","description":"Подарок судьбы.","language":"Китайский","audioUrl":"/nte-meta/game-audio/1a0650972346d760943c.ogg"},{"id":"en-Play_Vo_Char_NPC021_hp_001","title":"Низкий уровень здоровья I","description":"Это дурной знак…","language":"Английский","audioUrl":"/nte-meta/game-audio/832c21ed7382fe4a43dd.ogg"},{"id":"en-Play_Vo_Char_NPC021_Switch_001","title":"Переключение I","description":"Что-то случилось?","language":"Английский","audioUrl":"/nte-meta/game-audio/b5ee677bd61cacc8be49.ogg"},{"id":"ja-Play_Vo_Char_NPC021_windfall_002","title":"Неожиданная добыча II","description":"Приятный сюрприз.","language":"Японский","audioUrl":"/nte-meta/game-audio/d3d0ff22dbc7edabf04c.ogg"},{"id":"ko-Play_Vo_Char_NPC021_greet_001","title":"Утреннее приветствие","description":"Доброе утро, сегодня удача на твоей стороне.","language":"Корейский","audioUrl":"/nte-meta/game-audio/955be7ced7f7044d0ea0.ogg"},{"id":"ko-Play_Vo_Char_NPC021_hp_003","title":"Низкий уровень здоровья III","description":"Мне нужно отдохнуть…","language":"Корейский","audioUrl":"/nte-meta/game-audio/524bbb1eb0c21ccc4692.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill01_SE_001","title":"Навык перенаправления IV","description":"Не нужно бояться…","language":"Корейский","audioUrl":"/nte-meta/game-audio/08d20102c58fb74a9d8b.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill02_SE_001","title":"Навык перенаправления X","description":"Час суда настал.","language":"Английский","audioUrl":"/nte-meta/game-audio/a93c0b1fcf4adc222139.ogg"},{"id":"ja-Play_Vo_Char_NPC021_ultraskill_SE_UI_003","title":"Сверхспособность VI","description":"Погибель ваша близка…","language":"Японский","audioUrl":"/nte-meta/game-audio/aba7a41236f8ec9a12fd.ogg"},{"id":"ko-Play_Vo_Char_NPC021_struck_001","title":"Урон I","description":"Сосредоточься… Со мной всё в порядке.","language":"Корейский","audioUrl":"/nte-meta/game-audio/0a12b6c42376541010bf.ogg"},{"id":"zh-Play_Vo_Char_NPC021_hp_001","title":"Низкий уровень здоровья I","description":"Это дурной знак…","language":"Китайский","audioUrl":"/nte-meta/game-audio/84bff389f73b710e668d.ogg"},{"id":"en-Play_Vo_Char_NPC021_gift_002","title":"Подарок получен II","description":"Мне нравится… Спасибо, я буду всегда им дорожить…","language":"Английский","audioUrl":"/nte-meta/game-audio/2d046695f780e1972421.ogg"},{"id":"en-Play_Vo_Char_NPC021_meet_001","title":"Первая встреча","description":"Хрусталь направляет меня, птица взывает ко мне. Я здесь, и наши судьбы сплелись в единый клубок…","language":"Английский","audioUrl":"/nte-meta/game-audio/d840ae2579df6a0d0f78.ogg"},{"id":"en-Play_Vo_Char_NPC021_windfall_003","title":"Неожиданная добыча III","description":"Знак удачи.","language":"Английский","audioUrl":"/nte-meta/game-audio/7020836c0a080beb12e1.ogg"},{"id":"ja-Play_Vo_Char_NPC021_windfall_006","title":"Неожиданная добыча VI","description":"Подарок судьбы.","language":"Японский","audioUrl":"/nte-meta/game-audio/acbc0d53f6337f17a564.ogg"},{"id":"ko-Play_Vo_Char_NPC021_fh_002","title":"Исцеление II","description":"Так гораздо лучше.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b285d19f9271c0819733.ogg"},{"id":"zh-Play_Vo_Char_NPC021_meet_001","title":"Первая встреча","description":"Хрусталь направляет меня, птица взывает ко мне. Я здесь, и наши судьбы сплелись в единый клубок…","language":"Китайский","audioUrl":"/nte-meta/game-audio/6751aa009ff2e605a8df.ogg"},{"id":"zh-Play_Vo_Char_NPC021_self_002","title":"Обо мне: Блэкбёрд","description":"Когда мне действительно нужно выйти наружу или когда мне не хочется работать, я превращаюсь в птицу. Это просто, не привлекает лишнего внимания, да и выглядит мило, правда ведь? Этот секрет известен только тебе и Лавинии. В следующий раз, когда мимо тебя пролетит птица, присмотрись получше — вдруг это я.","language":"Китайский","audioUrl":"/nte-meta/game-audio/545ffb51d51d48376c2a.ogg"},{"id":"zh-Play_Vo_Char_NPC021_self_003","title":"Обо мне: шляпа","description":"Я передала этой шляпе часть своих сил. Даже когда меня нет рядом, я могу чувствовать, что происходит возле неё. И когда мне не хочется никого видеть, я использую её как рупор, а сама уютно устраиваюсь на чердаке… Я-я вовсе не бездельничаю, конечно! Я всё ещё гадаю для своих клиентов, честно…","language":"Китайский","audioUrl":"/nte-meta/game-audio/8781b7893324f152a216.ogg"},{"id":"en-Play_Vo_Char_NPC021_self_002","title":"Обо мне: Блэкбёрд","description":"Когда мне действительно нужно выйти наружу или когда мне не хочется работать, я превращаюсь в птицу. Это просто, не привлекает лишнего внимания, да и выглядит мило, правда ведь? Этот секрет известен только тебе и Лавинии. В следующий раз, когда мимо тебя пролетит птица, присмотрись получше — вдруг это я.","language":"Английский","audioUrl":"/nte-meta/game-audio/91c2befba5675cca7fae.ogg"},{"id":"ja-Play_Vo_Char_NPC021_self_003","title":"Обо мне: шляпа","description":"Я передала этой шляпе часть своих сил. Даже когда меня нет рядом, я могу чувствовать, что происходит возле неё. И когда мне не хочется никого видеть, я использую её как рупор, а сама уютно устраиваюсь на чердаке… Я-я вовсе не бездельничаю, конечно! Я всё ещё гадаю для своих клиентов, честно…","language":"Японский","audioUrl":"/nte-meta/game-audio/e90b38b4832c1b640644.ogg"},{"id":"ja-Play_Vo_Char_NPC021_weather_002","title":"Дождливо","description":"Пусть дождь смоет всю боль этого мира.","language":"Японский","audioUrl":"/nte-meta/game-audio/a1c291583973cf9b5818.ogg"},{"id":"ko-Play_Vo_Char_NPC021_dead_002","title":"Потеря сознания II","description":"Неужели… всё закончится здесь?..","language":"Корейский","audioUrl":"/nte-meta/game-audio/e517695e13a8a9d877f2.ogg"},{"id":"ko-Play_Vo_Char_NPC021_greet_003","title":"Вечернее приветствие","description":"Давай вместе найдём наши две звезды на ночном небе.","language":"Корейский","audioUrl":"/nte-meta/game-audio/95b0849f8f53836c4fe3.ogg"},{"id":"ko-Play_Vo_Char_NPC021_QTE_003","title":"Атака на входе III","description":"Непростительно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/dd8b6f9bfabe6ab37516.ogg"},{"id":"zh-Play_Vo_Char_NPC021_greet_001","title":"Утреннее приветствие","description":"Доброе утро, сегодня удача на твоей стороне.","language":"Китайский","audioUrl":"/nte-meta/game-audio/9033c307d0f361581cde.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill01_001","title":"Навык перенаправления I","description":"Бесполезно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/8d5194735c7ed37e607f.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill02_SE_002","title":"Навык перенаправления XI","description":"Бежать некуда.","language":"Китайский","audioUrl":"/nte-meta/game-audio/89da581ff2cd1e6918a1.ogg"},{"id":"en-Play_Vo_Char_NPC021_self_003","title":"Обо мне: шляпа","description":"Я передала этой шляпе часть своих сил. Даже когда меня нет рядом, я могу чувствовать, что происходит возле неё. И когда мне не хочется никого видеть, я использую её как рупор, а сама уютно устраиваюсь на чердаке… Я-я вовсе не бездельничаю, конечно! Я всё ещё гадаю для своих клиентов, честно…","language":"Английский","audioUrl":"/nte-meta/game-audio/b1190671a3ff08f3c2d7.ogg"},{"id":"ja-Play_Vo_Char_NPC021_self_002","title":"Обо мне: Блэкбёрд","description":"Когда мне действительно нужно выйти наружу или когда мне не хочется работать, я превращаюсь в птицу. Это просто, не привлекает лишнего внимания, да и выглядит мило, правда ведь? Этот секрет известен только тебе и Лавинии. В следующий раз, когда мимо тебя пролетит птица, присмотрись получше — вдруг это я.","language":"Японский","audioUrl":"/nte-meta/game-audio/47b00f26f3926113db74.ogg"},{"id":"ja-Play_Vo_Char_NPC021_struck_002","title":"Урон II","description":"Всего лишь царапина.","language":"Японский","audioUrl":"/nte-meta/game-audio/e3353388cc1c3f7fa11f.ogg"},{"id":"zh-Play_Vo_Char_NPC021_gift_001","title":"Подарок получен I","description":"Ценен не только сам подарок… но и чувства, которые за ним стоят.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5f549b7616c77b8d962b.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill02_002","title":"Навык перенаправления VIII","description":"Падите в безмолвии.","language":"Китайский","audioUrl":"/nte-meta/game-audio/af80fc93904dc6c1ad18.ogg"},{"id":"en-Play_Vo_Char_NPC021_struck_002","title":"Урон II","description":"Всего лишь царапина.","language":"Английский","audioUrl":"/nte-meta/game-audio/74ad5aa6bdfebb5714c0.ogg"},{"id":"ja-Play_Vo_Char_NPC021_self_001","title":"Обо мне: способности аномалии","description":"Мои силы позволяют мне читать судьбы и очищать Камни оракула. Я не знаю, почему мне были дарованы такие могущественные способности… Вернее, я даже не знаю, почему вообще существую в этом мире. Я прочла судьбы бесчисленного множества людей, но моя собственная скрыта за туманом, клубящимся внутри хрустального шара. Эсперы всегда платят свою цену за дар, и, возможно, мои силы как аномалии просто ограничены в этом плане… Какой бы ни оказалась правда о моей судьбе, я с радостью приму её.","language":"Японский","audioUrl":"/nte-meta/game-audio/80d5d63701469a7ef984.ogg"},{"id":"ja-Play_Vo_Char_NPC021_windfall_005","title":"Неожиданная добыча V","description":"Хорошая вещица. Тебе нравится?","language":"Японский","audioUrl":"/nte-meta/game-audio/56d58d31abc203767e68.ogg"},{"id":"ko-Play_Vo_Char_NPC021_windfall_006","title":"Неожиданная добыча VI","description":"Подарок судьбы.","language":"Корейский","audioUrl":"/nte-meta/game-audio/bcc0043b323a2fb97433.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill01_003","title":"Навык перенаправления III","description":"Вспышка тени.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3a6ab19acf418bbb0497.ogg"},{"id":"en-Play_Vo_Char_NPC021_dead_001","title":"Потеря сознания I","description":"Это… моя судьба…","language":"Английский","audioUrl":"/nte-meta/game-audio/f9eada3d06248d0a0c8c.ogg"},{"id":"ja-Play_Vo_Char_NPC021_dead_001","title":"Потеря сознания I","description":"Это… моя судьба…","language":"Японский","audioUrl":"/nte-meta/game-audio/1c8c3be8fea3d0d33738.ogg"},{"id":"ko-Play_Vo_Char_NPC021_ultraskill_SE_UI_003","title":"Сверхспособность VI","description":"Погибель ваша близка…","language":"Корейский","audioUrl":"/nte-meta/game-audio/12ee76d73405ca781d1f.ogg"},{"id":"zh-Play_Vo_Char_NPC021_gift_002","title":"Подарок получен II","description":"Мне нравится… Спасибо, я буду всегда им дорожить…","language":"Китайский","audioUrl":"/nte-meta/game-audio/a0acac9ca4224de2b8b0.ogg"},{"id":"en-Play_Vo_Char_NPC021_containment_001","title":"Сдерживание I","description":"Отправляйся туда, где тебе место.","language":"Английский","audioUrl":"/nte-meta/game-audio/e866114052090b34737d.ogg"},{"id":"ko-Play_Vo_Char_NPC021_gift_003","title":"Подарок получен III","description":"Это… мне? Спасибо, мне очень приятно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6d878831501f0d88ddea.ogg"},{"id":"ko-Play_Vo_Char_NPC021_QTE_SE_001","title":"Атака на входе IV","description":"Да утихнет ваша обида…","language":"Корейский","audioUrl":"/nte-meta/game-audio/3c4606aacf94ba4c3325.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill02_SE_003","title":"Навык перенаправления XII","description":"Возрождённая в огне…","language":"Корейский","audioUrl":"/nte-meta/game-audio/37725c1bbfd49a8d47a6.ogg"},{"id":"zh-Play_Vo_Char_NPC021_fh_001","title":"Исцеление I","description":"Фух…","language":"Китайский","audioUrl":"/nte-meta/game-audio/6f6dcfcbd1cb0b724ea3.ogg"},{"id":"zh-Play_Vo_Char_NPC021_Fly_002","title":"Планирование II","description":"Знакомый ветерок…","language":"Китайский","audioUrl":"/nte-meta/game-audio/389f9dfb22dab2cadfe3.ogg"},{"id":"zh-Play_Vo_Char_NPC021_skill01_SE_003","title":"Навык перенаправления VI","description":"Какая жалость…","language":"Китайский","audioUrl":"/nte-meta/game-audio/b5001c9f153e43e20f2a.ogg"},{"id":"ja-Play_Vo_Char_NPC021_Fly_002","title":"Планирование II","description":"Знакомый ветерок…","language":"Японский","audioUrl":"/nte-meta/game-audio/4f1ce3282730258d7a2e.ogg"},{"id":"ko-Play_Vo_Char_NPC021_greet_004","title":"Спокойной ночи","description":"Глубокая ночь — идеальное время для фильма ужасов…","language":"Корейский","audioUrl":"/nte-meta/game-audio/db40bc10c6a614f93475.ogg"},{"id":"zh-Play_Vo_Char_NPC021_about_002","title":"О Хотори","description":"Несколько раз, когда я была на мели, я наугад брала кое-какие вещи из своей коллекции и пыталась продать их владелице того антикварного магазина. Думала, она будет хитрой деловой женщиной, но она оказалась на удивление сговорчивой и щедрой. Каждый раз предлагала такую цену, что даже я удивлялась… Не слишком ли легко её обвести вокруг пальца?","language":"Китайский","audioUrl":"/nte-meta/game-audio/c8a3299b34f38e4306e4.ogg"},{"id":"zh-Play_Vo_Char_NPC021_kill_001","title":"Убийство I","description":"Приговор судьбы.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a5e2f916c30b60e9726d.ogg"},{"id":"ja-Play_Vo_Char_NPC021_chat_002","title":"Чат: коллекция","description":"Я обожаю собирать всякий антиквариат. И чем причудливее его дизайн, тем больше он мне нравится… Моя коллекция? У меня куда больше вещей, чем кажется на первый взгляд. Я даже выделила для них целую комнату. Если интересно — заглядывай как-нибудь, посмотришь.","language":"Японский","audioUrl":"/nte-meta/game-audio/444b7e416dc83d07c8dc.ogg"},{"id":"ja-Play_Vo_Char_NPC021_ultraskill_SE_UI_002","title":"Сверхспособность V","description":"Вот и настал ваш последний миг…","language":"Японский","audioUrl":"/nte-meta/game-audio/73d6f3e47b50c1930e9f.ogg"},{"id":"ko-Play_Vo_Char_NPC021_gift_001","title":"Подарок получен I","description":"Ценен не только сам подарок… но и чувства, которые за ним стоят.","language":"Корейский","audioUrl":"/nte-meta/game-audio/126ee1585f584530aef1.ogg"},{"id":"ko-Play_Vo_Char_NPC021_ug_002","title":"Вознесение персонажа II","description":"Я сыграю фугу судьбы.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b4303b5e1b0fc4aa3697.ogg"},{"id":"zh-Play_Vo_Char_NPC021_anomaly_003","title":"Нуллификация I","description":"Я буду молиться за тебя.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2d897baba22c56229cac.ogg"},{"id":"zh-Play_Vo_Char_NPC021_hobby_001","title":"Хобби","description":"Умение покупать товары со скидкой по самой выгодной цене — это целое искусство! Нужно знать точное время акций, размер максимальных скидок, какие именно товары распродают, и распланировать бюджет ещё до выхода из дома… Е-если тебе интересно, я могла бы поделиться с тобой своей тактикой закупок…","language":"Китайский","audioUrl":"/nte-meta/game-audio/74a757b96c6fc875fe14.ogg"},{"id":"zh-Play_Vo_Char_NPC021_struck_002","title":"Урон II","description":"Всего лишь царапина.","language":"Китайский","audioUrl":"/nte-meta/game-audio/97f17dea7eccd820c8cb.ogg"},{"id":"zh-Play_Vo_Char_NPC021_ultraskill_SE_UI_001","title":"Сверхспособность IV","description":"Пламя смерти вершит над вами суд!","language":"Китайский","audioUrl":"/nte-meta/game-audio/6c6fb9baae925f898051.ogg"},{"id":"en-Play_Vo_Char_NPC021_chat_003","title":"Чат: вне дома","description":"В «Доме ведьмы» так тихо и спокойно, и у меня есть всё необходимое: закуски, комиксы и мой хрустальный шар… Зачем мне вообще выходить наружу? О, ты пойдёшь со мной? Эх… сорвался мой план посидеть дома…","language":"Английский","audioUrl":"/nte-meta/game-audio/5ef5e53342bdf0ed9c6e.ogg"},{"id":"ko-Play_Vo_Char_NPC021_dead_001","title":"Потеря сознания I","description":"Это… моя судьба…","language":"Корейский","audioUrl":"/nte-meta/game-audio/2ff3da7c506defe60a75.ogg"},{"id":"ko-Play_Vo_Char_NPC021_dead_003","title":"Потеря сознания III","description":"Пламя… пожирает меня…","language":"Корейский","audioUrl":"/nte-meta/game-audio/9286b09cfdc611fefcb7.ogg"},{"id":"ko-Play_Vo_Char_NPC021_greet_002","title":"Дневное приветствие","description":"Лавиния приготовила на обед равиоли. Тебе тоже оставила порцию.","language":"Корейский","audioUrl":"/nte-meta/game-audio/0a6a87808b4c21899cbc.ogg"},{"id":"ko-Play_Vo_Char_NPC021_ug_003","title":"Вознесение персонажа III","description":"Я узрела тайны звёзд.","language":"Корейский","audioUrl":"/nte-meta/game-audio/851a07e047931c3fbe91.ogg"},{"id":"ko-Play_Vo_Char_NPC021_ultraskill_UI_002","title":"Сверхспособность II","description":"Внемлите отголоскам погибели.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4e6770876b70e82a7cd0.ogg"},{"id":"zh-Play_Vo_Char_NPC021_deploy_001","title":"Отправка I","description":"Если ты этого хочешь…","language":"Китайский","audioUrl":"/nte-meta/game-audio/5c6761dbdb0b4a5a6a08.ogg"},{"id":"zh-Play_Vo_Char_NPC021_TeammateDown_001","title":"Поражен товарищ по команде – Ноль","description":"Оценщик!.. Неужели это тоже… воля судьбы?..Оценщица!.. Неужели это тоже… воля судьбы?..","language":"Китайский","audioUrl":"/nte-meta/game-audio/ae5370b26a66a459b12c.ogg"},{"id":"ja-Play_Vo_Char_NPC021_QTE_SE_003","title":"Атака на входе VI","description":"Да очистятся души ваши…","language":"Японский","audioUrl":"/nte-meta/game-audio/47eae659757bd696bf26.ogg"},{"id":"ja-Play_Vo_Char_NPC021_talk_002","title":"Тема: «Ведьма»","description":"Если честно, никакая я не ведьма. Кроме своих аномальных способностей, я не знаю никаких заклинаний. У меня никогда не было чёрной кошки, и я даже не человек в полном смысле этого слова… Но я уже давно смирилась с тем, что все называют меня «ведьмой». Так мне не приходится многого объяснять. Конечно, любой бы подумал, что в «Доме ведьмы» живёт ведьма, разве нет?","language":"Японский","audioUrl":"/nte-meta/game-audio/f696f4daacad95879e45.ogg"},{"id":"ja-Play_Vo_Char_NPC021_weather_001","title":"Солнечно","description":"Солнце сияет ярко — прямо как твоё будущее.","language":"Японский","audioUrl":"/nte-meta/game-audio/f6ee053867d1effa009d.ogg"},{"id":"ko-Play_Vo_Char_NPC021_skill02_SE_002","title":"Навык перенаправления XI","description":"Бежать некуда.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5a9c9a6e8f898993c483.ogg"},{"id":"ko-Play_Vo_Char_NPC021_Switch_002","title":"Переключение II","description":"Желаю всем вам удачи…","language":"Корейский","audioUrl":"/nte-meta/game-audio/5a7b0caf5b216c5143c5.ogg"},{"id":"en-Play_Vo_Char_NPC021_vexation_001","title":"Проблемы","description":"Стоит мне взяться за работу, как сразу голова кругом. Я больше не могу удерживать человеческий облик…","language":"Английский","audioUrl":"/nte-meta/game-audio/bd07577b809e867ca50d.ogg"},{"id":"ja-Play_Vo_Char_NPC021_hstruck_002","title":"Сильный урон II","description":"Где мои обезболивающие…","language":"Японский","audioUrl":"/nte-meta/game-audio/a2fdaaa097284011ee2d.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill01_003","title":"Навык перенаправления III","description":"Вспышка тени.","language":"Японский","audioUrl":"/nte-meta/game-audio/adf277b0a2a8a81333d9.ogg"},{"id":"zh-Play_Vo_Char_NPC021_containment_001","title":"Сдерживание I","description":"Отправляйся туда, где тебе место.","language":"Китайский","audioUrl":"/nte-meta/game-audio/c08f73b7fad5754b17a6.ogg"},{"id":"zh-Play_Vo_Char_NPC021_Switch_001","title":"Переключение I","description":"Что-то случилось?","language":"Китайский","audioUrl":"/nte-meta/game-audio/c1597fe06232934421b8.ogg"},{"id":"zh-Play_Vo_Char_NPC021_ug_003","title":"Вознесение персонажа III","description":"Я узрела тайны звёзд.","language":"Китайский","audioUrl":"/nte-meta/game-audio/639e4774e2f24988bc44.ogg"},{"id":"ja-Play_Vo_Char_NPC021_QTE_002","title":"Атака на входе II","description":"Покайтесь.","language":"Японский","audioUrl":"/nte-meta/game-audio/b93c63998a8bc0ba71ec.ogg"},{"id":"ko-Play_Vo_Char_NPC021_hp_002","title":"Низкий уровень здоровья II","description":"В глазах… всё плывёт…","language":"Корейский","audioUrl":"/nte-meta/game-audio/d9433d2d5030c5361de1.ogg"},{"id":"zh-Play_Vo_Char_NPC021_Parry_002","title":"Парирование II","description":"Я это предвидела.","language":"Китайский","audioUrl":"/nte-meta/game-audio/451dcd3c694ddcd9f9bc.ogg"},{"id":"zh-Play_Vo_Char_NPC021_ultraskill_UI_003","title":"Сверхспособность III","description":"Примите благословение Ведьмы.","language":"Китайский","audioUrl":"/nte-meta/game-audio/18589f31846a933ee6d2.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill02_003","title":"Навык перенаправления IX","description":"Чахните и увядайте.","language":"Английский","audioUrl":"/nte-meta/game-audio/154c61527807145fb729.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill01_SE_003","title":"Навык перенаправления VI","description":"Какая жалость…","language":"Японский","audioUrl":"/nte-meta/game-audio/22526dae4650f341d2fe.ogg"},{"id":"zh-Play_Vo_Char_NPC021_dead_002","title":"Потеря сознания II","description":"Неужели… всё закончится здесь?..","language":"Китайский","audioUrl":"/nte-meta/game-audio/126f02952a43c190c4ee.ogg"},{"id":"en-Play_Vo_Char_NPC021_dead_002","title":"Потеря сознания II","description":"Неужели… всё закончится здесь?..","language":"Английский","audioUrl":"/nte-meta/game-audio/99f4594309e167236be9.ogg"},{"id":"en-Play_Vo_Char_NPC021_skill02_SE_002","title":"Навык перенаправления XI","description":"Бежать некуда.","language":"Английский","audioUrl":"/nte-meta/game-audio/70e3c8cd6f1b274a2aaf.ogg"},{"id":"en-Play_Vo_Char_NPC021_ug_003","title":"Вознесение персонажа III","description":"Я узрела тайны звёзд.","language":"Английский","audioUrl":"/nte-meta/game-audio/b42bcbc430ebcdf01751.ogg"},{"id":"ja-Play_Vo_Char_NPC021_vexation_001","title":"Проблемы","description":"Стоит мне взяться за работу, как сразу голова кругом. Я больше не могу удерживать человеческий облик…","language":"Японский","audioUrl":"/nte-meta/game-audio/3ad743e206b69b5f93ed.ogg"},{"id":"zh-Play_Vo_Char_NPC021_windfall_002","title":"Неожиданная добыча II","description":"Приятный сюрприз.","language":"Китайский","audioUrl":"/nte-meta/game-audio/fa622808b875c6c15cbc.ogg"},{"id":"en-Play_Vo_Char_NPC021_QTE_001","title":"Атака на входе I","description":"Всё предрешено.","language":"Английский","audioUrl":"/nte-meta/game-audio/42c2bb617b00850fa387.ogg"},{"id":"en-Play_Vo_Char_NPC021_about_004","title":"О Меруле","description":"Чем ближе я становлюсь к ней, тем сильнее ощущаю неведомый мне прежде покой, словно… я вернулась в объятия матери. Я не была хорошим ребёнком. Я скиталась веками, не зная её. Но ещё не поздно. Её кровь всё ещё горяча, её глаза видят этот новый мир через мои, и каждое мгновение, что потеряла Мерула, я верну ей.","language":"Английский","audioUrl":"/nte-meta/game-audio/98811cb0369f7717b97a.ogg"},{"id":"ko-Play_Vo_Char_NPC021_QTE_002","title":"Атака на входе II","description":"Покайтесь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/93ea6ed61a6f2d367388.ogg"},{"id":"zh-Play_Vo_Char_NPC021_weather_001","title":"Солнечно","description":"Солнце сияет ярко — прямо как твоё будущее.","language":"Китайский","audioUrl":"/nte-meta/game-audio/89d1e5c4f5bf13e68122.ogg"},{"id":"ja-Play_Vo_Char_NPC021_dead_002","title":"Потеря сознания II","description":"Неужели… всё закончится здесь?..","language":"Японский","audioUrl":"/nte-meta/game-audio/471e1fe658d97a7cf86f.ogg"},{"id":"ja-Play_Vo_Char_NPC021_skill02_002","title":"Навык перенаправления VIII","description":"Падите в безмолвии.","language":"Японский","audioUrl":"/nte-meta/game-audio/34cafb8890d0909cf25a.ogg"},{"id":"ja-Play_Vo_Char_NPC021_talk_003","title":"Тема: звёздное небо","description":"Когда мир ещё не обрёл форму, звёзды уже записали судьбу всего сущего. Над завесой ночи каждая нить звёздного света — видимая и незримая, — каждое мерцание, каждая пылинка шепчут о сокрытом. Именно в них таятся разгадки судеб всего живого.","language":"Японский","audioUrl":"/nte-meta/game-audio/0a1a9ffb825afc2432e7.ogg"},{"id":"ko-Play_Vo_Char_NPC021_hobby_001","title":"Хобби","description":"Умение покупать товары со скидкой по самой выгодной цене — это целое искусство! Нужно знать точное время акций, размер максимальных скидок, какие именно товары распродают, и распланировать бюджет ещё до выхода из дома… Е-если тебе интересно, я могла бы поделиться с тобой своей тактикой закупок…","language":"Корейский","audioUrl":"/nte-meta/game-audio/50d0ac8f11df18d21e1b.ogg"},{"id":"ko-Play_Vo_Char_NPC021_windfall_001","title":"Неожиданная добыча I","description":"Добрый знак.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b34c18f0f97ea2998b03.ogg"},{"id":"zh-Play_Vo_Char_NPC021_about_004","title":"О Меруле","description":"Чем ближе я становлюсь к ней, тем сильнее ощущаю неведомый мне прежде покой, словно… я вернулась в объятия матери. Я не была хорошим ребёнком. Я скиталась веками, не зная её. Но ещё не поздно. Её кровь всё ещё горяча, её глаза видят этот новый мир через мои, и каждое мгновение, что потеряла Мерула, я верну ей.","language":"Китайский","audioUrl":"/nte-meta/game-audio/6ae615d81207b3628114.ogg"},{"id":"en-Play_Vo_Char_NPC021_greet_001","title":"Утреннее приветствие","description":"Доброе утро, сегодня удача на твоей стороне.","language":"Английский","audioUrl":"/nte-meta/game-audio/b4a86c8a90e2b1528c75.ogg"},{"id":"en-Play_Vo_Char_NPC021_hp_003","title":"Низкий уровень здоровья III","description":"Мне нужно отдохнуть…","language":"Английский","audioUrl":"/nte-meta/game-audio/f4031de10c2a3f12246f.ogg"},{"id":"ja-Play_Vo_Char_NPC021_ultraskill_UI_002","title":"Сверхспособность II","description":"Внемлите отголоскам погибели.","language":"Японский","audioUrl":"/nte-meta/game-audio/0441bf40aedfee7375c7.ogg"},{"id":"ko-Play_Vo_Char_NPC021_vexation_001","title":"Проблемы","description":"Стоит мне взяться за работу, как сразу голова кругом. Я больше не могу удерживать человеческий облик…","language":"Корейский","audioUrl":"/nte-meta/game-audio/88607bd6f7ceacfcab24.ogg"}]'))) WHERE character_id='blackbird' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-22 22:24:48');

