UPDATE character_profiles SET voice_actors_json=json('[{"language":"Китайский","name":"陈彦亦"},{"language":"Английский","name":"Natalie Van Sistine"},{"language":"Японский","name":"大原さやか"},{"language":"Корейский","name":"이명호"},{"language":"Китайский","name":"Chen Yanyi (陈彦亦)"},{"language":"Японский","name":"Sayaka Ohara (大原さやか)"},{"language":"Корейский","name":"Lee Myeongho (이명호)"}]') WHERE character_id='daffodill' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-17 22:04:33');

UPDATE character_profiles SET voice_lines_json=json('[{"id":"zh-Play_Vo_Char_NPC013_dead_001","title":"Потеря сознания I","description":"Прости… Я тебя подвела…","language":"Китайский","audioUrl":"/nte-meta/game-audio/cb459505a7b4aee71dea.ogg"},{"id":"zh-Play_Vo_Char_NPC013_gift_003","title":"Подарок получен III","description":"Спасибо за старания.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e5f7e54cd05353950416.ogg"},{"id":"zh-Play_Vo_Char_NPC013_windfall_006","title":"Неожиданная добыча VI","description":"Как раз то, что нам нужно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/47a4619acf98cb9800f8.ogg"},{"id":"en-Play_Vo_Char_NPC013_gift_001","title":"Подарок получен I","description":"Кажется, я тебе ещё не говорила, но… мне очень нравится. Спасибо.","language":"Английский","audioUrl":"/nte-meta/game-audio/d96f1315ec8476a4fba9.ogg"},{"id":"ja-Play_Vo_Char_NPC013_about_003","title":"О Наналли","description":"Эта девчонка постоянно подсматривает за мной, когда я тренируюсь. Я несколько раз её ловила, но она просто находит другое место и продолжает… Что ж, пока она мне не мешает, пусть.","language":"Японский","audioUrl":"/nte-meta/game-audio/53021b2e2289a0734280.ogg"},{"id":"ja-Play_Vo_Char_NPC013_ug_003","title":"Вознесение персонажа III","description":"Таким образом, твоя безопасность гарантирована.","language":"Японский","audioUrl":"/nte-meta/game-audio/b7d3d3c9e46a9db28771.ogg"},{"id":"ko-Play_Vo_Char_NPC013_about_004","title":"О Занку","description":"Она очень опасна. По возможности лучше избегать любого контакта с ней.","language":"Корейский","audioUrl":"/nte-meta/game-audio/3c0ba84289aab2d02bee.ogg"},{"id":"ko-Play_Vo_Char_NPC013_DodgeCombo_001","title":"Серия критических уклонений I","description":"Двигаешься как попало.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a8bff90b65c0d10c9c3a.ogg"},{"id":"ko-Play_Vo_Char_NPC013_hp_002","title":"Низкий уровень здоровья II","description":"Не волнуйся.","language":"Корейский","audioUrl":"/nte-meta/game-audio/cf02871a154342abd826.ogg"},{"id":"ko-Play_Vo_Char_NPC013_SSC_004","title":"Особое переключение — Наналли","description":"Отличная работа.","language":"Корейский","audioUrl":"/nte-meta/game-audio/40c2a988561ccfb4732c.ogg"},{"id":"ko-Play_Vo_Char_NPC013_ug_001","title":"Вознесение персонажа I","description":"Упорный труд приносит результат.","language":"Корейский","audioUrl":"/nte-meta/game-audio/8dee4ea00eba1a5d5461.ogg"},{"id":"en-Play_Vo_Char_NPC013_deploy_001","title":"Отправка I","description":"Новое поручение?","language":"Английский","audioUrl":"/nte-meta/game-audio/d65567e3816a53dab1c2.ogg"},{"id":"ja-Play_Vo_Char_NPC013_Switch_002","title":"Переключение II","description":"Предоставь это мне.","language":"Японский","audioUrl":"/nte-meta/game-audio/aa2ca5232603a1142fbb.ogg"},{"id":"ko-Play_Vo_Char_NPC013_self_001","title":"Обо мне: способности эспера","description":"Просто обмен на часть моего зрения, не сильно влияет на повседневную жизнь. Иногда слышишь больше, чем видишь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/984383897f7584c09416.ogg"},{"id":"ja-Play_Vo_Char_NPC013_greet_003","title":"Вечернее приветствие","description":"Мы можем ещё немного потренироваться. Хочешь присоединиться?","language":"Японский","audioUrl":"/nte-meta/game-audio/8da4369b67ee7942a2eb.ogg"},{"id":"ko-Play_Vo_Char_NPC013_QTE_003","title":"Атака на входе III","description":"Передача завершена.","language":"Корейский","audioUrl":"/nte-meta/game-audio/8a8b080e03e96654d42f.ogg"},{"id":"zh-Play_Vo_Char_NPC013_about_004","title":"О Занку","description":"Она очень опасна. По возможности лучше избегать любого контакта с ней.","language":"Китайский","audioUrl":"/nte-meta/game-audio/956b60729125728129ac.ogg"},{"id":"zh-Play_Vo_Char_NPC013_SSC_005","title":"Особое переключение — Эдгар","description":"Передохни немного.","language":"Китайский","audioUrl":"/nte-meta/game-audio/db7b034380310a25072c.ogg"},{"id":"ja-Play_Vo_Char_NPC013_about_006","title":"Об антикварном магазине Эйбон","description":"«Эйбон» не похож на те места, к которым я привыкла. Здесь приходится иметь дело со сложными клиентами, чтобы заработать на жизнь, и твои друзья все время здесь, от них столько шума… но, по крайней мере, я могу спать, ни о чем не волнуясь.","language":"Японский","audioUrl":"/nte-meta/game-audio/c3a4fc703eafeab43a4f.ogg"},{"id":"ja-Play_Vo_Char_NPC013_TeammateDown_002","title":"Поражен товарищ по команде – Адлер","description":"Это ещё не конец.","language":"Японский","audioUrl":"/nte-meta/game-audio/ca531fe8cf33d9ccb582.ogg"},{"id":"ko-Play_Vo_Char_NPC013_TeammateDown_004","title":"Поражен товарищ по команде – Наналли","description":"Ты сделал всё, что мог, остальное оставь мне.","language":"Корейский","audioUrl":"/nte-meta/game-audio/09a8b0fe7db9f9fb3132.ogg"},{"id":"ko-Play_Vo_Char_NPC013_TeammateDown_005","title":"Поражён товарищ по команде — Занку","description":"Похоже, тебе всё ещё без меня никуда.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4b2c17d1d4d39f452c14.ogg"},{"id":"en-Play_Vo_Char_NPC013_anomaly_003","title":"Нуллификация II","description":"Кризис предотвращён.","language":"Английский","audioUrl":"/nte-meta/game-audio/536d8551b68d977ab886.ogg"},{"id":"en-Play_Vo_Char_NPC013_vexation_001","title":"Проблемы","description":"С некоторыми клиентами сложнее, чем с аномалиями, но Хотори говорит, нужно всегда улыбаться ради благополучия «Эйбона»… А? Думаешь, процент успешно выполненных поручений в последнее время снизился? Кхм… это совершенно не так.","language":"Английский","audioUrl":"/nte-meta/game-audio/17a02b586d7ede0346fd.ogg"},{"id":"ja-Play_Vo_Char_NPC013_gift_002","title":"Подарок получен II","description":"Для меня это бесценно. Огромное спасибо.","language":"Японский","audioUrl":"/nte-meta/game-audio/608a50cfa752e6212209.ogg"},{"id":"ja-Play_Vo_Char_NPC013_ug_001","title":"Вознесение персонажа I","description":"Упорный труд приносит результат.","language":"Японский","audioUrl":"/nte-meta/game-audio/3e61bdbc721d5526e580.ogg"},{"id":"ko-Play_Vo_Char_NPC013_Switch_003","title":"Переключение III","description":"Вот я.","language":"Корейский","audioUrl":"/nte-meta/game-audio/bd409b0ab0831d5b0a2f.ogg"},{"id":"zh-Play_Vo_Char_NPC013_self_001","title":"Обо мне: способности эспера","description":"Просто обмен на часть моего зрения, не сильно влияет на повседневную жизнь. Иногда слышишь больше, чем видишь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2f6b151bc0f26b67fb59.ogg"},{"id":"en-Play_Vo_Char_NPC013_about_004","title":"О Занку","description":"Она очень опасна. По возможности лучше избегать любого контакта с ней.","language":"Английский","audioUrl":"/nte-meta/game-audio/192668190c800764a543.ogg"},{"id":"en-Play_Vo_Char_NPC013_self_001","title":"Обо мне: способности эспера","description":"Просто обмен на часть моего зрения, не сильно влияет на повседневную жизнь. Иногда слышишь больше, чем видишь.","language":"Английский","audioUrl":"/nte-meta/game-audio/83fb29b3383b5504bcab.ogg"},{"id":"ko-Play_Vo_Char_NPC013_hstruck_002","title":"Сильный урон II","description":"Опять.","language":"Корейский","audioUrl":"/nte-meta/game-audio/290a4f71a70bad689429.ogg"},{"id":"zh-Play_Vo_Char_NPC013_aoe_UI_002","title":"Сверхспособность II","description":"Перед тобой иллюзия!","language":"Китайский","audioUrl":"/nte-meta/game-audio/22d1af9f97ed93b7b071.ogg"},{"id":"zh-Play_Vo_Char_NPC013_skill_SE_001","title":"Навык перенаправления IV","description":"Тщетная попытка.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e2cad0f57ef5b4145819.ogg"},{"id":"zh-Play_Vo_Char_NPC013_ug_001","title":"Вознесение персонажа I","description":"Упорный труд приносит результат.","language":"Китайский","audioUrl":"/nte-meta/game-audio/968fdee97f32306514b2.ogg"},{"id":"en-Play_Vo_Char_NPC013_hstruck_002","title":"Сильный урон II","description":"Опять.","language":"Английский","audioUrl":"/nte-meta/game-audio/1c2d66e23d1ea9f27021.ogg"},{"id":"en-Play_Vo_Char_NPC013_talk_002","title":"Тема: тренировки","description":"Я не считаю ежедневные тренировки утомительными. Без боли не бывает результата, так? Единственный способ не облажаться — стать сильнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/21fa62a7e3bba12c8d52.ogg"},{"id":"en-Play_Vo_Char_NPC013_windfall_005","title":"Неожиданная добыча V","description":"Приятный сюрприз.","language":"Английский","audioUrl":"/nte-meta/game-audio/7574122bc108f4c8dd01.ogg"},{"id":"ko-Play_Vo_Char_NPC013_fh_001","title":"Исцеление I","description":"Спасибо.","language":"Корейский","audioUrl":"/nte-meta/game-audio/51744a992cab7dc81ac2.ogg"},{"id":"ko-Play_Vo_Char_NPC013_hstruck_001","title":"Сильный урон I","description":"Просто царапина.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4b8f1d3513c9df0a2521.ogg"},{"id":"zh-Play_Vo_Char_NPC013_kill_002","title":"Убийство II","description":"Какая хрупкость.","language":"Китайский","audioUrl":"/nte-meta/game-audio/216d7df77115460231b5.ogg"},{"id":"zh-Play_Vo_Char_NPC013_SSC_004","title":"Особое переключение — Наналли","description":"Отличная работа.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a5f1f5f000fcf440c58a.ogg"},{"id":"zh-Play_Vo_Char_NPC013_weather_001","title":"Солнечно","description":"Хорошая погода. Время потренироваться на свежем воздухе.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d14d317d3709ca66e2ca.ogg"},{"id":"en-Play_Vo_Char_NPC013_Switch_003","title":"Переключение III","description":"Вот я.","language":"Английский","audioUrl":"/nte-meta/game-audio/e8254507a681ac9264f6.ogg"},{"id":"ja-Play_Vo_Char_NPC013_dead_001","title":"Потеря сознания I","description":"Прости… Я тебя подвела…","language":"Японский","audioUrl":"/nte-meta/game-audio/061984ae9edb7f29fbaa.ogg"},{"id":"ko-Play_Vo_Char_NPC013_TeammateDown_001","title":"Поражен товарищ по команде – Хотори","description":"Ты пожалеешь об этом.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ba86803f1e0901475eeb.ogg"},{"id":"zh-Play_Vo_Char_NPC013_containment_002","title":"Сдерживание II","description":"Сдерживание завершено.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7f767047bf23308b0e66.ogg"},{"id":"en-Play_Vo_Char_NPC013_skill_002","title":"Навык перенаправления II","description":"Никакой пощады!","language":"Английский","audioUrl":"/nte-meta/game-audio/afc35431f8dc9ec61380.ogg"},{"id":"en-Play_Vo_Char_NPC013_ug_002","title":"Вознесение персонажа II","description":"Я могу стать сильнее.","language":"Английский","audioUrl":"/nte-meta/game-audio/0a97594c9ed07429b4b8.ogg"},{"id":"en-Play_Vo_Char_NPC013_windfall_001","title":"Неожиданная добыча I","description":"Давай отнесем это обратно в «Эйбон».","language":"Английский","audioUrl":"/nte-meta/game-audio/a8d6a651d9a455c997d0.ogg"},{"id":"ja-Play_Vo_Char_NPC013_about_002","title":"О Хотори: первая встреча","description":"Когда мы впервые встретились, она была пьяна. Я просто решила, что она какая-то странная женщина. Но почему‑то… рядом с ней было так спокойно, и я ей доверилась. Полагаю, поэтому я сейчас здесь.","language":"Японский","audioUrl":"/nte-meta/game-audio/6af0117d6842e2060dbc.ogg"},{"id":"ja-Play_Vo_Char_NPC013_fh_002","title":"Исцеление II","description":"Восстанавливаю силы.","language":"Японский","audioUrl":"/nte-meta/game-audio/4a000560fef101aa3a10.ogg"},{"id":"ja-Play_Vo_Char_NPC013_gift_001","title":"Подарок получен I","description":"Кажется, я тебе ещё не говорила, но… мне очень нравится. Спасибо.","language":"Японский","audioUrl":"/nte-meta/game-audio/e6315d2d0f5eab4b6d89.ogg"},{"id":"ja-Play_Vo_Char_NPC013_Parry_001","title":"Парирование I","description":"Предсказуемо.","language":"Японский","audioUrl":"/nte-meta/game-audio/ee657dae8002ff73f891.ogg"},{"id":"ko-Play_Vo_Char_NPC013_Fly_002","title":"Планирование II","description":"Аааа…","language":"Корейский","audioUrl":"/nte-meta/game-audio/41172c10c805417862fd.ogg"},{"id":"zh-Play_Vo_Char_NPC013_QTE_001","title":"Атака на входе I","description":"Цель захвачена.","language":"Китайский","audioUrl":"/nte-meta/game-audio/cd3e473e95a915c1834d.ogg"},{"id":"zh-Play_Vo_Char_NPC013_skill_SE_002","title":"Навык перенаправления V","description":"Приговор!","language":"Китайский","audioUrl":"/nte-meta/game-audio/c64086ee2d7c978f4fb1.ogg"},{"id":"en-Play_Vo_Char_NPC013_Parry_002","title":"Парирование II","description":"Будь начеку.","language":"Английский","audioUrl":"/nte-meta/game-audio/dd6564e6cc89e387e94f.ogg"},{"id":"ja-Play_Vo_Char_NPC013_ug_002","title":"Вознесение персонажа II","description":"Я могу стать сильнее.","language":"Японский","audioUrl":"/nte-meta/game-audio/bca3cfc22bf9c847f5d2.ogg"},{"id":"zh-Play_Vo_Char_NPC013_about_003","title":"О Наналли","description":"Эта девчонка постоянно подсматривает за мной, когда я тренируюсь. Я несколько раз её ловила, но она просто находит другое место и продолжает… Что ж, пока она мне не мешает, пусть.","language":"Китайский","audioUrl":"/nte-meta/game-audio/4f5fb37a909371a799ab.ogg"},{"id":"zh-Play_Vo_Char_NPC013_self_003","title":"Обо мне: имя","description":"Похоже, это означает «нарцисс». На каждом стебле распускается только один цветок. Хотори сказала, что он есть в озере возле моего дома, хотя я его никогда не видела. Если можно, я бы предпочла, чтобы вы называли меня Даффодил, а не… кхм.","language":"Китайский","audioUrl":"/nte-meta/game-audio/362d59c42c9f2360b90b.ogg"},{"id":"en-Play_Vo_Char_NPC013_SSC_004","title":"Особое переключение — Наналли","description":"Отличная работа.","language":"Английский","audioUrl":"/nte-meta/game-audio/a09eb4374dc39ef89081.ogg"},{"id":"en-Play_Vo_Char_NPC013_windfall_006","title":"Неожиданная добыча VI","description":"Как раз то, что нам нужно.","language":"Английский","audioUrl":"/nte-meta/game-audio/04e1ff97fe6ffb50a37f.ogg"},{"id":"ja-Play_Vo_Char_NPC013_skill_003","title":"Навык перенаправления III","description":"Зачистка!","language":"Японский","audioUrl":"/nte-meta/game-audio/97a935c8d7c128c09ee6.ogg"},{"id":"ja-Play_Vo_Char_NPC013_vexation_001","title":"Проблемы","description":"С некоторыми клиентами сложнее, чем с аномалиями, но Хотори говорит, нужно всегда улыбаться ради благополучия «Эйбона»… А? Думаешь, процент успешно выполненных поручений в последнее время снизился? Кхм… это совершенно не так.","language":"Японский","audioUrl":"/nte-meta/game-audio/9c9e92d661f7c5adc19c.ogg"},{"id":"ko-Play_Vo_Char_NPC013_aoe_UI_002","title":"Сверхспособность II","description":"Перед тобой иллюзия!","language":"Корейский","audioUrl":"/nte-meta/game-audio/97173f803e3446bf9b1e.ogg"},{"id":"ko-Play_Vo_Char_NPC013_deploy_001","title":"Отправка I","description":"Новое поручение?","language":"Корейский","audioUrl":"/nte-meta/game-audio/8a1f396fb3db1b0b2c92.ogg"},{"id":"ja-Play_Vo_Char_NPC013_aoe_UI_002","title":"Сверхспособность II","description":"Перед тобой иллюзия!","language":"Японский","audioUrl":"/nte-meta/game-audio/c16c1bfd0d058438cde5.ogg"},{"id":"ko-Play_Vo_Char_NPC013_gift_004","title":"Подарок получен IV","description":"Хотори сказала, что подарки от друзей нужно принимать с радостью. Что ж… я с радостью его принимаю.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e6750f909c03c261ed83.ogg"},{"id":"ko-Play_Vo_Char_NPC013_skill_SE_003","title":"Навык перенаправления VI","description":"Ничто не устоит перед моим клинком!","language":"Корейский","audioUrl":"/nte-meta/game-audio/fc1daae49d752a831339.ogg"},{"id":"zh-Play_Vo_Char_NPC013_meet_001","title":"Первая встреча","description":"Привет, я Даффодил, телохранитель Хотори… Слишком просто? Извини, беседы — не мой конек. Если что-то понадобится, обращайся в антикварный магазин «Эйбон».","language":"Китайский","audioUrl":"/nte-meta/game-audio/70ca48e1a092f691e284.ogg"},{"id":"en-Play_Vo_Char_NPC013_about_005","title":"Об Адлере","description":"Адлер — весьма уважаемый человек. До того, как я встретила Хотори, он всегда был рядом с ней. Мне предстоит многому у него научиться.","language":"Английский","audioUrl":"/nte-meta/game-audio/0505c00d1eeea0e3ed57.ogg"},{"id":"en-Play_Vo_Char_NPC013_self_003","title":"Обо мне: имя","description":"Похоже, это означает «нарцисс». На каждом стебле распускается только один цветок. Хотори сказала, что он есть в озере возле моего дома, хотя я его никогда не видела. Если можно, я бы предпочла, чтобы вы называли меня Даффодил, а не… кхм.","language":"Английский","audioUrl":"/nte-meta/game-audio/2cf209c9a80b8004e791.ogg"},{"id":"ja-Play_Vo_Char_NPC013_anomaly_002","title":"Нуллификация I","description":"Готово.","language":"Японский","audioUrl":"/nte-meta/game-audio/0f5c67bf9d6bb310aed8.ogg"},{"id":"ja-Play_Vo_Char_NPC013_self_001","title":"Обо мне: способности эспера","description":"Просто обмен на часть моего зрения, не сильно влияет на повседневную жизнь. Иногда слышишь больше, чем видишь.","language":"Японский","audioUrl":"/nte-meta/game-audio/3e4400a7c2ab4ba620ca.ogg"},{"id":"ko-Play_Vo_Char_NPC013_deploy_002","title":"Отправка II","description":"Ожидаю приказов.","language":"Корейский","audioUrl":"/nte-meta/game-audio/913032592f676ba15277.ogg"},{"id":"en-Play_Vo_Char_NPC013_Parry_001","title":"Парирование I","description":"Предсказуемо.","language":"Английский","audioUrl":"/nte-meta/game-audio/79cba6cef3d206ae98d6.ogg"},{"id":"en-Play_Vo_Char_NPC013_talk_001","title":"Тема: аномалии","description":"Истина нередко прячется среди лжи. И люди, и аномалии — не то, чем кажутся на первый взгляд. Одного лишь «смотреть» недостаточно. Нужно понимать, чувствовать и анализировать. Лишь когда ты смотришь на всё как через калейдоскоп, с множества ракурсов… ты сможешь постичь саму истину.","language":"Английский","audioUrl":"/nte-meta/game-audio/0bc21156b83bbf5041c1.ogg"},{"id":"en-Play_Vo_Char_NPC013_windfall_004","title":"Неожиданная добыча IV","description":"Береги это.","language":"Английский","audioUrl":"/nte-meta/game-audio/26533d2d56beefcbcc77.ogg"},{"id":"ko-Play_Vo_Char_NPC013_greet_004","title":"Спокойной ночи","description":"Отдыхай, ночью «Эйбон» в безопасности.","language":"Корейский","audioUrl":"/nte-meta/game-audio/df2bc68aab87db24a1af.ogg"},{"id":"zh-Play_Vo_Char_NPC013_chat_003","title":"Чат: приветствия","description":"Уважаемый клиент… добро… добро пожаловать. Ш-ш.","language":"Китайский","audioUrl":"/nte-meta/game-audio/faf326c20892fc6edfeb.ogg"},{"id":"en-Play_Vo_Char_NPC013_containment_001","title":"Сдерживание I","description":"Нужно сопровождение в Бюро?","language":"Английский","audioUrl":"/nte-meta/game-audio/c76b851cb97c0a2b14ce.ogg"},{"id":"en-Play_Vo_Char_NPC013_meet_001","title":"Первая встреча","description":"Привет, я Даффодил, телохранитель Хотори… Слишком просто? Извини, беседы — не мой конек. Если что-то понадобится, обращайся в антикварный магазин «Эйбон».","language":"Английский","audioUrl":"/nte-meta/game-audio/bd853b9c65a8e9ea05e9.ogg"},{"id":"ja-Play_Vo_Char_NPC013_chat_003","title":"Чат: приветствия","description":"Уважаемый клиент… добро… добро пожаловать. Ш-ш.","language":"Японский","audioUrl":"/nte-meta/game-audio/f22859fed6a711075d4c.ogg"},{"id":"ja-Play_Vo_Char_NPC013_weather_001","title":"Солнечно","description":"Хорошая погода. Время потренироваться на свежем воздухе.","language":"Японский","audioUrl":"/nte-meta/game-audio/010702a97d73156f5b45.ogg"},{"id":"ko-Play_Vo_Char_NPC013_skill_001","title":"Навык перенаправления I","description":"Я это предвидела!","language":"Корейский","audioUrl":"/nte-meta/game-audio/0c67809f7c343566cae3.ogg"},{"id":"en-Play_Vo_Char_NPC013_kill_002","title":"Убийство II","description":"Какая хрупкость.","language":"Английский","audioUrl":"/nte-meta/game-audio/419ade85fb48a7499f1d.ogg"},{"id":"ja-Play_Vo_Char_NPC013_about_004","title":"О Занку","description":"Она очень опасна. По возможности лучше избегать любого контакта с ней.","language":"Японский","audioUrl":"/nte-meta/game-audio/22bcbed66b7da731f0a8.ogg"},{"id":"ja-Play_Vo_Char_NPC013_aoe_UI_001","title":"Сверхспособность I","description":"Негде спрятаться!","language":"Японский","audioUrl":"/nte-meta/game-audio/96a8680b3efd5c5399c7.ogg"},{"id":"ja-Play_Vo_Char_NPC013_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Передохни немного, оценщик.Передохни немного, оценщица.","language":"Японский","audioUrl":"/nte-meta/game-audio/0792f2a34fbd5e22cec9.ogg"},{"id":"ko-Play_Vo_Char_NPC013_containment_002","title":"Сдерживание II","description":"Сдерживание завершено.","language":"Корейский","audioUrl":"/nte-meta/game-audio/271e758970cdaa78a026.ogg"},{"id":"en-Play_Vo_Char_NPC013_about_002","title":"О Хотори: первая встреча","description":"Когда мы впервые встретились, она была пьяна. Я просто решила, что она какая-то странная женщина. Но почему‑то… рядом с ней было так спокойно, и я ей доверилась. Полагаю, поэтому я сейчас здесь.","language":"Английский","audioUrl":"/nte-meta/game-audio/b159f851c3329688f754.ogg"},{"id":"ja-Play_Vo_Char_NPC013_weather_003","title":"Холодно","description":"Холод сковывает тело и притупляет чувства… В такой момент, наверное, охотник и добыча могут поменяться местами.","language":"Японский","audioUrl":"/nte-meta/game-audio/6a6094d91a20a2a950d0.ogg"},{"id":"ja-Play_Vo_Char_NPC013_windfall_002","title":"Неожиданная добыча II","description":"Когда-нибудь пригодится.","language":"Японский","audioUrl":"/nte-meta/game-audio/908965474e1dfe036d94.ogg"},{"id":"ko-Play_Vo_Char_NPC013_gift_003","title":"Подарок получен III","description":"Спасибо за старания.","language":"Корейский","audioUrl":"/nte-meta/game-audio/85ae58e75aff351f7017.ogg"},{"id":"ko-Play_Vo_Char_NPC013_hp_001","title":"Низкий уровень здоровья I","description":"Я в порядке.","language":"Корейский","audioUrl":"/nte-meta/game-audio/04956d04db7fff4be431.ogg"},{"id":"ko-Play_Vo_Char_NPC013_struck_002","title":"Урон II","description":"Без проблем.","language":"Корейский","audioUrl":"/nte-meta/game-audio/53374b4bba947b1cf762.ogg"},{"id":"ko-Play_Vo_Char_NPC013_TeammateDown_003","title":"Поражен товарищ по команде – Сакири","description":"Я отведу тебя назад.","language":"Корейский","audioUrl":"/nte-meta/game-audio/25fbd2d18a0faa71f3e5.ogg"},{"id":"zh-Play_Vo_Char_NPC013_about_006","title":"Об антикварном магазине Эйбон","description":"«Эйбон» не похож на те места, к которым я привыкла. Здесь приходится иметь дело со сложными клиентами, чтобы заработать на жизнь, и твои друзья все время здесь, от них столько шума… но, по крайней мере, я могу спать, ни о чем не волнуясь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/433f484d23f769297268.ogg"},{"id":"zh-Play_Vo_Char_NPC013_aoe_UI_003","title":"Сверхспособность III","description":"Тысяча глаз… Пробуждение.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a781764184f1d6a4ff67.ogg"},{"id":"zh-Play_Vo_Char_NPC013_deploy_002","title":"Отправка II","description":"Ожидаю приказов.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e91fc2afe53f39b00e96.ogg"},{"id":"zh-Play_Vo_Char_NPC013_windfall_005","title":"Неожиданная добыча V","description":"Приятный сюрприз.","language":"Китайский","audioUrl":"/nte-meta/game-audio/26ae4bfe06be7b80215e.ogg"},{"id":"en-Play_Vo_Char_NPC013_about_003","title":"О Наналли","description":"Эта девчонка постоянно подсматривает за мной, когда я тренируюсь. Я несколько раз её ловила, но она просто находит другое место и продолжает… Что ж, пока она мне не мешает, пусть.","language":"Английский","audioUrl":"/nte-meta/game-audio/3cb3adaf8e94975d05ba.ogg"},{"id":"ja-Play_Vo_Char_NPC013_DodgeCombo_001","title":"Серия критических уклонений I","description":"Двигаешься как попало.","language":"Японский","audioUrl":"/nte-meta/game-audio/6d791f6cfed6d6983e5b.ogg"},{"id":"ja-Play_Vo_Char_NPC013_Fly_002","title":"Планирование II","description":"Аааа…","language":"Японский","audioUrl":"/nte-meta/game-audio/495f5d3cff171fbd072b.ogg"},{"id":"ja-Play_Vo_Char_NPC013_Switch_003","title":"Переключение III","description":"Вот я.","language":"Японский","audioUrl":"/nte-meta/game-audio/c9f755872b121411fa61.ogg"},{"id":"ko-Play_Vo_Char_NPC013_QTE_002","title":"Атака на входе II","description":"Есть.","language":"Корейский","audioUrl":"/nte-meta/game-audio/176e9b746a1189244df3.ogg"},{"id":"zh-Play_Vo_Char_NPC013_about_001","title":"О Хотори: проблемы","description":"Знаю, Хотори готова на все, чтобы получить желаемое, в том числе пойти на любые риски. Но иногда она немного перегибает палку… Что ж, думаю, мне есть, куда стремиться.","language":"Китайский","audioUrl":"/nte-meta/game-audio/6b9791750ed4a7da7487.ogg"},{"id":"zh-Play_Vo_Char_NPC013_SSC_003","title":"Особое переключение — Сакири","description":"Я разберусь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/24cb0e7a0459cc357d1e.ogg"},{"id":"zh-Play_Vo_Char_NPC013_Switch_003","title":"Переключение III","description":"Вот я.","language":"Китайский","audioUrl":"/nte-meta/game-audio/899d6cbb9d91daf78f6f.ogg"},{"id":"ko-Play_Vo_Char_NPC013_containment_001","title":"Сдерживание I","description":"Нужно сопровождение в Бюро?","language":"Корейский","audioUrl":"/nte-meta/game-audio/2ce11a93f0d72ce27164.ogg"},{"id":"ko-Play_Vo_Char_NPC013_TeammateDown_007","title":"Поражен товарищ по команде – Ноль","description":"Я тебя не брошу.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6fbac0109025850e2e9c.ogg"},{"id":"zh-Play_Vo_Char_NPC013_Switch_001","title":"Переключение I","description":"Я займусь этим.","language":"Китайский","audioUrl":"/nte-meta/game-audio/49433e27048ab85716f4.ogg"},{"id":"zh-Play_Vo_Char_NPC013_weather_003","title":"Холодно","description":"Холод сковывает тело и притупляет чувства… В такой момент, наверное, охотник и добыча могут поменяться местами.","language":"Китайский","audioUrl":"/nte-meta/game-audio/2f02ee35d053ddfb82c2.ogg"},{"id":"zh-Play_Vo_Char_NPC013_windfall_001","title":"Неожиданная добыча I","description":"Давай отнесем это обратно в «Эйбон».","language":"Китайский","audioUrl":"/nte-meta/game-audio/6c5337a9a4d0c05ba58d.ogg"},{"id":"en-Play_Vo_Char_NPC013_gift_004","title":"Подарок получен IV","description":"Хотори сказала, что подарки от друзей нужно принимать с радостью. Что ж… я с радостью его принимаю.","language":"Английский","audioUrl":"/nte-meta/game-audio/5a2043fc366ddc61195e.ogg"},{"id":"en-Play_Vo_Char_NPC013_hp_002","title":"Низкий уровень здоровья II","description":"Не волнуйся.","language":"Английский","audioUrl":"/nte-meta/game-audio/396ccea78488b80f4d7e.ogg"},{"id":"en-Play_Vo_Char_NPC013_SSC_005","title":"Особое переключение — Эдгар","description":"Передохни немного.","language":"Английский","audioUrl":"/nte-meta/game-audio/8a19551b77196c706e50.ogg"},{"id":"ja-Play_Vo_Char_NPC013_Fly_001","title":"Планирование I","description":"Это место…","language":"Японский","audioUrl":"/nte-meta/game-audio/1d8944e6774dbea52795.ogg"},{"id":"ja-Play_Vo_Char_NPC013_hobby_001","title":"Хобби","description":"Не могу сказать, что у меня есть какие-то предпочтения, еда нужна мне просто для выживания. Прессованные конфеты легко носить с собой, и они дают много энергии, так что они всегда со мной на всякий случай. А их вкус для меня не особо важен.","language":"Японский","audioUrl":"/nte-meta/game-audio/2a1d85ff2d6c0e84ddaf.ogg"},{"id":"ja-Play_Vo_Char_NPC013_skill_SE_002","title":"Навык перенаправления V","description":"Приговор!","language":"Японский","audioUrl":"/nte-meta/game-audio/46bb51689f0cb0dd8dd6.ogg"},{"id":"ko-Play_Vo_Char_NPC013_about_005","title":"Об Адлере","description":"Адлер — весьма уважаемый человек. До того, как я встретила Хотори, он всегда был рядом с ней. Мне предстоит многому у него научиться.","language":"Корейский","audioUrl":"/nte-meta/game-audio/dc3a641ba310b77b22ac.ogg"},{"id":"ko-Play_Vo_Char_NPC013_SSC_002","title":"Особое переключение — Адлер","description":"Берегите себя.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1c3051362b27c05e8156.ogg"},{"id":"ko-Play_Vo_Char_NPC013_TeammateDown_002","title":"Поражен товарищ по команде – Адлер","description":"Это ещё не конец.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ba5166ca4f07f29a97b2.ogg"},{"id":"ko-Play_Vo_Char_NPC013_ug_002","title":"Вознесение персонажа II","description":"Я могу стать сильнее.","language":"Корейский","audioUrl":"/nte-meta/game-audio/1c795b5f48b5e469ce0f.ogg"},{"id":"zh-Play_Vo_Char_NPC013_TeammateDown_002","title":"Поражен товарищ по команде – Адлер","description":"Это ещё не конец.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e77da1e46e40ceda1180.ogg"},{"id":"en-Play_Vo_Char_NPC013_TeammateDown_004","title":"Поражен товарищ по команде – Наналли","description":"Ты сделал всё, что мог, остальное оставь мне.","language":"Английский","audioUrl":"/nte-meta/game-audio/c3fc69453fdd92bd7ad7.ogg"},{"id":"ko-Play_Vo_Char_NPC013_weather_003","title":"Холодно","description":"Холод сковывает тело и притупляет чувства… В такой момент, наверное, охотник и добыча могут поменяться местами.","language":"Корейский","audioUrl":"/nte-meta/game-audio/7a3ffe8062a2efd5e428.ogg"},{"id":"en-Play_Vo_Char_NPC013_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Передохни немного, оценщик.Передохни немного, оценщица.","language":"Английский","audioUrl":"/nte-meta/game-audio/fd31314bde483bb89564.ogg"},{"id":"ja-Play_Vo_Char_NPC013_talk_001","title":"Тема: аномалии","description":"Истина нередко прячется среди лжи. И люди, и аномалии — не то, чем кажутся на первый взгляд. Одного лишь «смотреть» недостаточно. Нужно понимать, чувствовать и анализировать. Лишь когда ты смотришь на всё как через калейдоскоп, с множества ракурсов… ты сможешь постичь саму истину.","language":"Японский","audioUrl":"/nte-meta/game-audio/734f883c1d7ec3d5c73c.ogg"},{"id":"ja-Play_Vo_Char_NPC013_TeammateDown_007","title":"Поражен товарищ по команде – Ноль","description":"Я тебя не брошу.","language":"Японский","audioUrl":"/nte-meta/game-audio/6fcc0233961412fc030c.ogg"},{"id":"ko-Play_Vo_Char_NPC013_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Передохни немного, оценщик.Передохни немного, оценщица.","language":"Корейский","audioUrl":"/nte-meta/game-audio/110868a74e0af9e5cb42.ogg"},{"id":"zh-Play_Vo_Char_NPC013_hp_003","title":"Низкий уровень здоровья III","description":"Это… вообще неважно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/60ae7425cdf8217b556c.ogg"},{"id":"zh-Play_Vo_Char_NPC013_TeammateDown_007","title":"Поражен товарищ по команде – Ноль","description":"Я тебя не брошу.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f120057dc60ee1ad7f85.ogg"},{"id":"en-Play_Vo_Char_NPC013_anomaly_002","title":"Нуллификация I","description":"Готово.","language":"Английский","audioUrl":"/nte-meta/game-audio/0ee84fb6442ff30d8652.ogg"},{"id":"en-Play_Vo_Char_NPC013_Fly_001","title":"Планирование I","description":"Это место…","language":"Английский","audioUrl":"/nte-meta/game-audio/95e9153621bf445c1830.ogg"},{"id":"en-Play_Vo_Char_NPC013_Switch_002","title":"Переключение II","description":"Предоставь это мне.","language":"Английский","audioUrl":"/nte-meta/game-audio/c88096865d943214dbc1.ogg"},{"id":"en-Play_Vo_Char_NPC013_TeammateDown_006","title":"Поражен товарищ по команде – Эдгар","description":"Не переживай, я возьму это на себя.","language":"Английский","audioUrl":"/nte-meta/game-audio/67fbbf8d67c56f8070e0.ogg"},{"id":"ja-Play_Vo_Char_NPC013_self_002","title":"Обо мне: темные цвета","description":"Интересно, почему я все время в темной одежде..? Не потому, что мне нравится, а потому что она лучше скрывает раны и обманывает врагов.","language":"Японский","audioUrl":"/nte-meta/game-audio/37dd6d87c8d5cc430c5b.ogg"},{"id":"ja-Play_Vo_Char_NPC013_self_003","title":"Обо мне: имя","description":"Похоже, это означает «нарцисс». На каждом стебле распускается только один цветок. Хотори сказала, что он есть в озере возле моего дома, хотя я его никогда не видела. Если можно, я бы предпочла, чтобы вы называли меня Даффодил, а не… кхм.","language":"Японский","audioUrl":"/nte-meta/game-audio/8acb781d32b58a049045.ogg"},{"id":"ja-Play_Vo_Char_NPC013_SSC_004","title":"Особое переключение — Наналли","description":"Отличная работа.","language":"Японский","audioUrl":"/nte-meta/game-audio/c4ee663978608902deb1.ogg"},{"id":"zh-Play_Vo_Char_NPC013_chat_001","title":"Чат: отдых","description":"Займись чем-нибудь. Сидеть без движения вредно для здоровья.","language":"Китайский","audioUrl":"/nte-meta/game-audio/14e97fbf15146f304ecd.ogg"},{"id":"en-Play_Vo_Char_NPC013_dead_002","title":"Потеря сознания II","description":"Если я чем-то могу помочь…","language":"Английский","audioUrl":"/nte-meta/game-audio/e78d65098ebc2fe16a9b.ogg"},{"id":"en-Play_Vo_Char_NPC013_hstruck_001","title":"Сильный урон I","description":"Просто царапина.","language":"Английский","audioUrl":"/nte-meta/game-audio/d1ae843848237bd936e0.ogg"},{"id":"en-Play_Vo_Char_NPC013_skill_003","title":"Навык перенаправления III","description":"Зачистка!","language":"Английский","audioUrl":"/nte-meta/game-audio/713bc0a6d2534fabb916.ogg"},{"id":"ja-Play_Vo_Char_NPC013_hstruck_002","title":"Сильный урон II","description":"Опять.","language":"Японский","audioUrl":"/nte-meta/game-audio/2b71eab3f702882a5087.ogg"},{"id":"ja-Play_Vo_Char_NPC013_skill_SE_001","title":"Навык перенаправления IV","description":"Тщетная попытка.","language":"Японский","audioUrl":"/nte-meta/game-audio/da1da48cb68a1728829b.ogg"},{"id":"ko-Play_Vo_Char_NPC013_about_001","title":"О Хотори: проблемы","description":"Знаю, Хотори готова на все, чтобы получить желаемое, в том числе пойти на любые риски. Но иногда она немного перегибает палку… Что ж, думаю, мне есть, куда стремиться.","language":"Корейский","audioUrl":"/nte-meta/game-audio/bbaf5662422e5e71c12c.ogg"},{"id":"ko-Play_Vo_Char_NPC013_Fly_001","title":"Планирование I","description":"Это место…","language":"Корейский","audioUrl":"/nte-meta/game-audio/0a6b7f13c8b78f4e2f01.ogg"},{"id":"zh-Play_Vo_Char_NPC013_containment_001","title":"Сдерживание I","description":"Нужно сопровождение в Бюро?","language":"Китайский","audioUrl":"/nte-meta/game-audio/b53561d272cfb0bd6d63.ogg"},{"id":"zh-Play_Vo_Char_NPC013_QTE_002","title":"Атака на входе II","description":"Есть.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5a2c91354a2003073c76.ogg"},{"id":"zh-Play_Vo_Char_NPC013_TeammateDown_005","title":"Поражён товарищ по команде — Занку","description":"Похоже, тебе всё ещё без меня никуда.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f40c4b6b69ebd02cbfaa.ogg"},{"id":"zh-Play_Vo_Char_NPC013_windfall_002","title":"Неожиданная добыча II","description":"Когда-нибудь пригодится.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b2f521c8aa74a0c6702e.ogg"},{"id":"en-Play_Vo_Char_NPC013_chat_002","title":"Чат: оружие","description":"Даже лучшему оружию требуется регулярная заточка, чтобы сохранять остроту, то же касается и людей.","language":"Английский","audioUrl":"/nte-meta/game-audio/e85f5bee01901b8f97f6.ogg"},{"id":"en-Play_Vo_Char_NPC013_greet_001","title":"Утреннее приветствие","description":"Доброе утро, какие планы на сегодня?","language":"Английский","audioUrl":"/nte-meta/game-audio/c2cb1b3614a99ba864a6.ogg"},{"id":"ja-Play_Vo_Char_NPC013_chat_001","title":"Чат: отдых","description":"Займись чем-нибудь. Сидеть без движения вредно для здоровья.","language":"Японский","audioUrl":"/nte-meta/game-audio/a275f41d0775aeec49ac.ogg"},{"id":"ja-Play_Vo_Char_NPC013_containment_002","title":"Сдерживание II","description":"Сдерживание завершено.","language":"Японский","audioUrl":"/nte-meta/game-audio/10ca7abcdf84dfc500d5.ogg"},{"id":"ja-Play_Vo_Char_NPC013_DodgeCombo_002","title":"Серия критических уклонений II","description":"Ты, похоже, вообще не умеешь сдаваться.","language":"Японский","audioUrl":"/nte-meta/game-audio/416c8a433842e96eb505.ogg"},{"id":"ko-Play_Vo_Char_NPC013_talk_002","title":"Тема: тренировки","description":"Я не считаю ежедневные тренировки утомительными. Без боли не бывает результата, так? Единственный способ не облажаться — стать сильнее.","language":"Корейский","audioUrl":"/nte-meta/game-audio/8f99622312355d321ae1.ogg"},{"id":"ko-Play_Vo_Char_NPC013_windfall_004","title":"Неожиданная добыча IV","description":"Береги это.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c36cda81a1c34a3487e1.ogg"},{"id":"zh-Play_Vo_Char_NPC013_windfall_003","title":"Неожиданная добыча III","description":"Хорошо иметь успехи.","language":"Китайский","audioUrl":"/nte-meta/game-audio/7e7f859cfbabf1bba372.ogg"},{"id":"en-Play_Vo_Char_NPC013_DodgeCombo_002","title":"Серия критических уклонений II","description":"Ты, похоже, вообще не умеешь сдаваться.","language":"Английский","audioUrl":"/nte-meta/game-audio/77000384238c66225f62.ogg"},{"id":"en-Play_Vo_Char_NPC013_greet_004","title":"Спокойной ночи","description":"Отдыхай, ночью «Эйбон» в безопасности.","language":"Английский","audioUrl":"/nte-meta/game-audio/15dd8fdb6ffccdecdd70.ogg"},{"id":"en-Play_Vo_Char_NPC013_hp_001","title":"Низкий уровень здоровья I","description":"Я в порядке.","language":"Английский","audioUrl":"/nte-meta/game-audio/6cc4340f258f29a43993.ogg"},{"id":"en-Play_Vo_Char_NPC013_QTE_003","title":"Атака на входе III","description":"Передача завершена.","language":"Английский","audioUrl":"/nte-meta/game-audio/6262260cbe37b39da0f7.ogg"},{"id":"ko-Play_Vo_Char_NPC013_greet_002","title":"Дневное приветствие","description":"Если хочется спать, вздремни. Я тебя разбужу.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a235911021efc7dc325b.ogg"},{"id":"zh-Play_Vo_Char_NPC013_gift_004","title":"Подарок получен IV","description":"Хотори сказала, что подарки от друзей нужно принимать с радостью. Что ж… я с радостью его принимаю.","language":"Китайский","audioUrl":"/nte-meta/game-audio/93e1ed539e1bac1fd27e.ogg"},{"id":"zh-Play_Vo_Char_NPC013_Parry_001","title":"Парирование I","description":"Предсказуемо.","language":"Китайский","audioUrl":"/nte-meta/game-audio/eb750e21a1a3b0856549.ogg"},{"id":"zh-Play_Vo_Char_NPC013_QTE_003","title":"Атака на входе III","description":"Передача завершена.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b65958c810228a1b0225.ogg"},{"id":"en-Play_Vo_Char_NPC013_containment_002","title":"Сдерживание II","description":"Сдерживание завершено.","language":"Английский","audioUrl":"/nte-meta/game-audio/d2f868df4c0c427f3b3a.ogg"},{"id":"en-Play_Vo_Char_NPC013_self_002","title":"Обо мне: темные цвета","description":"Интересно, почему я все время в темной одежде..? Не потому, что мне нравится, а потому что она лучше скрывает раны и обманывает врагов.","language":"Английский","audioUrl":"/nte-meta/game-audio/8d951e40e9481f6c8b82.ogg"},{"id":"ja-Play_Vo_Char_NPC013_dead_002","title":"Потеря сознания II","description":"Если я чем-то могу помочь…","language":"Японский","audioUrl":"/nte-meta/game-audio/5230b817ecd489f13d85.ogg"},{"id":"ko-Play_Vo_Char_NPC013_hp_003","title":"Низкий уровень здоровья III","description":"Это… вообще неважно.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c51a0ee1e3e33b222f15.ogg"},{"id":"zh-Play_Vo_Char_NPC013_SSC_ZERO_001","title":"Особое переключение — Ноль","description":"Передохни немного, оценщик.Передохни немного, оценщица.","language":"Китайский","audioUrl":"/nte-meta/game-audio/78e360ab2b8b6ed24c84.ogg"},{"id":"zh-Play_Vo_Char_NPC013_ug_003","title":"Вознесение персонажа III","description":"Таким образом, твоя безопасность гарантирована.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e5bbded97c8a74e11709.ogg"},{"id":"zh-Play_Vo_Char_NPC013_vexation_001","title":"Проблемы","description":"С некоторыми клиентами сложнее, чем с аномалиями, но Хотори говорит, нужно всегда улыбаться ради благополучия «Эйбона»… А? Думаешь, процент успешно выполненных поручений в последнее время снизился? Кхм… это совершенно не так.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5e533d16ce8fb8224d03.ogg"},{"id":"ja-Play_Vo_Char_NPC013_anomaly_003","title":"Нуллификация II","description":"Кризис предотвращён.","language":"Японский","audioUrl":"/nte-meta/game-audio/b4dd06aea7e2d4e80570.ogg"},{"id":"ja-Play_Vo_Char_NPC013_skill_002","title":"Навык перенаправления II","description":"Никакой пощады!","language":"Японский","audioUrl":"/nte-meta/game-audio/c7699f9df595d05a74dd.ogg"},{"id":"ja-Play_Vo_Char_NPC013_SSC_005","title":"Особое переключение — Эдгар","description":"Передохни немного.","language":"Японский","audioUrl":"/nte-meta/game-audio/c524e576b6ddb2df88c9.ogg"},{"id":"ko-Play_Vo_Char_NPC013_hobby_001","title":"Хобби","description":"Не могу сказать, что у меня есть какие-то предпочтения, еда нужна мне просто для выживания. Прессованные конфеты легко носить с собой, и они дают много энергии, так что они всегда со мной на всякий случай. А их вкус для меня не особо важен.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d4e61f295478f9de9da5.ogg"},{"id":"zh-Play_Vo_Char_NPC013_ug_002","title":"Вознесение персонажа II","description":"Я могу стать сильнее.","language":"Китайский","audioUrl":"/nte-meta/game-audio/52f15bd22cc8042035fc.ogg"},{"id":"en-Play_Vo_Char_NPC013_aoe_UI_003","title":"Сверхспособность III","description":"Тысяча глаз… Пробуждение.","language":"Английский","audioUrl":"/nte-meta/game-audio/4898992271fb2f0902ce.ogg"},{"id":"ko-Play_Vo_Char_NPC013_about_002","title":"О Хотори: первая встреча","description":"Когда мы впервые встретились, она была пьяна. Я просто решила, что она какая-то странная женщина. Но почему‑то… рядом с ней было так спокойно, и я ей доверилась. Полагаю, поэтому я сейчас здесь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5c8d983430b50905beb7.ogg"},{"id":"zh-Play_Vo_Char_NPC013_gift_001","title":"Подарок получен I","description":"Кажется, я тебе ещё не говорила, но… мне очень нравится. Спасибо.","language":"Китайский","audioUrl":"/nte-meta/game-audio/9216f44d6dc1d9ef5194.ogg"},{"id":"zh-Play_Vo_Char_NPC013_kill_001","title":"Убийство I","description":"Аннигилировать.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a26ccfb68ba0199497c7.ogg"},{"id":"zh-Play_Vo_Char_NPC013_TeammateDown_003","title":"Поражен товарищ по команде – Сакири","description":"Я отведу те