UPDATE character_profiles SET voice_lines_json=json('[{"id":"zh-Play_Vo_Char_NPC028_ug_003","title":"Вознесение персонажа III","description":"Пожалуй, это мой предел… Спасибо за помощь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/61489fb891f75762f16b.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Switch_001","title":"Переключение I","description":"А, уже моя очередь?","language":"Японский","audioUrl":"/nte-meta/game-audio/bff55f7b7a7bae196beb.ogg"},{"id":"ja-Play_Vo_Char_NPC028_windfall_001","title":"Неожиданная добыча I","description":"Как неожиданно!","language":"Японский","audioUrl":"/nte-meta/game-audio/76ac509b6825b41b45af.ogg"},{"id":"en-Play_Vo_Char_NPC028_ug_001","title":"Вознесение персонажа I","description":"Я буду стараться дальше!","language":"Английский","audioUrl":"/nte-meta/game-audio/094a504c2e9bc9272d76.ogg"},{"id":"ja-Play_Vo_Char_NPC028_ug_003","title":"Вознесение персонажа III","description":"Пожалуй, это мой предел… Спасибо за помощь.","language":"Японский","audioUrl":"/nte-meta/game-audio/8ecf421a78072ca2ccbc.ogg"},{"id":"zh-Play_Vo_Char_NPC028_dead_002","title":"Потеря сознания II","description":"Мне… можно наконец вернуться?","language":"Китайский","audioUrl":"/nte-meta/game-audio/fca7ea7c3b06589a4856.ogg"},{"id":"zh-Play_Vo_Char_NPC028_QTE_001","title":"Атака на входе I","description":"Вперёд!","language":"Китайский","audioUrl":"/nte-meta/game-audio/a5bb52a9649ee636d49d.ogg"},{"id":"en-Play_Vo_Char_NPC028_TeammateDown_002","title":"Поражён товарищ по команде – Шинку","description":"Ох, ну вот опять…","language":"Английский","audioUrl":"/nte-meta/game-audio/08c7cd49a226da53cd10.ogg"},{"id":"ja-Play_Vo_Char_NPC028_QTE_001","title":"Атака на входе I","description":"Вперёд!","language":"Японский","audioUrl":"/nte-meta/game-audio/2eb252bbf99b06df1cc6.ogg"},{"id":"ja-Play_Vo_Char_NPC028_SSC_ZH_002","title":"Особое переключение — Шинку","description":"Ой-ой, Шинку, неужели ты сама с этим не справишься?","language":"Японский","audioUrl":"/nte-meta/game-audio/bb2d9a9522dd81acacdd.ogg"},{"id":"ko-Play_Vo_Char_NPC028_about_003","title":"О Шинку II","description":"Сейчас мы в ладах. Эта скептичная дракониха просто меня не так поняла. По крайней мере, Минт говорит, что мы с Шинку теперь «души не чаем» друг в друге!","language":"Корейский","audioUrl":"/nte-meta/game-audio/fe47df0f102e0dc3bd7c.ogg"},{"id":"zh-Play_Vo_Char_NPC028_hstruck_002","title":"Сильный урон II","description":"Я поранилась…","language":"Китайский","audioUrl":"/nte-meta/game-audio/430b31108bf1e3ca7c1b.ogg"},{"id":"zh-Play_Vo_Char_NPC028_kill_001","title":"Убийство I","description":"Ой, забыла попрощаться!","language":"Китайский","audioUrl":"/nte-meta/game-audio/5ccb77523ff31d1480d8.ogg"},{"id":"en-Play_Vo_Char_NPC028_SSC_ZH_002","title":"Особое переключение — Шинку","description":"Ой-ой, Шинку, неужели ты сама с этим не справишься?","language":"Английский","audioUrl":"/nte-meta/game-audio/4ac7a64c76bb8f8a5f01.ogg"},{"id":"en-Play_Vo_Char_NPC028_Switch_002","title":"Переключение II","description":"Ребятки, настало наше время сиять!","language":"Английский","audioUrl":"/nte-meta/game-audio/344686e29542c104cb8b.ogg"},{"id":"ja-Play_Vo_Char_NPC028_weather_001","title":"Солнечно","description":"Солнце светит, и цветы распускаются…","language":"Японский","audioUrl":"/nte-meta/game-audio/1466e0ecbe179f8d39d0.ogg"},{"id":"ko-Play_Vo_Char_NPC028_DodgeCombo_002","title":"Серия критических уклонений II","description":"Фух! Пронесло.","language":"Корейский","audioUrl":"/nte-meta/game-audio/071ec4813ce6492508a8.ogg"},{"id":"ko-Play_Vo_Char_NPC028_hp_003","title":"Низкий уровень здоровья III","description":"Тело. Болит.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ffe03b09de43e8e2d25d.ogg"},{"id":"ko-Play_Vo_Char_NPC028_self_001","title":"Обо мне: семья","description":"Родители очень меня любят и столько для меня сделали. Они просто хотят, чтобы я была счастлива. Я им очень благодарна, но иногда не могу отделаться от мысли… если бы на моем месте родился ребенок поздоровее…","language":"Корейский","audioUrl":"/nte-meta/game-audio/fd9b7d16e1593cad7845.ogg"},{"id":"zh-Play_Vo_Char_NPC028_self_004","title":"Обо… мне?","description":"Моё тело медленно разрушалось, но способность эспера позволила мне жить. Я — это не она. Она живёт вместо меня. Жива ли я до сих пор? Я… не знаю","language":"Китайский","audioUrl":"/nte-meta/game-audio/d1400c27497e1b41984c.ogg"},{"id":"en-Play_Vo_Char_NPC028_struck_001","title":"Урон I","description":"Ох!","language":"Английский","audioUrl":"/nte-meta/game-audio/7ffb21f2f7e533199fd2.ogg"},{"id":"en-Play_Vo_Char_NPC028_TeammateDown_001","title":"Поражен товарищ по команде – Минт","description":"Минт-сенпай потеряла сознание? Я разберусь!","language":"Английский","audioUrl":"/nte-meta/game-audio/a41845e86e0b52cd2c3c.ogg"},{"id":"en-Play_Vo_Char_NPC028_weather_004","title":"Жарко","description":"Хочу поскорее убраться от этого пекла.","language":"Английский","audioUrl":"/nte-meta/game-audio/729aed6113de87d0f539.ogg"},{"id":"ja-Play_Vo_Char_NPC028_containment_001","title":"Сдерживание I","description":"Слушай внимательно: оставайся здесь и ни в коем случае не убегай!","language":"Японский","audioUrl":"/nte-meta/game-audio/9185299fe0e92d16f440.ogg"},{"id":"ja-Play_Vo_Char_NPC028_windfall_005","title":"Неожиданная добыча V","description":"Я такого ещё не видела.","language":"Японский","audioUrl":"/nte-meta/game-audio/87e440b222cf898899c3.ogg"},{"id":"ko-Play_Vo_Char_NPC028_fh_002","title":"Исцеление II","description":"Я снова в деле!","language":"Корейский","audioUrl":"/nte-meta/game-audio/279069ec83d76e41616a.ogg"},{"id":"ko-Play_Vo_Char_NPC028_ug_001","title":"Вознесение персонажа I","description":"Я буду стараться дальше!","language":"Корейский","audioUrl":"/nte-meta/game-audio/a1d1b37263c86a54d25c.ogg"},{"id":"zh-Play_Vo_Char_NPC028_SSC_ZH_002","title":"Особое переключение — Шинку","description":"Ой-ой, Шинку, неужели ты сама с этим не справишься?","language":"Китайский","audioUrl":"/nte-meta/game-audio/0e6802a0348487884560.ogg"},{"id":"ja-Play_Vo_Char_NPC028_weather_002","title":"Дождливо","description":"У меня хвост промок…","language":"Японский","audioUrl":"/nte-meta/game-audio/092c1e0885ca62284097.ogg"},{"id":"ko-Play_Vo_Char_NPC028_kill_001","title":"Убийство I","description":"Ой, забыла попрощаться!","language":"Корейский","audioUrl":"/nte-meta/game-audio/1883db2ee851a31e58f5.ogg"},{"id":"zh-Play_Vo_Char_NPC028_greet_003","title":"Вечернее приветствие","description":"Вот и скрылся мистер Солнце.","language":"Китайский","audioUrl":"/nte-meta/game-audio/828b5a2bec580d1c88be.ogg"},{"id":"zh-Play_Vo_Char_NPC028_talk_003","title":"Тема: миры грёз","description":"Тебе нравится видеть сны? Хочешь взглянуть на мои? Только пройди через ворота с бычьими рогами. Если пройдёшь через ворота из слоновой кости — я не смогу тебя вытащить. Тебе придётся заново прожить весь путь: от эмбриона до нынешнего себя! Тебе нравится видеть сны? Хочешь взглянуть на мои? Только пройди через ворота с бычьими рогами. Если пройдёшь через ворота из слоновой кости — я не смогу тебя вытащить. Тебе придётся заново прожить весь путь: от эмбриона до нынешней себя!","language":"Китайский","audioUrl":"/nte-meta/game-audio/3d649516b166505d11c4.ogg"},{"id":"ja-Play_Vo_Char_NPC028_vexation_001","title":"Проблемы","description":"Мои ребятки — Морфей, Икел и Фантас — вечно влипают в неприятности. Интересно, есть ли способ удержать их в узде…","language":"Японский","audioUrl":"/nte-meta/game-audio/e500c1a9162eaceaa8d7.ogg"},{"id":"ja-Play_Vo_Char_NPC028_windfall_004","title":"Неожиданная добыча IV","description":"Морфей, ну-ка прекрати!","language":"Японский","audioUrl":"/nte-meta/game-audio/90e8ec68c65b3ea76457.ogg"},{"id":"ko-Play_Vo_Char_NPC028_hp_002","title":"Низкий уровень здоровья II","description":"Ноги совсем не слушаются.","language":"Корейский","audioUrl":"/nte-meta/game-audio/956c8426308431eb755f.ogg"},{"id":"ko-Play_Vo_Char_NPC028_Switch_002","title":"Переключение II","description":"Ребятки, настало наше время сиять!","language":"Корейский","audioUrl":"/nte-meta/game-audio/5d1ee3a820f16d62ddea.ogg"},{"id":"zh-Play_Vo_Char_NPC028_deploy_001","title":"Отправка I","description":"Ирой здесь — готова к бою!","language":"Китайский","audioUrl":"/nte-meta/game-audio/04ea0962e52072c66e7f.ogg"},{"id":"zh-Play_Vo_Char_NPC028_hp_003","title":"Низкий уровень здоровья III","description":"Тело. Болит.","language":"Китайский","audioUrl":"/nte-meta/game-audio/3f9416d83c4252ac2999.ogg"},{"id":"zh-Play_Vo_Char_NPC028_SSC_zero_003","title":"Особое переключение — Ноль","description":"Оценщик, я пришла на помощь! Оценщица, я пришла на помощь!","language":"Китайский","audioUrl":"/nte-meta/game-audio/7df420dc583fbb0c1206.ogg"},{"id":"en-Play_Vo_Char_NPC028_aoe_UI_003","title":"Сверхспособность III","description":"Приятных снов… Вернее, кошмаров!","language":"Английский","audioUrl":"/nte-meta/game-audio/92f229ad7f25ce4e8203.ogg"},{"id":"ko-Play_Vo_Char_NPC028_Fly_002","title":"Планирование II","description":"Ура!","language":"Корейский","audioUrl":"/nte-meta/game-audio/0f5c3dae27b791d9fe7f.ogg"},{"id":"ko-Play_Vo_Char_NPC028_skill_001","title":"Навык перенаправления I","description":"Время кошмара!","language":"Корейский","audioUrl":"/nte-meta/game-audio/710e3177dbc8e87b6acd.ogg"},{"id":"zh-Play_Vo_Char_NPC028_anomaly_003","title":"Нуллификация I","description":"Тех, кто не способен учиться, придётся нуллифицировать… Прости!","language":"Китайский","audioUrl":"/nte-meta/game-audio/092181eab98709d914fb.ogg"},{"id":"en-Play_Vo_Char_NPC028_greet_003","title":"Вечернее приветствие","description":"Вот и скрылся мистер Солнце.","language":"Английский","audioUrl":"/nte-meta/game-audio/1d065ed4ec5b5262aa42.ogg"},{"id":"en-Play_Vo_Char_NPC028_QTE_001","title":"Атака на входе I","description":"Вперёд!","language":"Английский","audioUrl":"/nte-meta/game-audio/9cd95c93d9d0f9685676.ogg"},{"id":"en-Play_Vo_Char_NPC028_windfall_002","title":"Неожиданная добыча II","description":"Класс!","language":"Английский","audioUrl":"/nte-meta/game-audio/d6107394f8d6b3182e25.ogg"},{"id":"en-Play_Vo_Char_NPC028_windfall_003","title":"Неожиданная добыча III","description":"Что за вкусняшки на этот раз?","language":"Английский","audioUrl":"/nte-meta/game-audio/270abf8aa2a4f4bcca6f.ogg"},{"id":"ja-Play_Vo_Char_NPC028_ug_002","title":"Вознесение персонажа II","description":"Хм… как далеко я смогу зайти?","language":"Японский","audioUrl":"/nte-meta/game-audio/96817bf97d87e04c5591.ogg"},{"id":"ko-Play_Vo_Char_NPC028_about_004","title":"О Наналли","description":"Наналли ведь немного младше меня, да? Я ей даже чуточку завидую — в её-то годы она уже точно знает, чего хочет от жизни!","language":"Корейский","audioUrl":"/nte-meta/game-audio/19d5a61859d51e2a6295.ogg"},{"id":"ko-Play_Vo_Char_NPC028_greet_002","title":"Дневное приветствие","description":"Пора вздремнуть.","language":"Корейский","audioUrl":"/nte-meta/game-audio/35399931b038cb62b0e6.ogg"},{"id":"zh-Play_Vo_Char_NPC028_windfall_002","title":"Неожиданная добыча II","description":"Класс!","language":"Китайский","audioUrl":"/nte-meta/game-audio/8c7fb6ef99437c416e90.ogg"},{"id":"ko-Play_Vo_Char_NPC028_Switch_001","title":"Переключение I","description":"А, уже моя очередь?","language":"Корейский","audioUrl":"/nte-meta/game-audio/c935ad63185bbba893e8.ogg"},{"id":"zh-Play_Vo_Char_NPC028_talk_001","title":"Тема: овцы","description":"Слышала, в некоторых культурах коз считают воплощением зла… Ребятки, а вы сами-то считаете себя плохишами? Ой, нет? Ребята, ложь только портит нашу репутацию!","language":"Китайский","audioUrl":"/nte-meta/game-audio/de434ac2b4b0c79389b0.ogg"},{"id":"ko-Play_Vo_Char_NPC028_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"А?.. Оценщика… одолели? А?.. Оценщицу… одолели?","language":"Корейский","audioUrl":"/nte-meta/game-audio/dd4ae2e95cb2379c06ad.ogg"},{"id":"zh-Play_Vo_Char_NPC028_meet_001","title":"Первая встреча","description":"Привет! Меня зовут Онейрой. Выговорить трудновато, так что зови просто Ирой! Если что понадобится — только дай знать. Увидимся!","language":"Китайский","audioUrl":"/nte-meta/game-audio/6ae824c424e6381d28db.ogg"},{"id":"zh-Play_Vo_Char_NPC028_self_003","title":"Обо мне: способность эспера","description":"Оболочка по имени Онейрой ожила лишь после пробуждения способности эспера. Но это не настоящая я, понимаешь? Настоящая я — та, что сейчас видит сон. А та, что говорит с тобой — лишь подделка, играющая роль «хорошей девочки»!","language":"Китайский","audioUrl":"/nte-meta/game-audio/5f246ccd81e60c664497.ogg"},{"id":"zh-Play_Vo_Char_NPC028_skill_003","title":"Навык перенаправления III","description":"Ребятки, по моей команде!","language":"Китайский","audioUrl":"/nte-meta/game-audio/1857dfa81b136cc65498.ogg"},{"id":"en-Play_Vo_Char_NPC028_about_003","title":"О Шинку II","description":"Сейчас мы в ладах. Эта скептичная дракониха просто меня не так поняла. По крайней мере, Минт говорит, что мы с Шинку теперь «души не чаем» друг в друге!","language":"Английский","audioUrl":"/nte-meta/game-audio/4aa58b7fb2d81f44e121.ogg"},{"id":"en-Play_Vo_Char_NPC028_chat_001","title":"Чат: пинать камушки","description":"Когда вижу мелкие камушки, прям тянет пнуть их… всё дальше и дальше, пока они не исчезнут там, где я их больше не увижу. Ты тоже так делаешь?","language":"Английский","audioUrl":"/nte-meta/game-audio/53b80f43f44c80dd7c7a.ogg"},{"id":"en-Play_Vo_Char_NPC028_Parry_002","title":"Парирование II","description":"Рука. Ноет.","language":"Английский","audioUrl":"/nte-meta/game-audio/61b047b468258eff6271.ogg"},{"id":"en-Play_Vo_Char_NPC028_self_003","title":"Обо мне: способность эспера","description":"Оболочка по имени Онейрой ожила лишь после пробуждения способности эспера. Но это не настоящая я, понимаешь? Настоящая я — та, что сейчас видит сон. А та, что говорит с тобой — лишь подделка, играющая роль «хорошей девочки»!","language":"Английский","audioUrl":"/nte-meta/game-audio/070209ace35025708e0e.ogg"},{"id":"en-Play_Vo_Char_NPC028_weather_002","title":"Дождливо","description":"У меня хвост промок…","language":"Английский","audioUrl":"/nte-meta/game-audio/f58584a759e66cb539dd.ogg"},{"id":"zh-Play_Vo_Char_NPC028_talk_002","title":"Тема: комната","description":"В детстве я проводила кучу времени в больницах, потому что постоянно болела. Тогда я думала, что абсолютно все спят в белых кроватях под писк и тиканье этих медицинских аппаратов. Когда я рассказала об этом коллегам из благотворительного фонда, они решили, что я жила в комнате с привидениями!","language":"Китайский","audioUrl":"/nte-meta/game-audio/2163bf26e364a025afc9.ogg"},{"id":"zh-Play_Vo_Char_NPC028_Parry_002","title":"Парирование II","description":"Рука. Ноет.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f45761fa8ed53ce67d74.ogg"},{"id":"zh-Play_Vo_Char_NPC028_ug_002","title":"Вознесение персонажа II","description":"Хм… как далеко я смогу зайти?","language":"Китайский","audioUrl":"/nte-meta/game-audio/ee584ed421f8fe350151.ogg"},{"id":"en-Play_Vo_Char_NPC028_QTE_003","title":"Атака на входе III","description":"Прицел… Огонь!","language":"Английский","audioUrl":"/nte-meta/game-audio/a45b5ce4ffad6d9044b1.ogg"},{"id":"ko-Play_Vo_Char_NPC028_kill_002","title":"Убийство II","description":"Ого, неужели уже всё?","language":"Корейский","audioUrl":"/nte-meta/game-audio/1a6dbf7dc6f15cf01501.ogg"},{"id":"ko-Play_Vo_Char_NPC028_talk_002","title":"Тема: комната","description":"В детстве я проводила кучу времени в больницах, потому что постоянно болела. Тогда я думала, что абсолютно все спят в белых кроватях под писк и тиканье этих медицинских аппаратов. Когда я рассказала об этом коллегам из благотворительного фонда, они решили, что я жила в комнате с привидениями!","language":"Корейский","audioUrl":"/nte-meta/game-audio/21cd8fa087114e58417b.ogg"},{"id":"en-Play_Vo_Char_NPC028_anomaly_003","title":"Нуллификация I","description":"Тех, кто не способен учиться, придётся нуллифицировать… Прости!","language":"Английский","audioUrl":"/nte-meta/game-audio/adddf0528e860a9d04b6.ogg"},{"id":"ja-Play_Vo_Char_NPC028_chat_002","title":"Чат: школа","description":"Мои друзья вечно рассказывают что-то интересное про школу, а я училась дома, и у меня не было одноклассников. Жаль, что я так и не узнала, что такое настоящая школьная жизнь.","language":"Японский","audioUrl":"/nte-meta/game-audio/5d9f6ed936c6f3e40137.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Fly_001","title":"Планирование I","description":"Я что, правда лечу?..","language":"Японский","audioUrl":"/nte-meta/game-audio/93a4fbeb97e72141ddd9.ogg"},{"id":"zh-Play_Vo_Char_NPC028_greet_001","title":"Утреннее приветствие","description":"(Зевок) Доброе утро!","language":"Китайский","audioUrl":"/nte-meta/game-audio/3efd0ca2f56919b3c620.ogg"},{"id":"zh-Play_Vo_Char_NPC028_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"А?.. Оценщика… одолели? А?.. Оценщицу… одолели?","language":"Китайский","audioUrl":"/nte-meta/game-audio/d898392e753c65c21078.ogg"},{"id":"en-Play_Vo_Char_NPC028_about_004","title":"О Наналли","description":"Наналли ведь немного младше меня, да? Я ей даже чуточку завидую — в её-то годы она уже точно знает, чего хочет от жизни!","language":"Английский","audioUrl":"/nte-meta/game-audio/ee6cb2e429c2e48d9393.ogg"},{"id":"en-Play_Vo_Char_NPC028_Parry_001","title":"Парирование I","description":"Я смогла это парировать!","language":"Английский","audioUrl":"/nte-meta/game-audio/4581f6189e3e2935e6d0.ogg"},{"id":"en-Play_Vo_Char_NPC028_talk_001","title":"Тема: овцы","description":"Слышала, в некоторых культурах коз считают воплощением зла… Ребятки, а вы сами-то считаете себя плохишами? Ой, нет? Ребята, ложь только портит нашу репутацию!","language":"Английский","audioUrl":"/nte-meta/game-audio/bc1ccd32d09f654b0012.ogg"},{"id":"ja-Play_Vo_Char_NPC028_chat_001","title":"Чат: пинать камушки","description":"Когда вижу мелкие камушки, прям тянет пнуть их… всё дальше и дальше, пока они не исчезнут там, где я их больше не увижу. Ты тоже так делаешь?","language":"Японский","audioUrl":"/nte-meta/game-audio/a45c118e86808e163271.ogg"},{"id":"ko-Play_Vo_Char_NPC028_QTE_002","title":"Атака на входе II","description":"Ребятковый луч!","language":"Корейский","audioUrl":"/nte-meta/game-audio/4003745411ebfab9ff60.ogg"},{"id":"zh-Play_Vo_Char_NPC028_about_002","title":"О Шинку I","description":"После того как я затащила Шинку в свои сны, она начала меня ненавидеть. Ей не понравилось то, что я ей показала? Или… она о чём-то догадалась?","language":"Китайский","audioUrl":"/nte-meta/game-audio/4e47dd2274d90cec3532.ogg"},{"id":"en-Play_Vo_Char_NPC028_fh_001","title":"Исцеление I","description":"Глоток свежего воздуха!","language":"Английский","audioUrl":"/nte-meta/game-audio/68899d20dff67457fc6d.ogg"},{"id":"ja-Play_Vo_Char_NPC028_about_003","title":"О Шинку II","description":"Сейчас мы в ладах. Эта скептичная дракониха просто меня не так поняла. По крайней мере, Минт говорит, что мы с Шинку теперь «души не чаем» друг в друге!","language":"Японский","audioUrl":"/nte-meta/game-audio/8e5eaea6738acd963f91.ogg"},{"id":"ja-Play_Vo_Char_NPC028_hp_001","title":"Низкий уровень здоровья I","description":"Холодно… очень холодно…","language":"Японский","audioUrl":"/nte-meta/game-audio/98672fd07b013b0e4350.ogg"},{"id":"ko-Play_Vo_Char_NPC028_containment_001","title":"Сдерживание I","description":"Слушай внимательно: оставайся здесь и ни в коем случае не убегай!","language":"Корейский","audioUrl":"/nte-meta/game-audio/e28ae2ce60a7b721fb67.ogg"},{"id":"ko-Play_Vo_Char_NPC028_meet_001","title":"Первая встреча","description":"Привет! Меня зовут Онейрой. Выговорить трудновато, так что зови просто Ирой! Если что понадобится — только дай знать. Увидимся!","language":"Корейский","audioUrl":"/nte-meta/game-audio/bdafef2241e8e5c53b97.ogg"},{"id":"zh-Play_Vo_Char_NPC028_about_001","title":"О Минт","description":"У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взял? Я серьёзно! У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взяла? Я серьёзно!","language":"Китайский","audioUrl":"/nte-meta/game-audio/482b6cf9a0ef5d48ee43.ogg"},{"id":"zh-Play_Vo_Char_NPC028_gift_003","title":"Подарок получен III","description":"Я это ценю!","language":"Китайский","audioUrl":"/nte-meta/game-audio/4c03e8da12538db7b751.ogg"},{"id":"en-Play_Vo_Char_NPC028_windfall_006","title":"Неожиданная добыча VI","description":"Вау, а это можно взять с собой в сон?","language":"Английский","audioUrl":"/nte-meta/game-audio/322629b97b0fd6104c10.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Fly_002","title":"Планирование II","description":"Ура!","language":"Японский","audioUrl":"/nte-meta/game-audio/22f51c6542af19bd69a0.ogg"},{"id":"ko-Play_Vo_Char_NPC028_TeammateDown_002","title":"Поражён товарищ по команде – Шинку","description":"Ох, ну вот опять…","language":"Корейский","audioUrl":"/nte-meta/game-audio/0fc71ad7c1f7f061a16b.ogg"},{"id":"zh-Play_Vo_Char_NPC028_hstruck_001","title":"Сильный урон I","description":"Ай, ай, ай…","language":"Китайский","audioUrl":"/nte-meta/game-audio/57ca06ed214c52a9ef01.ogg"},{"id":"zh-Play_Vo_Char_NPC028_struck_001","title":"Урон I","description":"Ох!","language":"Китайский","audioUrl":"/nte-meta/game-audio/1e47fddecc9c7532fbfc.ogg"},{"id":"ja-Play_Vo_Char_NPC028_SSC_BH_001","title":"Особое переключение — Минт","description":"Минт-сенпай, я тут!","language":"Японский","audioUrl":"/nte-meta/game-audio/f638b2d435005d65bf1a.ogg"},{"id":"ko-Play_Vo_Char_NPC028_anomaly_003","title":"Нуллификация I","description":"Тех, кто не способен учиться, придётся нуллифицировать… Прости!","language":"Корейский","audioUrl":"/nte-meta/game-audio/66bb225a3bff204334df.ogg"},{"id":"ko-Play_Vo_Char_NPC028_Switch_003","title":"Переключение III","description":"А, я? Уже бегу!","language":"Корейский","audioUrl":"/nte-meta/game-audio/b6872e775c0aabc121d2.ogg"},{"id":"ko-Play_Vo_Char_NPC028_vexation_001","title":"Проблемы","description":"Мои ребятки — Морфей, Икел и Фантас — вечно влипают в неприятности. Интересно, есть ли способ удержать их в узде…","language":"Корейский","audioUrl":"/nte-meta/game-audio/ebe3995844e2fd90befa.ogg"},{"id":"en-Play_Vo_Char_NPC028_anomaly_004","title":"Нуллификация II","description":"Может, мы ещё увидимся.","language":"Английский","audioUrl":"/nte-meta/game-audio/138b6c4ecb7facce6529.ogg"},{"id":"en-Play_Vo_Char_NPC028_dead_001","title":"Потеря сознания I","description":"В этом небе… нет просветов.","language":"Английский","audioUrl":"/nte-meta/game-audio/4aa380b19655eb7d2e2e.ogg"},{"id":"ja-Play_Vo_Char_NPC028_dead_002","title":"Потеря сознания II","description":"Мне… можно наконец вернуться?","language":"Японский","audioUrl":"/nte-meta/game-audio/2e86902db44fbbeff081.ogg"},{"id":"ja-Play_Vo_Char_NPC028_weather_004","title":"Жарко","description":"Хочу поскорее убраться от этого пекла.","language":"Японский","audioUrl":"/nte-meta/game-audio/c6524458cdd7589a9c3f.ogg"},{"id":"ja-Play_Vo_Char_NPC028_windfall_003","title":"Неожиданная добыча III","description":"Что за вкусняшки на этот раз?","language":"Японский","audioUrl":"/nte-meta/game-audio/e60822a66d420b114e6f.ogg"},{"id":"ko-Play_Vo_Char_NPC028_greet_004","title":"Спокойной ночи","description":"Ночь. Пришла.","language":"Корейский","audioUrl":"/nte-meta/game-audio/60c755f420433a37c762.ogg"},{"id":"zh-Play_Vo_Char_NPC028_fh_002","title":"Исцеление II","description":"Я снова в деле!","language":"Китайский","audioUrl":"/nte-meta/game-audio/602899d0254f22f1e118.ogg"},{"id":"ja-Play_Vo_Char_NPC028_deploy_002","title":"Отправка II","description":"Я сделаю всё, что смогу!","language":"Японский","audioUrl":"/nte-meta/game-audio/da5d3b045dd9bb6ebe01.ogg"},{"id":"ja-Play_Vo_Char_NPC028_skill_002","title":"Навык перенаправления II","description":"Пора встава-а-ать!","language":"Японский","audioUrl":"/nte-meta/game-audio/beb41182da824d679728.ogg"},{"id":"ko-Play_Vo_Char_NPC028_anomaly_004","title":"Нуллификация II","description":"Может, мы ещё увидимся.","language":"Корейский","audioUrl":"/nte-meta/game-audio/e3bbc8172f8e93cc26a2.ogg"},{"id":"ja-Play_Vo_Char_NPC028_struck_001","title":"Урон I","description":"Ох!","language":"Японский","audioUrl":"/nte-meta/game-audio/d446f9e4fd7f41d2cdbe.ogg"},{"id":"ko-Play_Vo_Char_NPC028_QTE_001","title":"Атака на входе I","description":"Вперёд!","language":"Корейский","audioUrl":"/nte-meta/game-audio/ad3b3b56cf0ba9f06d5a.ogg"},{"id":"ko-Play_Vo_Char_NPC028_weather_001","title":"Солнечно","description":"Солнце светит, и цветы распускаются…","language":"Корейский","audioUrl":"/nte-meta/game-audio/4776904c67c8dfed7947.ogg"},{"id":"zh-Play_Vo_Char_NPC028_dead_003","title":"Потеря сознания III","description":"Снаружи… становится тихо.","language":"Китайский","audioUrl":"/nte-meta/game-audio/1af6d3401167cd40a4c2.ogg"},{"id":"en-Play_Vo_Char_NPC028_SSC_BH_001","title":"Особое переключение — Минт","description":"Минт-сенпай, я тут!","language":"Английский","audioUrl":"/nte-meta/game-audio/56efa91dc130b709a8be.ogg"},{"id":"ja-Play_Vo_Char_NPC028_about_001","title":"О Минт","description":"У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взял? Я серьёзно! У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взяла? Я серьёзно!","language":"Японский","audioUrl":"/nte-meta/game-audio/93085149fe0b46039c47.ogg"},{"id":"ja-Play_Vo_Char_NPC028_dead_003","title":"Потеря сознания III","description":"Снаружи… становится тихо.","language":"Японский","audioUrl":"/nte-meta/game-audio/80d81fe42f696e11bd2d.ogg"},{"id":"ja-Play_Vo_Char_NPC028_self_004","title":"Обо… мне?","description":"Моё тело медленно разрушалось, но способность эспера позволила мне жить. Я — это не она. Она живёт вместо меня. Жива ли я до сих пор? Я… не знаю","language":"Японский","audioUrl":"/nte-meta/game-audio/2801c4fafb42f3bf5ef3.ogg"},{"id":"ko-Play_Vo_Char_NPC028_hstruck_001","title":"Сильный урон I","description":"Ай, ай, ай…","language":"Корейский","audioUrl":"/nte-meta/game-audio/24751e1f1da1d0638494.ogg"},{"id":"ko-Play_Vo_Char_NPC028_Parry_002","title":"Парирование II","description":"Рука. Ноет.","language":"Корейский","audioUrl":"/nte-meta/game-audio/3085a9b6f436a554e0b9.ogg"},{"id":"ko-Play_Vo_Char_NPC028_self_002","title":"Обо мне: сон","description":"Кажется, я всегда спала. Даже когда бодра и полна сил, я всё равно блуждаю во сне!","language":"Корейский","audioUrl":"/nte-meta/game-audio/6f1e0e7f3c6de7b709c2.ogg"},{"id":"zh-Play_Vo_Char_NPC028_gift_001","title":"Подарок получен I","description":"О… ого! Мне очень нравится! Спасибо тебе большое!","language":"Китайский","audioUrl":"/nte-meta/game-audio/7c72f449115de2d7fc77.ogg"},{"id":"en-Play_Vo_Char_NPC028_SSC_zero_003","title":"Особое переключение — Ноль","description":"Оценщик, я пришла на помощь! Оценщица, я пришла на помощь!","language":"Английский","audioUrl":"/nte-meta/game-audio/9b68865cfdf22adbf320.ogg"},{"id":"en-Play_Vo_Char_NPC028_weather_003","title":"Холодно","description":"Я уже не чувствую ни рук, ни ног.","language":"Английский","audioUrl":"/nte-meta/game-audio/d5a29b09da43cf15c3e6.ogg"},{"id":"ja-Play_Vo_Char_NPC028_anomaly_004","title":"Нуллификация II","description":"Может, мы ещё увидимся.","language":"Японский","audioUrl":"/nte-meta/game-audio/f0657a7d39befb2fa56f.ogg"},{"id":"ja-Play_Vo_Char_NPC028_DodgeCombo_002","title":"Серия критических уклонений II","description":"Фух! Пронесло.","language":"Японский","audioUrl":"/nte-meta/game-audio/58e30d36bd65bd5763a0.ogg"},{"id":"en-Play_Vo_Char_NPC028_skill_003","title":"Навык перенаправления III","description":"Ребятки, по моей команде!","language":"Английский","audioUrl":"/nte-meta/game-audio/193733d25e88a027b85c.ogg"},{"id":"zh-Play_Vo_Char_NPC028_fh_001","title":"Исцеление I","description":"Глоток свежего воздуха!","language":"Китайский","audioUrl":"/nte-meta/game-audio/63939818738474e067b4.ogg"},{"id":"en-Play_Vo_Char_NPC028_greet_001","title":"Утреннее приветствие","description":"(Зевок) Доброе утро!","language":"Английский","audioUrl":"/nte-meta/game-audio/e7b6e58bbd23c6adcd79.ogg"},{"id":"ja-Play_Vo_Char_NPC028_aoe_UI_003","title":"Сверхспособность III","description":"Приятных снов… Вернее, кошмаров!","language":"Японский","audioUrl":"/nte-meta/game-audio/d6fc904cb4cd14031d74.ogg"},{"id":"ko-Play_Vo_Char_NPC028_ug_003","title":"Вознесение персонажа III","description":"Пожалуй, это мой предел… Спасибо за помощь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/78c11e7acc41b9fc082e.ogg"},{"id":"zh-Play_Vo_Char_NPC028_deploy_002","title":"Отправка II","description":"Я сделаю всё, что смогу!","language":"Китайский","audioUrl":"/nte-meta/game-audio/4997e7c00b0fafe5881f.ogg"},{"id":"en-Play_Vo_Char_NPC028_hp_001","title":"Низкий уровень здоровья I","description":"Холодно… очень холодно…","language":"Английский","audioUrl":"/nte-meta/game-audio/96ed00edc892c08fae49.ogg"},{"id":"en-Play_Vo_Char_NPC028_windfall_004","title":"Неожиданная добыча IV","description":"Морфей, ну-ка прекрати!","language":"Английский","audioUrl":"/nte-meta/game-audio/fc3e017515fd46ed3cbf.ogg"},{"id":"ko-Play_Vo_Char_NPC028_dead_003","title":"Потеря сознания III","description":"Снаружи… становится тихо.","language":"Корейский","audioUrl":"/nte-meta/game-audio/0ad5d42eb2d515b12e52.ogg"},{"id":"zh-Play_Vo_Char_NPC028_Switch_001","title":"Переключение I","description":"А, уже моя очередь?","language":"Китайский","audioUrl":"/nte-meta/game-audio/36a2ba61d4ecf4a8bd71.ogg"},{"id":"zh-Play_Vo_Char_NPC028_weather_001","title":"Солнечно","description":"Солнце светит, и цветы распускаются…","language":"Китайский","audioUrl":"/nte-meta/game-audio/62c89dd6a21eb6ff5af3.ogg"},{"id":"en-Play_Vo_Char_NPC028_fh_002","title":"Исцеление II","description":"Я снова в деле!","language":"Английский","audioUrl":"/nte-meta/game-audio/f6cfe04fac762460fe4d.ogg"},{"id":"en-Play_Vo_Char_NPC028_gift_003","title":"Подарок получен III","description":"Я это ценю!","language":"Английский","audioUrl":"/nte-meta/game-audio/3f71c2ca6db081fab951.ogg"},{"id":"en-Play_Vo_Char_NPC028_hp_002","title":"Низкий уровень здоровья II","description":"Ноги совсем не слушаются.","language":"Английский","audioUrl":"/nte-meta/game-audio/1d2b9160f0d4ce8d63a5.ogg"},{"id":"en-Play_Vo_Char_NPC028_Switch_001","title":"Переключение I","description":"А, уже моя очередь?","language":"Английский","audioUrl":"/nte-meta/game-audio/9efc6df77fdaae9df60d.ogg"},{"id":"en-Play_Vo_Char_NPC028_ug_002","title":"Вознесение персонажа II","description":"Хм… как далеко я смогу зайти?","language":"Английский","audioUrl":"/nte-meta/game-audio/cd2d6ef9bfa72706e12c.ogg"},{"id":"ja-Play_Vo_Char_NPC028_gift_004","title":"Подарок получен IV","description":"Какой классный подарок!","language":"Японский","audioUrl":"/nte-meta/game-audio/b612cb313e3c6ec2dc50.ogg"},{"id":"ja-Play_Vo_Char_NPC028_QTE_002","title":"Атака на входе II","description":"Ребятковый луч!","language":"Японский","audioUrl":"/nte-meta/game-audio/f8fb3f5ab2ba681a4885.ogg"},{"id":"ja-Play_Vo_Char_NPC028_ug_001","title":"Вознесение персонажа I","description":"Я буду стараться дальше!","language":"Японский","audioUrl":"/nte-meta/game-audio/80a09aa457d967310081.ogg"},{"id":"ko-Play_Vo_Char_NPC028_Parry_001","title":"Парирование I","description":"Я смогла это парировать!","language":"Корейский","audioUrl":"/nte-meta/game-audio/436984cc7d006024ddb6.ogg"},{"id":"zh-Play_Vo_Char_NPC028_chat_003","title":"Чат: теория эволюции","description":"«Естественный отбор — это выживание сильнейших…» — это всё, что моя учительница сказала о теории эволюции. Ей не пришлось объяснять: это был первый сон, который «я» увидела в своей жизни…","language":"Китайский","audioUrl":"/nte-meta/game-audio/0760d4f910cc8744a7f3.ogg"},{"id":"ja-Play_Vo_Char_NPC028_gift_001","title":"Подарок получен I","description":"О… ого! Мне очень нравится! Спасибо тебе большое!","language":"Японский","audioUrl":"/nte-meta/game-audio/8720df1fb63b75cee25b.ogg"},{"id":"ko-Play_Vo_Char_NPC028_about_001","title":"О Минт","description":"У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взял? Я серьёзно! У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взяла? Я серьёзно!","language":"Корейский","audioUrl":"/nte-meta/game-audio/685777535198c08ce18a.ogg"},{"id":"ko-Play_Vo_Char_NPC028_windfall_002","title":"Неожиданная добыча II","description":"Класс!","language":"Корейский","audioUrl":"/nte-meta/game-audio/4e455de12ee4ee46a0a8.ogg"},{"id":"ja-Play_Vo_Char_NPC028_about_002","title":"О Шинку I","description":"После того как я затащила Шинку в свои сны, она начала меня ненавидеть. Ей не понравилось то, что я ей показала? Или… она о чём-то догадалась?","language":"Японский","audioUrl":"/nte-meta/game-audio/8f4cf82c12e5312b0c5a.ogg"},{"id":"ja-Play_Vo_Char_NPC028_kill_001","title":"Убийство I","description":"Ой, забыла попрощаться!","language":"Японский","audioUrl":"/nte-meta/game-audio/841d32963eda6803d3a0.ogg"},{"id":"ja-Play_Vo_Char_NPC028_skill_001","title":"Навык перенаправления I","description":"Время кошмара!","language":"Японский","audioUrl":"/nte-meta/game-audio/a2a27f450f2487f33819.ogg"},{"id":"en-Play_Vo_Char_NPC028_about_002","title":"О Шинку I","description":"После того как я затащила Шинку в свои сны, она начала меня ненавидеть. Ей не понравилось то, что я ей показала? Или… она о чём-то догадалась?","language":"Английский","audioUrl":"/nte-meta/game-audio/67647672e01847b78718.ogg"},{"id":"en-Play_Vo_Char_NPC028_gift_004","title":"Подарок получен IV","description":"Какой классный подарок!","language":"Английский","audioUrl":"/nte-meta/game-audio/18a92a8bd7f4b716f537.ogg"},{"id":"ja-Play_Vo_Char_NPC028_DodgeCombo_001","title":"Серия критических уклонений I","description":"Хех, и как ты умудрился проглядеть?","language":"Японский","audioUrl":"/nte-meta/game-audio/504984a10c9ec443ba06.ogg"},{"id":"ko-Play_Vo_Char_NPC028_ug_002","title":"Вознесение персонажа II","description":"Хм… как далеко я смогу зайти?","language":"Корейский","audioUrl":"/nte-meta/game-audio/a60982f82d75b657958c.ogg"},{"id":"zh-Play_Vo_Char_NPC028_gift_002","title":"Подарок получен II","description":"Это мне? С радостью приму, спасибо!","language":"Китайский","audioUrl":"/nte-meta/game-audio/9520cef1b366626f805b.ogg"},{"id":"ja-Play_Vo_Char_NPC028_meet_001","title":"Первая встреча","description":"Привет! Меня зовут Онейрой. Выговорить трудновато, так что зови просто Ирой! Если что понадобится — только дай знать. Увидимся!","language":"Японский","audioUrl":"/nte-meta/game-audio/24e2f5ef76490d8ce8bf.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Switch_002","title":"Переключение II","description":"Ребятки, настало наше время сиять!","language":"Японский","audioUrl":"/nte-meta/game-audio/9ad783e4c9fa65d2f7ea.ogg"},{"id":"ja-Play_Vo_Char_NPC028_weather_003","title":"Холодно","description":"Я уже не чувствую ни рук, ни ног.","language":"Японский","audioUrl":"/nte-meta/game-audio/3b238d4f0c6f4a79e51e.ogg"},{"id":"ko-Play_Vo_Char_NPC028_deploy_001","title":"Отправка I","description":"Ирой здесь — готова к бою!","language":"Корейский","audioUrl":"/nte-meta/game-audio/1cc6f5e0676d98644901.ogg"},{"id":"ko-Play_Vo_Char_NPC028_windfall_004","title":"Неожиданная добыча IV","description":"Морфей, ну-ка прекрати!","language":"Корейский","audioUrl":"/nte-meta/game-audio/ab97ab23015697be35f0.ogg"},{"id":"zh-Play_Vo_Char_NPC028_Fly_001","title":"Планирование I","description":"Я что, правда лечу?..","language":"Китайский","audioUrl":"/nte-meta/game-audio/07df4440f0197b8a4a94.ogg"},{"id":"zh-Play_Vo_Char_NPC028_kill_002","title":"Убийство II","description":"Ого, неужели уже всё?","language":"Китайский","audioUrl":"/nte-meta/game-audio/09c43767bc2f7f36db36.ogg"},{"id":"en-Play_Vo_Char_NPC028_DodgeCombo_001","title":"Серия критических уклонений I","description":"Хех, и как ты умудрился проглядеть?","language":"Английский","audioUrl":"/nte-meta/game-audio/3611b2861143ac5969b8.ogg"},{"id":"en-Play_Vo_Char_NPC028_TeammateDown_003","title":"Поражен товарищ по команде – Ноль","description":"А?.. Оценщика… одолели? А?.. Оценщицу… одолели?","language":"Английский","audioUrl":"/nte-meta/game-audio/2793d29b90341c516d29.ogg"},{"id":"ja-Play_Vo_Char_NPC028_dead_001","title":"Потеря сознания I","description":"В этом небе… нет просветов.","language":"Японский","audioUrl":"/nte-meta/game-audio/ac5f1258d0352545c936.ogg"},{"id":"ko-Play_Vo_Char_NPC028_struck_002","title":"Урон II","description":"Ой!","language":"Корейский","audioUrl":"/nte-meta/game-audio/195393505d68f4c3800d.ogg"},{"id":"zh-Play_Vo_Char_NPC028_chat_001","title":"Чат: пинать камушки","description":"Когда вижу мелкие камушки, прям тянет пнуть их… всё дальше и дальше, пока они не исчезнут там, где я их больше не увижу. Ты тоже так делаешь?","language":"Китайский","audioUrl":"/nte-meta/game-audio/774290e5f44802f72e7b.ogg"},{"id":"en-Play_Vo_Char_NPC028_weather_001","title":"Солнечно","description":"Солнце светит, и цветы распускаются…","language":"Английский","audioUrl":"/nte-meta/game-audio/cd8607b93e5cbb25c59a.ogg"},{"id":"ja-Play_Vo_Char_NPC028_greet_004","title":"Спокойной ночи","description":"Ночь. Пришла.","language":"Японский","audioUrl":"/nte-meta/game-audio/fef637ba70bb875dae71.ogg"},{"id":"ja-Play_Vo_Char_NPC028_Parry_001","title":"Парирование I","description":"Я смогла это парировать!","language":"Японский","audioUrl":"/nte-meta/game-audio/b845018c0ce35685490a.ogg"},{"id":"ko-Play_Vo_Char_NPC028_aoe_UI_001","title":"Сверхспособность I","description":"А теперь, ребята, давайте-ка все поползём обратно в мамин животик!","language":"Корейский","audioUrl":"/nte-meta/game-audio/6dbdce72d0119fa9f9df.ogg"},{"id":"ko-Play_Vo_Char_NPC028_aoe_UI_002","title":"Сверхспособность II","description":"Мои сны жутко страшные!","language":"Корейский","audioUrl":"/nte-meta/game-audio/cc6f301f984f6dba77c2.ogg"},{"id":"ko-Play_Vo_Char_NPC028_gift_002","title":"Подарок получен II","description":"Это мне? С радостью приму, спасибо!","language":"Корейский","audioUrl":"/nte-meta/game-audio/b75e0f6400b713085476.ogg"},{"id":"zh-Play_Vo_Char_NPC028_hobby_001","title":"Хобби","description":"Что мне нравится? Да всё то же, что и остальным! Погоди, ты хочешь сказать, что есть люди, которым нравится то, что другие ненавидят? Ну, тогда пусть подерутся, а я примкну к победителю!","language":"Китайский","audioUrl":"/nte-meta/game-audio/fb26ff7a6c0d7f4e8be7.ogg"},{"id":"en-Play_Vo_Char_NPC028_talk_003","title":"Тема: миры грёз","description":"Тебе нравится видеть сны? Хочешь взглянуть на мои? Только пройди через ворота с бычьими рогами. Если пройдёшь через ворота из слоновой кости — я не смогу тебя вытащить. Тебе придётся заново прожить весь путь: от эмбриона до нынешнего себя! Тебе нравится видеть сны? Хочешь взглянуть на мои? Только пройди через ворота с бычьими рогами. Если пройдёшь через ворота из слоновой кости — я не смогу тебя вытащить. Тебе придётся заново прожить весь путь: от эмбриона до нынешней себя!","language":"Английский","audioUrl":"/nte-meta/game-audio/63c5900f727e8c6ab3f3.ogg"},{"id":"ja-Play_Vo_Char_NPC028_hp_002","title":"Низкий уровень здоровья II","description":"Ноги совсем не слушаются.","language":"Японский","audioUrl":"/nte-meta/game-audio/c81a0ad5f04bb5ced5ba.ogg"},{"id":"ja-Play_Vo_Char_NPC028_talk_003","title":"Тема: миры грёз","description":"Тебе нравится видеть сны? Хочешь взглянуть на мои? Только пройди через ворота с бычьими рогами. Если пройдёшь через ворота из слоновой кости — я не смогу тебя вытащить. Тебе придётся заново прожить весь путь: от эмбриона до нынешнего себя! Тебе нравится видеть сны? Хочешь взглянуть на мои? Только пройди через ворота с бычьими рогами. Если пройдёшь через ворота из слоновой кости — я не смогу тебя вытащить. Тебе придётся заново прожить весь путь: от эмбриона до нынешней себя!","language":"Японский","audioUrl":"/nte-meta/game-audio/55803b8b74ee8ef95cb4.ogg"},{"id":"ko-Play_Vo_Char_NPC028_chat_002","title":"Чат: школа","description":"Мои друзья вечно рассказывают что-то интересное про школу, а я училась дома, и у меня не было одноклассников. Жаль, что я так и не узнала, что такое настоящая школьная жизнь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/81be4c5f712a5a126af0.ogg"},{"id":"zh-Play_Vo_Char_NPC028_about_003","title":"О Шинку II","description":"Сейчас мы в ладах. Эта скептичная дракониха просто меня не так поняла. По крайней мере, Минт говорит, что мы с Шинку теперь «души не чаем» друг в друге!","language":"Китайский","audioUrl":"/nte-meta/game-audio/933ced057d6fc986210c.ogg"},{"id":"zh-Play_Vo_Char_NPC028_gift_004","title":"Подарок получен IV","description":"Какой классный подарок!","language":"Китайский","audioUrl":"/nte-meta/game-audio/286b8b62c6aade683f54.ogg"},{"id":"zh-Play_Vo_Char_NPC028_self_002","title":"Обо мне: сон","description":"Кажется, я всегда спала. Даже когда бодра и полна сил, я всё равно блуждаю во сне!","language":"Китайский","audioUrl":"/nte-meta/game-audio/aecf643cf6523a203376.ogg"},{"id":"zh-Play_Vo_Char_NPC028_windfall_005","title":"Неожиданная добыча V","description":"Я такого ещё не видела.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f72f4c91737d6bf2156e.ogg"},{"id":"en-Play_Vo_Char_NPC028_hobby_001","title":"Хобби","description":"Что мне нравится? Да всё то же, что и остальным! Погоди, ты хочешь сказать, что есть люди, которым нравится то, что другие ненавидят? Ну, тогда пусть подерутся, а я примкну к победителю!","language":"Английский","audioUrl":"/nte-meta/game-audio/0b1fba24ced8faf4e86b.ogg"},{"id":"ja-Play_Vo_Char_NPC028_about_004","title":"О Наналли","description":"Наналли ведь немного младше меня, да? Я ей даже чуточку завидую — в её-то годы она уже точно знает, чего хочет от жизни!","language":"Японский","audioUrl":"/nte-meta/game-audio/fe4356ba10456f479c1c.ogg"},{"id":"ja-Play_Vo_Char_NPC028_fh_002","title":"Исцеление II","description":"Я снова в деле!","language":"Японский","audioUrl":"/nte-meta/game-audio/a074ed0e2717b68b22f0.ogg"},{"id":"ko-Play_Vo_Char_NPC028_about_002","title":"О Шинку I","description":"После того как я затащила Шинку в свои сны, она начала меня ненавидеть. Ей не понравилось то, что я ей показала? Или… она о чём-то догадалась?","language":"Корейский","audioUrl":"/nte-meta/game-audio/a0022bd21040da609a0e.ogg"},{"id":"ko-Play_Vo_Char_NPC028_greet_003","title":"Вечернее приветствие","description":"Вот и скрылся мистер Солнце.","language":"Корейский","audioUrl":"/nte-meta/game-audio/d71eefdbbf5c33cdb461.ogg"},{"id":"ko-Play_Vo_Char_NPC028_SSC_zero_003","title":"Особое переключение — Ноль","description":"Оценщик, я пришла на помощь! Оценщица, я пришла на помощь!","language":"Корейский","audioUrl":"/nte-meta/game-audio/1feb7707a1b46148d134.ogg"},{"id":"zh-Play_Vo_Char_NPC028_TeammateDown_002","title":"Поражён товарищ по команде – Шинку","description":"Ох, ну вот опять…","language":"Китайский","audioUrl":"/nte-meta/game-audio/b890974855ceca14c2b4.ogg"},{"id":"zh-Play_Vo_Char_NPC028_windfall_001","title":"Неожиданная добыча I","description":"Как неожиданно!","language":"Китайский","audioUrl":"/nte-meta/game-audio/efd5d2c2e888e1b0fbcc.ogg"},{"id":"en-Play_Vo_Char_NPC028_deploy_002","title":"Отправка II","description":"Я сделаю всё, что смогу!","language":"Английский","audioUrl":"/nte-meta/game-audio/41b397708e881372c1a2.ogg"},{"id":"en-Play_Vo_Char_NPC028_ug_003","title":"Вознесение персонажа III","description":"Пожалуй, это мой предел… Спасибо за помощь.","language":"Английский","audioUrl":"/nte-meta/game-audio/ee3775427c4da8c2878a.ogg"},{"id":"ja-Play_Vo_Char_NPC028_hobby_001","title":"Хобби","description":"Что мне нравится? Да всё то же, что и остальным! Погоди, ты хочешь сказать, что есть люди, которым нравится то, что другие ненавидят? Ну, тогда пусть подерутся, а я примкну к победителю!","language":"Японский","audioUrl":"/nte-meta/game-audio/70b6a4ae4090ebba82b2.ogg"},{"id":"ko-Play_Vo_Char_NPC028_skill_002","title":"Навык перенаправления II","description":"Пора встава-а-ать!","language":"Корейский","audioUrl":"/nte-meta/game-audio/cdb6d6dea986630f5bd2.ogg"},{"id":"zh-Play_Vo_Char_NPC028_greet_004","title":"Спокойной ночи","description":"Ночь. Пришла.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e325e2edd116cb0cfa11.ogg"},{"id":"en-Play_Vo_Char_NPC028_containment_002","title":"Сдерживание II","description":"Сдерживание завершено!","language":"Английский","audioUrl":"/nte-meta/game-audio/307f90b7734f43e993c4.ogg"},{"id":"ja-Play_Vo_Char_NPC028_deploy_001","title":"Отправка I","description":"Ирой здесь — готова к бою!","language":"Японский","audioUrl":"/nte-meta/game-audio/199b8c469be46540bf20.ogg"},{"id":"ja-Play_Vo_Char_NPC028_greet_003","title":"Вечернее приветствие","description":"Вот и скрылся мистер Солнце.","language":"Японский","audioUrl":"/nte-meta/game-audio/54cab160e701d01e5fae.ogg"},{"id":"ko-Play_Vo_Char_NPC028_fh_001","title":"Исцеление I","description":"Глоток свежего воздуха!","language":"Корейский","audioUrl":"/nte-meta/game-audio/56c9d3c6183935c13138.ogg"},{"id":"ko-Play_Vo_Char_NPC028_TeammateDown_001","title":"Поражен товарищ по команде – Минт","description":"Минт-сенпай потеряла сознание? Я разберусь!","language":"Корейский","audioUrl":"/nte-meta/game-audio/75fce83fe3d376c95416.ogg"},{"id":"ko-Play_Vo_Char_NPC028_windfall_003","title":"Неожиданная добыча III","description":"Что за вкусняшки на этот раз?","language":"Корейский","audioUrl":"/nte-meta/game-audio/04d2f0ebb7c91c26267f.ogg"},{"id":"en-Play_Vo_Char_NPC028_about_001","title":"О Минт","description":"У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взял? Я серьёзно! У Минт сенпай столько энергии и страсти. Я тоже хочу быть как она! Я вру? Нет-нет-нет, с чего ты взяла? Я серьёзно!","language":"Английский","audioUrl":"/nte-meta/game-audio/de97ea808ff8940efcac.ogg"},{"id":"en-Play_Vo_Char_NPC028_meet_001","title":"Первая встреча","description":"Привет! Меня зовут Онейрой. Выговорить трудновато, так что зови просто Ирой! Если что понадобится — только дай знать. Увидимся!","language":"Английский","audioUrl":"/nte-meta/game-audio/0c1af16c604e7f5e56a0.ogg"},{"id":"en-Play_Vo_Char_NPC028_skill_002","title":"Навык перенаправления II","description":"Пора встава-а-ать!","language":"Английский","audioUrl":"/nte-meta/game-audio/3677abb5fecebfc02659.ogg"},{"id":"ja-Play_Vo_Char_NPC028_containment_002","title":"Сдерживание II","description":"Сдерживание завершено!","language":"Японский","audioUrl":"/nte-meta/game-audio/c651e9fdeabce4c8209a.ogg"},{"id":"ja-Play_Vo_Char_NPC028_self_001","title":"Обо мне: семья","description":"Родители очень меня любят и столько для меня сделали. Они просто хотят, чтобы я была счастлива. Я им очень благодарна, но иногда не могу отделаться от мысли… если бы на моем месте родился ребенок поздоровее…","language":"Японский","audioUrl":"/nte-meta/game-audio/860f70494ef9c7b08222.ogg"},{"id":"ko-Play_Vo_Char_NPC028_chat_001","title":"Чат: пинать камушки","description":"Когда вижу мелкие камушки, прям тянет пнуть их… всё дальше и дальше, пока они не исчезнут там, где я их больше не увижу. Ты тоже так делаешь?","language":"Корейский","audioUrl":"/nte-meta/game-audio/b9b6231b8d6db352cfff.ogg"},{"id":"ko-Play_Vo_Char_NPC028_chat_003","title":"Чат: теория эволюции","description":"«Естественный отбор — это выживание сильнейших…» — это всё, что моя учительница сказала о теории эволюции. Ей не пришлось объяснять: это был первый сон, который «я» увидела в своей жизни…","language":"Корейский","audioUrl":"/nte-meta/game-audio/1423f49ef573ac12d8b7.ogg"},{"id":"ko-Play_Vo_Char_NPC028_dead_002","title":"Потеря сознания II","description":"Мне… можно наконец вернуться?","language":"Корейский","audioUrl":"/nte-meta/game-audio/d6cd6dfbf5f6fb0144b2.ogg"},{"id":"en-Play_Vo_Char_NPC028_vexation_001","title":"Проблемы","description":"Мои ребятки — Морфей, Икел и Фантас — вечно влипают в неприятности. Интересно, есть ли способ удержать их в узде…","language":"Английский","audioUrl":"/nte-meta/game-audio/7b0a9a244aa5469afdc5.ogg"},{"id":"ja-Play_Vo_Char_NPC028_gift_002","title":"Подарок получен II","description":"Это мне? С радостью приму, спасибо!","language":"Японский","audioUrl":"/nte-meta/game-audio/d05415f96653bbb9f3fc.ogg"},{"id":"ja-Play_Vo_Char_NPC028_greet_001","title":"Утреннее приветствие","description":"(Зевок) Доброе утро!","language":"Японский","audioUrl":"/nte-meta/game-audio/5a497d994d702569f09e.ogg"},{"id":"ko-Play_Vo_Char_NPC028_SSC_BH_001","title":"Особое переключение — Минт","description":"Минт-сенпай, я тут!","language":"Корейский","audioUrl":"/nte-meta/game-audio/688f79cd6d4d570fdd31.ogg"},{"id":"zh-Play_Vo_Char_NPC028_QTE_003","title":"Атака на входе III","description":"Прицел… Огонь!","language":"Китайский","audioUrl":"/nte-meta/game-audio/7a3fbba74268f194692b.ogg"},{"id":"zh-Play_Vo_Char_NPC028_vexation_001","title":"Проблемы","description":"Мои ребятки — Морфей, Икел и Фантас — вечно влипают в неприятности. Интересно, есть ли способ удержать их в узде…","language":"Китайский","audioUrl":"/nte-meta/game-audio/536f1701fd3dde4b138d.ogg"},{"id":"en-Play_Vo_Char_NPC028_chat_003","title":"Чат: теория эволюции","description":"«Естественный отбор — это выживание сильнейших…» — это всё, что моя учительница сказала о теории эволюции. Ей не пришлось объяснять: это был первый сон, который «я» увидела в своей жизни…","language":"Английский","audioUrl":"/nte-meta/game-audio/ee06457a6b43abf272dc.ogg"}]') WHERE character_id='iroi' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-10-21 03:56:00');

