UPDATE character_profiles SET voice_lines_json=(SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(voice_lines_json) UNION ALL SELECT value FROM json_each('[{"id":"zh-Play_Vo_Char_NPC012_greet_001","title":"Утреннее приветствие","description":"Доброе утро. Какие у тебя планы на сегодня? Можно с тобой?","language":"Китайский","audioUrl":"/nte-meta/game-audio/a4661289fc2cc617183d.ogg"},{"id":"en-Play_Vo_Char_NPC012_chat_001","title":"Чат: шарф","description":"Этот шарф связала мама. Он лёгкий и тёплый. Что я ношу, когда жарко? Меняю на шёлковый, который достался от отца. Он с таким же узором.","language":"Английский","audioUrl":"/nte-meta/game-audio/afd02342adeb4e3062fe.ogg"},{"id":"en-Play_Vo_Char_NPC012_hp_002","title":"Низкий уровень здоровья II","description":"Мой мозг… больше не работает.","language":"Английский","audioUrl":"/nte-meta/game-audio/4cdd5f1f078108be170d.ogg"},{"id":"ja-Play_Vo_Char_NPC012_dead_002","title":"Потеря сознания II","description":"Это всё, на что я способен?","language":"Японский","audioUrl":"/nte-meta/game-audio/cd44956392952ccd1ca7.ogg"},{"id":"ja-Play_Vo_Char_NPC012_gift_003","title":"Подарок получен III","description":"С-спасибо.","language":"Японский","audioUrl":"/nte-meta/game-audio/75360eb483269f486a1d.ogg"},{"id":"ja-Play_Vo_Char_NPC012_hp_002","title":"Низкий уровень здоровья II","description":"Мой мозг… больше не работает.","language":"Японский","audioUrl":"/nte-meta/game-audio/7d18b1c5421f1512bc29.ogg"},{"id":"ja-Play_Vo_Char_NPC012_Parry_002","title":"Парирование II","description":"Сейчас.","language":"Японский","audioUrl":"/nte-meta/game-audio/01f83992709550526ba5.ogg"},{"id":"ja-Play_Vo_Char_NPC012_TeammateDown_004","title":"Поражен товарищ по команде – Хотори","description":"Хотори…? Как такое вообще возможно…!","language":"Японский","audioUrl":"/nte-meta/game-audio/62df1c056188261f655a.ogg"},{"id":"ko-Play_Vo_Char_NPC012_SSC_005","title":"Особое переключение — Адлер","description":"Адлер, мне ещё многому нужно у тебя научиться.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6c0c6ce48894ff8ea903.ogg"},{"id":"zh-Play_Vo_Char_NPC012_chat_003","title":"Чат: аномалия","description":"Мне нравятся аномалии. Я вступил в Эйбон, потому что хотел узнать о них больше. Для начала я могу наблюдать за Тайгедо вблизи…","language":"Китайский","audioUrl":"/nte-meta/game-audio/ab97bd3d5335e9598a01.ogg"},{"id":"ja-Play_Vo_Char_NPC012_hstruck_001","title":"Сильный урон I","description":"…Только не по голове.","language":"Японский","audioUrl":"/nte-meta/game-audio/20251d407617636ad55e.ogg"},{"id":"ja-Play_Vo_Char_NPC012_weather_004","title":"Жарко","description":"Хочу жить в холодильнике.","language":"Японский","audioUrl":"/nte-meta/game-audio/d26540bbe7287f2288c0.ogg"},{"id":"ko-Play_Vo_Char_NPC012_QTE_003","title":"Атака на входе III","description":"Идеальный момент!","language":"Корейский","audioUrl":"/nte-meta/game-audio/34df04548daffa902768.ogg"},{"id":"zh-Play_Vo_Char_NPC012_about_007","title":"О Тайгедо","description":"Я решил устроиться в магазин, когда увидел объявление о найме, нарисованное Тайгедо от руки. Тайгедо был моим первым другом в Этеро.","language":"Китайский","audioUrl":"/nte-meta/game-audio/1f88127607962f911f9d.ogg"},{"id":"zh-Play_Vo_Char_NPC012_SSC_002","title":"Особое переключение — Наналли","description":"Давайте сражаться как одна семья.","language":"Китайский","audioUrl":"/nte-meta/game-audio/8c9a33ab25a698e39a94.ogg"},{"id":"en-Play_Vo_Char_NPC012_about_001","title":"Об Адлере","description":"Я хочу быть таким же организованным и внимательным к мелочам, как Адлер. Мне ещё многому предстоит научиться.","language":"Английский","audioUrl":"/nte-meta/game-audio/63e6629d35ecb209548b.ogg"},{"id":"ja-Play_Vo_Char_NPC012_chat_003","title":"Чат: аномалия","description":"Мне нравятся аномалии. Я вступил в Эйбон, потому что хотел узнать о них больше. Для начала я могу наблюдать за Тайгедо вблизи…","language":"Японский","audioUrl":"/nte-meta/game-audio/e66c4f3be38eea8119f0.ogg"},{"id":"ko-Play_Vo_Char_NPC012_SSC_006","title":"Особое переключение — Даффодил","description":"Даффодил, я постараюсь сделать всё так, как ты меня учила.","language":"Корейский","audioUrl":"/nte-meta/game-audio/61b130bc5c3f815a6415.ogg"},{"id":"en-Play_Vo_Char_NPC012_about_002","title":"О Хотори","description":"Хотори всегда говорит, что в работе с антиквариатом главное — иметь наметанный глаз. Но что это вообще значит? Ни в одной книге это толком не объясняют… Или это просто тот самый опыт, который приходит, когда постоянно копаешься в старинных вещах?","language":"Английский","audioUrl":"/nte-meta/game-audio/dff7173bc7415c8cd76b.ogg"},{"id":"ja-Play_Vo_Char_NPC012_DodgeCombo_001","title":"Серия критических уклонений I","description":"Уклонился!","language":"Японский","audioUrl":"/nte-meta/game-audio/5552d47b2d16e03980e5.ogg"},{"id":"ja-Play_Vo_Char_NPC012_greet_004","title":"Спокойной ночи","description":"В детстве мама рассказывала мне сказку об Облачных Овцах. Когда ребёнок засыпает, Облачные Овцы взбивают ему подушку, чтобы он спокойно проспал всю ночь. Но Облачные Овцы ложатся рано, так что если ложиться слишком поздно, они уже могут спать на луне. Всё же надеюсь, что ты встретишь их сегодня ночью. Спокойной ночи.","language":"Японский","audioUrl":"/nte-meta/game-audio/ffd6b36d7fec2c48d940.ogg"},{"id":"ko-Play_Vo_Char_NPC012_TeammateDown_001","title":"Поражен товарищ по команде – Ноль","description":"Ты в порядке?","language":"Корейский","audioUrl":"/nte-meta/game-audio/74f7ff7bd8386bc881a7.ogg"},{"id":"zh-Play_Vo_Char_NPC012_weather_001","title":"Солнечно","description":"Давай вынесем это растение во двор, пусть погреется на солнышке.","language":"Китайский","audioUrl":"/nte-meta/game-audio/b3d9e4b783b245b6fbe2.ogg"},{"id":"ja-Play_Vo_Char_NPC012_talk_002","title":"Тема: Накупеда","description":"У Накупеды тоже бывают такие желания, типа: «Сегодня хочу съесть кучу-кучу монеток»?","language":"Японский","audioUrl":"/nte-meta/game-audio/e20b092cd5da961d31af.ogg"},{"id":"ko-Play_Vo_Char_NPC012_hstruck_002","title":"Сильный урон II","description":"…у меня голова кружится.","language":"Корейский","audioUrl":"/nte-meta/game-audio/314a9c348b5e235c8acb.ogg"},{"id":"en-Play_Vo_Char_NPC012_containment_002","title":"Сдерживание II","description":"Надеюсь, ты найдёшь хорошее место.","language":"Английский","audioUrl":"/nte-meta/game-audio/a064bbe478476904e21d.ogg"},{"id":"en-Play_Vo_Char_NPC012_TeammateDown_002","title":"Поражен товарищ по команде – Наналли","description":"Наналли, отдохни немного.","language":"Английский","audioUrl":"/nte-meta/game-audio/4ce2053aca572b7d1bae.ogg"},{"id":"en-Play_Vo_Char_NPC012_windfall_003","title":"Неожиданная добыча III","description":"Хотори это точно понравится.","language":"Английский","audioUrl":"/nte-meta/game-audio/0ed16f416458bd1aa735.ogg"},{"id":"ja-Play_Vo_Char_NPC012_struck_001","title":"Урон I","description":"М-м.","language":"Японский","audioUrl":"/nte-meta/game-audio/51ad911e9a2e63cdaf7b.ogg"},{"id":"ja-Play_Vo_Char_NPC012_struck_002","title":"Урон II","description":"О нет!","language":"Японский","audioUrl":"/nte-meta/game-audio/ae1d4074a12a2a5a2966.ogg"},{"id":"ko-Play_Vo_Char_NPC012_anomaly_004","title":"Нуллификация II","description":"Мы ещё увидимся… правда?","language":"Корейский","audioUrl":"/nte-meta/game-audio/8e2104d94989dece9326.ogg"},{"id":"ko-Play_Vo_Char_NPC012_Fly_001","title":"Планирование I","description":"Отличный вид сверху…","language":"Корейский","audioUrl":"/nte-meta/game-audio/703b7b1f9c7e284a0b44.ogg"},{"id":"en-Play_Vo_Char_NPC012_talk_003","title":"Тема: Бонзита","description":"Вечно всё забываю, всё время любопытно…? Хм…","language":"Английский","audioUrl":"/nte-meta/game-audio/7e61e78276b7b52145e1.ogg"},{"id":"ja-Play_Vo_Char_NPC012_about_003","title":"О Сакири","description":"Кирумару довольно тяжёлый… Сакири, должно быть, очень сильная.","language":"Японский","audioUrl":"/nte-meta/game-audio/8feaaa70326616b4aa1c.ogg"},{"id":"ja-Play_Vo_Char_NPC012_SSC_002","title":"Особое переключение — Наналли","description":"Давайте сражаться как одна семья.","language":"Японский","audioUrl":"/nte-meta/game-audio/baec96e489e158f30e96.ogg"},{"id":"ja-Play_Vo_Char_NPC012_SSC_005","title":"Особое переключение — Адлер","description":"Адлер, мне ещё многому нужно у тебя научиться.","language":"Японский","audioUrl":"/nte-meta/game-audio/44b88d680cad461611cb.ogg"},{"id":"ko-Play_Vo_Char_NPC012_about_005","title":"О Наналли","description":"Босс как‑то сказала, что нам нужно провести собрание и обсудить книгу под названием «Семейный менеджмент». Я уже подготовил заметки, но у неё вечно нет времени…","language":"Корейский","audioUrl":"/nte-meta/game-audio/1be6f213870a18a98ce8.ogg"},{"id":"ko-Play_Vo_Char_NPC012_weather_004","title":"Жарко","description":"Хочу жить в холодильнике.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c254b78039d793e4f44f.ogg"},{"id":"ko-Play_Vo_Char_NPC012_windfall_002","title":"Неожиданная добыча II","description":"Оценщик должен это увидеть.Оценщица должна это увидеть.","language":"Корейский","audioUrl":"/nte-meta/game-audio/dab0bfd949dc4657e1ed.ogg"},{"id":"ja-Play_Vo_Char_NPC012_meet_001","title":"Первая встреча","description":"Приветствую, я Эдгар, сотрудник антикварного магазина Эйбон. Когда появляются заказы, я также работаю вместе с остальными — в качестве ученика охотника за аномалиями.","language":"Японский","audioUrl":"/nte-meta/game-audio/284353de85e7e66b434c.ogg"},{"id":"ja-Play_Vo_Char_NPC012_ug_001","title":"Вознесение персонажа I","description":"Мои знания множатся.","language":"Японский","audioUrl":"/nte-meta/game-audio/c32a7299ef93e3385833.ogg"},{"id":"ko-Play_Vo_Char_NPC012_fh_002","title":"Исцеление II","description":"Освежающе.","language":"Корейский","audioUrl":"/nte-meta/game-audio/7d38bb4e0d460b2963b9.ogg"},{"id":"ko-Play_Vo_Char_NPC012_meet_001","title":"Первая встреча","description":"Приветствую, я Эдгар, сотрудник антикварного магазина Эйбон. Когда появляются заказы, я также работаю вместе с остальными — в качестве ученика охотника за аномалиями.","language":"Корейский","audioUrl":"/nte-meta/game-audio/270deec6fa7191c0cdef.ogg"},{"id":"ko-Play_Vo_Char_NPC012_SSC_001","title":"Особое переключение — Ноль","description":"Я постараюсь изо всех сил.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a67be8b44b4e103adfc7.ogg"},{"id":"ko-Play_Vo_Char_NPC012_SSC_002","title":"Особое переключение — Наналли","description":"Давайте сражаться как одна семья.","language":"Корейский","audioUrl":"/nte-meta/game-audio/6a17269d28d36316e70a.ogg"},{"id":"ko-Play_Vo_Char_NPC012_Switch_001","title":"Переключение I","description":"А вот и я.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4d00459825b57241e694.ogg"},{"id":"en-Play_Vo_Char_NPC012_aoe_UI_004","title":"Сверхспособность IV","description":"Вот, это должно помочь.","language":"Английский","audioUrl":"/nte-meta/game-audio/d35ccc5d630f128622bd.ogg"},{"id":"en-Play_Vo_Char_NPC012_skill_001","title":"Навык перенаправления I","description":"Экстренная перевязка.","language":"Английский","audioUrl":"/nte-meta/game-audio/8e251eecd2e2abc458d8.ogg"},{"id":"en-Play_Vo_Char_NPC012_SSC_003","title":"Особое переключение — Сакири","description":"Сакири, дай Кирумару спокойно переварить еду.","language":"Английский","audioUrl":"/nte-meta/game-audio/09461f4f2fa1c7147e91.ogg"},{"id":"en-Play_Vo_Char_NPC012_talk_002","title":"Тема: Накупеда","description":"У Накупеды тоже бывают такие желания, типа: «Сегодня хочу съесть кучу-кучу монеток»?","language":"Английский","audioUrl":"/nte-meta/game-audio/77f34ebb4028868d048a.ogg"},{"id":"en-Play_Vo_Char_NPC012_weather_003","title":"Холодно","description":"С моим шарфом я не замёрзну.","language":"Английский","audioUrl":"/nte-meta/game-audio/5b7254ef8fff930e9090.ogg"},{"id":"ja-Play_Vo_Char_NPC012_anomaly_003","title":"Нуллификация I","description":"В следующий раз нужно придумать, как это сдержать…","language":"Японский","audioUrl":"/nte-meta/game-audio/904eaf7ffe873de77586.ogg"},{"id":"ja-Play_Vo_Char_NPC012_containment_002","title":"Сдерживание II","description":"Надеюсь, ты найдёшь хорошее место.","language":"Японский","audioUrl":"/nte-meta/game-audio/85fd445111fd682a9616.ogg"},{"id":"ja-Play_Vo_Char_NPC012_deploy_001","title":"Отправка I","description":"Я сделаю всё возможное.","language":"Японский","audioUrl":"/nte-meta/game-audio/85aca0ef9bb0e3ca737b.ogg"},{"id":"ja-Play_Vo_Char_NPC012_TeammateDown_001","title":"Поражен товарищ по команде – Ноль","description":"Ты в порядке?","language":"Японский","audioUrl":"/nte-meta/game-audio/8ea93a1492007aa3f067.ogg"},{"id":"ko-Play_Vo_Char_NPC012_about_003","title":"О Сакири","description":"Кирумару довольно тяжёлый… Сакири, должно быть, очень сильная.","language":"Корейский","audioUrl":"/nte-meta/game-audio/eb6be84739542a5773e9.ogg"},{"id":"ko-Play_Vo_Char_NPC012_kill_001","title":"Убийство I","description":"Проблема решена.","language":"Корейский","audioUrl":"/nte-meta/game-audio/5ca999acddac1bee947b.ogg"},{"id":"zh-Play_Vo_Char_NPC012_aoe_UI_004","title":"Сверхспособность IV","description":"Вот, это должно помочь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/5577e5184c875953116f.ogg"},{"id":"en-Play_Vo_Char_NPC012_QTE_001","title":"Атака на входе I","description":"Есть лазейка!","language":"Английский","audioUrl":"/nte-meta/game-audio/9090f53b3e0b90874de0.ogg"},{"id":"ja-Play_Vo_Char_NPC012_weather_002","title":"Дождливо","description":"Я только что видел, как Тайгедо выскочил на улицу без зонтика. Он что, непромокаемый…?","language":"Японский","audioUrl":"/nte-meta/game-audio/7242e5578a9ea8050571.ogg"},{"id":"zh-Play_Vo_Char_NPC012_hp_003","title":"Низкий уровень здоровья III","description":"Ай… больно.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0c4700a8bf270f2982fd.ogg"},{"id":"en-Play_Vo_Char_NPC012_aoe_UI_002","title":"Сверхспособность II","description":"Скоро всё будет в порядке.","language":"Английский","audioUrl":"/nte-meta/game-audio/fdf626c6ff87537759b2.ogg"},{"id":"en-Play_Vo_Char_NPC012_Fly_001","title":"Планирование I","description":"Отличный вид сверху…","language":"Английский","audioUrl":"/nte-meta/game-audio/53258f65c279160716e6.ogg"},{"id":"ko-Play_Vo_Char_NPC012_talk_004","title":"Тема: Данзабуру","description":"Данзабуру могут принимать человеческий облик, чтобы воровать. Но их маскировку легко раскусить: даже превращаясь в человека, они всё равно носят свою фирменную красную салфетку. Когда стоишь за прилавком, внимательнее следи за такими «покупателями».","language":"Корейский","audioUrl":"/nte-meta/game-audio/879ba405b43c8b1a59ad.ogg"},{"id":"zh-Play_Vo_Char_NPC012_kill_001","title":"Убийство I","description":"Проблема решена.","language":"Китайский","audioUrl":"/nte-meta/game-audio/446861ddd89ed1ef167a.ogg"},{"id":"zh-Play_Vo_Char_NPC012_Switch_001","title":"Переключение I","description":"А вот и я.","language":"Китайский","audioUrl":"/nte-meta/game-audio/a2de1336bf36ccdd5e79.ogg"},{"id":"zh-Play_Vo_Char_NPC012_talk_004","title":"Тема: Данзабуру","description":"Данзабуру могут принимать человеческий облик, чтобы воровать. Но их маскировку легко раскусить: даже превращаясь в человека, они всё равно носят свою фирменную красную салфетку. Когда стоишь за прилавком, внимательнее следи за такими «покупателями».","language":"Китайский","audioUrl":"/nte-meta/game-audio/966b39f25dd9c08e0575.ogg"},{"id":"ja-Play_Vo_Char_NPC012_about_008","title":"Об антикварном магазине Эйбон","description":"Это как второй дом. Здесь все близки, как одна дружная семья.","language":"Японский","audioUrl":"/nte-meta/game-audio/45bc8a4fe71286b98035.ogg"},{"id":"ja-Play_Vo_Char_NPC012_aoe_UI_002","title":"Сверхспособность II","description":"Скоро всё будет в порядке.","language":"Японский","audioUrl":"/nte-meta/game-audio/10e595396e40fdc9c2b3.ogg"},{"id":"ko-Play_Vo_Char_NPC012_Switch_002","title":"Переключение II","description":"Я тут.","language":"Корейский","audioUrl":"/nte-meta/game-audio/01e06b8a22988022f672.ogg"},{"id":"ko-Play_Vo_Char_NPC012_windfall_004","title":"Неожиданная добыча IV","description":"Деньги для Колуччи…?","language":"Корейский","audioUrl":"/nte-meta/game-audio/ff0e81042968c57cfcbc.ogg"},{"id":"ko-Play_Vo_Char_NPC012_about_008","title":"Об антикварном магазине Эйбон","description":"Это как второй дом. Здесь все близки, как одна дружная семья.","language":"Корейский","audioUrl":"/nte-meta/game-audio/3982fa25822aedfbf9e8.ogg"},{"id":"zh-Play_Vo_Char_NPC012_anomaly_003","title":"Нуллификация I","description":"В следующий раз нужно придумать, как это сдержать…","language":"Китайский","audioUrl":"/nte-meta/game-audio/a3abc9dc398118819adf.ogg"},{"id":"zh-Play_Vo_Char_NPC012_greet_004","title":"Спокойной ночи","description":"В детстве мама рассказывала мне сказку об Облачных Овцах. Когда ребёнок засыпает, Облачные Овцы взбивают ему подушку, чтобы он спокойно проспал всю ночь. Но Облачные Овцы ложатся рано, так что если ложиться слишком поздно, они уже могут спать на луне. Всё же надеюсь, что ты встретишь их сегодня ночью. Спокойной ночи.","language":"Китайский","audioUrl":"/nte-meta/game-audio/f739cefc04c4c468239f.ogg"},{"id":"zh-Play_Vo_Char_NPC012_hp_001","title":"Низкий уровень здоровья I","description":"Так устал.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0fcda7f9b9bd2950c976.ogg"},{"id":"en-Play_Vo_Char_NPC012_meet_001","title":"Первая встреча","description":"Приветствую, я Эдгар, сотрудник антикварного магазина Эйбон. Когда появляются заказы, я также работаю вместе с остальными — в качестве ученика охотника за аномалиями.","language":"Английский","audioUrl":"/nte-meta/game-audio/54751d4f1c52bd8dc675.ogg"},{"id":"zh-Play_Vo_Char_NPC012_aoe_UI_001","title":"Сверхспособность I","description":"Позволь мне вылечить тебя.","language":"Китайский","audioUrl":"/nte-meta/game-audio/0349da9c52577ae504ef.ogg"},{"id":"zh-Play_Vo_Char_NPC012_greet_002","title":"Дневное приветствие","description":"Тайгедо обожает спать. Наверняка где‑нибудь свернулся калачиком и дремлет.","language":"Китайский","audioUrl":"/nte-meta/game-audio/12a134037ab0c49cdfb9.ogg"},{"id":"en-Play_Vo_Char_NPC012_DodgeCombo_002","title":"Серия критических уклонений II","description":"Мне следует держать дистанцию.","language":"Английский","audioUrl":"/nte-meta/game-audio/ceb3869b2382dac0406b.ogg"},{"id":"en-Play_Vo_Char_NPC012_skill_002","title":"Навык перенаправления II","description":"Делаю, что могу.","language":"Английский","audioUrl":"/nte-meta/game-audio/ee0efe87ab7e83c5e7de.ogg"},{"id":"ja-Play_Vo_Char_NPC012_QTE_003","title":"Атака на входе III","description":"Идеальный момент!","language":"Японский","audioUrl":"/nte-meta/game-audio/24df3c307f06b1b0480f.ogg"},{"id":"zh-Play_Vo_Char_NPC012_DodgeCombo_001","title":"Серия критических уклонений I","description":"Уклонился!","language":"Китайский","audioUrl":"/nte-meta/game-audio/2a653d336283e76451f1.ogg"},{"id":"zh-Play_Vo_Char_NPC012_greet_003","title":"Вечернее приветствие","description":"Ещё один продуктивный день. Я многому научился.","language":"Китайский","audioUrl":"/nte-meta/game-audio/669de6798280cf642259.ogg"},{"id":"en-Play_Vo_Char_NPC012_SSC_001","title":"Особое переключение — Ноль","description":"Я постараюсь изо всех сил.","language":"Английский","audioUrl":"/nte-meta/game-audio/3252a0e91889ed362550.ogg"},{"id":"ja-Play_Vo_Char_NPC012_aoe_UI_004","title":"Сверхспособность IV","description":"Вот, это должно помочь.","language":"Японский","audioUrl":"/nte-meta/game-audio/6e38d76d5c945e401dd2.ogg"},{"id":"ja-Play_Vo_Char_NPC012_dead_003","title":"Потеря сознания III","description":"Как такое вообще возможно…?","language":"Японский","audioUrl":"/nte-meta/game-audio/fcf68db5643f322c6393.ogg"},{"id":"ja-Play_Vo_Char_NPC012_hp_001","title":"Низкий уровень здоровья I","description":"Так устал.","language":"Японский","audioUrl":"/nte-meta/game-audio/8b9ac8c00ae5d1c618d7.ogg"},{"id":"ko-Play_Vo_Char_NPC012_containment_001","title":"Сдерживание I","description":"Привет, новый друг.","language":"Корейский","audioUrl":"/nte-meta/game-audio/4b9b5e7abb1f57f51cbf.ogg"},{"id":"zh-Play_Vo_Char_NPC012_dead_001","title":"Потеря сознания I","description":"Мне ещё многое предстоит узнать…","language":"Китайский","audioUrl":"/nte-meta/game-audio/7a8d2a8e17b6ee2756f6.ogg"},{"id":"zh-Play_Vo_Char_NPC012_fh_001","title":"Исцеление I","description":"Так гораздо лучше.","language":"Китайский","audioUrl":"/nte-meta/game-audio/8d1fcfc93e00ec9d29fd.ogg"},{"id":"zh-Play_Vo_Char_NPC012_QTE_002","title":"Атака на входе II","description":"Слабое место.","language":"Китайский","audioUrl":"/nte-meta/game-audio/83e7c2c05d154fbecc32.ogg"},{"id":"zh-Play_Vo_Char_NPC012_self_001","title":"Обо мне: способность эспера","description":"Это, конечно, не какая‑то суперспособность, но Хотори сказала: «Не дай этим курьерам тебя переманить». И Наналли тоже сказала: «Семья Колуччи без тебя не справится!» А я и правда просто рад помочь.","language":"Китайский","audioUrl":"/nte-meta/game-audio/e634319b1e05c2c9bab3.ogg"},{"id":"zh-Play_Vo_Char_NPC012_Switch_003","title":"Переключение III","description":"Пошли.","language":"Китайский","audioUrl":"/nte-meta/game-audio/d6fbbeccb59b1540688b.ogg"},{"id":"en-Play_Vo_Char_NPC012_QTE_002","title":"Атака на входе II","description":"Слабое место.","language":"Английский","audioUrl":"/nte-meta/game-audio/838562eb3179b5fc59eb.ogg"},{"id":"ko-Play_Vo_Char_NPC012_gift_003","title":"Подарок получен III","description":"С-спасибо.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c0783f4d072dc35affde.ogg"},{"id":"ko-Play_Vo_Char_NPC012_QTE_001","title":"Атака на входе I","description":"Есть лазейка!","language":"Корейский","audioUrl":"/nte-meta/game-audio/a3db1a474239353d5ce4.ogg"},{"id":"zh-Play_Vo_Char_NPC012_weather_002","title":"Дождливо","description":"Я только что видел, как Тайгедо выскочил на улицу без зонтика. Он что, непромокаемый…?","language":"Китайский","audioUrl":"/nte-meta/game-audio/adab50990756e3092ee9.ogg"},{"id":"en-Play_Vo_Char_NPC012_greet_003","title":"Вечернее приветствие","description":"Ещё один продуктивный день. Я многому научился.","language":"Английский","audioUrl":"/nte-meta/game-audio/ade8d8e80d9b34a64570.ogg"},{"id":"en-Play_Vo_Char_NPC012_talk_005","title":"Тема: Офицер Усатик","description":"Я слышал, что Усатики дружат с аномалией по имени «Палач справедливости», которая выглядит как джунгли из светофоров. Усатики даже используют эту аномалию в качестве базы. Как они там тренируются и отдыхают? Хотел бы я увидеть это своими глазами… Хм, вообще-то почти никто никогда не видел, как выглядит «Палач справедливости». Может, это городская легенда…?","language":"Английский","audioUrl":"/nte-meta/game-audio/d906e3060d074e7b393b.ogg"},{"id":"ja-Play_Vo_Char_NPC012_aoe_UI_003","title":"Сверхспособность III","description":"Тебе уже лучше?","language":"Японский","audioUrl":"/nte-meta/game-audio/5af2a8da1e0ba49d1a8f.ogg"},{"id":"ko-Play_Vo_Char_NPC012_greet_003","title":"Вечернее приветствие","description":"Ещё один продуктивный день. Я многому научился.","language":"Корейский","audioUrl":"/nte-meta/game-audio/32ed343fc3c6d758abd5.ogg"},{"id":"ko-Play_Vo_Char_NPC012_windfall_001","title":"Неожиданная добыча I","description":"Готово.","language":"Корейский","audioUrl":"/nte-meta/game-audio/8debba8936d6903b27bc.ogg"},{"id":"ko-Play_Vo_Char_NPC012_windfall_003","title":"Неожиданная добыча III","description":"Хотори это точно понравится.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ea41cbfd2856239fc8d6.ogg"},{"id":"zh-Play_Vo_Char_NPC012_hstruck_001","title":"Сильный урон I","description":"…Только не по голове.","language":"Китайский","audioUrl":"/nte-meta/game-audio/aa9cd8deaa6a8881f81b.ogg"},{"id":"zh-Play_Vo_Char_NPC012_vexation_001","title":"Проблемы","description":"В последнее время моё зрение ухудшилось. Наналли сказала, что если я и дальше буду читать в полумраке, тоже буду ходить в очках, как она…","language":"Китайский","audioUrl":"/nte-meta/game-audio/7a95576b4ea4f61aeaa3.ogg"},{"id":"ja-Play_Vo_Char_NPC012_SSC_006","title":"Особое переключение — Даффодил","description":"Даффодил, я постараюсь сделать всё так, как ты меня учила.","language":"Японский","audioUrl":"/nte-meta/game-audio/2a3773bd1e55f7297ab0.ogg"},{"id":"ja-Play_Vo_Char_NPC012_windfall_005","title":"Неожиданная добыча V","description":"Это могло бы помочь Адлеру.","language":"Японский","audioUrl":"/nte-meta/game-audio/3ad42163061342de4319.ogg"},{"id":"ko-Play_Vo_Char_NPC012_dead_002","title":"Потеря сознания II","description":"Это всё, на что я способен?","language":"Корейский","audioUrl":"/nte-meta/game-audio/dee9b8195f1b6a3c3d81.ogg"},{"id":"ko-Play_Vo_Char_NPC012_talk_005","title":"Тема: Офицер Усатик","description":"Я слышал, что Усатики дружат с аномалией по имени «Палач справедливости», которая выглядит как джунгли из светофоров. Усатики даже используют эту аномалию в качестве базы. Как они там тренируются и отдыхают? Хотел бы я увидеть это своими глазами… Хм, вообще-то почти никто никогда не видел, как выглядит «Палач справедливости». Может, это городская легенда…?","language":"Корейский","audioUrl":"/nte-meta/game-audio/a5d7661cf1a64db88ee5.ogg"},{"id":"ko-Play_Vo_Char_NPC012_weather_001","title":"Солнечно","description":"Давай вынесем это растение во двор, пусть погреется на солнышке.","language":"Корейский","audioUrl":"/nte-meta/game-audio/ea01b45bf931bac50728.ogg"},{"id":"en-Play_Vo_Char_NPC012_skill_003","title":"Навык перенаправления III","description":"Стабилизирую твоё состояние.","language":"Английский","audioUrl":"/nte-meta/game-audio/900918de6de8d5d47a19.ogg"},{"id":"ja-Play_Vo_Char_NPC012_chat_001","title":"Чат: шарф","description":"Этот шарф связала мама. Он лёгкий и тёплый. Что я ношу, когда жарко? Меняю на шёлковый, который достался от отца. Он с таким же узором.","language":"Японский","audioUrl":"/nte-meta/game-audio/8109608f5b5af2fbe145.ogg"},{"id":"ja-Play_Vo_Char_NPC012_talk_005","title":"Тема: Офицер Усатик","description":"Я слышал, что Усатики дружат с аномалией по имени «Палач справедливости», которая выглядит как джунгли из светофоров. Усатики даже используют эту аномалию в качестве базы. Как они там тренируются и отдыхают? Хотел бы я увидеть это своими глазами… Хм, вообще-то почти никто никогда не видел, как выглядит «Палач справедливости». Может, это городская легенда…?","language":"Японский","audioUrl":"/nte-meta/game-audio/ca6e6d6a5634b88629cc.ogg"},{"id":"ja-Play_Vo_Char_NPC012_TeammateDown_003","title":"Поражен товарищ по команде – Сакири","description":"Сакири, сейчас не время выпендриваться.","language":"Японский","audioUrl":"/nte-meta/game-audio/95bba419594a546bd0b1.ogg"},{"id":"ko-Play_Vo_Char_NPC012_self_001","title":"Обо мне: способность эспера","description":"Это, конечно, не какая‑то суперспособность, но Хотори сказала: «Не дай этим курьерам тебя переманить». И Наналли тоже сказала: «Семья Колуччи без тебя не справится!» А я и правда просто рад помочь.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c7445f26de301a57162f.ogg"},{"id":"zh-Play_Vo_Char_NPC012_TeammateDown_001","title":"Поражен товарищ по команде – Ноль","description":"Ты в порядке?","language":"Китайский","audioUrl":"/nte-meta/game-audio/b7913cd7a38ae1a9721a.ogg"},{"id":"en-Play_Vo_Char_NPC012_weather_002","title":"Дождливо","description":"Я только что видел, как Тайгедо выскочил на улицу без зонтика. Он что, непромокаемый…?","language":"Английский","audioUrl":"/nte-meta/game-audio/6e86d7f9bd1356383ebc.ogg"},{"id":"ja-Play_Vo_Char_NPC012_windfall_004","title":"Неожиданная добыча IV","description":"Деньги для Колуччи…?","language":"Японский","audioUrl":"/nte-meta/game-audio/d18a93e6146526b1b23c.ogg"},{"id":"zh-Play_Vo_Char_NPC012_skill_003","title":"Навык перенаправления III","description":"Стабилизирую твоё состояние.","language":"Китайский","audioUrl":"/nte-meta/game-audio/9f11c4f9727cb0a34ffb.ogg"},{"id":"en-Play_Vo_Char_NPC012_SSC_006","title":"Особое переключение — Даффодил","description":"Даффодил, я постараюсь сделать всё так, как ты меня учила.","language":"Английский","audioUrl":"/nte-meta/game-audio/12e65ac5e229b1b6afc3.ogg"},{"id":"en-Play_Vo_Char_NPC012_windfall_001","title":"Неожиданная добыча I","description":"Готово.","language":"Английский","audioUrl":"/nte-meta/game-audio/68e4dad8a6254f6cc4ed.ogg"},{"id":"ja-Play_Vo_Char_NPC012_Switch_003","title":"Переключение III","description":"Пошли.","language":"Японский","audioUrl":"/nte-meta/game-audio/b5693efbf52c46eaeb79.ogg"},{"id":"ko-Play_Vo_Char_NPC012_aoe_UI_001","title":"Сверхспособность I","description":"Позволь мне вылечить тебя.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b3bdd62d45f30cbaa42d.ogg"},{"id":"zh-Play_Vo_Char_NPC012_about_008","title":"Об антикварном магазине Эйбон","description":"Это как второй дом. Здесь все близки, как одна дружная семья.","language":"Китайский","audioUrl":"/nte-meta/game-audio/df0f51881f1657f4b0c0.ogg"},{"id":"zh-Play_Vo_Char_NPC012_gift_002","title":"Подарок получен II","description":"Мне очень нравится. Спасибо за все твои старания!","language":"Китайский","audioUrl":"/nte-meta/game-audio/1ae95d6ad4238782da40.ogg"},{"id":"zh-Play_Vo_Char_NPC012_windfall_006","title":"Неожиданная добыча VI","description":"Кирумару точно это заинтересует.","language":"Китайский","audioUrl":"/nte-meta/game-audio/64d06891202bef7ac661.ogg"},{"id":"en-Play_Vo_Char_NPC012_TeammateDown_003","title":"Поражен товарищ по команде – Сакири","description":"Сакири, сейчас не время выпендриваться.","language":"Английский","audioUrl":"/nte-meta/game-audio/ee384f0df61aa55be16c.ogg"},{"id":"ko-Play_Vo_Char_NPC012_fh_001","title":"Исцеление I","description":"Так гораздо лучше.","language":"Корейский","audioUrl":"/nte-meta/game-audio/a9f101c0608352d8c407.ogg"},{"id":"en-Play_Vo_Char_NPC012_self_001","title":"Обо мне: способность эспера","description":"Это, конечно, не какая‑то суперспособность, но Хотори сказала: «Не дай этим курьерам тебя переманить». И Наналли тоже сказала: «Семья Колуччи без тебя не справится!» А я и правда просто рад помочь.","language":"Английский","audioUrl":"/nte-meta/game-audio/8a929ab09a482ba2534d.ogg"},{"id":"ja-Play_Vo_Char_NPC012_anomaly_004","title":"Нуллификация II","description":"Мы ещё увидимся… правда?","language":"Японский","audioUrl":"/nte-meta/game-audio/fb79ef2072f28d36c7bf.ogg"},{"id":"zh-Play_Vo_Char_NPC012_struck_001","title":"Урон I","description":"М-м.","language":"Китайский","audioUrl":"/nte-meta/game-audio/570035cd6c7599a5d6ea.ogg"},{"id":"en-Play_Vo_Char_NPC012_weather_001","title":"Солнечно","description":"Давай вынесем это растение во двор, пусть погреется на солнышке.","language":"Английский","audioUrl":"/nte-meta/game-audio/fea427f427611bf600a4.ogg"},{"id":"ja-Play_Vo_Char_NPC012_Fly_001","title":"Планирование I","description":"Отличный вид сверху…","language":"Японский","audioUrl":"/nte-meta/game-audio/9ffb20393605739f6194.ogg"},{"id":"ja-Play_Vo_Char_NPC012_Parry_001","title":"Парирование I","description":"Самое время.","language":"Японский","audioUrl":"/nte-meta/game-audio/573034cb1c5290b222e8.ogg"},{"id":"ja-Play_Vo_Char_NPC012_weather_001","title":"Солнечно","description":"Давай вынесем это растение во двор, пусть погреется на солнышке.","language":"Японский","audioUrl":"/nte-meta/game-audio/5867b0c7094f108f765f.ogg"},{"id":"ko-Play_Vo_Char_NPC012_ug_002","title":"Вознесение персонажа II","description":"Ещё так многому нужно научиться.","language":"Корейский","audioUrl":"/nte-meta/game-audio/b2d3fc9df953bc40887b.ogg"},{"id":"en-Play_Vo_Char_NPC012_fh_001","title":"Исцеление I","description":"Так гораздо лучше.","language":"Английский","audioUrl":"/nte-meta/game-audio/d556e30990ab50f43084.ogg"},{"id":"ja-Play_Vo_Char_NPC012_kill_001","title":"Убийство I","description":"Проблема решена.","language":"Японский","audioUrl":"/nte-meta/game-audio/d5994467731cefb45f9e.ogg"},{"id":"ko-Play_Vo_Char_NPC012_hobby_001","title":"Хобби","description":"Чтение и наблюдение за аномалиями.","language":"Корейский","audioUrl":"/nte-meta/game-audio/0b7c11785d8204b37a39.ogg"},{"id":"ko-Play_Vo_Char_NPC012_Parry_001","title":"Парирование I","description":"Самое время.","language":"Корейский","audioUrl":"/nte-meta/game-audio/c5d5a6b2b131c3597110.ogg"},{"id":"ko-Play_Vo_Char_NPC012_skill_001","title":"Навык перенаправления I","description":"Экстренная перевязка.","language":"Корейский","audioUrl":"/nte-meta/game-audio/3bdb457f87ab49ff79d8.ogg"}]'))) WHERE character_id='edgar' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:25:55');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Edgar_Melee","name":"Боевая тренировка","type":"Базовая атака","iconUrl":"/nte-meta/game-assets/2f793bb1767aa1bb65ea.webp","description":"Базовая атака: Боевая тренировка\nВспоминает уроки физкультуры в академии «Ламплайт» и проводит до 5 последовательных атак, которые наносят урон космоса.\n\nБазовая атака: Рассчитанное приземление\nНажмите базовую атаку, находясь в воздухе, чтобы устремиться вниз, нанося 1 удар урона космоса по области при ударе. Урон увеличивается в зависимости от высоты падения (до 100 %).\n\nКритический контрудар: кризис — это возможность\nСрабатывает при использовании «Боевой тренировки» после критического уклонения.\n\nБросается к цели и выпускает из рюкзака поток энергии, нанося 1 удар урона космоса по области и снижая разрушение.\n\nЭдгар уверен, что есть какой-то более гуманный способ их сдерживания. Но пока такое решение не найдено, он вынужден прибегать к жестким методам.","attributes":[{"id":"parameter-0","label":"Множитель 1-го удара","value":"1: 30.9 % · 2: 33.4 % · 3: 36 % · 4: 38.9 % · 5: 42 % · 6: 45.4 % · 7: 49 % · 8: 53 % · 9: 57.2 % · 10: 61.8 % · 11: 66.7 % · 12: 72 % · 13: 77.8 %"},{"id":"parameter-1","label":"Множитель 2-го удара","value":"1: 62.7 % · 2: 67.7 % · 3: 73.1 % · 4: 79 % · 5: 85.3 % · 6: 92.1 % · 7: 99.5 % · 8: 107.5 % · 9: 116.1 % · 10: 125.3 % · 11: 135.4 % · 12: 146.2 % · 13: 157.9 %"},{"id":"parameter-2","label":"Множитель 3-го удара","value":"1: 39 %*2 · 2: 42.1 %*2 · 3: 45.5 %*2 · 4: 49.1 %*2 · 5: 53.1 %*2 · 6: 57.3 %*2 · 7: 61.9 %*2 · 8: 66.8 %*2 · 9: 72.2 %*2 · 10: 78 %*2 · 11: 84.2 %*2 · 12: 90.9 %*2 · 13: 98.2 %*2"},{"id":"parameter-3","label":"Множитель 4-го удара","value":"1: 83.3 % · 2: 90 % · 3: 97.2 % · 4: 104.9 % · 5: 113.3 % · 6: 122.4 % · 7: 132.2 % · 8: 142.8 % · 9: 154.2 % · 10: 166.5 % · 11: 179.8 % · 12: 194.2 % · 13: 209.8 %"},{"id":"parameter-4","label":"Множитель 5-го удара","value":"1: 69.8 % · 2: 75.4 % · 3: 81.4 % · 4: 87.9 % · 5: 95 % · 6: 102.6 % · 7: 110.8 % · 8: 119.6 % · 9: 129.2 % · 10: 139.5 % · 11: 150.7 % · 12: 162.7 % · 13: 175.8 %"},{"id":"parameter-5","label":"Множитель урона атаки в падении","value":"1: 31.2 % · 2: 33.7 % · 3: 36.4 % · 4: 39.3 % · 5: 42.4 % · 6: 45.8 % · 7: 49.5 % · 8: 53.5 % · 9: 57.7 % · 10: 62.4 % · 11: 67.4 % · 12: 72.7 % · 13: 78.6 %"},{"id":"parameter-6","label":"Множитель урона критического контрудара","value":"1: 104 % · 2: 112.3 % · 3: 121.3 % · 4: 131 % · 5: 141.5 % · 6: 152.8 % · 7: 165 % · 8: 178.2 % · 9: 192.5 % · 10: 207.9 % · 11: 224.5 % · 12: 242.5 % · 13: 261.9 %"}]},{"id":"GA_Edgar_Skill","name":"Дикое течение","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/705f69d32bd9d1f1eaaa.webp","description":"Удерживайте для входа в состояние непрерывного применения навыка, направляя Течение на цель, нанося урон космоса и непрерывно исцеляя товарища по команде с наименьшим количеством ОЗ.\n\nВремя перезарядки навыка перенаправления «Дикое течение» увеличивается в зависимости от длительности использования.\n\nИсцеление — важная работа. Эдгар понял, что правила, которые он выучил в играх, применимы и в реальной жизни.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 80 % *7 · 2: 86.4 % *7 · 3: 93.3 % *7 · 4: 100.8 % *7 · 5: 108.8 % *7 · 6: 117.5 % *7 · 7: 126.9 % *7 · 8: 137.1 % *7 · 9: 148.1 % *7 · 10: 159.9 % *7 · 11: 172.7 % *7 · 12: 186.5 % *7 · 13: 201.5 % *7"}]},{"id":"GA_Edgar_UltraSkill","name":"Поминки по Финнегану","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/2e7ed83b24a5e11236cc.webp","description":"Погружается в свои мысли, создавая область лабиринта на 10 сек. Наносит 1 удар урона космоса по области. Исцеляет текущего персонажа, пока лабиринт активен.\n\nЭдгар, всегда любопытный и любознательный, зачастую без предупреждения погружается в глубокие размышления. Вытащить его из лабиринта мыслей — нелегкая задача.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 400 % · 2: 432 % · 3: 466.6 % · 4: 503.9 % · 5: 544.2 % · 6: 587.7 % · 7: 634.7 % · 8: 685.5 % · 9: 740.4 % · 10: 799.6 % · 11: 863.6 % · 12: 932.7 % · 13: 1007.3 %"}]},{"id":"GA_Edgar_QTE","name":"Вес знаний","type":"Навык поддержки","iconUrl":"/nte-meta/game-assets/271eef633923352f175a.webp","description":"Эта сумка очень тяжёлая. Эдгар бросается к цели и изо всех сил размахивает сумкой, нанося 1 удар урона космоса по области.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 200 % · 2: 216 % · 3: 233.3 % · 4: 251.9 % · 5: 272.1 % · 6: 293.9 % · 7: 317.4 % · 8: 342.8 % · 9: 370.2 % · 10: 399.8 % · 11: 431.8 % · 12: 466.3 % · 13: 503.6 %"}]},{"id":"GA_Edgar_Passive_1","name":"Нежный край","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/117fff5de9d007d4c97f.webp","description":"Усиление зарядки: когда персонаж активирует зарядку с помощью навыка поддержки, он мгновенно получает 120 ед. энергии сверхспособности. После этого Пестики жизни больше не будут давать энергию сверхспособности при попадании по замедленным целям. Перезарядка: 30 сек.\n\nКак и многие гении, Эдгар отличается сдержанной гордостью. Впрочем, в отличие от большинства, его гениальность мягкая и сдержанная; она помогает ему преодолевать все трудности, с которыми он сталкивается.","attributes":[]},{"id":"GA_Edgar_Passive_2","name":"Неизменное тепло","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/e6f659ffe8a24b16cbe6.webp","description":"Используйте навык перенаправления «Дикое течение» или навык поддержки «Вес знаний», чтобы получить Ключ истины (максимум 3 ключа).\n\nКаждый Ключ истины увеличивает длительность сверхспособности «Поминки по Финнегану» на 1 сек.\n\nВсякий раз, когда Эдгар видит теплый свет окон «Эйбона», в его сердце возникает ощущение уюта. В постоянно меняющемся мире эта теплота остается неизменной.","attributes":[]},{"id":"City_Ability_Aidejia_01","name":"Знания в действии","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/6d80ca3a4efc6c2c352d.webp","description":"Эдгар увеличивает поток на 18.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Эдгар увеличивает поток на 18."},{"id":"city-1","label":"Уровень 2","value":"Эдгар снижает скорость расхода ингредиентов на 1 %."},{"id":"city-2","label":"Уровень 3","value":"Эдгар увеличивает поток на 18."},{"id":"city-3","label":"Уровень 4","value":"Эдгар снижает скорость расхода ингредиентов на 1 %."},{"id":"city-4","label":"Уровень 5","value":"Эдгар увеличивает поток на 27."}]}]') WHERE character_id='edgar' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:25:55');

UPDATE character_profiles SET updated_at=CURRENT_TIMESTAMP WHERE character_id='edgar' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-06-30 13:25:55');

UPDATE character_profiles SET abilities_json=json('[{"id":"GA_Female051_Skill","name":"Оценка и гравировка","type":"Навык перенаправления","iconUrl":"/nte-meta/game-assets/46d11502e8d986fe3f62.webp","description":"Промах, враг раскрыт! Совершает 3 быстрых удара оружием, затем прыгает в воздух для зарядки и применяет Пушку эспера, нанося 1 удар урона космоса по области. Дополнительно наносит первому пораженному противнику, чей уровень ниже уровня Ноль, 1 удар урона космоса.\n\nОчерченная тонкими штрихами сюрреалистическая сцена возникает словно из ниоткуда…","attributes":[{"id":"parameter-0","label":"Множитель удара оружием","value":"1: 20 %+20 %+125.6 %+134.4 % · 2: 21.6 %+21.6 %+135.6 %+145.2 % · 3: 23.3 %+23.3 %+146.5 %+156.8 % · 4: 25.2 %+25.2 %+158.2 %+169.3 % · 5: 27.2 %+27.2 %+170.9 %+182.8 % · 6: 29.4 %+29.4 %+184.5 %+197.5 % · 7: 31.7 %+31.7 %+199.3 %+213.3 % · 8: 34.3 %+34.3 %+215.3 %+230.3 % · 9: 37 %+37 %+232.5 %+248.8 % · 10: 40 %+40 %+251.1 %+268.7 % · 11: 43.2 %+43.2 %+271.2 %+290.2 % · 12: 46.6 %+46.6 %+292.9 %+313.4 % · 13: 50.4 %+50.4 %+316.3 %+338.4 %"},{"id":"parameter-1","label":"Множитель доп. урона","value":"1: 200 % · 2: 200 % · 3: 200 % · 4: 200 % · 5: 200 % · 6: 200 % · 7: 200 % · 8: 200 % · 9: 200 % · 10: 200 % · 11: 200 % · 12: 200 % · 13: 200 %"}]},{"id":"GA_Female051_UltraSkill","name":"Деление на ноль","type":"Сверхспособность","iconUrl":"/nte-meta/game-assets/498d8117fd2f3573fbc1.webp","description":"Танцуя, я разрываю связи между Нексусами, что вижу лишь я. Наносит несколько ударов урона космоса по области.\n\nЯ чувствую нексус аномалии, связанный невидимыми, неслышимыми, неосязаемыми узами… Все они мгновенно разрубаются одним изящным ударом.","attributes":[{"id":"parameter-0","label":"Множитель урона","value":"1: 132.7 % + 5.3 % *4 + 177.5 % + 168.6 % · 2: 143.3 % + 5.7 % *4 + 191.7 % + 182.1 % · 3: 154.8 % + 6.2 % *4 + 207 % + 196.7 % · 4: 167.2 % + 6.7 % *4 + 223.6 % + 212.4 % · 5: 180.5 % + 7.2 % *4 + 241.5 % + 229.4 % · 6: 195 % + 7.8 % *4 + 260.8 % + 247.7 % · 7: 210.6 % + 8.4 % *4 + 281.7 % + 267.5 % · 8: 227.4 % + 9.1 % *4 + 304.2 % + 289 % · 9: 245.6 % + 9.8 % *4 + 328.5 % + 312.1 % · 10: 265.3 % + 10.6 % *4 + 354.8 % + 337 % · 11: 286.5 % + 11.4 % *4 + 383.2 % + 364 % · 12: 309.4 % + 12.4 % *4 + 413.9 % + 393.1 % · 13: 334.2 % + 13.3 % *4 + 447 % + 424.6 %"}]},{"id":"GA_Female_Passive_1","name":"Оценщик","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/4196160bf74bdc68a0ee.webp","description":"Усиление зарядки: восстанавливает ОЗ в размере 50 % базовой атаки Ноль, когда активный персонаж получает энергию сверхспособности.\n\nКуда приведет меня эта способность читать и понимать аномалии?","attributes":[]},{"id":"GA_Female_Passive_2","name":"Восприятие аномалий","type":"Пассивный навык","iconUrl":"/nte-meta/game-assets/5ee8e7fb9bdfbb3aff17.webp","description":"Сверхспособность «Деление на ноль»: урон увеличивается на 25 %.\n\nСинхронизация нулевого чувства","attributes":[]},{"id":"City_Ability_palyer_01","name":"Пятизвездочный образец","type":"Городской пассивный навык","iconUrl":"/nte-meta/game-assets/f86210463f7747e5df8c.webp","description":"Если уровень связи равен 4 или ниже, подарки дают на 5 % больше симпатии.","attributes":[{"id":"city-0","label":"Уровень 1","value":"Если уровень связи равен 4 или ниже, подарки дают на 5 % больше симпатии."},{"id":"city-1","label":"Уровень 2","value":"Если уровень связи равен 5 или ниже, подарки дают на 5 % больше симпатии."},{"id":"city-2","label":"Уровень 3","value":"Если уровень связи равен 6 или ниже, подарки дают на 5 % больше симпатии."},{"id":"city-3","label":"Уровень 4","value":"Если уровень связи равен 7 или ниже, подарки дают на 5 % больше симпатии."},{"id":"city-4","label":"Уровень 5","value":"Если уровень связи равен 8 или ниже, подарки дают на 5 % больше симпатии."}]}]') WHERE character_id='esper-zero' AND updated_at<='2026-10-25 15:50:55' AND EXISTS(SELECT 1 FROM characters WHERE id=character_id AND updated_at='2026-07-28 14:58:37');

UPDATE character_appearance_variants SET voice_lines_json=json('[{"id":"zh-Play_Vo_Char_ZERO_M_QTE_002","title":"Атака на входе II","language":"Китайский","audioUrl":"/nte-meta/game-audio/033b047e054ad4100766.ogg","sourceUrl":"","description":"Дуговой свет!"},{"id":"zh-Play_Vo_Char_ZERO_M_skill_002","title":"Навык перенаправления II","language":"Китайский","audioUrl":"/nte-meta/game-audio/fc2fce3e38b6f08e6176.ogg","sourceUrl":"","description":"Удар!"},{"id":"en-Play_Vo_Char_ZERO_M_DodgeCombo_002","title":"Серия критических уклонений II","language":"Английский","audioUrl":"/nte-meta/game-audio/283d5428f7c1aca6c557.ogg","sourceUrl":"","description":"Хм-м, не так уж сложно."},{"id":"ko-Play_Vo_Char_ZERO_M_dead_002","title":"Потеря сознания II","language":"Корейский","audioUrl":"/nte-meta/game-audio/f9649bd7b8a9ed482233.ogg","sourceUrl":"","description":"Прости… За неудачу…"},{"id":"ja-Play_Vo_Char_ZERO_M_TeammateDown_003","title":"Поражен товарищ по команде – Адлер","language":"Японский","audioUrl":"/nte-meta/game-audio/9221058ab3c16a2926f4.ogg","sourceUrl":"","description":"«Эйбон» никогда не сдаётся."},{"id":"ko-Play_Vo_Char_ZERO_M_kill_002","title":"Убийство II","language":"Корейский","audioUrl":"/nte-meta/game-audio/0dfa180341e0b0e94575.ogg","sourceUrl":"","description":"Нексус, вот он."},{"id":"zh-Play_Vo_Char_ZERO_M_dead_001","title":"Потеря сознания I","language":"Китайский","audioUrl":"/nte-meta/game-audio/b0b198610175826a7f01.ogg","sourceUrl":"","description":"Нексус… Мне его не увидеть…"},{"id":"zh-Play_Vo_Char_ZERO_M_QTE_003","title":"Атака на входе III","language":"Китайский","audioUrl":"/nte-meta/game-audio/b292be7e1fb5b7b71101.ogg","sourceUrl":"","description":"Изыди!"},{"id":"zh-Play_Vo_Char_ZERO_M_TeammateDown_003","title":"Поражен товарищ по команде – Адлер","language":"Китайский","audioUrl":"/nte-meta/game-audio/2d8a0ece8a3c6a5f4a56.ogg","sourceUrl":"","description":"«Эйбон» никогда не сдаётся."},{"id":"zh-Play_Vo_Char_ZERO_M_TeammateDown_007","title"